import { useState, useEffect } from 'react';
import { Plus, Edit2, Trash2, Search, AlertCircle, CheckCircle2 } from 'lucide-react';
import cashBookApi from '@/lib/cashBookApi';
import { ExpenseCategory } from '@/lib/types/cashBook';

export default function ExpenseCategoriesPage() {
  const [categories, setCategories] = useState<ExpenseCategory[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);

  const [formData, setFormData] = useState<Partial<ExpenseCategory>>({
    name: '',
    number: undefined,
    description: '',
    is_active: true,
  });

  const [validationError, setValidationError] = useState('');

  // Note: We'll need to fetch expense categories from a different endpoint
  // For now, we'll create a separate API method or use the existing one
  
  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await cashBookApi.expenseCategories.list();
      setCategories(response.results || []);
    } catch (err) {
      setError('Failed to load expense categories');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const validateCategoryCode = (numberStr: string): boolean => {
    // Backend range: ExpenseCategory.number is a PositiveIntegerField,
    // 1-99999999 (apps/settings/models.py) — free-form, not restricted to
    // a Chart-of-Accounts band. The manual's own example categories span
    // ranges a fixed band would reject.
    const numRegex = /^[0-9]{1,8}$/;
    if (!numRegex.test(numberStr)) {
      setValidationError('Category number must be numeric, 1-8 digits (e.g., 6100)');
      return false;
    }

    const num = parseInt(numberStr, 10);
    if (num < 1 || num > 99999999) {
      setValidationError('Category number must be between 1 and 99999999');
      return false;
    }

    // Check for duplicates
    if (!editingId && categories.some(c => c.number === num)) {
      setValidationError('This category number already exists');
      return false;
    }

    setValidationError('');
    return true;
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? (e.target as HTMLInputElement).checked
        : name === 'number' ? (value === '' ? undefined : Number(value))
        : value,
    }));

    // Validate number as user types
    if (name === 'number') {
      validateCategoryCode(value);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!formData.name?.trim() || !formData.number) {
      setError('Please fill in all required fields');
      return;
    }

    if (!validateCategoryCode(String(formData.number))) {
      return;
    }

    setLoading(true);

    try {
      if (editingId) {
        await cashBookApi.expenseCategories.update(editingId, formData);
        setSuccess('Expense category updated successfully!');
      } else {
        await cashBookApi.expenseCategories.create(formData);
        setSuccess('Expense category created successfully!');
      }

      // Reset form
      setFormData({
        name: '',
        code: '',
        description: '',
        is_active: true,
      });
      setShowForm(false);
      setEditingId(null);

      // Refresh list
      await fetchCategories();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save category');
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (category: ExpenseCategory) => {
    setFormData(category);
    setEditingId(category.id ?? null);
    setShowForm(true);
  };

  const handleDelete = async (id: number) => {
    if (!confirm('Are you sure you want to delete this category?')) return;

    setLoading(true);
    setError('');

    try {
      await cashBookApi.expenseCategories.delete(id);
      setSuccess('Category deleted successfully!');
      await fetchCategories();
    } catch (err) {
      setError('Failed to delete category');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    setFormData({
      name: '',
      code: '',
      description: '',
      is_active: true,
    });
    setEditingId(null);
    setShowForm(false);
    setValidationError('');
  };

  const filteredCategories = categories.filter(cat =>
    cat.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    String(cat.number).includes(searchTerm)
  );

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-6xl mx-auto">
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900">Expense Categories</h1>
          <p className="text-gray-600 mt-2">Manage expense category numbers (1-99999999)</p>
        </div>

        {/* Messages */}
        {error && (
          <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg flex items-start gap-3">
            <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
            <p className="text-red-800">{error}</p>
          </div>
        )}

        {success && (
          <div className="mb-4 p-4 bg-green-50 border border-green-200 rounded-lg flex items-start gap-3">
            <CheckCircle2 className="w-5 h-5 text-green-600 flex-shrink-0 mt-0.5" />
            <p className="text-green-800">{success}</p>
          </div>
        )}

        {/* Form Section */}
        {showForm && (
          <div className="mb-6 bg-white rounded-lg shadow-md p-6 border-l-4 border-orange-500">
            <h2 className="text-xl font-bold mb-4">
              {editingId ? 'Edit Expense Category' : 'Create New Expense Category'}
            </h2>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Category Number * (1-99999999)
                  </label>
                  <input
                    type="text"
                    name="number"
                    value={formData.number ?? ''}
                    onChange={handleInputChange}
                    placeholder="e.g., 6100"
                    required
                    className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 ${
                      validationError ? 'border-red-300 focus:ring-red-500' : 'border-gray-300 focus:ring-orange-500'
                    }`}
                  />
                  {validationError && (
                    <p className="text-red-600 text-sm mt-1">{validationError}</p>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Category Name *
                  </label>
                  <input
                    type="text"
                    name="name"
                    value={formData.name || ''}
                    onChange={handleInputChange}
                    placeholder="e.g., Salary Expense"
                    required
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Description
                </label>
                <textarea
                  name="description"
                  value={formData.description || ''}
                  onChange={handleInputChange}
                  placeholder="Optional description"
                  rows={3}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500"
                />
              </div>

              <div className="flex items-center gap-3">
                <input
                  type="checkbox"
                  name="is_active"
                  checked={formData.is_active || false}
                  onChange={handleInputChange}
                  className="w-4 h-4 border-gray-300 rounded"
                />
                <label className="text-sm font-medium text-gray-700">
                  Active
                </label>
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  type="submit"
                  disabled={loading || !!validationError}
                  className="px-4 py-2 bg-orange-600 text-white rounded-lg hover:bg-orange-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium"
                >
                  {loading ? 'Saving...' : editingId ? 'Update' : 'Create'}
                </button>
                <button
                  type="button"
                  onClick={handleCancel}
                  className="px-4 py-2 bg-gray-300 text-gray-900 rounded-lg hover:bg-gray-400 font-medium"
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        )}

        {/* Search and Add Button */}
        <div className="flex gap-4 mb-6">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-3 w-5 h-5 text-gray-400" />
            <input
              type="text"
              placeholder="Search by name or code..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500"
            />
          </div>
          {!showForm && (
            <button
              onClick={() => setShowForm(true)}
              className="px-4 py-2 bg-orange-600 text-white rounded-lg hover:bg-orange-700 font-medium flex items-center gap-2"
            >
              <Plus className="w-5 h-5" />
              New Category
            </button>
          )}
        </div>

        {/* Categories Grid */}
        {loading && !showForm ? (
          <div className="text-center py-8">
            <p className="text-gray-500">Loading categories...</p>
          </div>
        ) : filteredCategories.length === 0 ? (
          <div className="text-center py-8 bg-white rounded-lg border border-gray-200">
