'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { ArrowLeft, Download, ArrowUpDown } from 'lucide-react';
import { API_BASE_URL } from '@/lib/api-config';

interface PurchaseData {
  year: number;
  sorted_by: string;
  purchases: Array<{
    supplier_number: number;
    supplier_name: string;
    net_purchases: number;
    vat: number;
    total_purchases: number;
  }>;
  summary: {
    net_purchases: number;
    vat: number;
    total_purchases: number;
  };
  supplier_count: number;
}

export default function PurchaseHistory({ onBack }: { onBack: () => void }) {
  const [year, setYear] = useState(new Date().getFullYear());
  const [sortBy, setSortBy] = useState('supplier_number');
  const [purchaseData, setPurchaseData] = useState<PurchaseData | null>(null);
  const [loading, setLoading] = useState(false);

  const currentYear = new Date().getFullYear();
  const years = Array.from({ length: 5 }, (_, i) => currentYear - 2 + i);

  const handleSearch = async () => {
    setLoading(true);
    try {
      const response = await fetch(
        `${API_BASE_URL}/api/creditors/enquiries/purchase_history/?year=${year}&sort_by=${sortBy}`,
        {
          credentials: 'include',
        }
      );

      if (response.ok) {
        const data = await response.json();
        setPurchaseData(data);
      }
    } catch (err) {
      console.error('Error fetching purchase history:', err);
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('en-ZA', {
      style: 'currency',
      currency: 'ZAR',
    }).format(value);
  };

  const toggleSort = () => {
    const newSort = sortBy === 'supplier_number' ? 'total_purchases' : 'supplier_number';
    setSortBy(newSort);
  };

  useEffect(() => {
    // Auto-fetch when year or sort changes
    if (purchaseData) {
      handleSearch();
    }
  }, [year, sortBy]);

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="outline" onClick={onBack}>
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back
        </Button>
        <div>
          <h1 className="text-3xl font-bold">Purchase History</h1>
          <p className="text-gray-600">Net stock purchases analysis by supplier</p>
        </div>
      </div>

      {/* Search Criteria */}
      <Card>
        <CardHeader>
          <CardTitle>Purchase History Criteria</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="text-sm font-medium block mb-2">Year</label>
              <Select value={year.toString()} onValueChange={(val: string) => setYear(parseInt(val))}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {years.map((y) => (
                    <SelectItem key={y} value={y.toString()}>
                      {y}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <label className="text-sm font-medium block mb-2">Sort By</label>
              <Select value={sortBy} onValueChange={setSortBy}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="supplier_number">Supplier Number</SelectItem>
                  <SelectItem value="total_purchases">Total Purchases</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="flex flex-col justify-end gap-2">
              <Button onClick={handleSearch} disabled={loading}>
                {loading ? 'Loading...' : 'Search'}
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Results */}
      {purchaseData && (
        <>
          {/* Summary Cards */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <Card>
              <CardContent className="pt-6">
                <p className="text-sm text-gray-600">Total Suppliers</p>
                <p className="text-3xl font-bold text-blue-700">{purchaseData.supplier_count}</p>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="pt-6">
                <p className="text-sm text-gray-600">Net Purchases</p>
                <p className="text-2xl font-bold text-green-700">
                  {formatCurrency(purchaseData.summary.net_purchases)}
                </p>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="pt-6">
                <p className="text-sm text-gray-600">Total VAT</p>
                <p className="text-2xl font-bold text-orange-700">
                  {formatCurrency(purchaseData.summary.vat)}
                </p>
              </CardContent>
            </Card>
            <Card className="border-2 border-purple-300 bg-purple-50">
              <CardContent className="pt-6">
                <p className="text-sm text-gray-600">Total Purchases</p>
                <p className="text-2xl font-bold text-purple-700">
                  {formatCurrency(purchaseData.summary.total_purchases)}
                </p>
              </CardContent>
            </Card>
          </div>

          {/* Purchase Listing */}
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0">
              <div>
                <CardTitle>Purchase History - {purchaseData.year}</CardTitle>
                <p className="text-sm text-gray-600 mt-1">
                  Sorted by:{' '}
                  {sortBy === 'supplier_number'
                    ? 'Supplier Number (A-Z)'
                    : 'Total Purchases (High to Low)'}
                </p>
              </div>
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={toggleSort}
                  title="Toggle sort order"
                >
                  <ArrowUpDown className="w-4 h-4 mr-2" />
                  Toggle Sort
                </Button>
                <Button variant="outline" size="sm">
                  <Download className="w-4 h-4 mr-2" />
                  Print
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              {purchaseData.purchases.length > 0 ? (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b bg-gray-50">
                        <th className="text-left py-3 px-4 font-semibold">Supplier #</th>
                        <th className="text-left py-3 px-4 font-semibold">Supplier Name</th>
                        <th className="text-right py-3 px-4 font-semibold">Net Purchases</th>
                        <th className="text-right py-3 px-4 font-semibold">VAT</th>
                        <th className="text-right py-3 px-4 font-semibold">Total Purchases</th>
                        <th className="text-right py-3 px-4 font-semibold">% of Total</th>
                      </tr>
                    </thead>
                    <tbody>
                      {purchaseData.purchases.map((purchase, idx) => {
                        const percentage =
                          purchaseData.summary.total_purchases > 0
                            ? (
                                (purchase.total_purchases /
                                  purchaseData.summary.total_purchases) *
                                100
                              ).toFixed(2)
                            : '0.00';

                        return (
                          <tr key={idx} className="border-b hover:bg-gray-50">
                            <td className="py-2 px-4 font-medium">{purchase.supplier_number}</td>
                            <td className="py-2 px-4">{purchase.supplier_name}</td>
                            <td className="text-right py-2 px-4">
                              {formatCurrency(purchase.net_purchases)}
                            </td>
                            <td className="text-right py-2 px-4">
                              {formatCurrency(purchase.vat)}
                            </td>
                            <td className="text-right py-2 px-4 font-bold">
                              {formatCurrency(purchase.total_purchases)}
                            </td>
                            <td className="text-right py-2 px-4">
                              <span className="bg-blue-100 text-blue-800 px-2 py-1 rounded text-xs font-semibold">
                                {percentage}%
                              </span>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                    <tfoot>
                      <tr className="border-t-2 bg-gray-100 font-bold">
                        <td colSpan={2} className="py-3 px-4">
                          TOTALS
                        </td>
                        <td className="text-right py-3 px-4">
                          {formatCurrency(purchaseData.summary.net_purchases)}
                        </td>
                        <td className="text-right py-3 px-4">
                          {formatCurrency(purchaseData.summary.vat)}
                        </td>
                        <td className="text-right py-3 px-4">
                          {formatCurrency(purchaseData.summary.total_purchases)}
                        </td>
                        <td className="text-right py-3 px-4">100%</td>
                      </tr>
                    </tfoot>
                  </table>
                </div>
              ) : (
                <p className="text-gray-500 text-center py-8">No purchase history found</p>
              )}
            </CardContent>
          </Card>

          {/* Top Suppliers */}
          {purchaseData.purchases.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle>Top 10 Suppliers by Purchase Amount</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {purchaseData.purchases.slice(0, 10).map((purchase, idx) => {
                    const percentage =
                      purchaseData.summary.total_purchases > 0
                        ? (
                            (purchase.total_purchases /
                              purchaseData.summary.total_purchases) *
                            100
                          ).toFixed(1)
                        : '0.0';

                    return (
                      <div key={idx}>
                        <div className="flex justify-between mb-1">
                          <p className="text-sm font-medium">
                            {idx + 1}. {purchase.supplier_name}
                          </p>
                          <div className="flex gap-4">
                            <p className="text-sm font-bold">
                              {formatCurrency(purchase.total_purchases)}
                            </p>
                            <p className="text-sm text-gray-600">{percentage}%</p>
                          </div>
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-6 overflow-hidden">
                          <div
                            className="bg-gradient-to-r from-green-500 to-green-600 h-full flex items-center justify-end pr-2 text-white text-xs font-semibold"
                            style={{
                              width: `${Math.max(
                                (purchase.total_purchases /
                                  purchaseData.purchases[0].total_purchases) *
                                  100,
                                5
                              )}%`,
                            }}
                          >
                            {parseFloat(percentage) > 5 && `${percentage}%`}
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </CardContent>
            </Card>
          )}
        </>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { ArrowLeft, Download } from 'lucide-react';
import { API_BASE_URL } from '@/lib/api-config';

const TRANSACTION_TYPES = [
  { value: 'INVOICE_STOCK', label: 'Invoice - Stock' },
  { value: 'INVOICE_EXPENSE', label: 'Invoice - Expense' },
  { value: 'CREDIT_STOCK', label: 'Credit Note - Stock' },
  { value: 'CREDIT_EXPENSE', label: 'Credit Note - Expense' },
  { value: 'PAYMENT', label: 'Payment' },
  { value: 'SETTLEMENT_DISCOUNT', label: 'Settlement Discount' },
  { value: 'DEBIT_JOURNAL', label: 'Debit Journal' },
  { value: 'CREDIT_JOURNAL', label: 'Credit Journal' },
];

export default function TransactionScroll({ onBack }: { onBack: () => void }) {
  const [startDate, setStartDate] = useState(
    new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]
  );
  const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
  const [enquiryType, setEnquiryType] = useState<'scroll' | 'totals'>('scroll');
  const [selectedTypes, setSelectedTypes] = useState<string[]>([]);
  const [scrollData, setScrollData] = useState<any>(null);
  const [totalsData, setTotalsData] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const handleTypeToggle = (type: string) => {
    setSelectedTypes((prev) =>
      prev.includes(type) ? prev.filter((t) => t !== type) : [...prev, type]
    );
  };

  const handleSearch = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      params.append('start_date', startDate);
      params.append('end_date', endDate);
      params.append('enquiry_type', enquiryType);

      selectedTypes.forEach((type) => {
        params.append('entry_types', type);
      });

      const response = await fetch(
        `${API_BASE_URL}/api/creditors/enquiries/transaction_scroll/?${params.toString()}`,
        {
          credentials: 'include',
        }
      );

      if (response.ok) {
        const data = await response.json();
        if (enquiryType === 'scroll') {
          setScrollData(data);
          setTotalsData(null);
        } else {
          setTotalsData(data);
          setScrollData(null);
        }
      }
    } catch (err) {
      console.error('Error fetching transactions:', err);
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('en-ZA', {
      style: 'currency',
      currency: 'ZAR',
    }).format(value);
  };

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="outline" onClick={onBack}>
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back
        </Button>
        <div>
          <h1 className="text-3xl font-bold">Transaction Scroll</h1>
          <p className="text-gray-600">Detailed transaction listing and analysis</p>
        </div>
      </div>

      {/* Search Criteria */}
      <Card>
        <CardHeader>
          <CardTitle>Search Criteria</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Date Range */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="text-sm font-medium block mb-2">Start Date</label>
              <Input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} />
            </div>
            <div>
              <label className="text-sm font-medium block mb-2">End Date</label>
              <Input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} />
            </div>
            <div className="flex flex-col justify-end">
              <Button onClick={handleSearch} disabled={loading}>
                {loading ? 'Loading...' : 'Search'}
              </Button>
            </div>
          </div>

          {/* Enquiry Type */}
          <div>
            <label className="text-sm font-medium block mb-2">Enquiry Type</label>
            <div className="flex gap-4">
              <label className="flex items-center gap-2">
                <input
                  type="radio"
                  value="scroll"
                  checked={enquiryType === 'scroll'}
                  onChange={(e) => setEnquiryType(e.target.value as any)}
                  className="w-4 h-4"
                />
                <span className="text-sm">Scroll (Detailed List)</span>
              </label>
              <label className="flex items-center gap-2">
                <input
                  type="radio"
                  value="totals"
                  checked={enquiryType === 'totals'}
                  onChange={(e) => setEnquiryType(e.target.value as any)}
                  className="w-4 h-4"
                />
                <span className="text-sm">Totals (Summary)</span>
              </label>
            </div>
          </div>

          {/* Transaction Types */}
          <div>
            <label className="text-sm font-medium block mb-2">Transaction Types</label>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {TRANSACTION_TYPES.map((type) => (
                <label key={type.value} className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={selectedTypes.includes(type.value)}
                    onChange={() => handleTypeToggle(type.value)}
                    className="w-4 h-4"
                  />
                  <span className="text-sm">{type.label}</span>
                </label>
              ))}
            </div>
            <p className="text-xs text-gray-500 mt-2">
              {selectedTypes.length === 0
                ? 'Select transaction types to include, or leave blank for all'
                : `${selectedTypes.length} type(s) selected`}
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Results - Scroll View */}
      {scrollData && enquiryType === 'scroll' && (
        <>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0">
              <div>
                <CardTitle>Transaction Scroll</CardTitle>
                <p className="text-sm text-gray-600 mt-1">
                  Period: {startDate} to {endDate} ({scrollData.count} transactions)
                </p>
              </div>
              <Button variant="outline" size="sm">
                <Download className="w-4 h-4 mr-2" />
                Export
              </Button>
            </CardHeader>
            <CardContent>
              {scrollData.transactions && scrollData.transactions.length > 0 ? (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b bg-gray-50">
                        <th className="text-left py-3 px-4 font-semibold">Date</th>
                        <th className="text-left py-3 px-4 font-semibold">Ref #</th>
                        <th className="text-left py-3 px-4 font-semibold">Type</th>
                        <th className="text-left py-3 px-4 font-semibold">Supplier</th>
                        <th className="text-right py-3 px-4 font-semibold">Net Amount</th>
                        <th className="text-right py-3 px-4 font-semibold">VAT</th>
                        <th className="text-right py-3 px-4 font-semibold">Total Amount</th>
                      </tr>
                    </thead>
                    <tbody>
                      {scrollData.transactions.map((txn: any, idx: number) => (
                        <tr key={idx} className="border-b hover:bg-gray-50">
                          <td className="py-2 px-4">
                            {new Date(txn.date).toLocaleDateString()}
                          </td>
                          <td className="py-2 px-4 font-mono text-xs">{txn.transaction_number}</td>
                          <td className="py-2 px-4 text-xs">{txn.transaction_type}</td>
                          <td className="py-2 px-4">{txn.supplier_name}</td>
                          <td className="text-right py-2 px-4">
                            {formatCurrency(txn.net_amount)}
                          </td>
                          <td className="text-right py-2 px-4">
                            {formatCurrency(txn.vat_amount)}
                          </td>
                          <td className="text-right py-2 px-4 font-semibold">
                            {formatCurrency(txn.total_amount)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <p className="text-gray-500 text-center py-8">No transactions found</p>
              )}
            </CardContent>
          </Card>

          {/* Grand Totals */}
          <Card>
            <CardHeader>
              <CardTitle>Grand Totals</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="p-4 bg-blue-50 rounded">
                  <p className="text-sm text-gray-600">Transaction Count</p>
                  <p className="text-2xl font-bold text-blue-700">{scrollData.grand_total?.count}</p>
                </div>
                <div className="p-4 bg-green-50 rounded">
                  <p className="text-sm text-gray-600">Total Net Amount</p>
                  <p className="text-2xl font-bold text-green-700">
                    {formatCurrency(scrollData.grand_total?.total_exclusive || 0)}
                  </p>
                </div>
                <div className="p-4 bg-orange-50 rounded">
                  <p className="text-sm text-gray-600">Total VAT</p>
                  <p className="text-2xl font-bold text-orange-700">
                    {formatCurrency(scrollData.grand_total?.total_vat || 0)}
                  </p>
                </div>
                <div className="p-4 bg-purple-50 rounded border-2 border-purple-300">
                  <p className="text-sm text-gray-600">Grand Total</p>
                  <p className="text-2xl font-bold text-purple-700">
                    {formatCurrency(scrollData.grand_total?.total_inclusive || 0)}
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
        </>
      )}

      {/* Results - Totals View */}
      {totalsData && enquiryType === 'totals' && (
        <>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0">
              <div>
                <CardTitle>Transaction Totals Summary</CardTitle>
                <p className="text-sm text-gray-600 mt-1">
                  Period: {startDate} to {endDate}
                </p>
              </div>
              <Button variant="outline" size="sm">
                <Download className="w-4 h-4 mr-2" />
                Export
              </Button>
            </CardHeader>
            <CardContent>
              {totalsData.totals && totalsData.totals.length > 0 ? (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b bg-gray-50">
                        <th className="text-left py-3 px-4 font-semibold">Transaction Type</th>
                        <th className="text-right py-3 px-4 font-semibold">Count</th>
                        <th className="text-right py-3 px-4 font-semibold">Net Amount</th>
                        <th className="text-right py-3 px-4 font-semibold">VAT</th>
                        <th className="text-right py-3 px-4 font-semibold">Total Amount</th>
                      </tr>
                    </thead>
                    <tbody>
                      {totalsData.totals.map((total: any, idx: number) => (
                        <tr key={idx} className="border-b hover:bg-gray-50">
                          <td className="py-2 px-4">{total.transaction_type}</td>
                          <td className="text-right py-2 px-4 font-semibold">{total.count}</td>
                          <td className="text-right py-2 px-4">
                            {formatCurrency(total.total_exclusive)}
                          </td>
                          <td className="text-right py-2 px-4">
                            {formatCurrency(total.total_vat)}
                          </td>
                          <td className="text-right py-2 px-4 font-semibold">
                            {formatCurrency(total.total_inclusive)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <p className="text-gray-500 text-center py-8">No transactions found</p>
              )}
            </CardContent>
          </Card>

          {/* Grand Totals */}
          <Card>
            <CardHeader>
              <CardTitle>Grand Totals</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="p-4 bg-blue-50 rounded">
                  <p className="text-sm text-gray-600">Total Transactions</p>
                  <p className="text-2xl font-bold text-blue-700">{totalsData.grand_total?.count}</p>
                </div>
                <div className="p-4 bg-green-50 rounded">
                  <p className="text-sm text-gray-600">Total Net Amount</p>
                  <p className="text-2xl font-bold text-green-700">
                    {formatCurrency(totalsData.grand_total?.total_exclusive || 0)}
                  </p>
                </div>
                <div className="p-4 bg-orange-50 rounded">
                  <p className="text-sm text-gray-600">Total VAT</p>
                  <p className="text-2xl font-bold text-orange-700">
                    {formatCurrency(totalsData.grand_total?.total_vat || 0)}
                  </p>
                </div>
                <div className="p-4 bg-purple-50 rounded border-2 border-purple-300">
                  <p className="text-sm text-gray-600">Grand Total</p>
                  <p className="text-2xl font-bold text-purple-700">
                    {formatCurrency(totalsData.grand_total?.total_inclusive || 0)}
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
        </>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { creditorsApi } from '@/lib/creditorsApi';
import settingsApi from '@/lib/settingsApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Loader } from 'lucide-react';

export default function ExpenseAnalysisPage() {
  const [dateRange, setDateRange] = useState({
    from: new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0],
    to: new Date().toISOString().split('T')[0],
  });
  const [page, setPage] = useState(1);

  const { data: expenseData, isLoading: isExpenseLoading } = useQuery({
    queryKey: ['creditors-expense-analysis', dateRange, page],
    queryFn: () =>
      creditorsApi.transactions.list({
        transaction_type: 'IN',
        start_date: dateRange.from,
        end_date: dateRange.to,
        page,
        page_size: 50,
        ordering: '-transaction_date',
      }),
  });

  const { data: categoryBreakdown, isLoading: isCategoryLoading } = useQuery({
    queryKey: ['expense-category-breakdown', dateRange],
    queryFn: () =>
      settingsApi.expenseCategories.list({
        start_date: dateRange.from,
        end_date: dateRange.to,
        page_size: 100,
      }),
  });

  const isLoading = isExpenseLoading || isCategoryLoading;

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  const totalExpenses = expenseData?.results?.reduce((sum: number, exp: any) => sum + (exp.amount || 0), 0) || 0;
  const totalTax = expenseData?.results?.reduce((sum: number, exp: any) => sum + (exp.tax_amount || 0), 0) || 0;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold">Expense & Tax Analysis</h1>
        <p className="text-gray-600 mt-1">Analyze expenses and tax by category and supplier</p>
      </div>

      {/* Date Filter */}
      <Card className="p-4">
        <div className="flex gap-4 items-end">
          <div>
            <label className="block text-sm font-medium mb-1">From Date</label>
            <Input
              type="date"
              value={dateRange.from}
              onChange={(e) => setDateRange({ ...dateRange, from: e.target.value })}
            />
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">To Date</label>
            <Input
              type="date"
              value={dateRange.to}
              onChange={(e) => setDateRange({ ...dateRange, to: e.target.value })}
            />
          </div>
          <Button className="bg-blue-600 hover:bg-blue-700">Generate Report</Button>
        </div>
      </Card>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card className="p-6">
          <p className="text-xs text-gray-600 uppercase">Total Expenses</p>
          <p className="text-2xl font-bold text-blue-600 mt-2">
            R {totalExpenses.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
          </p>
          <p className="text-xs text-gray-600 mt-1">{expenseData?.results?.length || 0} invoices</p>
        </Card>

        <Card className="p-6">
          <p className="text-xs text-gray-600 uppercase">Total VAT</p>
          <p className="text-2xl font-bold text-amber-600 mt-2">
            R {totalTax.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
          </p>
          <p className="text-xs text-gray-600 mt-1">{totalExpenses > 0 ? ((totalTax / totalExpenses) * 100).toFixed(1) : 0}% of expenses</p>
        </Card>

        <Card className="p-6">
          <p className="text-xs text-gray-600 uppercase">Taxable Amount</p>
          <p className="text-2xl font-bold text-green-600 mt-2">
            R {(totalExpenses - totalTax).toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
          </p>
        </Card>
      </div>

      {/* Breakdown by Category */}
      {categoryBreakdown?.results && categoryBreakdown.results.length > 0 && (
        <Card className="p-6">
          <h2 className="text-lg font-bold mb-4">Expense by Category</h2>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="border-b bg-gray-50">
                <tr>
                  <th className="px-4 py-3 text-left font-semibold">Category</th>
                  <th className="px-4 py-3 text-right font-semibold">Count</th>
                  <th className="px-4 py-3 text-right font-semibold">Amount</th>
                  <th className="px-4 py-3 text-right font-semibold">VAT</th>
                  <th className="px-4 py-3 text-right font-semibold">% of Total</th>
                </tr>
              </thead>
              <tbody>
                {categoryBreakdown.results.map((cat: any) => (
                  <tr key={cat.id} className="border-b">
                    <td className="px-4 py-3 font-medium">{cat.name}</td>
                    <td className="px-4 py-3 text-right">{cat.transaction_count || 0}</td>
                    <td className="px-4 py-3 text-right font-bold">
                      R {cat.total_amount?.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                    </td>
                    <td className="px-4 py-3 text-right">
                      R {cat.total_tax?.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                    </td>
                    <td className="px-4 py-3 text-right text-gray-600">
                      {totalExpenses > 0 ? ((cat.total_amount || 0) / totalExpenses * 100).toFixed(1) : 0}%
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {/* Expenses Table */}
      <Card className="p-6">
        <h2 className="text-lg font-bold mb-4">Expense Invoices</h2>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="border-b bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left font-semibold">Invoice #</th>
                <th className="px-4 py-3 text-left font-semibold">Supplier</th>
                <th className="px-4 py-3 text-left font-semibold">Category</th>
                <th className="px-4 py-3 text-left font-semibold">Date</th>
                <th className="px-4 py-3 text-right font-semibold">Amount</th>
                <th className="px-4 py-3 text-right font-semibold">VAT</th>
              </tr>
            </thead>
            <tbody>
              {expenseData?.results?.map((exp: any) => (
                <tr key={exp.id} className="border-b hover:bg-gray-50">
                  <td className="px-4 py-3 font-medium">{exp.invoice_number}</td>
                  <td className="px-4 py-3">{exp.supplier_name}</td>
                  <td className="px-4 py-3 text-xs text-gray-600">{exp.category_name}</td>
                  <td className="px-4 py-3 text-sm">
                    {new Date(exp.transaction_date).toLocaleDateString('en-ZA')}
                  </td>
                  <td className="px-4 py-3 text-right font-bold">
                    R {exp.amount?.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                  </td>
                  <td className="px-4 py-3 text-right">
                    R {exp.tax_amount?.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="flex items-center justify-between mt-4 pt-4 border-t">
          <p className="text-sm text-gray-600">
            Showing {expenseData?.results?.length || 0} of {expenseData?.count || 0} invoices
          </p>
          <div className="flex gap-2">
            <Button
              variant="outline"
              disabled={!expenseData?.previous}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              Previous
            </Button>
            <Button
              variant="outline"
              disabled={!expenseData?.next}
              onClick={() => setPage((p) => p + 1)}
            >
              Next
            </Button>
          </div>
        </div>
      </Card>

      {/* Export Options */}
      <div className="flex gap-2">
        <Button className="bg-blue-600 hover:bg-blue-700">Export to Excel</Button>
        <Button className="bg-green-600 hover:bg-green-700">Export to PDF</Button>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { creditorsApi } from '@/lib/creditorsApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Loader, Search } from 'lucide-react';

export default function TransactionScrollPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [filters, setFilters] = useState({
    transaction_type: '',
    date_from: '',
    date_to: new Date().toISOString().split('T')[0],
  });
  const [page, setPage] = useState(1);

  const { data: transactions, isLoading } = useQuery({
    queryKey: ['creditors-transaction-scroll', searchTerm, filters, page],
    queryFn: () =>
      creditorsApi.transactions.list({
        search: searchTerm || undefined,
        transaction_type: filters.transaction_type || undefined,
        start_date: filters.date_from || undefined,
        end_date: filters.date_to || undefined,
        page,
        page_size: 50,
        ordering: '-transaction_date',
      }),
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  const totalAmount = transactions?.results?.reduce((sum: number, txn: any) => sum + (txn.amount || 0), 0) || 0;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold">Transaction Scroll</h1>
        <p className="text-gray-600 mt-1">View all creditor transactions in chronological order</p>
      </div>

      {/* Filters */}
      <Card className="p-6">
        <h2 className="font-bold mb-4">Filters</h2>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div>
            <label className="block text-sm font-medium mb-1">Search</label>
            <div className="relative">
              <Search className="absolute left-3 top-3 w-4 h-4 text-gray-400" />
              <Input
                type="text"
                placeholder="Account, reference..."
                value={searchTerm}
                onChange={(e) => {
                  setSearchTerm(e.target.value);
                  setPage(1);
                }}
                className="pl-10"
              />
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Transaction Type</label>
            <select
              value={filters.transaction_type}
              onChange={(e) => {
                setFilters({ ...filters, transaction_type: e.target.value });
                setPage(1);
              }}
              className="w-full border border-gray-300 rounded px-3 py-2"
            >
              <option value="">All Types</option>
              <option value="GRN">Stock Receipt</option>
              <option value="INVOICE_EXPENSE">Invoice</option>
              <option value="PAYMENT">Payment</option>
              <option value="RETURN_STOCK">Stock Return</option>
              <option value="RETURN_EXPENSE">Credit Note</option>
              <option value="JOURNAL">Journal</option>
              <option value="RFC">RFC</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">From Date</label>
            <Input
              type="date"
              value={filters.date_from}
              onChange={(e) => {
                setFilters({ ...filters, date_from: e.target.value });
                setPage(1);
              }}
            />
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">To Date</label>
            <Input
              type="date"
              value={filters.date_to}
              onChange={(e) => {
                setFilters({ ...filters, date_to: e.target.value });
                setPage(1);
              }}
            />
          </div>
        </div>
      </Card>

      {/* Totals Summary */}
      <Card className="p-6 bg-blue-50">
        <p className="text-sm text-gray-600 mb-1">Total Amount ({transactions?.results?.length || 0} transactions)</p>
        <p className="text-3xl font-bold text-blue-700">
          R {totalAmount.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
        </p>
      </Card>

      {/* Transactions Table */}
      <Card className="p-6">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="border-b bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left font-semibold">Date</th>
                <th className="px-4 py-3 text-left font-semibold">Reference</th>
                <th className="px-4 py-3 text-left font-semibold">Supplier</th>
                <th className="px-4 py-3 text-left font-semibold">Type</th>
                <th className="px-4 py-3 text-left font-semibold">Description</th>
                <th className="px-4 py-3 text-right font-semibold">Amount</th>
              </tr>
            </thead>
            <tbody>
              {transactions?.results?.map((txn: any) => (
                <tr key={txn.id} className="border-b hover:bg-gray-50">
                  <td className="px-4 py-3 font-medium">
                    {new Date(txn.transaction_date).toLocaleDateString('en-ZA')}
                  </td>
                  <td className="px-4 py-3">{txn.reference_number}</td>
                  <td className="px-4 py-3 text-sm">{txn.supplier_name}</td>
                  <td className="px-4 py-3">
                    <span className="px-2 py-1 bg-blue-100 text-blue-800 text-xs rounded font-medium">
                      {txn.transaction_type}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-xs text-gray-600">{txn.description}</td>
                  <td className="px-4 py-3 text-right font-bold">
                    R {txn.amount?.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {(!transactions?.results || transactions.results.length === 0) && (
          <div className="text-center py-8 text-gray-500">No transactions found.</div>
        )}

        {/* Pagination */}
        <div className="flex items-center justify-between mt-4 pt-4 border-t">
          <p className="text-sm text-gray-600">
            Showing {transactions?.results?.length || 0} of {transactions?.count || 0} transactions
          </p>
          <div className="flex gap-2">
            <Button
              variant="outline"
              disabled={!transactions?.previous}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              Previous
            </Button>
            <Button
              variant="outline"
              disabled={!transactions?.next}
              onClick={() => setPage((p) => p + 1)}
            >
              Next
            </Button>
          </div>
        </div>
      </Card>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { creditorsApi } from '@/lib/creditorsApi';
import type { CreditorAccount } from '@/lib/types/creditors';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Loader, Search } from 'lucide-react';

export default function BalanceCapturePageComponent() {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedAccount, setSelectedAccount] = useState<CreditorAccount | null>(null);
  const [balanceData, setBalanceData] = useState({
    balance_brought_forward: 0,
    effective_date: new Date().toISOString().split('T')[0],
  });

  const { data: accounts, isLoading } = useQuery({
    queryKey: ['creditor-accounts-search', searchTerm],
    queryFn: () =>
      creditorsApi.accounts.list({
        search: searchTerm || undefined,
        page_size: 50,
      }),
  });

  const updateMutation = useMutation({
    mutationFn: (data: any) =>
      creditorsApi.outstandingBalances.update(selectedAccount!.id, data),
    onSuccess: () => {
      setSelectedAccount(null);
      setBalanceData({ balance_brought_forward: 0, effective_date: new Date().toISOString().split('T')[0] });
      alert('Balance updated successfully');
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedAccount) return;
    updateMutation.mutate(balanceData);
  };

  if (isLoading && !selectedAccount) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold">Balance Capture</h1>
        <p className="text-gray-600 mt-1">Record opening balances for BBF (Balance Brought Forward) or Open Item accounts</p>
      </div>

      {!selectedAccount ? (
        <>
          {/* Search */}
          <Card className="p-6">
            <h2 className="text-lg font-bold mb-4">Select Account</h2>
            <div className="relative">
              <Search className="absolute left-3 top-3 w-4 h-4 text-gray-400" />
              <Input
                placeholder="Search by account number or name..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
              />
            </div>
          </Card>

          {/* Account List */}
          <Card className="p-6">
            <div className="space-y-2">
              {accounts?.results?.map((account: CreditorAccount) => (
                <div
                  key={account.id}
                  className="p-4 border rounded hover:bg-blue-50 cursor-pointer transition"
                  onClick={() => setSelectedAccount(account)}
                >
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="font-medium">{account.supplier_number} - {account.name}</p>
                      <p className="text-xs text-gray-600">
                        Type: {account.account_category === 'B' ? 'BBF' : account.account_category === 'O' ? 'Open Item' : 'Unknown'} | Current Balance: R {account.total_outstanding_balance?.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                      </p>
                    </div>
                    <span className="text-blue-600">→</span>
                  </div>
                </div>
              ))}
            </div>
            {(!accounts?.results || accounts.results.length === 0) && (
              <p className="text-center text-gray-500 py-8">No accounts found. Try a different search term.</p>
            )}
          </Card>
        </>
      ) : (
        <>
          {/* Selected Account */}
          <Card className="p-6 bg-blue-50 border-blue-200">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Selected Account</p>
                <p className="text-lg font-bold">{selectedAccount.supplier_number} - {selectedAccount.name}</p>
                <p className="text-xs text-gray-600 mt-1">Type: {selectedAccount.account_category === 'B' ? 'BBF' : selectedAccount.account_category === 'O' ? 'Open Item' : 'Unknown'}</p>
              </div>
              <Button
                variant="outline"
                onClick={() => setSelectedAccount(null)}
              >
                Change
              </Button>
            </div>
          </Card>

          {/* Balance Form */}
          <form onSubmit={handleSubmit}>
            <Card className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium mb-1">Effective Date</label>
                <Input
                  type="date"
                  value={balanceData.effective_date}
                  onChange={(e) => setBalanceData({ ...balanceData, effective_date: e.target.value })}
                  required
                />
                <p className="text-xs text-gray-600 mt-1">Date when this balance becomes effective</p>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Balance Brought Forward (R)</label>
                <Input
                  type="number"
                  step="0.01"
                  value={balanceData.balance_brought_forward}
                  onChange={(e) =>
                    setBalanceData({
                      ...balanceData,
                      balance_brought_forward: parseFloat(e.target.value),
                    })
                  }
                  placeholder="0.00"
                  required
                />
                <p className="text-xs text-gray-600 mt-1">The opening balance as at the effective date</p>
              </div>

              {selectedAccount.account_category === 'O' && (
                <div className="p-4 bg-amber-50 border border-amber-200 rounded">
                  <p className="text-sm text-amber-800">
                    <strong>Note:</strong> For Open Item accounts, you may also need to record individual open items in the Transactions section.
                  </p>
                </div>
              )}
            </Card>

            {/* Actions */}
            <div className="flex gap-2 mt-6">
              <Button
                type="submit"
                className="bg-green-600 hover:bg-green-700"
                disabled={updateMutation.isPending}
              >
                {updateMutation.isPending ? 'Saving...' : 'Save Balance'}
              </Button>
              <Button
                type="button"
                variant="outline"
                onClick={() => setSelectedAccount(null)}
              >
                Cancel
              </Button>
            </div>
          </form>
        </>
      )}
    </div>
  );
}

'use client';

import { useQuery } from '@tanstack/react-query';
import { creditorsApi } from '@/lib/creditorsApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Loader, Plus, Receipt, RotateCcw, FileText, Zap } from 'lucide-react';
import Link from 'next/link';

export default function CreditorsOverviewPage() {
  const { data: _summary, isLoading: summaryLoading } = useQuery({
    queryKey: ['creditors-summary'],
    queryFn: () => creditorsApi.summary.get(),
    staleTime: 5 * 60 * 1000,
  });

  const { data: ageData } = useQuery({
    queryKey: ['creditors-age-analysis'],
    queryFn: () => creditorsApi.summary.ageAnalysis({ include_zero_balance: false }),
    staleTime: 5 * 60 * 1000,
  });

  const { data: recentActivity } = useQuery({
    queryKey: ['creditors-recent-activity'],
    queryFn: () => creditorsApi.ledger.list({ ordering: '-transaction_date', page_size: 5 }),
  });

  // Calculate summary from age analysis data
  const calculatedSummary = ageData ? ageData.reduce(
    (acc, creditor) => ({
      totalPayable: acc.totalPayable + creditor.total_outstanding_balance,
      current: acc.current + creditor.balance_current,
      days30to60: acc.days30to60 + creditor.balance_30_days,
      days60to90: acc.days60to90 + creditor.balance_60_days,
      days90Plus: acc.days90Plus + creditor.balance_90_days + creditor.balance_120_days + creditor.balance_150_days + creditor.balance_180_days,
      count: acc.count + 1,
    }),
    { totalPayable: 0, current: 0, days30to60: 0, days60to90: 0, days90Plus: 0, count: 0 }
  ) : null;

  if (summaryLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold">Creditors Management</h1>
        <p className="text-gray-600 mt-1">Manage supplier accounts, transactions, and payments</p>
      </div>

      {/* Summary Cards */}
      {calculatedSummary && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Card className="p-6">
            <p className="text-xs text-gray-600 uppercase">Total Outstanding</p>
            <p className="text-3xl font-bold text-red-600 mt-2">
              R {calculatedSummary.totalPayable.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}
            </p>
            <p className="text-xs text-gray-500 mt-2">{calculatedSummary.count} suppliers</p>
          </Card>

          <Card className="p-6 border-l-4 border-l-green-500">
            <p className="text-xs text-gray-600 uppercase">Current</p>
            <p className="text-2xl font-bold text-green-600 mt-2">
              R {calculatedSummary.current.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}
            </p>
          </Card>

          <Card className="p-6 border-l-4 border-l-amber-500">
            <p className="text-xs text-gray-600 uppercase">30-90 Days</p>
            <p className="text-2xl font-bold text-amber-600 mt-2">
              R {(calculatedSummary.days30to60 + calculatedSummary.days60to90).toLocaleString('en-ZA', { maximumFractionDigits: 0 })}
            </p>
          </Card>

          <Card className="p-6 border-l-4 border-l-red-500">
            <p className="text-xs text-gray-600 uppercase">90+ Days Overdue</p>
            <p className="text-2xl font-bold text-red-600 mt-2">
              R {calculatedSummary.days90Plus.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}
            </p>
          </Card>
        </div>
      )}

      {/* Quick Action Buttons */}
      <div className="grid grid-cols-2 md:grid-cols-6 gap-2">
        <Link href="/dashboard/admin/creditors/transactions/stock-receipts">
          <Button className="w-full bg-blue-600 hover:bg-blue-700 flex flex-col gap-2 h-auto py-4">
            <Receipt className="w-5 h-5" />
            <span className="text-xs">Stock Receipt</span>
          </Button>
        </Link>
        <Link href="/dashboard/admin/creditors/transactions/invoices/expense">
          <Button className="w-full bg-purple-600 hover:bg-purple-700 flex flex-col gap-2 h-auto py-4">
            <FileText className="w-5 h-5" />
            <span className="text-xs">Invoice</span>
          </Button>
        </Link>
        <Link href="/dashboard/admin/creditors/transactions/payments">
          <Button className="w-full bg-green-600 hover:bg-green-700 flex flex-col gap-2 h-auto py-4">
            <Plus className="w-5 h-5" />
            <span className="text-xs">Payment</span>
          </Button>
        </Link>
        <Link href="/dashboard/admin/creditors/transactions/rfc">
          <Button className="w-full bg-orange-600 hover:bg-orange-700 flex flex-col gap-2 h-auto py-4">
            <RotateCcw className="w-5 h-5" />
            <span className="text-xs">RFC</span>
          </Button>
        </Link>
        <Link href="/dashboard/admin/creditors/transactions/journals">
          <Button className="w-full bg-indigo-600 hover:bg-indigo-700 flex flex-col gap-2 h-auto py-4">
            <Zap className="w-5 h-5" />
            <span className="text-xs">Journal</span>
          </Button>
        </Link>
        <Link href="/dashboard/admin/creditors/maintenance/accounts">
          <Button className="w-full bg-gray-600 hover:bg-gray-700 flex flex-col gap-2 h-auto py-4">
            <Plus className="w-5 h-5" />
            <span className="text-xs">New Account</span>
          </Button>
        </Link>
      </div>

      {/* Recent Activity */}
      {recentActivity?.results && recentActivity.results.length > 0 && (
        <Card className="p-6">
          <h2 className="text-lg font-bold mb-4">Recent Activity</h2>
          <div className="space-y-3">
            {recentActivity.results.map((transaction: any) => (
              <div key={transaction.id} className="flex items-center justify-between py-2 border-b last:border-b-0">
                <div>
                  <p className="font-medium">{transaction.creditor_name}</p>
                  <p className="text-xs text-gray-600">{new Date(transaction.transaction_date).toLocaleDateString('en-ZA')}</p>
                </div>
                <p className="font-bold text-right">
                  R {transaction.total_amount?.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                </p>
              </div>
            ))}
          </div>
        </Card>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ArrowLeft, Printer } from 'lucide-react';
import { API_BASE_URL } from '@/lib/api-config';

interface Account {
  account_number: number;
  name: string;
  short_name: string;
  account_type: string;
  contact_person: string;
  telephone1: string;
  telephone2: string;
  email: string;
  fax: string;
  postal_address?: Record<string, any>;
  physical_address?: Record<string, any>;
  banking_details?: Record<string, any>;
}

interface ReportData {
  report_title: string;
  report_date: string;
  sequence: string;
  address_type: string;
  include_banking_details: boolean;
  total_accounts: number;
  accounts: Account[];
}

export default function AccountDetailsReport({ onBack }: { onBack: () => void }) {
  const [reportData, setReportData] = useState<ReportData | null>(null);
  const [loading, setLoading] = useState(false);
  const [includeBanking, setIncludeBanking] = useState(false);
  const [sequence, setSequence] = useState('A');
  const [addressType, setAddressType] = useState('both');
  const [includePostal, setIncludePostal] = useState(true);

  const handleGenerate = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      params.append('include_postal', includePostal.toString());
      params.append('address_type', addressType);
      params.append('sequence', sequence);
      params.append('include_banking', includeBanking.toString());

      const response = await fetch(
        `${API_BASE_URL}/api/creditors/reports/account_details/?${params.toString()}`,
        {
          credentials: 'include',
        }
      );

      if (response.ok) {
        const data = await response.json();
        setReportData(data);
      }
    } catch (err) {
      console.error('Error generating report:', err);
    } finally {
      setLoading(false);
    }
  };

  const _formatCurrency = (value: number | undefined) => {
    if (!value) return '-';
    return new Intl.NumberFormat('en-ZA', {
      style: 'currency',
      currency: 'ZAR',
    }).format(value);
  };

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="outline" onClick={onBack}>
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back
        </Button>
        <div>
          <h1 className="text-3xl font-bold">Account Details Report</h1>
          <p className="text-gray-600">List all creditors with detailed information</p>
        </div>
      </div>

      {!reportData ? (
        <Card>
          <CardHeader>
            <CardTitle>Report Options</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Address Type</label>
                <select
                  value={addressType}
                  onChange={(e) => setAddressType(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg mt-1"
                >
                  <option value="both">Both (Postal & Physical)</option>
                  <option value="postal">Postal Address Only</option>
                  <option value="delivery">Physical Address Only</option>
                </select>
              </div>

              <div>
                <label className="text-sm font-medium">Sequence</label>
                <select
                  value={sequence}
                  onChange={(e) => setSequence(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg mt-1"
                >
                  <option value="A">Alphabetical</option>
                  <option value="N">Numerical</option>
                </select>
              </div>
            </div>

            <div className="space-y-2">
              <label className="flex items-center gap-2">
                <input
                  type="checkbox"
                  checked={includePostal}
                  onChange={(e) => setIncludePostal(e.target.checked)}
                  className="w-4 h-4"
                />
                <span className="text-sm">Include Postal/Delivery Addresses</span>
              </label>
              <label className="flex items-center gap-2">
                <input
                  type="checkbox"
                  checked={includeBanking}
                  onChange={(e) => setIncludeBanking(e.target.checked)}
                  className="w-4 h-4"
                />
                <span className="text-sm">Include Banking Details</span>
              </label>
            </div>

            <div className="flex gap-2">
              <Button onClick={handleGenerate} disabled={loading} className="bg-blue-600 hover:bg-blue-700">
                {loading ? 'Generating...' : 'Generate Report'}
              </Button>
            </div>
          </CardContent>
        </Card>
      ) : (
        <>
          {/* Report Header */}
          <div className="flex justify-between items-start">
            <div>
              <h2 className="text-2xl font-bold">{reportData.report_title}</h2>
              <p className="text-gray-600 text-sm mt-1">
                Date: {reportData.report_date} | Sequence: {reportData.sequence} | Total Accounts: {reportData.total_accounts}
              </p>
            </div>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => window.print()}>
                <Printer className="w-4 h-4 mr-2" />
                Print
              </Button>
              <Button variant="outline" onClick={() => setReportData(null)}>
                Generate New Report
              </Button>
            </div>
          </div>

          {/* Accounts Table */}
          <Card>
            <CardHeader>
              <CardTitle>Account Listing</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-gray-100 border-b">
                    <tr>
                      <th className="text-left p-2">Account #</th>
                      <th className="text-left p-2">Name</th>
                      <th className="text-left p-2">Contact</th>
                      <th className="text-left p-2">Telephone</th>
                      <th className="text-left p-2">Email</th>
                    </tr>
                  </thead>
                  <tbody>
                    {reportData.accounts.map((account) => (
                      <tr key={account.account_number} className="border-b hover:bg-gray-50">
                        <td className="p-2">{account.account_number}</td>
                        <td className="p-2 font-medium">{account.name}</td>
                        <td className="p-2">{account.contact_person}</td>
                        <td className="p-2">{account.telephone1}</td>
                        <td className="p-2">{account.email}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </CardContent>
          </Card>
        </>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ArrowLeft, Printer } from 'lucide-react';
import { API_BASE_URL } from '@/lib/api-config';

export default function ExpenseTaxReport({ onBack }: { onBack: () => void }) {
  const [reportData, setReportData] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [reportType, setReportType] = useState('monthly_tax');
  const [sequence, setSequence] = useState('A');
  const [reportZero, setReportZero] = useState(false);

  const handleGenerate = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      params.append('report_type', reportType);
      params.append('sequence', sequence);
      params.append('report_zero', reportZero.toString());
      params.append('report_date', new Date().toISOString().split('T')[0]);

      const response = await fetch(
        `${API_BASE_URL}/api/creditors/reports/expense_tax/?${params.toString()}`,
        {
          credentials: 'include',
        }
      );

      if (response.ok) {
        const data = await response.json();
        setReportData(data);
      }
    } catch (err) {
      console.error('Error:', err);
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(value);
  };

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="outline" onClick={onBack}>
          <ArrowLeft className="w-4 h-4 mr-2" /> Back
        </Button>
        <div>
          <h1 className="text-3xl font-bold">Expense & Tax Report</h1>
          <p className="text-gray-600">Expense analysis and tax details</p>
        </div>
      </div>

      {!reportData ? (
        <Card>
          <CardHeader>
            <CardTitle>Report Options</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Report Type</label>
                <select
                  value={reportType}
                  onChange={(e) => setReportType(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg mt-1"
                >
                  <option value="monthly_tax">Monthly & Tax Analysis</option>
                  <option value="ytd">Year to Date</option>
                  <option value="detailed">Detailed Transactions</option>
                  <option value="by_range">Categories by Range</option>
                </select>
              </div>

              <div>
                <label className="text-sm font-medium">Sequence</label>
                <select
                  value={sequence}
                  onChange={(e) => setSequence(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg mt-1"
                >
                  <option value="A">Alphabetical</option>
                  <option value="N">Numerical</option>
                </select>
              </div>
            </div>

            <label className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={reportZero}
                onChange={(e) => setReportZero(e.target.checked)}
                className="w-4 h-4"
              />
              <span className="text-sm">Report on Zero Expenses</span>
            </label>

            <Button onClick={handleGenerate} disabled={loading} className="bg-pink-600 hover:bg-pink-700">
              {loading ? 'Generating...' : 'Generate Report'}
            </Button>
          </CardContent>
        </Card>
      ) : (
        <>
          <div className="flex justify-between items-start">
            <div>
              <h2 className="text-2xl font-bold">{reportData.report_title}</h2>
              <p className="text-gray-600 text-sm">Type: {reportData.report_type}</p>
            </div>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => window.print()}>
                <Printer className="w-4 h-4 mr-2" /> Print
              </Button>
              <Button variant="outline" onClick={() => setReportData(null)}>
                Generate New Report
              </Button>
            </div>
          </div>

          {/* Categories */}
          {reportData.categories && reportData.categories.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle>Expense Categories</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead className="bg-gray-100 border-b">
                      <tr>
                        <th className="text-left p-2">Category</th>
                        <th className="text-right p-2">Exclusive VAT</th>
                        <th className="text-right p-2">VAT</th>
                        <th className="text-right p-2">Total</th>
                        <th className="text-right p-2">Count</th>
                      </tr>
                    </thead>
                    <tbody>
                      {reportData.categories.map((cat: any, idx: number) => (
                        <tr key={idx} className="border-b hover:bg-gray-50">
                          <td className="p-2 font-medium">{cat.category_name}</td>
                          <td className="text-right p-2">{formatCurrency(cat.amount_vat_exclusive)}</td>
