            type="button"
            variant="outline"
            onClick={() => router.back()}
          >
            Cancel
          </Button>
        </div>
      </form>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { creditorsApi } from '@/lib/creditorsApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Loader, Plus, Edit, Printer } from 'lucide-react';
import Link from 'next/link';

export default function ExpenseInvoicesPage() {
  const [page, setPage] = useState(1);

  const { data: invoices, isLoading } = useQuery({
    queryKey: ['expense-invoices', page],
    queryFn: () =>
      creditorsApi.transactions.list({
        transaction_type: 'INVOICE_EXPENSE',
        page,
        page_size: 25,
        ordering: '-transaction_date',
      }),
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Expense Invoices</h1>
          <p className="text-gray-600 mt-1">Record expense invoices from suppliers</p>
        </div>
        <Link href="/dashboard/admin/creditors/transactions/invoices/expense/new">
          <Button className="bg-blue-600 hover:bg-blue-700 flex items-center gap-2">
            <Plus className="w-4 h-4" />
            New Invoice
          </Button>
        </Link>
      </div>

      {/* Invoices Table */}
      <Card className="p-6">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="border-b bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left font-semibold">Reference</th>
                <th className="px-4 py-3 text-left font-semibold">Supplier</th>
                <th className="px-4 py-3 text-left font-semibold">Invoice #</th>
                <th className="px-4 py-3 text-left font-semibold">Date</th>
                <th className="px-4 py-3 text-left font-semibold">Category</th>
                <th className="px-4 py-3 text-right font-semibold">Amount</th>
                <th className="px-4 py-3 text-left font-semibold">Due Date</th>
                <th className="px-4 py-3 text-center font-semibold">Actions</th>
              </tr>
            </thead>
            <tbody>
              {invoices?.results?.map((invoice: any) => (
                <tr key={invoice.id} className="border-b hover:bg-gray-50">
                  <td className="px-4 py-3 font-medium">{invoice.reference_number}</td>
                  <td className="px-4 py-3">{invoice.supplier_name}</td>
                  <td className="px-4 py-3 text-gray-600">{invoice.invoice_number}</td>
                  <td className="px-4 py-3 text-sm">
                    {new Date(invoice.transaction_date).toLocaleDateString('en-ZA')}
                  </td>
                  <td className="px-4 py-3 text-xs text-gray-600">{invoice.category_name}</td>
                  <td className="px-4 py-3 text-right font-bold">
                    R {invoice.amount?.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                  </td>
                  <td className="px-4 py-3 text-sm">
                    {invoice.due_date ? new Date(invoice.due_date).toLocaleDateString('en-ZA') : 'N/A'}
                  </td>
                  <td className="px-4 py-3 text-center">
                    <div className="flex items-center justify-center gap-2">
                      <Link href={`/dashboard/admin/creditors/transactions/invoices/expense/${invoice.id}`}>
                        <Button size="sm" variant="outline" className="w-8 h-8 p-0">
                          <Edit className="w-4 h-4" />
                        </Button>
                      </Link>
                      <Button
                        size="sm"
                        variant="outline"
                        className="w-8 h-8 p-0"
                        onClick={() => window.print()}
                      >
                        <Printer className="w-4 h-4" />
                      </Button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="flex items-center justify-between mt-4 pt-4 border-t">
          <p className="text-sm text-gray-600">
            Showing {invoices?.results?.length || 0} of {invoices?.count || 0} invoices
          </p>
          <div className="flex gap-2">
            <Button
              variant="outline"
              disabled={!invoices?.previous}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              Previous
            </Button>
            <Button
              variant="outline"
              disabled={!invoices?.next}
              onClick={() => setPage((p) => p + 1)}
            >
              Next
            </Button>
          </div>
        </div>
      </Card>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter, useParams } from 'next/navigation';
import { useQuery, useMutation } from '@tanstack/react-query';
import { creditorsApi } from '@/lib/creditorsApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Loader } from 'lucide-react';

export default function JournalEntryForm() {
  const router = useRouter();
  const params = useParams();
  const entryId = params.id as string;
  const isNew = entryId === 'new';

  const [formData, setFormData] = useState({
    supplier_id: 0,
    entry_date: new Date().toISOString().split('T')[0],
    entry_type: 'DEBIT',
    description: '',
    amount: 0,
    reference: '',
  });

  const { data: suppliers } = useQuery({
    queryKey: ['creditors-accounts'],
    queryFn: () => creditorsApi.accounts.list({ page_size: 500 }),
  });

  const { data: _entry, isLoading } = useQuery({
    queryKey: ['journal-entry', entryId],
    queryFn: () => creditorsApi.journals.get(entryId),
    enabled: !isNew,
  });

  const mutation = useMutation({
    mutationFn: (data: any) =>
      isNew
        ? creditorsApi.journals.create(data)
        : creditorsApi.journals.update(entryId, data),
    onSuccess: () => {
      router.push('/dashboard/admin/creditors/transactions/journals');
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    mutation.mutate(formData);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold">{isNew ? 'New Journal Entry' : 'Edit Journal Entry'}</h1>
        <p className="text-gray-600 mt-1">Record an adjustment or correction to a creditor account</p>
      </div>

      <form onSubmit={handleSubmit}>
        {/* Entry Details */}
        <Card className="p-6 mb-6">
          <h2 className="text-lg font-bold mb-4">Entry Details</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-1">Creditor Account</label>
              <select
                value={formData.supplier_id}
                onChange={(e) => setFormData({ ...formData, supplier_id: parseInt(e.target.value) })}
                className="w-full border border-gray-300 rounded px-3 py-2"
                required
              >
                <option value={0}>Select Account...</option>
                {suppliers?.results?.map((supplier: any) => (
                  <option key={supplier.id} value={supplier.id}>
                    {supplier.account_number} - {supplier.name}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Entry Date</label>
              <Input
                type="date"
                value={formData.entry_date}
                onChange={(e) => setFormData({ ...formData, entry_date: e.target.value })}
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Entry Type</label>
              <select
                value={formData.entry_type}
                onChange={(e) => setFormData({ ...formData, entry_type: e.target.value })}
                className="w-full border border-gray-300 rounded px-3 py-2"
                required
              >
                <option value="DEBIT">Debit (Increase Payable)</option>
                <option value="CREDIT">Credit (Reduce Payable)</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Reference</label>
              <Input
                type="text"
                value={formData.reference}
                onChange={(e) => setFormData({ ...formData, reference: e.target.value })}
                placeholder="e.g., Correction, Adjustment"
              />
            </div>
          </div>
        </Card>

        {/* Amount & Description */}
        <Card className="p-6 mb-6">
          <h2 className="text-lg font-bold mb-4">Amount & Description</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-1">Amount (R)</label>
              <Input
                type="number"
                step="0.01"
                value={formData.amount}
                onChange={(e) => setFormData({ ...formData, amount: parseFloat(e.target.value) })}
                placeholder="0.00"
                required
              />
            </div>
          </div>
          <div className="grid grid-cols-1 gap-4 mt-4">
            <div>
              <label className="block text-sm font-medium mb-1">Description</label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                className="w-full border border-gray-300 rounded px-3 py-2"
                rows={3}
                placeholder="Reason for the journal entry"
                required
              />
            </div>
          </div>
        </Card>

        {/* Summary */}
        {formData.amount > 0 && (
          <Card className="p-6 mb-6 bg-gray-50">
            <h3 className="font-bold mb-3">Entry Summary</h3>
            <div className="flex justify-between items-center">
              <div>
                <p className="text-sm text-gray-600 mb-1">Entry Type: <strong>{formData.entry_type}</strong></p>
                <p className="text-sm text-gray-600">Amount: <strong>R {formData.amount.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}</strong></p>
              </div>
              <div className={`px-4 py-2 rounded ${
                formData.entry_type === 'DEBIT' 
                  ? 'bg-red-100 text-red-800' 
                  : 'bg-green-100 text-green-800'
              }`}>
                <p className="text-sm font-bold">{formData.entry_type === 'DEBIT' ? 'PAYABLE ↑' : 'PAYABLE ↓'}</p>
              </div>
            </div>
          </Card>
        )}

        {/* Actions */}
        <div className="flex gap-2">
          <Button
            type="submit"
            className="bg-blue-600 hover:bg-blue-700"
            disabled={mutation.isPending}
          >
            {mutation.isPending ? 'Saving...' : 'Save Entry'}
          </Button>
          <Button
            type="button"
            variant="outline"
            onClick={() => router.back()}
          >
            Cancel
          </Button>
        </div>
      </form>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter, useParams } from 'next/navigation';
import { useQuery, useMutation } from '@tanstack/react-query';
import { creditorsApi } from '@/lib/creditorsApi';
import settingsApi from '@/lib/settingsApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Loader } from 'lucide-react';

export default function ExpenseReturnForm() {
  const router = useRouter();
  const params = useParams();
  const returnId = params.id as string;
  const isNew = returnId === 'new';

  const [formData, setFormData] = useState({
    supplier_id: 0,
    credit_note_date: new Date().toISOString().split('T')[0],
    credit_note_number: '',
    category_id: 0,
    description: '',
    amount: 0,
    vat_rate: 14,
    vat_option: 'I',
  });

  const { data: suppliers } = useQuery({
    queryKey: ['creditors-accounts'],
    queryFn: () => creditorsApi.accounts.list({ page_size: 500 }),
  });

  const { data: categories } = useQuery({
    queryKey: ['expense-categories'],
    queryFn: () => settingsApi.expenseCategories.list({ page_size: 100 }),
  });

  const { data: _creditNoteData, isLoading } = useQuery({
    queryKey: ['expense-return', returnId],
    queryFn: () => creditorsApi.creditNotes.get(returnId),
    enabled: !isNew,
  });

  const mutation = useMutation({
    mutationFn: (data: any) =>
      isNew
        ? creditorsApi.creditNotes.create({ ...data, transaction_type: 'RETURN_EXPENSE' })
        : creditorsApi.creditNotes.update(returnId, data),
    onSuccess: () => {
      router.push('/dashboard/admin/creditors/transactions/returns/expense');
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    mutation.mutate(formData);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  const taxableAmount = formData.vat_option === 'I' 
    ? formData.amount / (1 + formData.vat_rate / 100)
    : formData.amount;
  const taxAmount = taxableAmount * (formData.vat_rate / 100);
  const finalAmount = formData.vat_option === 'I' ? formData.amount : taxableAmount + taxAmount;

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold">{isNew ? 'New Expense Credit Note' : 'Edit Expense Credit Note'}</h1>
        <p className="text-gray-600 mt-1">Record an expense credit note from a supplier</p>
      </div>

      <form onSubmit={handleSubmit}>
        {/* Credit Note Details */}
        <Card className="p-6 mb-6">
          <h2 className="text-lg font-bold mb-4">Credit Note Details</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-1">Supplier</label>
              <select
                value={formData.supplier_id}
                onChange={(e) => setFormData({ ...formData, supplier_id: parseInt(e.target.value) })}
                className="w-full border border-gray-300 rounded px-3 py-2"
                required
              >
                <option value={0}>Select Supplier...</option>
                {suppliers?.results?.map((supplier: any) => (
                  <option key={supplier.id} value={supplier.id}>
                    {supplier.account_number} - {supplier.name}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Credit Note #</label>
              <Input
                type="text"
                value={formData.credit_note_number}
                onChange={(e) => setFormData({ ...formData, credit_note_number: e.target.value })}
                placeholder="e.g., CN001"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Credit Note Date</label>
              <Input
                type="date"
                value={formData.credit_note_date}
                onChange={(e) => setFormData({ ...formData, credit_note_date: e.target.value })}
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Expense Category</label>
              <select
                value={formData.category_id}
                onChange={(e) => setFormData({ ...formData, category_id: parseInt(e.target.value) })}
                className="w-full border border-gray-300 rounded px-3 py-2"
                required
              >
                <option value={0}>Select Category...</option>
                {categories?.results?.map((category: any) => (
                  <option key={category.id} value={category.id}>
                    {category.category_number} - {category.name}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </Card>

        {/* Amount Details */}
        <Card className="p-6 mb-6">
          <h2 className="text-lg font-bold mb-4">Amount Details</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="md:col-span-2">
              <label className="block text-sm font-medium mb-1">Description</label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                className="w-full border border-gray-300 rounded px-3 py-2"
                rows={3}
                placeholder="Reason for credit note"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Amount (R)</label>
              <Input
                type="number"
                step="0.01"
                value={formData.amount}
                onChange={(e) => setFormData({ ...formData, amount: parseFloat(e.target.value) })}
                placeholder="0.00"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">VAT Option</label>
              <select
                value={formData.vat_option}
                onChange={(e) => setFormData({ ...formData, vat_option: e.target.value })}
                className="w-full border border-gray-300 rounded px-3 py-2"
              >
                <option value="I">Inclusive (I)</option>
                <option value="E">Exclusive (E)</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">VAT Rate (%)</label>
              <Input
                type="number"
                step="0.01"
                value={formData.vat_rate}
                onChange={(e) => setFormData({ ...formData, vat_rate: parseFloat(e.target.value) })}
              />
            </div>
          </div>
        </Card>

        {/* Totals */}
        <Card className="p-6 mb-6 bg-gray-50">
          <h3 className="font-bold mb-3">Amount Breakdown</h3>
          <div className="space-y-2 text-sm">
            <div className="flex justify-between">
              <span>Taxable Amount:</span>
              <span className="font-bold">R {taxableAmount.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}</span>
            </div>
            <div className="flex justify-between">
              <span>VAT ({formData.vat_rate}%):</span>
              <span className="font-bold">R {taxAmount.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}</span>
            </div>
            <div className="border-t pt-2 flex justify-between">
              <span className="font-bold">Total Credit Note:</span>
              <span className="font-bold text-lg text-blue-600">
                R {finalAmount.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
              </span>
            </div>
          </div>
        </Card>

        {/* Actions */}
        <div className="flex gap-2">
          <Button
            type="submit"
            className="bg-blue-600 hover:bg-blue-700"
            disabled={mutation.isPending}
          >
            {mutation.isPending ? 'Saving...' : 'Save Credit Note'}
          </Button>
          <Button
            type="button"
            variant="outline"
            onClick={() => router.back()}
          >
            Cancel
          </Button>
        </div>
      </form>
    </div>
  );
}

