'use client';

import { useState } from 'react';
import { useRouter, useParams } from 'next/navigation';
import { useQuery, useMutation } from '@tanstack/react-query';
import { creditorsApi } from '@/lib/creditorsApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Loader, Trash2, Plus } from 'lucide-react';

interface RFCItem {
  id?: number;
  stock_code: string;
  description: string;
  quantity: number;
  unit_value: number;
  return_reason: string;
}

interface RFCData {
  supplier_id: number;
  rfc_date: string;
  items: RFCItem[];
  status: 'pending' | 'approved' | 'credited' | 'replaced';
}

export default function RFCForm() {
  const router = useRouter();
  const params = useParams();
  const rfcId = params.id as string;
  const isNew = rfcId === 'new';
  const isEdit = params.id === 'edit';

  const [formData, setFormData] = useState<RFCData>({
    supplier_id: 0,
    rfc_date: new Date().toISOString().split('T')[0],
    items: [{ stock_code: '', description: '', quantity: 0, unit_value: 0, return_reason: '' }],
    status: 'pending',
  });

  const { data: suppliers } = useQuery({
    queryKey: ['creditors-accounts'],
    queryFn: () => creditorsApi.accounts.list({ page_size: 500 }),
  });

  const { data: _rfc, isLoading } = useQuery({
    queryKey: ['rfc', rfcId],
    queryFn: () => creditorsApi.rfc.get(rfcId),
    enabled: !isNew && rfcId !== 'edit',
  });

  const mutation = useMutation({
    mutationFn: (data: RFCData) => {
      const apiData: any = {
        creditor: data.supplier_id,
        rfc_number: `RFC-${Date.now()}`, // Would need proper RFC number generation
        return_date: data.rfc_date,
        status: data.status,
        line_items: data.items.map((item, _index) => ({
          stock_item: 0,
          quantity_returned: item.quantity,
          line_value: item.quantity * item.unit_value,
          tax_code: 0,
          reason: item.return_reason,
        })),
      };
      return isNew 
        ? creditorsApi.rfc.create(apiData) 
        : creditorsApi.rfc.update(rfcId, apiData);
    },
    onSuccess: () => {
      router.push('/dashboard/admin/creditors/transactions/rfc');
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    mutation.mutate(formData);
  };

  const calculateLineValue = (item: RFCItem) => {
    return item.quantity * item.unit_value;
  };

  const calculateTotalValue = () => {
    return formData.items.reduce((sum, item) => sum + calculateLineValue(item), 0);
  };

  const addLineItem = () => {
    setFormData({
      ...formData,
      items: [...formData.items, { stock_code: '', description: '', quantity: 0, unit_value: 0, return_reason: '' }],
    });
  };

  const removeLineItem = (index: number) => {
    setFormData({
      ...formData,
      items: formData.items.filter((_, i) => i !== index),
    });
  };

  const updateLineItem = (index: number, updates: Partial<RFCItem>) => {
    const newItems = [...formData.items];
    newItems[index] = { ...newItems[index], ...updates };
    setFormData({ ...formData, items: newItems });
  };

  if (isLoading && !isNew && rfcId !== 'edit') {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold">{isNew ? 'New RFC' : 'RFC Details'}</h1>
        <p className="text-gray-600 mt-1">Track returns for credit from suppliers</p>
      </div>

      <form onSubmit={handleSubmit}>
        {/* RFC Header */}
        <Card className="p-6 mb-6">
          <h2 className="text-lg font-bold mb-4">RFC Details</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium mb-1">Supplier</label>
              <select
                value={formData.supplier_id}
                onChange={(e) => setFormData({ ...formData, supplier_id: parseInt(e.target.value) })}
                className="w-full border border-gray-300 rounded px-3 py-2"
                required
                disabled={!isNew && !isEdit}
              >
                <option value={0}>Select Supplier...</option>
                {suppliers?.results?.map((supplier: any) => (
                  <option key={supplier.id} value={supplier.id}>
                    {supplier.account_number} - {supplier.name}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">RFC Date</label>
              <Input
                type="date"
                value={formData.rfc_date}
                onChange={(e) => setFormData({ ...formData, rfc_date: e.target.value })}
                required
                disabled={!isNew && !isEdit}
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Status</label>
              <select
                value={formData.status}
                onChange={(e) => setFormData({ ...formData, status: e.target.value as any })}
                className="w-full border border-gray-300 rounded px-3 py-2"
              >
                <option value="pending">Pending</option>
                <option value="approved">Approved</option>
                <option value="credited">Credited</option>
                <option value="replaced">Stock Replaced</option>
              </select>
            </div>
          </div>
        </Card>

        {/* Items */}
        <Card className="p-6 mb-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-bold">Items for Return</h2>
            {(isNew || isEdit) && (
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={addLineItem}
                className="flex items-center gap-2"
              >
                <Plus className="w-4 h-4" />
                Add Item
              </Button>
            )}
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="border-b bg-gray-50">
                <tr>
                  <th className="px-2 py-2 text-left font-semibold">Stock Code</th>
                  <th className="px-2 py-2 text-left font-semibold">Description</th>
                  <th className="px-2 py-2 text-left font-semibold">Return Reason</th>
                  <th className="px-2 py-2 text-right font-semibold">Qty</th>
                  <th className="px-2 py-2 text-right font-semibold">Unit Value</th>
                  <th className="px-2 py-2 text-right font-semibold">Total</th>
                  {(isNew || isEdit) && <th className="px-2 py-2 text-center font-semibold">Action</th>}
                </tr>
              </thead>
              <tbody>
                {formData.items.map((item, index) => (
                  <tr key={index} className="border-b">
                    <td className="px-2 py-2">
                      {isNew || isEdit ? (
                        <Input
                          type="text"
                          value={item.stock_code}
                          onChange={(e) => updateLineItem(index, { stock_code: e.target.value })}
                          className="text-xs"
                          placeholder="Stock code"
                        />
                      ) : (
                        <span>{item.stock_code}</span>
                      )}
                    </td>
                    <td className="px-2 py-2">
                      {isNew || isEdit ? (
                        <Input
                          type="text"
                          value={item.description}
                          onChange={(e) => updateLineItem(index, { description: e.target.value })}
                          className="text-xs"
                          placeholder="Description"
                        />
                      ) : (
                        <span>{item.description}</span>
                      )}
                    </td>
                    <td className="px-2 py-2">
                      {isNew || isEdit ? (
                        <select
                          value={item.return_reason}
                          onChange={(e) => updateLineItem(index, { return_reason: e.target.value })}
                          className="w-full border border-gray-300 rounded px-2 py-1 text-xs"
                        >
                          <option value="">Select reason...</option>
                          <option value="DEFECTIVE">Defective</option>
                          <option value="OVERSTOCK">Overstock</option>
                          <option value="WRONG_ITEM">Wrong Item</option>
                          <option value="NO_LONGER_NEEDED">Not Needed</option>
                          <option value="EXPIRED">Expired</option>
                        </select>
                      ) : (
                        <span>{item.return_reason}</span>
                      )}
                    </td>
                    <td className="px-2 py-2">
                      {isNew || isEdit ? (
                        <Input
                          type="number"
                          step="0.01"
                          value={item.quantity}
                          onChange={(e) => updateLineItem(index, { quantity: parseFloat(e.target.value) })}
                          className="text-xs text-right"
                        />
                      ) : (
                        <span className="text-right inline-block w-full">{item.quantity}</span>
                      )}
                    </td>
                    <td className="px-2 py-2">
                      {isNew || isEdit ? (
                        <Input
                          type="number"
                          step="0.01"
                          value={item.unit_value}
                          onChange={(e) => updateLineItem(index, { unit_value: parseFloat(e.target.value) })}
                          className="text-xs text-right"
                        />
                      ) : (
                        <span className="text-right inline-block w-full">R {item.unit_value.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}</span>
                      )}
                    </td>
                    <td className="px-2 py-2 text-right font-bold">
                      R {calculateLineValue(item).toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                    </td>
                    {(isNew || isEdit) && (
                      <td className="px-2 py-2 text-center">
                        <Button
                          type="button"
                          variant="destructive"
                          size="sm"
                          className="w-8 h-8 p-0"
                          onClick={() => removeLineItem(index)}
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </td>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>

        {/* Total */}
        <Card className="p-6 mb-6">
          <div className="flex justify-end">
            <div className="w-full md:w-72">
              <div className="flex justify-between">
                <span className="font-bold">Total RFC Value:</span>
                <span className="font-bold text-lg text-blue-600">
                  R {calculateTotalValue().toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                </span>
              </div>
            </div>
          </div>
        </Card>

        {/* Actions */}
        {(isNew || isEdit) && (
          <div className="flex gap-2">
            <Button
              type="submit"
              className="bg-blue-600 hover:bg-blue-700"
              disabled={mutation.isPending}
            >
              {mutation.isPending ? 'Saving...' : 'Save RFC'}
            </Button>
            <Button
              type="button"
              variant="outline"
              onClick={() => router.back()}
            >
              Cancel
            </Button>
          </div>
        )}
      </form>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { creditorsApi } from '@/lib/creditorsApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Loader, Plus, Edit, Eye } from 'lucide-react';
import Link from 'next/link';

export default function RFCPage() {
  const [page, setPage] = useState(1);
  const [filterStatus, setFilterStatus] = useState('all');

  const { data: rfcs, isLoading } = useQuery({
    queryKey: ['rfc-transactions', page, filterStatus],
    queryFn: () =>
      creditorsApi.rfc.list({
        page,
        status: filterStatus !== 'all' ? filterStatus as any : undefined,
      }),
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Returns for Credit (RFC)</h1>
          <p className="text-gray-600 mt-1">Manage supplier returns and credit tracking</p>
        </div>
        <Link href="/dashboard/admin/creditors/transactions/rfc/new">
          <Button className="bg-blue-600 hover:bg-blue-700 flex items-center gap-2">
            <Plus className="w-4 h-4" />
            New RFC
          </Button>
        </Link>
      </div>

      {/* Filter */}
      <Card className="p-4">
        <div className="flex gap-2">
          {['all', 'pending', 'approved', 'credited', 'replaced'].map((status) => (
            <Button
              key={status}
              variant={filterStatus === status ? 'default' : 'outline'}
              className="capitalize"
              onClick={() => {
                setFilterStatus(status);
                setPage(1);
              }}
            >
              {status === 'all' ? 'All RFC' : status}
            </Button>
          ))}
        </div>
      </Card>

      {/* RFC List */}
      <Card className="p-6">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="border-b bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left font-semibold">RFC #</th>
                <th className="px-4 py-3 text-left font-semibold">Supplier</th>
                <th className="px-4 py-3 text-left font-semibold">Date</th>
                <th className="px-4 py-3 text-left font-semibold">Items</th>
                <th className="px-4 py-3 text-right font-semibold">Value</th>
                <th className="px-4 py-3 text-left font-semibold">Status</th>
                <th className="px-4 py-3 text-center font-semibold">Actions</th>
              </tr>
            </thead>
            <tbody>
              {rfcs?.results?.map((rfc: any) => (
                <tr key={rfc.id} className="border-b hover:bg-gray-50">
                  <td className="px-4 py-3 font-medium">{rfc.reference_number}</td>
                  <td className="px-4 py-3">{rfc.supplier_name}</td>
                  <td className="px-4 py-3 text-sm">
                    {new Date(rfc.transaction_date).toLocaleDateString('en-ZA')}
                  </td>
                  <td className="px-4 py-3 text-xs text-gray-600">
                    {rfc.item_count || 0} item(s)
                  </td>
                  <td className="px-4 py-3 text-right font-bold">
                    R {rfc.amount?.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                  </td>
                  <td className="px-4 py-3">
                    <span className={`px-2 py-1 text-xs rounded font-medium capitalize ${
                      rfc.status === 'credited' ? 'bg-green-100 text-green-800' :
                      rfc.status === 'replaced' ? 'bg-blue-100 text-blue-800' :
                      rfc.status === 'approved' ? 'bg-amber-100 text-amber-800' :
                      'bg-gray-100 text-gray-800'
                    }`}>
                      {rfc.status || 'Pending'}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-center">
                    <div className="flex items-center justify-center gap-2">
                      <Link href={`/dashboard/admin/creditors/transactions/rfc/${rfc.id}`}>
                        <Button size="sm" variant="outline" className="w-8 h-8 p-0">
                          <Eye className="w-4 h-4" />
                        </Button>
                      </Link>
                      {rfc.status !== 'credited' && rfc.status !== 'replaced' && (
                        <Link href={`/dashboard/admin/creditors/transactions/rfc/${rfc.id}/edit`}>
                          <Button size="sm" variant="outline" className="w-8 h-8 p-0">
                            <Edit className="w-4 h-4" />
                          </Button>
                        </Link>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="flex items-center justify-between mt-4 pt-4 border-t">
          <p className="text-sm text-gray-600">
            Showing {rfcs?.results?.length || 0} of {rfcs?.count || 0} RFC items
          </p>
          <div className="flex gap-2">
            <Button
              variant="outline"
              disabled={!rfcs?.previous}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              Previous
            </Button>
            <Button
              variant="outline"
              disabled={!rfcs?.next}
              onClick={() => setPage((p) => p + 1)}
            >
              Next
            </Button>
          </div>
        </div>
      </Card>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter, useParams } from 'next/navigation';
import { useQuery, useMutation } from '@tanstack/react-query';
import { creditorsApi } from '@/lib/creditorsApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Loader, Trash2, Plus } from 'lucide-react';

interface GRNLineItem {
  id?: number;
  stock_code: string;
  description: string;
  quantity: number;
  unit_cost: number;
  tax_rate: number;
}

interface GRNData {
  supplier_id: number;
  invoice_number: string;
  invoice_date: string;
  vat_option: 'I' | 'E';
  line_items: GRNLineItem[];
  surcharge: number;
}

export default function StockReceiptForm() {
  const router = useRouter();
  const params = useParams();
  const grnId = params.id as string;
  const isNew = grnId === 'new';

  const [formData, setFormData] = useState<GRNData>({
    supplier_id: 0,
    invoice_number: '',
    invoice_date: new Date().toISOString().split('T')[0],
    vat_option: 'I',
    line_items: [{ stock_code: '', description: '', quantity: 0, unit_cost: 0, tax_rate: 14 }],
    surcharge: 0,
  });

  const { data: suppliers } = useQuery({
    queryKey: ['creditors-accounts'],
    queryFn: () => creditorsApi.accounts.list({ page_size: 500 }),
  });

  const { data: _grn, isLoading } = useQuery({
    queryKey: ['grn', grnId],
    queryFn: () => creditorsApi.grns.get(grnId),
    enabled: !isNew,
  });

  const mutation = useMutation({
    mutationFn: (data: GRNData) => {
      const apiData: any = {
        creditor: data.supplier_id,
        transaction_date: data.invoice_date,
        supplier_invoice_number: data.invoice_number,
        inclusive_exclusive: data.vat_option === 'I' ? 'INC' as const : 'EXC' as const,
        surcharge_amount: data.surcharge,
        line_items: data.line_items.map((item) => ({
          stock_item: 0,
          quantity_received: item.quantity,
          unit_cost: item.unit_cost,
          tax_code: item.tax_rate,
        })),
      };
      return isNew 
        ? creditorsApi.grns.create(apiData) 
        : creditorsApi.grns.update(grnId, apiData);
    },
    onSuccess: () => {
      router.push('/dashboard/admin/creditors/transactions/stock-receipts');
    },
  });

  const calculateLineTotal = (item: GRNLineItem) => {
    const subtotal = item.quantity * item.unit_cost;
    if (formData.vat_option === 'I') {
      return subtotal;
    } else {
      return subtotal * (1 + item.tax_rate / 100);
    }
  };

  const calculateGrandTotal = () => {
    const itemsTotal = formData.line_items.reduce((sum, item) => sum + calculateLineTotal(item), 0);
    return itemsTotal + formData.surcharge;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    mutation.mutate(formData);
  };

  const addLineItem = () => {
    setFormData({
      ...formData,
      line_items: [...formData.line_items, { stock_code: '', description: '', quantity: 0, unit_cost: 0, tax_rate: 14 }],
    });
  };

  const removeLineItem = (index: number) => {
    setFormData({
      ...formData,
      line_items: formData.line_items.filter((_, i) => i !== index),
    });
  };

  const updateLineItem = (index: number, updates: Partial<GRNLineItem>) => {
    const newItems = [...formData.line_items];
    newItems[index] = { ...newItems[index], ...updates };
    setFormData({ ...formData, line_items: newItems });
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold">{isNew ? 'New Stock Receipt' : 'Edit Stock Receipt'}</h1>
        <p className="text-gray-600 mt-1">Record goods received from a supplier</p>
      </div>

      <form onSubmit={handleSubmit}>
        {/* Header Section */}
        <Card className="p-6 mb-6">
          <h2 className="text-lg font-bold mb-4">Receipt Details</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium mb-1">Supplier</label>
              <select
                value={formData.supplier_id}
                onChange={(e) => setFormData({ ...formData, supplier_id: parseInt(e.target.value) })}
                className="w-full border border-gray-300 rounded px-3 py-2"
                required
              >
                <option value={0}>Select Supplier...</option>
                {suppliers?.results?.map((supplier: any) => (
                  <option key={supplier.id} value={supplier.id}>
                    {supplier.account_number} - {supplier.name}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Invoice Number</label>
              <Input
                type="text"
                value={formData.invoice_number}
                onChange={(e) => setFormData({ ...formData, invoice_number: e.target.value })}
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Invoice Date</label>
              <Input
                type="date"
                value={formData.invoice_date}
                onChange={(e) => setFormData({ ...formData, invoice_date: e.target.value })}
                required
              />
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
            <div>
              <label className="block text-sm font-medium mb-1">VAT Option</label>
              <select
                value={formData.vat_option}
                onChange={(e) => setFormData({ ...formData, vat_option: e.target.value as 'I' | 'E' })}
                className="w-full border border-gray-300 rounded px-3 py-2"
              >
                <option value="I">Inclusive (I)</option>
                <option value="E">Exclusive (E)</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Surcharge (R)</label>
              <Input
                type="number"
                step="0.01"
                value={formData.surcharge}
                onChange={(e) => setFormData({ ...formData, surcharge: parseFloat(e.target.value) })}
              />
            </div>
          </div>
        </Card>

        {/* Line Items Section */}
        <Card className="p-6 mb-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-bold">Line Items</h2>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={addLineItem}
              className="flex items-center gap-2"
            >
              <Plus className="w-4 h-4" />
              Add Line
            </Button>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="border-b bg-gray-50">
                <tr>
                  <th className="px-2 py-2 text-left font-semibold">Stock Code</th>
                  <th className="px-2 py-2 text-left font-semibold">Description</th>
                  <th className="px-2 py-2 text-right font-semibold">Qty</th>
                  <th className="px-2 py-2 text-right font-semibold">Unit Cost</th>
                  <th className="px-2 py-2 text-right font-semibold">Tax %</th>
                  <th className="px-2 py-2 text-right font-semibold">Total</th>
                  <th className="px-2 py-2 text-center font-semibold">Action</th>
                </tr>
              </thead>
              <tbody>
                {formData.line_items.map((item, index) => (
                  <tr key={index} className="border-b">
                    <td className="px-2 py-2">
                      <Input
                        type="text"
                        value={item.stock_code}
                        onChange={(e) => updateLineItem(index, { stock_code: e.target.value })}
                        className="text-xs"
                        placeholder="e.g., SKU123"
                      />
                    </td>
                    <td className="px-2 py-2">
                      <Input
                        type="text"
                        value={item.description}
                        onChange={(e) => updateLineItem(index, { description: e.target.value })}
                        className="text-xs"
                        placeholder="Item description"
                      />
                    </td>
                    <td className="px-2 py-2">
                      <Input
                        type="number"
                        step="0.01"
                        value={item.quantity}
                        onChange={(e) => updateLineItem(index, { quantity: parseFloat(e.target.value) })}
                        className="text-xs text-right"
                      />
                    </td>
                    <td className="px-2 py-2">
                      <Input
                        type="number"
                        step="0.01"
                        value={item.unit_cost}
                        onChange={(e) => updateLineItem(index, { unit_cost: parseFloat(e.target.value) })}
                        className="text-xs text-right"
                      />
                    </td>
                    <td className="px-2 py-2">
                      <Input
                        type="number"
                        step="0.01"
                        value={item.tax_rate}
                        onChange={(e) => updateLineItem(index, { tax_rate: parseFloat(e.target.value) })}
                        className="text-xs text-right"
                      />
                    </td>
                    <td className="px-2 py-2 text-right font-bold text-xs">
                      R {calculateLineTotal(item).toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                    </td>
                    <td className="px-2 py-2 text-center">
                      <Button
                        type="button"
                        variant="destructive"
                        size="sm"
                        className="w-8 h-8 p-0"
                        onClick={() => removeLineItem(index)}
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>

        {/* Totals */}
        <Card className="p-6 mb-6">
          <div className="flex justify-end">
            <div className="w-full md:w-72">
              <div className="flex justify-between mb-2">
                <span>Subtotal:</span>
                <span className="font-bold">
                  R {formData.line_items.reduce((sum, item) => sum + item.quantity * item.unit_cost, 0).toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                </span>
              </div>
              <div className="flex justify-between mb-2">
                <span>Surcharge:</span>
                <span className="font-bold">
                  R {formData.surcharge.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                </span>
              </div>
              <div className="border-t-2 pt-2 flex justify-between">
                <span className="font-bold">Total:</span>
                <span className="font-bold text-lg text-blue-600">
                  R {calculateGrandTotal().toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                </span>
              </div>
            </div>
          </div>
        </Card>

        {/* Actions */}
        <div className="flex gap-2">
          <Button
            type="submit"
            className="bg-blue-600 hover:bg-blue-700"
            disabled={mutation.isPending}
          >
            {mutation.isPending ? 'Saving...' : 'Save Receipt'}
          </Button>
          <Button
            type="button"
            variant="outline"
            onClick={() => router.back()}
          >
            Cancel
          </Button>
        </div>
      </form>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { creditorsApi } from '@/lib/creditorsApi';
import type { CreditorAccount } from '@/lib/types/creditors';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Loader, Plus, Edit, Printer } from 'lucide-react';
import Link from 'next/link';

export default function StockReceiptsPage() {
  const _queryClient = useQueryClient();
  const [_selectedSupplier, setSelectedSupplier] = useState<CreditorAccount | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(1);

  const { data: suppliers } = useQuery({
    queryKey: ['creditors-suppliers', searchTerm],
    queryFn: () =>
      creditorsApi.accounts.list({
        search: searchTerm || undefined,
        page_size: 50,
      }),
  });

  const { data: grns, isLoading } = useQuery({
    queryKey: ['stock-receipts-grn', page],
    queryFn: () =>
      creditorsApi.transactions.list({
        transaction_type: 'GRN',
        page,
        page_size: 25,
        ordering: '-transaction_date',
      }),
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Stock Receipts (GRN)</h1>
          <p className="text-gray-600 mt-1">Record goods received from suppliers</p>
        </div>
        <Link href="/dashboard/admin/creditors/transactions/stock-receipts/new">
          <Button className="bg-blue-600 hover:bg-blue-700 flex items-center gap-2">
            <Plus className="w-4 h-4" />
            New Receipt
          </Button>
        </Link>
      </div>

      {/* Supplier Selection */}
      <Card className="p-6">
        <h2 className="text-lg font-bold mb-4">Filter by Supplier</h2>
        <Input
          type="text"
          placeholder="Search supplier by account number or name..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
        {searchTerm && suppliers?.results && (
          <div className="mt-3 max-h-48 overflow-y-auto border rounded">
            {suppliers.results.map((supplier: CreditorAccount) => (
              <div
                key={supplier.id}
                className="p-2 hover:bg-gray-100 cursor-pointer border-b last:border-b-0"
                onClick={() => {
                  setSelectedSupplier(supplier);
                  setSearchTerm('');
                }}
              >
                <p className="font-medium">{supplier.account_number} - {supplier.name}</p>
              </div>
            ))}
          </div>
        )}
      </Card>

      {/* GRN List */}
      <Card className="p-6">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="border-b bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left font-semibold">GRN #</th>
                <th className="px-4 py-3 text-left font-semibold">Supplier</th>
                <th className="px-4 py-3 text-left font-semibold">Invoice</th>
                <th className="px-4 py-3 text-left font-semibold">Date</th>
                <th className="px-4 py-3 text-right font-semibold">Amount</th>
                <th className="px-4 py-3 text-left font-semibold">Status</th>
                <th className="px-4 py-3 text-center font-semibold">Actions</th>
              </tr>
            </thead>
            <tbody>
              {grns?.results?.map((grn: any) => (
                <tr key={grn.id} className="border-b hover:bg-gray-50">
                  <td className="px-4 py-3 font-medium">{grn.reference_number}</td>
                  <td className="px-4 py-3">{grn.supplier_name}</td>
                  <td className="px-4 py-3 text-gray-600">{grn.invoice_number}</td>
                  <td className="px-4 py-3 text-sm">
                    {new Date(grn.transaction_date).toLocaleDateString('en-ZA')}
                  </td>
                  <td className="px-4 py-3 text-right font-bold">
                    R {grn.total_amount?.toLocaleString('en-ZA', { maximumFractionDigits: 2 })}
                  </td>
                  <td className="px-4 py-3">
                    <span className="px-2 py-1 bg-blue-100 text-blue-800 text-xs rounded font-medium">
                      {grn.status || 'Posted'}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-center">
                    <div className="flex items-center justify-center gap-2">
                      <Link href={`/dashboard/admin/creditors/transactions/stock-receipts/${grn.id}`}>
                        <Button size="sm" variant="outline" className="w-8 h-8 p-0">
                          <Edit className="w-4 h-4" />
                        </Button>
                      </Link>
                      <Button
                        size="sm"
                        variant="outline"
                        className="w-8 h-8 p-0"
                        onClick={() => window.print()}
                      >
                        <Printer className="w-4 h-4" />
                      </Button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="flex items-center justify-between mt-4 pt-4 border-t">
          <p className="text-sm text-gray-600">
            Showing {grns?.results?.length || 0} of {grns?.count || 0} receipts
          </p>
          <div className="flex gap-2">
            <Button
              variant="outline"
              disabled={!grns?.previous}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              Previous
            </Button>
            <Button
              variant="outline"
              disabled={!grns?.next}
              onClick={() => setPage((p) => p + 1)}
            >
              Next
            </Button>
          </div>
        </div>
      </Card>
    </div>
  );
}

