'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { apiRequest } from '@/lib/api';
import { Button } from '@/components/ui/button';
import { ArrowLeft } from 'lucide-react';

interface DebtorInfo {
  id: number;
  account_number: string;
  name: string;
  account_category: string;
  contact_person: string;
  telephone1: string;
  email: string;
  credit_limit: number;
  current_balance: number;
  is_active: boolean;
  is_blocked: boolean;
}

export default function DebtorBalancePage({ params }: { params: Promise<{ id: string }> }) {
  const router = useRouter();
  const [debtorId, setDebtorId] = useState<string | null>(null);
  const [debtor, setDebtor] = useState<DebtorInfo | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    params.then((p) => {
      setDebtorId(p.id);
    });
  }, [params]);

  useEffect(() => {
    if (debtorId) {
      fetchDebtor();
    }
  }, [debtorId]);

  const fetchDebtor = async () => {
    try {
      setLoading(true);
      const response = await apiRequest(`/api/v1/debtors/${debtorId}/`);
      setDebtor(response.data || response);
    } catch (err: unknown) {
      console.error('Failed to load debtor:', err);
      setError('Failed to load debtor information');
    } finally {
      setLoading(false);
    }
  };

  const getAccountCategoryLabel = (category: string) => {
    const labels: { [key: string]: string } = {
      '': 'Balance Brought Forward',
      'O': 'Open Item',
      'C': 'Cash Customer',
    };
    return labels[category] || category;
  };

  if (loading) {
    return (
      <div className="p-6">
        <div className="text-center py-8">Loading debtor information...</div>
      </div>
    );
  }

  if (error || !debtor) {
    return (
      <div className="p-6">
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded">
          {error || 'Debtor not found'}
        </div>
        <div className="mt-4">
          <Link
            href="/dashboard/admin/debtors/maintenance"
            className="text-blue-600 hover:text-blue-800"
          >
            ← Back to Debtors
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="outline" onClick={() => router.back()} size="sm">
            <ArrowLeft className="w-4 h-4" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">{debtor.name}</h1>
            <p className="text-gray-600 mt-1">Account #{debtor.account_number}</p>
          </div>
        </div>
      </div>

      {/* Debtor Info Card */}
      <div className="bg-white rounded-lg shadow overflow-hidden">
        <div className="bg-gray-50 px-6 py-4 border-b">
          <h2 className="text-lg font-semibold text-gray-900">Debtor Information</h2>
        </div>
        <div className="p-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <p className="text-sm text-gray-600">Contact Person</p>
              <p className="text-gray-900 font-medium">{debtor.contact_person || 'N/A'}</p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Telephone</p>
              <p className="text-gray-900 font-medium">{debtor.telephone1 || 'N/A'}</p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Email</p>
              <p className="text-gray-900 font-medium">{debtor.email || 'N/A'}</p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Account Category</p>
              <p className="text-gray-900 font-medium">
                {getAccountCategoryLabel(debtor.account_category)}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Credit Limit</p>
              <p className="text-gray-900 font-medium">
                R {parseFloat(String(debtor.credit_limit)).toFixed(2)}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Current Balance</p>
              <p className={`text-lg font-bold ${debtor.current_balance >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                R {parseFloat(String(debtor.current_balance)).toFixed(2)}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Status</p>
              <p className="text-gray-900 font-medium">
                {debtor.is_blocked ? (
                  <span className="px-2 py-1 bg-red-100 text-red-800 text-xs rounded">
                    Blocked
                  </span>
                ) : debtor.is_active ? (
                  <span className="px-2 py-1 bg-green-100 text-green-800 text-xs rounded">
                    Active
                  </span>
                ) : (
                  <span className="px-2 py-1 bg-gray-100 text-gray-800 text-xs rounded">
                    Inactive
                  </span>
                )}
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { useQuery } from '@tanstack/react-query';
import debtorsApi from '@/lib/debtorsApi';
import { Card } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Plus, Search, AlertCircle, Edit2, Trash2, Eye } from 'lucide-react';
import type { DebtorAccount } from '@/lib/types/debtors';

export default function AccountsPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<'all' | 'active' | 'blocked'>('all');
  const [page, setPage] = useState(1);

  const { data: response, isLoading, error } = useQuery({
    queryKey: ['debtors-accounts', searchTerm, filterType, page],
    queryFn: () => {
      // Map frontend filter names to backend expected names
      // Active: is_active=True, block_flag NOT in blocked states ['1','2','3','Y']
      // Blocked: block_flag IN blocked states ['1','2','3','Y']
      const apiFilters: any = {
        search: searchTerm || undefined,
        page,
        page_size: 20,
      };
      
      // Add filters based on filter type
      if (filterType === 'active') {
        apiFilters.is_active = true;
        apiFilters.blockflag__in = ['0', 'N'];
      } else if (filterType === 'blocked') {
        apiFilters.blockflag__in = ['1', '2', '3', 'Y'];
      }
      // For 'all' - no filters
      
      return debtorsApi.accounts.list(apiFilters);
    },
    staleTime: 2 * 60 * 1000,
  });

  const accounts = response?.results || [];
  const total = response?.count || 0;
  const totalPages = Math.ceil(total / 20);

  const handleDelete = async (id: number, name: string) => {
    if (window.confirm(`Delete ${name}?`)) {
      try {
        await debtorsApi.accounts.delete(id);
        // Refetch would happen via react-query invalidation
      } catch (err) {
        console.error('Delete failed:', err);
      }
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-start">
        <div>
          <h1 className="text-3xl font-bold">Debtor Accounts</h1>
          <p className="text-gray-600 mt-1">Manage customer accounts and credit settings</p>
        </div>
        <Link href="/dashboard/admin/debtors/maintenance/accounts/new">
          <Button className="bg-blue-600 hover:bg-blue-700">
            <Plus className="w-4 h-4 mr-2" />
            New Account
          </Button>
        </Link>
      </div>

      {/* Search & Filters */}
      <Card className="p-4">
        <div className="space-y-4">
          <div className="flex gap-2">
            <div className="flex-1 relative">
              <Search className="w-4 h-4 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
              <Input
                placeholder="Search by name, number, or email..."
                value={searchTerm}
                onChange={(e) => {
                  setSearchTerm(e.target.value);
                  setPage(1);
                }}
                className="flex-1 pl-10"
              />
            </div>
          </div>

          <div className="flex gap-2">
            <Button
              variant={filterType === 'all' ? 'default' : 'outline'}
              onClick={() => {
                setFilterType('all');
                setPage(1);
              }}
            >
              All
            </Button>
            <Button
              variant={filterType === 'active' ? 'default' : 'outline'}
              onClick={() => {
                setFilterType('active');
                setPage(1);
              }}
            >
              Active
            </Button>
            <Button
              variant={filterType === 'blocked' ? 'default' : 'outline'}
              onClick={() => {
                setFilterType('blocked');
                setPage(1);
              }}
            >
              Blocked
            </Button>
            {(searchTerm || filterType !== 'all') && (
              <Button
                variant="outline"
                onClick={() => {
                  setSearchTerm('');
                  setFilterType('all');
                  setPage(1);
                }}
              >
                Clear Filters
              </Button>
            )}
          </div>
        </div>
      </Card>

      {/* Table */}
      <Card className="p-4 overflow-x-auto">
        {isLoading ? (
          <div className="py-8 text-center text-gray-600">Loading accounts...</div>
        ) : error ? (
          <div className="py-8 px-4 bg-red-50 border border-red-200 rounded-lg flex gap-2">
            <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
            <div className="text-sm text-red-800">Failed to load accounts</div>
          </div>
        ) : accounts.length === 0 ? (
          <div className="py-8 text-center text-gray-600">No accounts found</div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="border-b bg-gray-50">
                <tr>
                  <th className="px-4 py-3 text-left font-semibold text-gray-700">Account #</th>
                  <th className="px-4 py-3 text-left font-semibold text-gray-700">Name</th>
                  <th className="px-4 py-3 text-left font-semibold text-gray-700">Contact</th>
                  <th className="px-4 py-3 text-left font-semibold text-gray-700">Sales Area</th>
                  <th className="px-4 py-3 text-right font-semibold text-gray-700">Balance</th>
                  <th className="px-4 py-3 text-right font-semibold text-gray-700">Credit Limit</th>
                  <th className="px-4 py-3 text-center font-semibold text-gray-700">Status</th>
                  <th className="px-4 py-3 text-center font-semibold text-gray-700">Actions</th>
                </tr>
              </thead>
              <tbody>
                {accounts.map((account: DebtorAccount) => (
                  <tr key={account.id} className="border-b hover:bg-gray-50 transition-colors">
                    <td className="px-4 py-3 font-medium">{account.customer_number}</td>
                    <td className="px-4 py-3">{account.name}</td>
                    <td className="px-4 py-3 text-gray-600">{account.contact_person || '-'}</td>
                    <td className="px-4 py-3 text-gray-600">{account.area_code ?? '-'}</td>
                    <td className="px-4 py-3 text-right font-semibold text-blue-600">
                      {typeof account.total_balance === 'number' ? `$${account.total_balance.toLocaleString('en-US', { maximumFractionDigits: 2 })}` : '-'}
                    </td>
                    <td className="px-4 py-3 text-right">{typeof account.credit_limit === 'number' ? `$${account.credit_limit.toLocaleString()}` : '-'}</td>
                    <td className="px-4 py-3 text-center">
                      {account.block_flag ? (
                        <Badge className="bg-red-500">Blocked</Badge>
                      ) : account.is_active ? (
                        <Badge className="bg-green-500">Active</Badge>
                      ) : (
                        <Badge className="bg-gray-500">Inactive</Badge>
                      )}
                    </td>
                    <td className="px-4 py-3 text-center">
                      <div className="flex justify-center gap-2">
                        <Link href={`/dashboard/admin/debtors/maintenance/accounts/${account.id}/view`}>
                          <Button variant="outline" size="sm" title="View details">
                            <Eye className="w-4 h-4" />
                          </Button>
                        </Link>
                        <Link href={`/dashboard/admin/debtors/maintenance/accounts/${account.id}/edit`}>
                          <Button variant="outline" size="sm" title="Edit account">
                            <Edit2 className="w-4 h-4" />
                          </Button>
                        </Link>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleDelete(account.id!, account.name)}
                          title="Delete account"
                        >
                          <Trash2 className="w-4 h-4 text-red-600" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex justify-center gap-2">
          {Array.from({ length: totalPages }, (_, i) => i + 1).map((p) => (
            <Button
              key={p}
              variant={page === p ? 'default' : 'outline'}
              onClick={() => setPage(p)}
            >
              {p}
            </Button>
          ))}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { api } from '@/lib/api';
import type { MaybeAxiosError } from '@/lib/types/errors';

import {
  Download,
  Filter,
  RotateCcw,
} from 'lucide-react';

interface ReportFilters {
  reportType: string;
  startDate?: string;
  endDate?: string;
  areaCode?: string;
  departmentNumber?: string;
  accountNumber?: string;
  shortName?: string;
  includeZeroBalance?: boolean;
  includeBlocked?: boolean;
  sortBy?: string;
  sequenceType?: 'alphabetical' | 'numerical';
  [key: string]: any;
}

const REPORT_TYPES = [
  {
    id: 'account_details',
    name: 'Account Details',
    description: 'List all debtors with account numbers, names, addresses, telephone, area, VAT and credit limits',
  },
  {
    id: 'age_analysis',
    name: 'Age Analysis',
    description: 'Outstanding balances by period (weekly/monthly) with payment info',
  },
  {
    id: 'statement',
    name: 'Statement Print',
    description: 'Current and historical statements with opening/closing balances',
  },
  {
    id: 'department_analysis',
    name: 'Department Analysis',
    description: 'Sales figures for departments (current, YTD, detailed, cash/account split)',
  },
  {
    id: 'transactions',
    name: 'Transactions',
    description: 'All account transactions (invoices, notes, receipts, interest, journals)',
  },
  {
    id: 'area_user',
    name: 'Area/User Report',
    description: 'Sales transactions and totals per area/salesman (YTD, detailed, masterfile)',
  },
  {
    id: 'address_labels',
    name: 'Address Labels',
    description: 'Address labels for statement envelopes (alphabetical/numeric order)',
  },
  {
    id: 'credit_limit_warning',
    name: 'Credit Limit Warning',
    description: 'Accounts exceeding credit limits or payment terms',
  },
  {
    id: 'account_performance',
    name: 'Account Performance',
    description: 'Sales and profit (MTD/YTD) by account with 12-month history',
  },
  {
    id: 'reprint_transaction',
    name: 'Reprint Transaction',
    description: 'Reprint invoices, credit notes and cash documents from current or archive',
  },
  {
    id: 'items_sold',
    name: 'Items Sold',
    description: 'Stock items sold to debtors (MTD, historical, average, by department/supplier)',
  },
];

export default function DebtorsReportsPage() {
  const [selectedReport, setSelectedReport] = useState<string>('account_details');
  const [filters, setFilters] = useState<ReportFilters>({
    reportType: 'account_details',
    includeZeroBalance: false,
    includeBlocked: false,
    sequenceType: 'alphabetical',
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reportData, setReportData] = useState<any>(null);

  const handleFilterChange = (key: string, value: any) => {
    setFilters((prev) => ({
      ...prev,
      [key]: value,
    }));
  };

  const generateReport = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await api.post(
        '/api/v1/debtors/reports/generate/',
        { ...filters, reportType: selectedReport },
        {
          headers: {
            'Content-Type': 'application/json',
          },
        }
      );
      setReportData(response.data);
    } catch (err: unknown) {
      setError((err as MaybeAxiosError).response?.data?.detail || 'Failed to generate report');
    } finally {
      setLoading(false);
    }
  };

  const downloadReport = async (format: 'pdf' | 'csv') => {
    try {
      const response = await api.post(
        `/api/v1/debtors/reports/generate/`,
        { ...filters, reportType: selectedReport, format },
        {
          responseType: 'blob',
        }
      );
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute(
        'download',
        `debtor_report_${selectedReport}_${new Date().toISOString().split('T')[0]}.${format}`
      );
      document.body.appendChild(link);
      link.click();
      link.parentNode?.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch {
      setError('Failed to download report');
    }
  };

  const resetFilters = () => {
    setFilters({
      reportType: selectedReport,
      includeZeroBalance: false,
      includeBlocked: false,
      sequenceType: 'alphabetical',
    });
    setReportData(null);
  };

  const currentReport = REPORT_TYPES.find((r) => r.id === selectedReport);

  return (
    <div className="p-6 space-y-6">
      <div>
        <h1 className="text-3xl font-bold">Debtors - Reports</h1>
        <p className="text-gray-600">Generate comprehensive debtor reports with customizable filters</p>
      </div>

      <div className="grid grid-cols-12 gap-6">
        {/* Report Types Sidebar */}
        <div className="col-span-3">
          <div className="bg-white rounded-lg shadow p-4">
            <h2 className="text-lg font-semibold mb-4">Report Types</h2>
            <div className="space-y-2">
              {REPORT_TYPES.map((report) => (
                <button
                  key={report.id}
                  onClick={() => {
                    setSelectedReport(report.id);
                    resetFilters();
                  }}
                  className={`w-full text-left px-4 py-2 rounded transition ${
                    selectedReport === report.id
                      ? 'bg-blue-500 text-white'
                      : 'hover:bg-gray-100'
                  }`}
                  title={report.description}
                >
                  <div className="text-sm font-medium">{report.name}</div>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Main Content */}
        <div className="col-span-9 space-y-6">
          {/* Report Description */}
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
            <h3 className="font-semibold text-blue-900">{currentReport?.name}</h3>
            <p className="text-sm text-blue-800 mt-1">{currentReport?.description}</p>
          </div>

          {/* Filters Section */}
          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold flex items-center gap-2">
                <Filter size={20} />
                Report Filters & Options
              </h3>
              <button
                onClick={resetFilters}
                className="text-gray-600 hover:text-gray-800 flex items-center gap-1"
              >
                <RotateCcw size={16} />
                Reset
              </button>
            </div>

            <div className="space-y-4">
              {/* Common Filters */}
              <div className="grid grid-cols-2 gap-4">
                {/* Sequence Type */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Sequence Type
                  </label>
                  <select
                    value={filters.sequenceType}
                    onChange={(e) =>
                      handleFilterChange('sequenceType', e.target.value)
                    }
                    className="w-full px-3 py-2 border border-gray-300 rounded-md"
                  >
                    <option value="alphabetical">Alphabetical</option>
                    <option value="numerical">Numerical</option>
                  </select>
                </div>

                {/* Area Code */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Area Code (Optional)
                  </label>
                  <input
                    type="text"
                    value={filters.areaCode || ''}
                    onChange={(e) =>
                      handleFilterChange('areaCode', e.target.value)
                    }
                    placeholder="Enter area code"
                    className="w-full px-3 py-2 border border-gray-300 rounded-md"
                  />
                </div>
              </div>

              {/* Report-Specific Filters */}
              {['age_analysis', 'statement', 'department_analysis', 'transactions', 'account_performance'].includes(selectedReport) && (
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Start Date
                    </label>
                    <input
                      type="date"
                      value={filters.startDate || ''}
                      onChange={(e) =>
                        handleFilterChange('startDate', e.target.value)
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      End Date
                    </label>
                    <input
                      type="date"
                      value={filters.endDate || ''}
                      onChange={(e) =>
                        handleFilterChange('endDate', e.target.value)
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    />
                  </div>
                </div>
              )}

              {/* Account Number Range */}
              {['account_details', 'account_performance'].includes(selectedReport) && (
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Start Account Number
                    </label>
                    <input
                      type="text"
                      value={filters.accountNumber || ''}
                      onChange={(e) =>
                        handleFilterChange('accountNumber', e.target.value)
                      }
                      placeholder="Enter start account"
                      className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      End Account Number
                    </label>
                    <input
                      type="text"
                      value={filters.endAccountNumber || ''}
                      onChange={(e) =>
                        handleFilterChange('endAccountNumber', e.target.value)
                      }
                      placeholder="Enter end account"
                      className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    />
                  </div>
                </div>
              )}

              {/* Department Number */}
              {['department_analysis', 'items_sold'].includes(selectedReport) && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Department Number (Optional)
                  </label>
                  <input
                    type="text"
                    value={filters.departmentNumber || ''}
                    onChange={(e) =>
                      handleFilterChange('departmentNumber', e.target.value)
                    }
                    placeholder="Enter department number"
                    className="w-full px-3 py-2 border border-gray-300 rounded-md"
                  />
                </div>
              )}

              {/* Checkboxes */}
              <div className="space-y-3 border-t pt-4">
                {['age_analysis', 'account_details'].includes(selectedReport) && (
                  <>
                    <label className="flex items-center gap-2">
                      <input
                        type="checkbox"
                        checked={filters.includeZeroBalance}
                        onChange={(e) =>
                          handleFilterChange('includeZeroBalance', e.target.checked)
                        }
                        className="rounded"
                      />
                      <span className="text-sm">Include Zero Balance Accounts</span>
                    </label>
                    <label className="flex items-center gap-2">
                      <input
                        type="checkbox"
                        checked={filters.includeBlocked}
                        onChange={(e) =>
                          handleFilterChange('includeBlocked', e.target.checked)
                        }
                        className="rounded"
                      />
                      <span className="text-sm">Include Blocked Accounts</span>
                    </label>
                  </>
                )}

                {selectedReport === 'address_labels' && (
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Number of Copies
                    </label>
                    <input
                      type="number"
                      min="1"
                      value={filters.numberOfCopies || 1}
                      onChange={(e) =>
                        handleFilterChange('numberOfCopies', parseInt(e.target.value))
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    />
                  </div>
                )}

                {selectedReport === 'statement' && (
                  <label className="flex items-center gap-2">
                    <input
                      type="checkbox"
                      checked={filters.includeCodAccounts}
                      onChange={(e) =>
                        handleFilterChange('includeCodAccounts', e.target.checked)
                      }
                      className="rounded"
                    />
                    <span className="text-sm">Include COD Accounts with Zero Balance</span>
                  </label>
                )}
              </div>
            </div>

            {/* Action Buttons */}
            <div className="flex gap-3 mt-6 pt-4 border-t">
              <button
                onClick={generateReport}
                disabled={loading}
                className="flex-1 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white px-4 py-2 rounded font-medium transition"
              >
                {loading ? 'Generating...' : 'Generate Report'}
              </button>
              <button
                onClick={() => downloadReport('pdf')}
                disabled={!reportData || loading}
                className="flex items-center gap-2 bg-red-600 hover:bg-red-700 disabled:bg-gray-400 text-white px-4 py-2 rounded font-medium transition"
              >
                <Download size={18} />
                PDF
              </button>
              <button
                onClick={() => downloadReport('csv')}
                disabled={!reportData || loading}
                className="flex items-center gap-2 bg-green-600 hover:bg-green-700 disabled:bg-gray-400 text-white px-4 py-2 rounded font-medium transition"
              >
                <Download size={18} />
                CSV
              </button>
            </div>
          </div>

          {/* Error Message */}
          {error && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-red-800">
              <p className="font-semibold">Error</p>
              <p className="text-sm">{error}</p>
            </div>
          )}

          {/* Report Preview */}
          {reportData && (
            <div className="bg-white rounded-lg shadow p-6">
              <h3 className="text-lg font-semibold mb-4">Report Preview</h3>
              <div className="overflow-x-auto max-h-96 overflow-y-auto border rounded">
                <table className="w-full text-sm">
                  <thead className="bg-gray-100 sticky top-0">
                    <tr>
                      {reportData.columns?.map((col: string) => (
                        <th
                          key={col}
                          className="px-4 py-2 text-left font-semibold border-b"
                        >
                          {col}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {reportData.rows?.map((row: any[], idx: number) => (
                      <tr key={idx} className="border-b hover:bg-gray-50">
                        {row.map((cell: any, cidx: number) => (
                          <td
                            key={cidx}
                            className="px-4 py-2"
                          >
                            {typeof cell === 'number'
                              ? cell.toLocaleString('en-US', {
                                  minimumFractionDigits: 2,
                                  maximumFractionDigits: 2,
                                })
                              : cell}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              {reportData.summary && (
                <div className="mt-4 p-4 bg-gray-50 rounded border">
                  <h4 className="font-semibold mb-2">Summary</h4>
                  <div className="grid grid-cols-2 gap-4 text-sm">
                    {Object.entries(reportData.summary).map(([key, value]) => (
                      <div key={key}>
                        <span className="text-gray-600">{key}:</span>{' '}
                        <span className="font-semibold">
                          {typeof value === 'number'
                            ? (value as number).toLocaleString('en-US', {
                                minimumFractionDigits: 2,
                                maximumFractionDigits: 2,
                              })
                            : String(value)}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import debtorsApi from '@/lib/debtorsApi';
import { Card } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import PostDatedChequeForm from '@/components/debtors/forms/PostDatedChequeForm';
import type { PostDatedCheque } from '@/lib/types/debtors';
import { Badge } from '@/components/ui/badge';
export default function PDCPage() {
  const [debtorId, setDebtorId] = useState<number | null>(null);
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  const { data: pdcs, isLoading } = useQuery({
    queryKey: ['pdcs', debtorId, refreshTrigger],
    queryFn: () => debtorsApi.pdcs.list(debtorId || undefined),
    staleTime: 2 * 60 * 1000,
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'OUTSTANDING':
        return 'bg-orange-500';
      case 'RECEIVED':
        return 'bg-blue-500';
      case 'CLEARED':
        return 'bg-green-500';
      case 'DISHONOURED':
        return 'bg-red-500';
      default:
        return 'bg-gray-500';
    }
  };

  const handleStatusChange = async (pdc: PostDatedCheque, newStatus: string) => {
    if (window.confirm(`Update PDC status to ${newStatus}?`)) {
      try {
        await debtorsApi.pdcs.updateStatus(
          pdc.id,
          newStatus as any,
          new Date().toISOString().split('T')[0]
        );
        setRefreshTrigger((prev) => prev + 1);
      } catch (err) {
        console.error('Update failed:', err);
      }
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold">Post-Dated Cheques (PDC)</h1>
        <p className="text-gray-600 mt-1">Track and manage post-dated cheques from customers</p>
      </div>

      {/* Add New PDC */}
      <Card className="p-6">
        <h2 className="text-lg font-bold mb-4">Record New PDC</h2>
        <PostDatedChequeForm onSuccess={() => setRefreshTrigger((prev) => prev + 1)} />
      </Card>

      {/* PDC List */}
      <Card className="p-6">
        <h2 className="text-lg font-bold mb-4">PDC Register</h2>

        <div className="mb-6">
          <label className="block text-sm font-medium mb-2">Filter by Debtor (Optional)</label>
          <Input
            type="number"
            placeholder="Enter debtor ID to filter"
            onChange={(e) => setDebtorId(e.target.value ? parseInt(e.target.value) : null)}
          />
        </div>

        {isLoading ? (
          <div className="text-center py-8 text-gray-600">Loading cheques...</div>
        ) : (pdcs?.results?.length || 0) === 0 ? (
          <div className="text-center py-8 text-gray-600">No PDCs found</div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="border-b bg-gray-50">
                <tr>
                  <th className="px-4 py-3 text-left font-semibold">Debtor</th>
                  <th className="px-4 py-3 text-left font-semibold">Cheque #</th>
                  <th className="px-4 py-3 text-left font-semibold">Bank</th>
                  <th className="px-4 py-3 text-right font-semibold">Amount</th>
                  <th className="px-4 py-3 text-left font-semibold">Expected Date</th>
                  <th className="px-4 py-3 text-left font-semibold">Status</th>
                  <th className="px-4 py-3 text-center font-semibold">Actions</th>
                </tr>
              </thead>
              <tbody>
                {pdcs?.results?.map((pdc: PostDatedCheque) => (
                  <tr key={pdc.id} className="border-b hover:bg-gray-50">
                    <td className="px-4 py-3">{pdc.debtor_id}</td>
                    <td className="px-4 py-3 font-medium">{pdc.cheque_number}</td>
                    <td className="px-4 py-3">{pdc.bank || '-'}</td>
                    <td className="px-4 py-3 text-right font-semibold">
                      ${pdc.amount?.toLocaleString('en-US', { maximumFractionDigits: 2 })}
                    </td>
                    <td className="px-4 py-3">
                      {new Date(pdc.expected_date).toLocaleDateString()}
                    </td>
                    <td className="px-4 py-3">
                      <Badge className={getStatusColor(pdc.status)}>
                        {pdc.status}
                      </Badge>
                    </td>
                    <td className="px-4 py-3 text-center">
                      <select
                        className="text-xs border rounded px-2 py-1"
                        value={pdc.status}
                        onChange={(e) => handleStatusChange(pdc, e.target.value)}
                      >
                        <option value={pdc.status}>Select action...</option>
                        {pdc.status === 'OUTSTANDING' && (
                          <>
                            <option value="RECEIVED">Mark Received</option>
                            <option value="DISHONOURED">Mark Dishonoured</option>
                          </>
                        )}
                        {pdc.status === 'RECEIVED' && <option value="CLEARED">Mark Cleared</option>}
                      </select>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>
    </div>
  );
}

