'use client';

import { useEffect, useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { glParametersApi } from '@/lib/general-ledger';
import { getApiErrorMessage } from '@/lib/api';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { ArrowLeft, Loader2, AlertTriangle } from 'lucide-react';
import Link from 'next/link';

export default function GLParametersPage() {
  const queryClient = useQueryClient();
  const [retainedEarningsAccno, setRetainedEarningsAccno] = useState<string>('');
  const [hasEditedRetainedEarnings, setHasEditedRetainedEarnings] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  const { data: param, isLoading } = useQuery({
    queryKey: ['gl-parameters'],
    queryFn: () => glParametersApi.get(),
  });

  // Sync the input from the fetched singleton once, without clobbering
  // whatever the user has typed since (TanStack Query v5 removed
  // useQuery's onSuccess callback, so this replaces that).
  useEffect(() => {
    if (param && !hasEditedRetainedEarnings) {
      setRetainedEarningsAccno(param.retained_earnings_accno ? String(param.retained_earnings_accno) : '');
    }
  }, [param, hasEditedRetainedEarnings]);

  const { data: status, refetch: refetchStatus } = useQuery({
    queryKey: ['gl-system-status'],
    queryFn: () => glParametersApi.systemStatus(),
  });

  const updateMutation = useMutation({
    mutationFn: () =>
      glParametersApi.update({
        retained_earnings_accno: retainedEarningsAccno ? parseInt(retainedEarningsAccno) : null,
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['gl-parameters'] });
      setMessage({ type: 'success', text: 'Parameters updated.' });
    },
    onError: (err) => setMessage({ type: 'error', text: getApiErrorMessage(err, 'Failed to update parameters') }),
  });

  const periodEndMutation = useMutation({
    mutationFn: () => glParametersApi.periodEnd(),
    onSuccess: (result) => {
      queryClient.invalidateQueries({ queryKey: ['gl-parameters'] });
      refetchStatus();
      setMessage({ type: 'success', text: `Period End complete — moved from period ${result.previous_period} to ${result.curperiod}.` });
    },
    onError: (err) => setMessage({ type: 'error', text: getApiErrorMessage(err, 'Period End failed') }),
  });

  const yearEndMutation = useMutation({
    mutationFn: () => glParametersApi.yearEnd(),
    onSuccess: (result) => {
      queryClient.invalidateQueries({ queryKey: ['gl-parameters'] });
      refetchStatus();
      setMessage({
        type: 'success',
        text: `Year End complete — closed ${result.previous_year} (net income ${result.net_income.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}), now in ${result.currentyr}.`,
      });
    },
    onError: (err) => setMessage({ type: 'error', text: getApiErrorMessage(err, 'Year End failed') }),
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Link href="/dashboard/admin/general-ledger/maintenance">
          <Button variant="outline" size="sm">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
        </Link>
        <div>
          <h1 className="text-3xl font-bold">GL Parameters</h1>
          <p className="text-gray-600 mt-1">Current period/year and Period/Year End</p>
        </div>
      </div>

      {message && (
        <div
          className={`rounded p-3 text-sm border ${
            message.type === 'success'
              ? 'bg-green-50 border-green-200 text-green-800'
              : 'bg-red-50 border-red-200 text-red-800'
          }`}
        >
          {message.text}
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <Card className="p-6">
          <h2 className="text-lg font-bold mb-4">Status</h2>
          <dl className="space-y-2 text-sm">
            <div className="flex justify-between">
              <dt className="text-gray-600">Current Period</dt>
              <dd className="font-medium">{status?.curperiod ?? param?.curperiod}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-gray-600">Current Year</dt>
              <dd className="font-medium">{status?.currentyr ?? param?.currentyr}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-gray-600">Start Period</dt>
              <dd className="font-medium">{param?.startper}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-gray-600">Next Batch Number</dt>
              <dd className="font-medium">{status?.next_batchno}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-gray-600">Outstanding Batches</dt>
              <dd className={`font-medium ${status && status.outstanding_batches > 0 ? 'text-amber-600' : ''}`}>
                {status?.outstanding_batches}
              </dd>
            </div>
          </dl>

          {status && status.outstanding_batches > 0 && (
            <div className="mt-4 flex items-start gap-2 text-xs text-amber-700 bg-amber-50 border border-amber-200 rounded p-2">
              <AlertTriangle className="w-4 h-4 flex-shrink-0 mt-0.5" />
              Batches {status.outstanding_batchnos.join(', ')} must be posted before Period End or Year End can run.
            </div>
          )}
        </Card>

        <Card className="p-6">
          <h2 className="text-lg font-bold mb-4">Retained Earnings Account</h2>
          <p className="text-sm text-gray-600 mb-3">
            Income Statement accounts are closed against this account at Year End.
          </p>
          <div className="flex gap-2">
            <Input
              type="number"
              value={retainedEarningsAccno}
              onChange={(e) => {
                setHasEditedRetainedEarnings(true);
                setRetainedEarningsAccno(e.target.value);
              }}
              placeholder="e.g., 3000"
            />
            <Button onClick={() => updateMutation.mutate()} disabled={updateMutation.isPending}>
              {updateMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Save'}
            </Button>
          </div>
        </Card>
      </div>

      <Card className="p-6 border-l-4 border-l-red-500">
        <h2 className="text-lg font-bold mb-2">Period End / Year End</h2>
        <p className="text-sm text-gray-600 mb-4">
          These operations are irreversible. Ensure all batches are posted before running either.
        </p>
        <div className="flex gap-3">
          <Button
            variant="outline"
            onClick={() => {
              if (window.confirm('Advance to the next period? This cannot be undone.')) {
                periodEndMutation.mutate();
              }
            }}
            disabled={periodEndMutation.isPending}
          >
            {periodEndMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
            Run Period End
          </Button>
          <Button
            variant="destructive"
            onClick={() => {
              if (
                window.confirm(
                  'Run Year End? This closes all Income Statement accounts to Retained Earnings, rolls balances forward, and advances the year. This cannot be undone.'
                )
              ) {
                yearEndMutation.mutate();
              }
            }}
            disabled={yearEndMutation.isPending}
          >
            {yearEndMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
            Run Year End
          </Button>
        </div>
      </Card>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { glReportFormatsApi } from '@/lib/general-ledger';
import { GLRep, GLRepCreateData } from '@/lib/types/generalLedger';
import { getApiErrorMessage } from '@/lib/api';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Plus, Pencil, Trash2, Loader2, ArrowLeft } from 'lucide-react';
import Link from 'next/link';

const emptyForm: GLRepCreateData = {
  type: 'I',
  fieldtype: 'D',
  line: 1,
  printdet: 'N',
  name: '',
  start: 1,
  endcalc: 1,
};

export default function ReportFormatsPage() {
  const queryClient = useQueryClient();
  const [typeFilter, setTypeFilter] = useState<'I' | 'B'>('I');
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingRow, setEditingRow] = useState<GLRep | null>(null);
  const [formData, setFormData] = useState<GLRepCreateData>(emptyForm);
  const [formError, setFormError] = useState<string | null>(null);

  const { data, isLoading } = useQuery({
    queryKey: ['gl-report-formats', typeFilter],
    queryFn: () => glReportFormatsApi.list({ type: typeFilter, ordering: 'line' }),
  });

  const createMutation = useMutation({
    mutationFn: (body: GLRepCreateData) => glReportFormatsApi.create(body),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['gl-report-formats'] });
      setIsDialogOpen(false);
      setFormError(null);
    },
    onError: (err) => setFormError(getApiErrorMessage(err, 'Failed to create row')),
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, body }: { id: number; body: Partial<GLRepCreateData> }) =>
      glReportFormatsApi.update(id, body),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['gl-report-formats'] });
      setIsDialogOpen(false);
      setEditingRow(null);
      setFormError(null);
    },
    onError: (err) => setFormError(getApiErrorMessage(err, 'Failed to update row')),
  });

  const deleteMutation = useMutation({
    mutationFn: (id: number) => glReportFormatsApi.delete(id),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['gl-report-formats'] }),
    onError: (err) => window.alert(getApiErrorMessage(err, 'Failed to delete row')),
  });

  const handleEdit = (row: GLRep) => {
    setEditingRow(row);
    setFormData({
      type: row.type,
      fieldtype: row.fieldtype,
      line: row.line,
      printdet: row.printdet,
      name: row.name,
      start: row.start,
      endcalc: row.endcalc,
    });
    setFormError(null);
    setIsDialogOpen(true);
  };

  const handleDelete = (row: GLRep) => {
    if (window.confirm(`Delete report format line ${row.line} - ${row.name}?`)) {
      deleteMutation.mutate(row.id);
    }
  };

  const handleSubmit = () => {
    if (editingRow) {
      updateMutation.mutate({ id: editingRow.id, body: formData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const rows = data?.results || [];

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Link href="/dashboard/admin/general-ledger/maintenance">
          <Button variant="outline" size="sm">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
        </Link>
        <div>
          <h1 className="text-3xl font-bold">Report Formats</h1>
          <p className="text-gray-600 mt-1">
            Layout rows for Income Statement / Balance Sheet. Detail rows sum account
            report lines (repline); Heading/Total/Subtotal rows sum earlier report lines.
          </p>
        </div>
      </div>

      <Card className="p-6">
        <div className="flex items-center justify-between mb-6">
          <div className="flex gap-2">
            <Button
              variant={typeFilter === 'I' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setTypeFilter('I')}
            >
              Income Statement
            </Button>
            <Button
              variant={typeFilter === 'B' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setTypeFilter('B')}
            >
              Balance Sheet
            </Button>
          </div>
          <Button
            onClick={() => {
              setFormData({ ...emptyForm, type: typeFilter });
              setEditingRow(null);
              setFormError(null);
              setIsDialogOpen(true);
            }}
          >
            <Plus className="w-4 h-4 mr-2" />
            Add Line
          </Button>
        </div>

        {isLoading ? (
          <div className="text-center py-8">
            <Loader2 className="w-6 h-6 animate-spin mx-auto" />
          </div>
        ) : rows.length === 0 ? (
          <div className="text-center py-8 text-gray-500">
            No report format lines defined for this report type yet.
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Line</TableHead>
                <TableHead>Field Type</TableHead>
                <TableHead>Name</TableHead>
                <TableHead>Start</TableHead>
                <TableHead>End Calc</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {rows.map((row) => (
                <TableRow key={row.id}>
                  <TableCell className="font-medium">{row.line}</TableCell>
                  <TableCell>{row.fieldtype_display}</TableCell>
                  <TableCell>{row.name}</TableCell>
                  <TableCell>{row.start}</TableCell>
                  <TableCell>{row.endcalc}</TableCell>
                  <TableCell className="text-right">
                    <div className="flex items-center justify-end gap-2">
                      <Button variant="ghost" size="sm" onClick={() => handleEdit(row)}>
                        <Pencil className="w-4 h-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleDelete(row)}
                        className="text-red-600 hover:text-red-700"
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </Card>

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>{editingRow ? 'Edit Report Line' : 'Add Report Line'}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            {formError && (
              <div className="text-sm text-red-600 bg-red-50 border border-red-200 rounded p-2">
                {formError}
              </div>
            )}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Line #</label>
                <Input
                  type="number"
                  value={formData.line}
                  onChange={(e) => setFormData({ ...formData, line: parseInt(e.target.value) || 0 })}
                />
              </div>
              <div>
                <label className="text-sm font-medium">Field Type</label>
                <select
                  value={formData.fieldtype}
                  onChange={(e) => setFormData({ ...formData, fieldtype: e.target.value as any })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm"
                >
                  <option value="H">Heading</option>
                  <option value="D">Detail</option>
                  <option value="S">Subtotal</option>
                  <option value="T">Total</option>
                </select>
              </div>
            </div>
            <div>
              <label className="text-sm font-medium">Name</label>
              <Input
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                maxLength={30}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">
                  Start {formData.fieldtype === 'D' ? '(account repline)' : '(report line)'}
                </label>
                <Input
                  type="number"
                  value={formData.start}
                  onChange={(e) => setFormData({ ...formData, start: parseInt(e.target.value) || 0 })}
                />
              </div>
              <div>
                <label className="text-sm font-medium">
                  End Calc {formData.fieldtype === 'D' ? '(account repline)' : '(report line)'}
                </label>
                <Input
                  type="number"
                  value={formData.endcalc}
                  onChange={(e) => setFormData({ ...formData, endcalc: parseInt(e.target.value) || 0 })}
                />
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSubmit} disabled={createMutation.isPending || updateMutation.isPending}>
              {createMutation.isPending || updateMutation.isPending ? (
                <Loader2 className="w-4 h-4 animate-spin mr-2" />
              ) : null}
              {editingRow ? 'Update' : 'Create'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { apiRequest } from '@/lib/api';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Plus, Search, Loader2, ArrowLeft } from 'lucide-react';
import Link from 'next/link';

interface BranchTransferInvoice {
  id: number;
  invoice_number: string;
  transfer: number;
  transfer_number?: string;
  from_branch: string;
  to_branch: string;
  total_amount: number;
  status: string;
  issued_at?: string;
  paid_at?: string;
}

interface IBIFormData {
  transfer: string;
}

interface IBISubmitData {
  transfer: number;
}

const statusColors: Record<string, string> = {
  DRAFT: 'bg-gray-500',
  ISSUED: 'bg-blue-500',
  PAID: 'bg-green-500',
  CANCELLED: 'bg-red-500',
};

export default function IBIPage() {
  const queryClient = useQueryClient();
  const [searchTerm, setSearchTerm] = useState('');
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [formData, setFormData] = useState<IBIFormData>({
    transfer: '',
  });

  const { data: invoices, isLoading } = useQuery({
    queryKey: ['branch-transfer-invoices', searchTerm],
    queryFn: () => apiRequest('/api/v1/stock-control/branch-transfer-invoices/'),
    select: (response) => response.data.results || response.data,
  });

  const { data: transfers } = useQuery({
    queryKey: ['branch-transfers'],
    queryFn: () => apiRequest('/api/v1/stock-control/branch-transfers/'),
    select: (response) => response.data.results || response.data,
  });

  const createMutation = useMutation({
    mutationFn: (data: IBISubmitData) =>
      apiRequest('/api/v1/stock-control/branch-transfer-invoices/', {
        method: 'POST',
        body: JSON.stringify(data),
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['branch-transfer-invoices'] });
      setIsDialogOpen(false);
      setFormData({ transfer: '' });
    },
  });

  const issueMutation = useMutation({
    mutationFn: (id: number) =>
      apiRequest(`/api/v1/stock-control/branch-transfer-invoices/${id}/issue/`, {
        method: 'POST',
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['branch-transfer-invoices'] });
    },
  });

  const paidMutation = useMutation({
    mutationFn: (id: number) =>
      apiRequest(`/api/v1/stock-control/branch-transfer-invoices/${id}/mark-paid/`, {
        method: 'POST',
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['branch-transfer-invoices'] });
    },
  });

  const filteredInvoices = invoices?.filter((invoice: BranchTransferInvoice) =>
    invoice.invoice_number?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    invoice.transfer_number?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    invoice.from_branch?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    invoice.to_branch?.toLowerCase().includes(searchTerm.toLowerCase())
  ) || [];

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString();
  };

  const formatCurrency = (amount: number) => {
    return `$${amount?.toFixed(2) || '0.00'}`;
  };

  const handleCreateInvoice = () => {
    if (!formData.transfer) return;
    const payload: IBISubmitData = { transfer: parseInt(formData.transfer) };
    createMutation.mutate(payload);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Link href="/dashboard/admin">
          <Button variant="outline" size="sm">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
        </Link>
        <div>
          <h1 className="text-3xl font-bold">Inter-Branch Invoices (IBI)</h1>
          <p className="text-gray-600 mt-1">Manage inter-branch transfer invoices</p>
        </div>
      </div>

      <Card className="p-6">
        <div className="flex items-center justify-between mb-6">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
            <Input
              placeholder="Search by item code, name, branch..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10"
            />
          </div>
          <Button
            onClick={() => setIsDialogOpen(true)}
            className="ml-4"
          >
            <Plus className="w-4 h-4 mr-2" />
            New Invoice
          </Button>
        </div>

        {isLoading ? (
          <div className="text-center py-8">
            <Loader2 className="w-6 h-6 animate-spin mx-auto" />
            <p className="text-gray-500 mt-2">Loading invoices...</p>
          </div>
        ) : filteredInvoices.length === 0 ? (
          <div className="text-center py-8 text-gray-500">
            No invoices found. Click &quot;New Invoice&quot; to create one.
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Invoice #</TableHead>
                <TableHead>Transfer #</TableHead>
                <TableHead>From</TableHead>
                <TableHead>To</TableHead>
                <TableHead className="text-right">Amount</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Issued</TableHead>
                <TableHead>Paid</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredInvoices.map((invoice: BranchTransferInvoice) => (
                <TableRow key={invoice.id}>
                  <TableCell className="font-medium">{invoice.invoice_number}</TableCell>
                  <TableCell>{invoice.transfer_number}</TableCell>
                  <TableCell>{invoice.from_branch}</TableCell>
                  <TableCell>{invoice.to_branch}</TableCell>
                  <TableCell className="text-right font-medium">{formatCurrency(invoice.total_amount)}</TableCell>
                  <TableCell>
                    <Badge className={statusColors[invoice.status] || 'bg-gray-500'}>
                      {invoice.status}
                    </Badge>
                  </TableCell>
                  <TableCell>{formatDate(invoice.issued_at)}</TableCell>
                  <TableCell>{formatDate(invoice.paid_at)}</TableCell>
                  <TableCell className="text-right">
                    <div className="flex items-center justify-end gap-2">
                      {invoice.status === 'DRAFT' && (
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => issueMutation.mutate(invoice.id)}
                        >
                          Issue
                        </Button>
                      )}
                      {invoice.status === 'ISSUED' && (
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => paidMutation.mutate(invoice.id)}
                        >
                          Mark Paid
                        </Button>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </Card>

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Create New Invoice</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm font-medium">Transfer</label>
              <Select
                value={formData.transfer}
                onValueChange={(value) => setFormData({ transfer: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select transfer" />
                </SelectTrigger>
                <SelectContent>
                  {transfers
                    ?.filter((t: any) => t.status === 'RECEIVED')
                    .map((transfer: any) => (
                      <SelectItem key={transfer.id} value={transfer.id.toString()}>
                        {transfer.transfer_number} - {transfer.to_branch}
                      </SelectItem>
                    ))}
                </SelectContent>
              </Select>
              <p className="text-xs text-gray-500 mt-1">
                Only received transfers can be invoiced
              </p>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
              Cancel
            </Button>
            <Button
              onClick={handleCreateInvoice}
              disabled={createMutation.isPending || !formData.transfer}
            >
              {createMutation.isPending ? (
                <Loader2 className="w-4 h-4 animate-spin mr-2" />
              ) : null}
              Create Invoice
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { apiRequest } from '@/lib/api';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Plus, Search, Loader2, ArrowLeft } from 'lucide-react';
import Link from 'next/link';

interface BranchTransfer {
  id: number;
  transfer_number: string;
  from_branch: string;
  to_branch: string;
  status: string;
  created_at: string;
  dispatched_at?: string;
  received_at?: string;
}

const statusColors: Record<string, string> = {
  PENDING: 'bg-yellow-500',
  APPROVED: 'bg-blue-500',
  DISPATCHED: 'bg-purple-500',
  IN_TRANSIT: 'bg-orange-500',
  RECEIVED: 'bg-green-500',
  CANCELLED: 'bg-red-500',
};

export default function IBTPage() {
  const queryClient = useQueryClient();
  const [searchTerm, setSearchTerm] = useState('');
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [formData, setFormData] = useState({
    from_branch: '',
    to_branch: '',
    notes: '',
  });

  const { data: transfers, isLoading, refetch: _refetch } = useQuery({
    queryKey: ['branch-transfers', searchTerm],
    queryFn: () => apiRequest('/api/v1/stock-control/branch-transfers/'),
    select: (response) => response.data.results || response.data,
  });

  const { data: branches } = useQuery({
    queryKey: ['branches'],
    queryFn: () => apiRequest('/api/v1/stock-control/branches/'),
    select: (response) => response.data.results || response.data,
  });

  const createMutation = useMutation({
    mutationFn: (data: typeof formData) =>
      apiRequest('/api/v1/stock-control/branch-transfers/', {
        method: 'POST',
        body: JSON.stringify(data),
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['branch-transfers'] });
      setIsDialogOpen(false);
      setFormData({ from_branch: '', to_branch: '', notes: '' });
    },
  });

  const filteredTransfers = transfers?.filter((transfer: BranchTransfer) =>
    transfer.transfer_number?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    transfer.from_branch?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    transfer.to_branch?.toLowerCase().includes(searchTerm.toLowerCase())
  ) || [];

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString();
  };

  const handleCreateTransfer = () => {
    if (!formData.from_branch || !formData.to_branch) return;
    if (formData.from_branch === formData.to_branch) {
      alert('Source and destination branches must be different');
      return;
    }
    createMutation.mutate(formData);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Link href="/dashboard/admin">
          <Button variant="outline" size="sm">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
        </Link>
        <div>
          <h1 className="text-3xl font-bold">Inter-Branch Transfers (IBT)</h1>
          <p className="text-gray-600 mt-1">Manage stock transfers between branches</p>
        </div>
      </div>

      <Card className="p-6">
        <div className="flex items-center justify-between mb-6">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
            <Input
              placeholder="Search by transfer number, branch..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10"
            />
          </div>
          <Button
            onClick={() => setIsDialogOpen(true)}
            className="ml-4"
          >
            <Plus className="w-4 h-4 mr-2" />
            New Transfer
          </Button>
        </div>

        {isLoading ? (
          <div className="text-center py-8">
            <Loader2 className="w-6 h-6 animate-spin mx-auto" />
            <p className="text-gray-500 mt-2">Loading transfers...</p>
          </div>
        ) : filteredTransfers.length === 0 ? (
          <div className="text-center py-8 text-gray-500">
            No transfers found. Click &quot;New Transfer&quot; to create one.
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Transfer #</TableHead>
                <TableHead>From Branch</TableHead>
                <TableHead>To Branch</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Created</TableHead>
                <TableHead>Dispatched</TableHead>
                <TableHead>Received</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredTransfers.map((transfer: BranchTransfer) => (
                <TableRow key={transfer.id}>
                  <TableCell className="font-medium">{transfer.transfer_number}</TableCell>
                  <TableCell>{transfer.from_branch}</TableCell>
                  <TableCell>{transfer.to_branch}</TableCell>
                  <TableCell>
                    <Badge className={statusColors[transfer.status] || 'bg-gray-500'}>
                      {transfer.status}
                    </Badge>
                  </TableCell>
                  <TableCell>{formatDate(transfer.created_at)}</TableCell>
                  <TableCell>{formatDate(transfer.dispatched_at)}</TableCell>
                  <TableCell>{formatDate(transfer.received_at)}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </Card>

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Create New Transfer</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm font-medium">Source Branch</label>
              <Select
                value={formData.from_branch}
                onValueChange={(value) => setFormData({ ...formData, from_branch: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select source branch" />
                </SelectTrigger>
                <SelectContent>
                  {branches?.map((branch: any) => (
                    <SelectItem key={branch.branch_code} value={branch.branch_code}>
                      {branch.branch_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-sm font-medium">Destination Branch</label>
              <Select
                value={formData.to_branch}
                onValueChange={(value) => setFormData({ ...formData, to_branch: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select destination branch" />
                </SelectTrigger>
                <SelectContent>
                  {branches?.map((branch: any) => (
                    <SelectItem key={branch.branch_code} value={branch.branch_code}>
                      {branch.branch_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-sm font-medium">Notes</label>
              <Input
                value={formData.notes}
                onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                placeholder="Optional notes"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
              Cancel
            </Button>
            <Button
              onClick={handleCreateTransfer}
              disabled={createMutation.isPending || !formData.from_branch || !formData.to_branch}
            >
              {createMutation.isPending ? (
                <Loader2 className="w-4 h-4 animate-spin mr-2" />
              ) : null}
              Create Transfer
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

