'use client';

import { useState, useEffect } from 'react';
import { useRouter, useParams } from 'next/navigation';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { getStockItem, createStockItem, updateStockItem } from '@/lib/stockApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Loader, Save } from 'lucide-react';

export default function StockItemFormPage() {
  const params = useParams();
  const router = useRouter();
  const queryClient = useQueryClient();
  const isNew = params.id === 'new';

  const [formData, setFormData] = useState({
    stock_code: '', description: '', department: '', supplier: '',
    supplier_code: '', tax_code: 1, reorder_quantity: 0,
    cost_price: 0, allow_negative_quantities: false,
    default_selling_quantity: 1, automatic_returns: false,
    maximum_discount_percent: 0,
    markup_1: 0, markup_2: 0, markup_3: 0,
    selling_price_1: 0, selling_price_2: 0, selling_price_3: 0,
  });

  const [quantities, setQuantities] = useState({
    quantity_on_hand: 0, quantity_allocated: 0, quantity_sale_order: 0,
  });

  const { data: existingItem, isLoading } = useQuery({
    queryKey: ['stock-item', params.id],
    queryFn: () => getStockItem(String(params.id)),
    enabled: !isNew,
  });

  useEffect(() => {
    if (existingItem) {
      const updated: any = { ...existingItem };
      setFormData(updated);
      setQuantities({
        quantity_on_hand: (existingItem as any)?.quantity_on_hand || 0,
        quantity_allocated: (existingItem as any)?.quantity_allocated || 0,
        quantity_sale_order: (existingItem as any)?.quantity_sale_order || 0,
      });
    }
  }, [existingItem]);

  const handleMarkupChange = (field: string, value: number) => {
    const markup = parseFloat(value.toString()) || 0;
    const cost = parseFloat(formData.cost_price.toString()) || 0;
    const sellingPrice = cost * (1 + markup / 100);
    setFormData(prev => ({
      ...prev,
      [field]: markup,
      [field.replace('markup', 'selling_price')]: sellingPrice,
    }));
  };

  const mutation = useMutation({
    mutationFn: (data: typeof formData) => {
      if (isNew) return createStockItem(data);
      return updateStockItem(String(params.id), data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['stock-items'] });
      router.push('/dashboard/admin/stock-control/maintenance/items');
    },
  });

  if (!isNew && isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">
            {isNew ? 'New Stock Item' : `Edit Stock Item: ${params.id}`}
          </h1>
          <p className="text-gray-600 mt-1">
            {isNew ? 'Create a new stock item' : 'Modify stock item details'}
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={() => router.back()}>Cancel</Button>
          <Button className="bg-green-600 hover:bg-green-700" onClick={() => mutation.mutate(formData)} disabled={mutation.isPending}>
            <Save className="w-4 h-4 mr-2" />
            {mutation.isPending ? 'Saving...' : 'Save'}
          </Button>
        </div>
      </div>

      {isNew && (
        <Card className="p-6">
          <h2 className="text-lg font-bold mb-4">Stock Code</h2>
          <div>
            <label className="text-sm font-medium">Stock Code</label>
            <Input
              value={formData.stock_code}
              onChange={(e) => setFormData(prev => ({ ...prev, stock_code: e.target.value }))}
              placeholder="Enter 1-13 alphanumeric code"
              maxLength={13}
              required
            />
          </div>
        </Card>
      )}

      <Card className="p-6">
        <h2 className="text-lg font-bold mb-4">Item Details</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="text-sm font-medium">Item Description</label>
            <Input
              value={formData.description}
              onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
              required
            />
          </div>
          <div>
            <label className="text-sm font-medium">Department</label>
            <Select value={formData.department?.toString()} onValueChange={(value: string) => setFormData(prev => ({ ...prev, department: value }))}>
              <SelectTrigger>
                <SelectValue placeholder="Select Department" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="">Select Department</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <label className="text-sm font-medium">Tax Code</label>
            <Select value={formData.tax_code?.toString()} onValueChange={(value: string) => setFormData(prev => ({ ...prev, tax_code: parseInt(value) }))}>
              <SelectTrigger>
                <SelectValue placeholder="Select Tax Code" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="1">1 - 15% VAT</SelectItem>
                <SelectItem value="2">2 - 0% VAT</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <label className="text-sm font-medium">Supplier</label>
            <Select value={formData.supplier?.toString()} onValueChange={(value: string) => setFormData(prev => ({ ...prev, supplier: value }))}>
              <SelectTrigger>
                <SelectValue placeholder="Select Supplier" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="">Select Supplier</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <label className="text-sm font-medium">Supplier Code</label>
            <Input value={formData.supplier_code || ''} onChange={(e) => setFormData(prev => ({ ...prev, supplier_code: e.target.value }))} />
          </div>
          <div>
            <label className="text-sm font-medium">Re-order Quantity</label>
            <Input type="number" value={formData.reorder_quantity} onChange={(e) => setFormData(prev => ({ ...prev, reorder_quantity: parseFloat(e.target.value) || 0 }))} />
          </div>
        </div>
      </Card>

      <Card className="p-6">
        <h2 className="text-lg font-bold mb-4">Quantities</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <label className="text-sm font-medium">Quantity on Hand</label>
            <Input type="number" value={quantities.quantity_on_hand} onChange={(e) => setQuantities(prev => ({ ...prev, quantity_on_hand: parseFloat(e.target.value) || 0 }))} />
          </div>
          <div>
            <label className="text-sm font-medium">Quantity Allocated</label>
            <Input type="number" value={quantities.quantity_allocated} onChange={(e) => setQuantities(prev => ({ ...prev, quantity_allocated: parseFloat(e.target.value) || 0 }))} />
          </div>
          <div>
            <label className="text-sm font-medium">Quantity on Sales Order</label>
            <Input type="number" value={quantities.quantity_sale_order} onChange={(e) => setQuantities(prev => ({ ...prev, quantity_sale_order: parseFloat(e.target.value) || 0 }))} />
          </div>
        </div>
        <div className="mt-4 p-4 bg-gray-100 rounded">
          <p className="font-bold">Available Quantity: {Math.max(0, quantities.quantity_on_hand - quantities.quantity_allocated - quantities.quantity_sale_order).toFixed(2)}</p>
        </div>
      </Card>

      <Card className="p-6">
        <h2 className="text-lg font-bold mb-4">Pricing</h2>
        <Tabs defaultValue="price1">
          <TabsList>
            <TabsTrigger value="price1">Price Level 1</TabsTrigger>
            <TabsTrigger value="price2">Price Level 2</TabsTrigger>
            <TabsTrigger value="price3">Price Level 3</TabsTrigger>
          </TabsList>

          <TabsContent value="price1" className="mt-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Cost Price</label>
                <Input type="number" value={formData.cost_price} onChange={(e) => setFormData(prev => ({ ...prev, cost_price: parseFloat(e.target.value) || 0 }))} />
              </div>
              <div>
                <label className="text-sm font-medium">Markup %</label>
                <Input type="number" value={formData.markup_1} onChange={(e) => handleMarkupChange('markup_1', parseFloat(e.target.value) || 0)} />
              </div>
              <div>
                <label className="text-sm font-medium">Selling Price 1</label>
                <Input type="number" value={formData.selling_price_1} onChange={(e) => {
                  const sp = parseFloat(e.target.value) || 0;
                  const cost = parseFloat(formData.cost_price.toString()) || 0;
                  const markup = cost > 0 ? ((sp - cost) / cost) * 100 : 0;
                  setFormData(prev => ({ ...prev, markup_1: markup, selling_price_1: sp }));
                }} />
              </div>
            </div>
          </TabsContent>

          <TabsContent value="price2" className="mt-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Markup %</label>
                <Input type="number" value={formData.markup_2} onChange={(e) => handleMarkupChange('markup_2', parseFloat(e.target.value) || 0)} />
              </div>
              <div>
                <label className="text-sm font-medium">Selling Price 2</label>
                <Input type="number" value={formData.selling_price_2} onChange={(e) => {
                  const sp = parseFloat(e.target.value) || 0;
                  const cost = parseFloat(formData.cost_price.toString()) || 0;
                  const markup = cost > 0 ? ((sp - cost) / cost) * 100 : 0;
                  setFormData(prev => ({ ...prev, markup_2: markup, selling_price_2: sp }));
                }} />
              </div>
            </div>
          </TabsContent>

          <TabsContent value="price3" className="mt-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Markup %</label>
                <Input type="number" value={formData.markup_3} onChange={(e) => handleMarkupChange('markup_3', parseFloat(e.target.value) || 0)} />
              </div>
              <div>
                <label className="text-sm font-medium">Selling Price 3</label>
                <Input type="number" value={formData.selling_price_3} onChange={(e) => {
                  const sp = parseFloat(e.target.value) || 0;
                  const cost = parseFloat(formData.cost_price.toString()) || 0;
                  const markup = cost > 0 ? ((sp - cost) / cost) * 100 : 0;
                  setFormData(prev => ({ ...prev, markup_3: markup, selling_price_3: sp }));
                }} />
              </div>
            </div>
          </TabsContent>
        </Tabs>
        <div className="mt-4">
          <label className="text-sm font-medium">Maximum Discount %</label>
          <Input type="number" value={formData.maximum_discount_percent} onChange={(e) => setFormData(prev => ({ ...prev, maximum_discount_percent: parseFloat(e.target.value) || 0 }))} />
        </div>
      </Card>

      <Card className="p-6">
        <h2 className="text-lg font-bold mb-4">Options</h2>
        <div className="space-y-4">
          <label className="flex items-center gap-2">
            <input type="checkbox" checked={formData.allow_negative_quantities} onChange={(e) => setFormData(prev => ({ ...prev, allow_negative_quantities: e.target.checked }))} />
            <span>Allow Negative Quantities</span>
          </label>
          <label className="flex items-center gap-2">
            <input type="checkbox" checked={formData.automatic_returns} onChange={(e) => setFormData(prev => ({ ...prev, automatic_returns: e.target.checked }))} />
            <span>Automatic Returns (e.g., empty bottles)</span>
          </label>
        </div>
      </Card>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { getStockItems, deleteStockItem } from '@/lib/stockApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/components/ui/select';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { 
  Loader, Plus, Edit, Trash2, Search, 
  Package, AlertTriangle 
} from 'lucide-react';
import Link from 'next/link';
import { Pagination } from '@/components/ui/pagination';

export default function StockItemsMaintenancePage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(1);
  const queryClient = useQueryClient();

  const { data: stockItems, isLoading } = useQuery({
    queryKey: ['stock-items', searchTerm, page],
    queryFn: () => getStockItems({ search: searchTerm, page }),
  });

  const deleteMutation = useMutation({
    mutationFn: (code: string) => deleteStockItem(code),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['stock-items'] });
    },
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Stock Items Maintenance</h1>
          <p className="text-gray-600 mt-1">Create and manage stock items</p>
        </div>
        <Link href="/dashboard/admin/stock-control/maintenance/items/new">
          <Button className="bg-blue-600 hover:bg-blue-700">
            <Plus className="w-4 h-4 mr-2" />
            New Stock Item
          </Button>
        </Link>
      </div>

      <Card className="p-4">
        <div className="flex gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
            <Input
              placeholder="Search by code or description..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10"
            />
          </div>
          <Select>
            <SelectTrigger className="w-48">
              <SelectValue placeholder="All Departments" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="">All Departments</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </Card>

      <Card>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Code</TableHead>
              <TableHead>Description</TableHead>
              <TableHead>Department</TableHead>
              <TableHead>Supplier</TableHead>
              <TableHead className="text-right">QOH</TableHead>
              <TableHead className="text-right">Cost</TableHead>
              <TableHead className="text-right">Selling</TableHead>
              <TableHead className="text-center">Status</TableHead>
              <TableHead className="text-right">Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {stockItems?.results?.map((item: any) => (
              <TableRow key={item.stock_code}>
                <TableCell className="font-mono">{item.stock_code}</TableCell>
                <TableCell>{item.description}</TableCell>
                <TableCell>{item.department_name || item.department}</TableCell>
                <TableCell>{item.supplier_name || item.supplier}</TableCell>
                <TableCell className="text-right">
                  <span className={item.quantity_on_hand <= 0 ? 'text-red-600 font-bold' : ''}>
                    {item.quantity_on_hand?.toFixed(2)}
                  </span>
                </TableCell>
                <TableCell className="text-right">R {item.cost_price?.toFixed(2)}</TableCell>
                <TableCell className="text-right">R {item.selling_price_1?.toFixed(2)}</TableCell>
                <TableCell className="text-center">
                  {item.quantity_on_hand <= item.reorder_quantity ? (
                    <div title="Low Stock"><AlertTriangle className="w-4 h-4 text-amber-500" /></div>
                  ) : item.quantity_on_hand <= 0 ? (
                    <div title="Out of Stock"><AlertTriangle className="w-4 h-4 text-red-500" /></div>
                  ) : (
                    <div title="In Stock"><Package className="w-4 h-4 text-green-500" /></div>
                  )}
                </TableCell>
                <TableCell className="text-right">
                  <div className="flex justify-end gap-2">
                    <Link href={`/dashboard/admin/stock-control/maintenance/items/${item.stock_code}`}>
                      <Button variant="outline" size="sm"><Edit className="w-3 h-3" /></Button>
                    </Link>
                    <Button 
                      variant="outline" 
                      size="sm"
                      onClick={() => {
                        if (confirm('Delete this item?')) {
                          deleteMutation.mutate(item.stock_code);
                        }
                      }}
                    >
                      <Trash2 className="w-3 h-3 text-red-500" />
                    </Button>
                  </div>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>

        {stockItems?.results && (
          <div className="flex items-center justify-between p-4 border-t">
            <p className="text-sm text-gray-600">
              Showing {((page - 1) * 20) + 1} to {Math.min(page * 20, stockItems.count)} of {stockItems.count}
            </p>
            <Pagination
              currentPage={page}
              totalPages={Math.ceil(stockItems.count / 20)}
              onPageChange={setPage}
            />
          </div>
        )}
      </Card>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { apiRequest } from '@/lib/api';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Plus, Pencil, Trash2, Search, Loader2, ArrowLeft } from 'lucide-react';
import Link from 'next/link';

interface ShrinkWrap {
  id: number;
  shrink_pack_code: string;
  shrink_pack_description?: string;
  bulk_pack_code: string;
  bulk_pack_description?: string;
  conversion_factor: number;
  is_active: boolean;
}

export default function ShrinkWrapsPage() {
  const queryClient = useQueryClient();
  const [searchTerm, setSearchTerm] = useState('');
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<ShrinkWrap | null>(null);
  const [formData, setFormData] = useState({
    shrink_pack_code: '',
    bulk_pack_code: '',
    conversion_factor: 1,
    is_active: true,
  });

  const { data: items, isLoading } = useQuery({
    queryKey: ['shrink-wraps'],
    queryFn: () => apiRequest('/api/v1/stock-control/shrink-wraps/'),
    select: (response) => response.data.results || response.data,
  });

  const { data: stockItems } = useQuery({
    queryKey: ['stock-items'],
    queryFn: () => apiRequest('/api/v1/stock-control/stock-items/'),
    select: (response) => response.data.results || response.data,
  });

  const createMutation = useMutation({
    mutationFn: (data: typeof formData) =>
      apiRequest('/api/v1/stock-control/shrink-wraps/', {
        method: 'POST',
        body: JSON.stringify(data),
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['shrink-wraps'] });
      setIsDialogOpen(false);
      resetForm();
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }: { id: number; data: typeof formData }) =>
      apiRequest(`/api/v1/stock-control/shrink-wraps/${id}/`, {
        method: 'PATCH',
        body: JSON.stringify(data),
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['shrink-wraps'] });
      setIsDialogOpen(false);
      setEditingItem(null);
      resetForm();
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id: number) =>
      apiRequest(`/api/v1/stock-control/shrink-wraps/${id}/`, {
        method: 'DELETE',
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['shrink-wraps'] });
    },
  });

  const resetForm = () => {
    setFormData({
      shrink_pack_code: '',
      bulk_pack_code: '',
      conversion_factor: 1,
      is_active: true,
    });
  };

  const handleEdit = (item: ShrinkWrap) => {
    setEditingItem(item);
    setFormData({
      shrink_pack_code: item.shrink_pack_code,
      bulk_pack_code: item.bulk_pack_code,
      conversion_factor: item.conversion_factor,
      is_active: item.is_active,
    });
    setIsDialogOpen(true);
  };

  const handleDelete = (id: number) => {
    if (window.confirm('Are you sure you want to delete this shrink wrap relationship?')) {
      deleteMutation.mutate(id);
    }
  };

  const handleSubmit = () => {
    if (editingItem) {
      updateMutation.mutate({ id: editingItem.id, data: formData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const filteredItems = items?.filter((item: ShrinkWrap) =>
    item.shrink_pack_code?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.bulk_pack_code?.toLowerCase().includes(searchTerm.toLowerCase())
  ) || [];

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Link href="/dashboard/admin/stock-control">
          <Button variant="outline" size="sm">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
        </Link>
        <div>
          <h1 className="text-3xl font-bold">Shrink Wraps</h1>
          <p className="text-gray-600 mt-1">Manage bulk to unit relationships</p>
        </div>
      </div>

      <Card className="p-6">
        <div className="flex items-center justify-between mb-6">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
            <Input
              placeholder="Search by pack code..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10"
            />
          </div>
          <Button
            onClick={() => {
              resetForm();
              setEditingItem(null);
              setIsDialogOpen(true);
            }}
            className="ml-4"
          >
            <Plus className="w-4 h-4 mr-2" />
            Add Shrink Wrap
          </Button>
        </div>

        {isLoading ? (
          <div className="text-center py-8">
            <Loader2 className="w-6 h-6 animate-spin mx-auto" />
            <p className="text-gray-500 mt-2">Loading shrink wraps...</p>
          </div>
        ) : filteredItems.length === 0 ? (
          <div className="text-center py-8 text-gray-500">
            No shrink wrap relationships found. Click &quot;Add Shrink Wrap&quot; to create one.
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Shrink Pack Code</TableHead>
                <TableHead>Shrink Pack Description</TableHead>
                <TableHead>Bulk Pack Code</TableHead>
                <TableHead>Bulk Pack Description</TableHead>
                <TableHead>Conversion Factor</TableHead>
                <TableHead>Status</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredItems.map((item: ShrinkWrap) => (
                <TableRow key={item.id}>
                  <TableCell className="font-medium">{item.shrink_pack_code}</TableCell>
                  <TableCell>{item.shrink_pack_description || '-'}</TableCell>
                  <TableCell>{item.bulk_pack_code}</TableCell>
                  <TableCell>{item.bulk_pack_description || '-'}</TableCell>
                  <TableCell>{item.conversion_factor}</TableCell>
                  <TableCell>
                    <Badge variant={item.is_active ? 'default' : 'secondary'}>
                      {item.is_active ? 'Active' : 'Inactive'}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-right">
                    <div className="flex items-center justify-end gap-2">
                      <Button variant="ghost" size="sm" onClick={() => handleEdit(item)}>
                        <Pencil className="w-4 h-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleDelete(item.id)}
                        className="text-red-600 hover:text-red-700"
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </Card>

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>
              {editingItem ? 'Edit Shrink Wrap' : 'Add Shrink Wrap'}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm font-medium">Shrink Pack (Unit)</label>
              <Select
                value={formData.shrink_pack_code}
                onValueChange={(value) => setFormData({ ...formData, shrink_pack_code: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select shrink pack" />
                </SelectTrigger>
                <SelectContent>
                  {stockItems?.map((item: any) => (
                    <SelectItem key={item.stock_code} value={item.stock_code}>
                      {item.stock_code} - {item.description}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-sm font-medium">Bulk Pack</label>
              <Select
                value={formData.bulk_pack_code}
                onValueChange={(value) => setFormData({ ...formData, bulk_pack_code: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select bulk pack" />
                </SelectTrigger>
                <SelectContent>
                  {stockItems?.map((item: any) => (
                    <SelectItem key={item.stock_code} value={item.stock_code}>
                      {item.stock_code} - {item.description}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-sm font-medium">Conversion Factor</label>
              <Input
                type="number"
                value={formData.conversion_factor}
                onChange={(e) =>
                  setFormData({ ...formData, conversion_factor: parseInt(e.target.value) || 1 })
                }
                placeholder="e.g., 12"
              />
              <p className="text-xs text-gray-500 mt-1">Number of units per bulk pack</p>
            </div>
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                id="is_active"
                checked={formData.is_active}
                onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                className="w-4 h-4"
              />
              <label htmlFor="is_active" className="text-sm font-medium">
                Active
              </label>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
              Cancel
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={createMutation.isPending || updateMutation.isPending}
            >
              {createMutation.isPending || updateMutation.isPending ? (
                <Loader2 className="w-4 h-4 animate-spin mr-2" />
              ) : null}
              {editingItem ? 'Update' : 'Create'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { stockControlApi } from '@/lib/stockControlApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/components/ui/select';
import {
  Loader, ArrowLeft, Layers, Download,
  TrendingUp, Percent
} from 'lucide-react';
import Link from 'next/link';
import { Pagination } from '@/components/ui/pagination';

export default function DepartmentAnalysisPage() {
  const [page, setPage] = useState(1);
  const [year, setYear] = useState(new Date().getFullYear());
  const [selectedDepartment, setSelectedDepartment] = useState('');

  const years = Array.from({ length: 5 }, (_, i) => new Date().getFullYear() - i);

  // Backend-aggregated sales/cost/profit by department — was previously
  // computed client-side by joining monthlyStats against a full 1000-item
  // stock-items fetch, reading total_sales/total_cost/gross_profit fields
  // that don't exist on StockMonthlyStatisticSerializer (real fields:
  // value_sold/profit_value; cost is derived as value_sold - profit_value),
  // so every number in this report rendered as R0 regardless of real data.
  const { data: rows, isLoading: statsLoading } = useQuery({
    queryKey: ['stats-by-department', year],
    queryFn: () => stockControlApi.enquiries.statsByDepartment({ year }),
    staleTime: 30 * 1000,
  });

  const departments = (rows || []).map((r) => ({ id: r.department_id, name: r.department_name }));

  const byDepartment = (rows || [])
    .filter((r) => !selectedDepartment || r.department_name === selectedDepartment)
    .map((r) => ({
      name: r.department_name,
      totalSales: Number(r.total_sales || 0),
      totalCost: Number(r.total_cost || 0),
      totalProfit: Number(r.total_profit || 0),
      quantitySold: Number(r.total_quantity || 0),
      margin: r.margin_pct,
      itemCount: r.item_count,
    }));

  const totals = byDepartment.length
    ? byDepartment.reduce(
        (acc, d) => ({
          sales: acc.sales + d.totalSales,
          cost: acc.cost + d.totalCost,
          profit: acc.profit + d.totalProfit,
          quantity: acc.quantity + d.quantitySold,
          departmentCount: acc.departmentCount + 1,
          margin: 0,
        }),
        { sales: 0, cost: 0, profit: 0, quantity: 0, departmentCount: 0, margin: 0 }
      )
    : null;
  if (totals) totals.margin = totals.sales > 0 ? (totals.profit / totals.sales) * 100 : 0;

  const paginatedDepts = byDepartment.slice((page - 1) * 10, page * 10);

  const exportToCSV = () => {
    const headers = ['Department', 'Item Count', 'Qty Sold', 'Total Sales', 'Total Cost', 'Gross Profit', 'Margin %'];
    const rows = byDepartment.map((dept: any) => [
      dept.name,
      dept.itemCount,
      dept.quantitySold,
      dept.totalSales.toFixed(2),
      dept.totalCost.toFixed(2),
      dept.totalProfit.toFixed(2),
      dept.margin.toFixed(2)
    ]);

    const csvContent = [headers, ...rows].map(row => row.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `department-analysis-${year}.csv`;
    a.click();
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link href="/dashboard/admin/stock-control/reports">
          <Button variant="outline" size="sm">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
        </Link>
        <div>
          <h1 className="text-3xl font-bold">Department Analysis</h1>
          <p className="text-gray-600 mt-1">Sales analysis by department</p>
        </div>
      </div>

      {/* Filters */}
      <Card className="p-6">
        <div className="flex flex-wrap items-end gap-4">
          <div>
            <label className="text-sm font-medium text-gray-700 mb-1 block">Year</label>
            <Select value={year.toString()} onValueChange={(v) => { setYear(parseInt(v)); setPage(1); }}>
              <SelectTrigger className="w-32">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {years.map(y => (
                  <SelectItem key={y} value={y.toString()}>{y}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div>
            <label className="text-sm font-medium text-gray-700 mb-1 block">Department</label>
            <Select value={selectedDepartment} onValueChange={(v) => { setSelectedDepartment(v); setPage(1); }}>
              <SelectTrigger className="w-48">
                <SelectValue placeholder="All Departments" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="">All Departments</SelectItem>
                {departments.map((dept: any) => (
                  <SelectItem key={dept.id} value={dept.name}>{dept.name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <Button onClick={exportToCSV} variant="outline">
            <Download className="w-4 h-4 mr-2" />
            Export CSV
          </Button>
        </div>
      </Card>

      {/* Summary Stats */}
      {totals && (
        <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
          <Card className="p-4">
            <p className="text-xs text-gray-600 uppercase">Departments</p>
            <p className="text-xl font-bold">{totals.departmentCount}</p>
          </Card>
          <Card className="p-4">
            <p className="text-xs text-gray-600 uppercase">Total Sales</p>
            <p className="text-xl font-bold">R {totals.sales.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</p>
          </Card>
          <Card className="p-4">
            <p className="text-xs text-gray-600 uppercase">Total Cost</p>
            <p className="text-xl font-bold text-red-600">R {totals.cost.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</p>
          </Card>
          <Card className="p-4 border-l-4 border-l-green-500">
            <div className="flex items-center gap-2">
              <TrendingUp className="w-5 h-5 text-green-600" />
              <div>
                <p className="text-xs text-gray-600 uppercase">Gross Profit</p>
                <p className="text-xl font-bold text-green-600">R {totals.profit.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</p>
              </div>
            </div>
          </Card>
          <Card className="p-4 border-l-4 border-l-blue-500">
            <div className="flex items-center gap-2">
              <Percent className="w-5 h-5 text-blue-600" />
              <div>
                <p className="text-xs text-gray-600 uppercase">Avg Margin</p>
                <p className="text-xl font-bold text-blue-600">{totals.margin.toFixed(1)}%</p>
              </div>
            </div>
          </Card>
        </div>
      )}

      {/* Department Table */}
      <Card className="p-6">
        <h3 className="text-lg font-semibold mb-4">Sales by Department</h3>
        
        {statsLoading ? (
          <div className="flex items-center justify-center h-64">
            <Loader className="w-8 h-8 animate-spin text-blue-600" />
          </div>
        ) : paginatedDepts.length > 0 ? (
          <>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b bg-gray-50">
                    <th className="text-left py-3 px-3 font-medium text-gray-600">Department</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Items</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Qty Sold</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Total Sales</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Total Cost</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Gross Profit</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">% of Total</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Margin</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedDepts.map((dept: any) => {
                    const pctOfTotal = totals ? (dept.totalSales / totals.sales) * 100 : 0;
                    return (
                      <tr key={dept.name} className="border-b hover:bg-gray-50">
                        <td className="py-3 px-3 font-medium">
                          <div className="flex items-center gap-2">
                            <Layers className="w-4 h-4 text-gray-400" />
                            {dept.name}
                          </div>
                        </td>
                        <td className="py-3 px-3 text-right">{dept.itemCount}</td>
                        <td className="py-3 px-3 text-right">{dept.quantitySold.toLocaleString('en-ZA')}</td>
                        <td className="py-3 px-3 text-right">R {dept.totalSales.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</td>
                        <td className="py-3 px-3 text-right text-red-600">R {dept.totalCost.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</td>
                        <td className="py-3 px-3 text-right font-medium text-green-600">
                          R {dept.totalProfit.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}
                        </td>
                        <td className="py-3 px-3 text-right">
                          <div className="flex items-center justify-end gap-2">
                            <div className="w-16 h-2 bg-gray-200 rounded-full overflow-hidden">
                              <div className="h-full bg-blue-600" style={{ width: `${pctOfTotal}%` }} />
                            </div>
                            <span className="text-sm">{pctOfTotal.toFixed(1)}%</span>
                          </div>
                        </td>
                        <td className="py-3 px-3 text-right">
                          <span className={`px-2 py-1 rounded text-xs font-medium ${
                            dept.margin >= 30 ? 'bg-green-100 text-green-800' :
                            dept.margin >= 20 ? 'bg-amber-100 text-amber-800' :
                            'bg-red-100 text-red-800'
                          }`}>
                            {dept.margin.toFixed(1)}%
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            {byDepartment.length > 10 && (
              <div className="flex items-center justify-between mt-4 pt-4 border-t">
                <p className="text-sm text-gray-600">
                  Showing {((page - 1) * 10) + 1} to {Math.min(page * 10, byDepartment.length)} of {byDepartment.length} departments
                </p>
                <Pagination
                  currentPage={page}
                  totalPages={Math.ceil(byDepartment.length / 10)}
                  onPageChange={setPage}
                />
              </div>
            )}
          </>
        ) : (
          <div className="text-center py-12">
            <Layers className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <p className="text-gray-600 text-lg">No department data available for {year}</p>
          </div>
        )}
      </Card>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getStockItems, getStockSummary } from '@/lib/stockApi';
import { api } from '@/lib/api';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/components/ui/select';
import {
  Loader, ArrowLeft, Download, Package,
  Filter, AlertTriangle
} from 'lucide-react';
import Link from 'next/link';
import { Pagination } from '@/components/ui/pagination';

const ORDERING_OPTIONS = [
  { value: 'stock_code', label: 'Stock Code' },
  { value: 'description', label: 'Description' },
  { value: 'department', label: 'Department' },
  { value: 'quantity_on_hand', label: 'Quantity on Hand' },
  { value: 'cost_price', label: 'Cost Price' },
  { value: 'selling_price_1', label: 'Selling Price' },
];

export default function DetailsReportPage() {
  const [page, setPage] = useState(1);
  const [filters, setFilters] = useState({
    search: '',
    is_active: 'all',
    department: 'all',
    code_from: '',
    code_to: '',
    ordering: 'stock_code',
  });

  const { data: summary } = useQuery({
    queryKey: ['stock-summary'],
    queryFn: getStockSummary,
    staleTime: 5 * 60 * 1000,
  });

  // Was previously declared in filter state but never had a UI control to
  // set it — always 'all' regardless of what the user picked, since there
  // was no picker at all.
  const { data: departments } = useQuery({
    queryKey: ['departments'],
    queryFn: async () => {
      const response = await api.get('/api/v1/settings/departments/');
      return response.data.results || response.data;
    },
    staleTime: 5 * 60 * 1000,
  });

  const { data: stockItems, isLoading } = useQuery({
    queryKey: ['stock-items-report', filters, page],
    queryFn: () => getStockItems({
      search: filters.search || undefined,
      is_active: filters.is_active === 'all' ? undefined : filters.is_active === 'true',
      department: filters.department === 'all' ? undefined : parseInt(filters.department),
      code_from: filters.code_from || undefined,
      code_to: filters.code_to || undefined,
      page,
      page_size: 25,
      ordering: filters.ordering,
    }),
    staleTime: 30 * 1000,
  });

  const handleFilterChange = (key: string, value: string) => {
    setFilters(prev => ({ ...prev, [key]: value }));
    setPage(1);
  };

  const exportToCSV = () => {
    if (!stockItems?.results) return;
    
    const headers = ['Stock Code', 'Description', 'Department', 'QOH', 'Reorder Qty', 'Cost Price', 'Selling Price 1', 'Active'];
    const rows = stockItems.results.map((item: any) => [
      item.stock_code,
      item.description,
      item.department_detail?.name || '',
      item.quantity_on_hand,
      item.reorder_quantity,
      item.cost_price,
      item.selling_price_1,
      item.is_active ? 'Yes' : 'No'
    ]);

    const csvContent = [headers, ...rows].map(row => row.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `stock-details-${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link href="/dashboard/admin/stock-control/reports">
          <Button variant="outline" size="sm">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
        </Link>
        <div>
          <h1 className="text-3xl font-bold">Stock Details Report</h1>
          <p className="text-gray-600 mt-1">Full item listings with all details</p>
        </div>
      </div>

      {/* Summary Stats */}
      {summary && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Card className="p-4">
            <p className="text-xs text-gray-600 uppercase">Total Items</p>
            <p className="text-xl font-bold">{summary.total_items?.toLocaleString() || 0}</p>
          </Card>
          <Card className="p-4">
            <p className="text-xs text-gray-600 uppercase">Active Items</p>
            <p className="text-xl font-bold text-green-600">{summary.active_items?.toLocaleString() || 0}</p>
          </Card>
          <Card className="p-4">
            <p className="text-xs text-gray-600 uppercase">Inactive Items</p>
            <p className="text-xl font-bold text-gray-600">{summary.inactive_items?.toLocaleString() || 0}</p>
          </Card>
          <Card className="p-4">
            <p className="text-xs text-gray-600 uppercase">Total Value</p>
            <p className="text-xl font-bold text-blue-600">R {(summary.total_value || 0).toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</p>
          </Card>
        </div>
      )}

      {/* Filters */}
      <Card className="p-6">
        <div className="flex items-center gap-2 mb-4">
          <Filter className="w-5 h-5 text-gray-600" />
          <h2 className="text-lg font-semibold">Filters</h2>
        </div>
        
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <label className="text-sm font-medium text-gray-700 mb-1 block">Search</label>
            <Input
              placeholder="Search by code or description..."
              value={filters.search}
              onChange={(e) => handleFilterChange('search', e.target.value)}
            />
          </div>

          <div>
            <label className="text-sm font-medium text-gray-700 mb-1 block">Status</label>
            <Select
              value={filters.is_active}
              onValueChange={(value) => handleFilterChange('is_active', value)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Items</SelectItem>
                <SelectItem value="true">Active Only</SelectItem>
                <SelectItem value="false">Inactive Only</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div>
            <label className="text-sm font-medium text-gray-700 mb-1 block">Department</label>
            <Select
              value={filters.department}
              onValueChange={(value) => handleFilterChange('department', value)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Departments</SelectItem>
                {departments?.map((dept: any) => (
                  <SelectItem key={dept.id} value={dept.id.toString()}>
                    {dept.department_name || dept.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div>
            <label className="text-sm font-medium text-gray-700 mb-1 block">Code From</label>
            <Input
              placeholder="e.g. 1000"
              value={filters.code_from}
              onChange={(e) => handleFilterChange('code_from', e.target.value)}
            />
          </div>

          <div>
            <label className="text-sm font-medium text-gray-700 mb-1 block">Code To</label>
            <Input
              placeholder="e.g. 9999"
              value={filters.code_to}
              onChange={(e) => handleFilterChange('code_to', e.target.value)}
            />
          </div>

          <div>
            <label className="text-sm font-medium text-gray-700 mb-1 block">Sort By</label>
            <Select
              value={filters.ordering}
              onValueChange={(value) => handleFilterChange('ordering', value)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {ORDERING_OPTIONS.map((opt) => (
                  <SelectItem key={opt.value} value={opt.value}>{opt.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="flex items-end">
            <Button onClick={exportToCSV} variant="outline" className="w-full">
              <Download className="w-4 h-4 mr-2" />
              Export CSV
            </Button>
          </div>
        </div>
      </Card>

      {/* Data Table */}
      <Card className="p-6">
        <h3 className="text-lg font-semibold mb-4">Stock Items</h3>
        
        {isLoading ? (
          <div className="flex items-center justify-center h-64">
            <Loader className="w-8 h-8 animate-spin text-blue-600" />
          </div>
        ) : stockItems?.results && stockItems.results.length > 0 ? (
          <>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b bg-gray-50">
                    <th className="text-left py-3 px-3 font-medium text-gray-600">Stock Code</th>
                    <th className="text-left py-3 px-3 font-medium text-gray-600">Description</th>
                    <th className="text-left py-3 px-3 font-medium text-gray-600">Department</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">QOH</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Reorder</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Cost</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Sell Price</th>
                    <th className="text-center py-3 px-3 font-medium text-gray-600">Status</th>
                  </tr>
                </thead>
                <tbody>
                  {stockItems.results.map((item: any) => (
                    <tr key={item.stock_code} className="border-b hover:bg-gray-50">
                      <td className="py-3 px-3 font-mono">{item.stock_code}</td>
                      <td className="py-3 px-3 max-w-xs truncate">{item.description}</td>
                      <td className="py-3 px-3">{item.department_detail?.name || '-'}</td>
                      <td className={`py-3 px-3 text-right font-medium ${
                        item.quantity_on_hand <= 0 ? 'text-red-600' :
                        item.quantity_on_hand <= item.reorder_quantity ? 'text-amber-600' : ''
                      }`}>
                        {item.quantity_on_hand?.toFixed(2)}
                      </td>
                      <td className="py-3 px-3 text-right text-gray-600">
                        {item.reorder_quantity?.toFixed(2)}
                      </td>
                      <td className="py-3 px-3 text-right">
                        R {item.cost_price?.toFixed(2)}
                      </td>
                      <td className="py-3 px-3 text-right">
                        R {item.selling_price_1?.toFixed(2)}
                      </td>
                      <td className="py-3 px-3 text-center">
                        {item.quantity_on_hand <= item.reorder_quantity && item.quantity_on_hand > 0 ? (
                          <span className="inline-flex items-center px-2 py-1 rounded text-xs bg-amber-100 text-amber-800">
                            <AlertTriangle className="w-3 h-3 mr-1" /> Low
                          </span>
                        ) : item.quantity_on_hand <= 0 ? (
                          <span className="inline-flex items-center px-2 py-1 rounded text-xs bg-red-100 text-red-800">
                            Out
                          </span>
                        ) : item.is_active ? (
                          <span className="px-2 py-1 rounded text-xs bg-green-100 text-green-800">Active</span>
                        ) : (
                          <span className="px-2 py-1 rounded text-xs bg-gray-100 text-gray-800">Inactive</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {stockItems.count > 25 && (
              <div className="flex items-center justify-between mt-4 pt-4 border-t">
                <p className="text-sm text-gray-600">
                  Showing {((page - 1) * 25) + 1} to {Math.min(page * 25, stockItems.count)} of {stockItems.count} items
                </p>
                <Pagination
                  currentPage={page}
                  totalPages={Math.ceil(stockItems.count / 25)}
                  onPageChange={setPage}
                />
              </div>
            )}
          </>
        ) : (
          <div className="text-center py-12">
            <Package className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <p className="text-gray-600 text-lg">No stock items found</p>
          </div>
        )}
      </Card>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { stockControlApi } from '@/lib/stockControlApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/components/ui/select';
import {
  Loader, ArrowLeft, TrendingUp, Download, Search,
  DollarSign, Percent
} from 'lucide-react';
import Link from 'next/link';
import { Pagination } from '@/components/ui/pagination';

export default function GrossProfitReportPage() {
  const [page, setPage] = useState(1);
  const [year, setYear] = useState(new Date().getFullYear());
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStockCode, setSelectedStockCode] = useState('');

  const years = Array.from({ length: 5 }, (_, i) => new Date().getFullYear() - i);

  // Backend-aggregated sales/cost/profit by item (+ monthly trend when a
  // specific item is selected) — was previously computed client-side from
  // monthlyStats rows reading total_sales/total_cost/gross_profit and
  // stock_item_detail?.description, none of which exist on
  // StockMonthlyStatisticSerializer, so every number here rendered R0 and
  // Description was always blank. selectedStockCode also had no UI path
  // to ever become non-empty — the search box only filtered a list that
  // was already empty of real data — so item-scoped trend was dead too;
  // clicking a row below now sets it for real.
  const { data: stats, isLoading: statsLoading } = useQuery({
    queryKey: ['stats-by-item', year, selectedStockCode],
    queryFn: () => stockControlApi.enquiries.statsByItem({
      year,
      stock_item: selectedStockCode || undefined,
    }),
    staleTime: 30 * 1000,
  });

  const byItem = (stats?.by_item || []).map((r) => ({
    stock_code: r.stock_item_id,
    description: r.description || '',
    totalSales: Number(r.total_sales || 0),
    totalCost: Number(r.total_cost || 0),
    totalProfit: Number(r.total_profit || 0),
    quantitySold: Number(r.total_quantity || 0),
    margin: r.margin_pct,
  }));

  const totals = byItem.length
    ? byItem.reduce(
        (acc, item) => ({
          totalSales: acc.totalSales + item.totalSales,
          totalCost: acc.totalCost + item.totalCost,
          totalProfit: acc.totalProfit + item.totalProfit,
          quantitySold: acc.quantitySold + item.quantitySold,
          margin: 0,
        }),
        { totalSales: 0, totalCost: 0, totalProfit: 0, quantitySold: 0, margin: 0 }
      )
    : null;
  if (totals) totals.margin = totals.totalSales > 0 ? (totals.totalProfit / totals.totalSales) * 100 : 0;

  const byMonth = (stats?.by_month || []).map((m) => ({
    month: m.month,
    totalSales: Number(m.total_sales || 0),
    totalCost: Number(m.total_cost || 0),
    totalProfit: Number(m.total_profit || 0),
    quantitySold: Number(m.total_quantity || 0),
  }));

  // Filter by search term
  const filteredItems = searchTerm
    ? byItem.filter((item) =>
        item.stock_code.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.description?.toLowerCase().includes(searchTerm.toLowerCase())
      )
    : byItem;

  const paginatedItems = filteredItems.slice((page - 1) * 25, page * 25);

  const exportToCSV = () => {
    const headers = ['Stock Code', 'Description', 'Qty Sold', 'Total Sales', 'Total Cost', 'Gross Profit', 'Margin %'];
    const rows = filteredItems.map((item: any) => [
      item.stock_code,
      item.description || '',
      item.quantitySold,
      item.totalSales.toFixed(2),
      item.totalCost.toFixed(2),
      item.totalProfit.toFixed(2),
      item.margin.toFixed(2)
    ]);

    const csvContent = [headers, ...rows].map(row => row.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `gross-profit-report-${year}.csv`;
    a.click();
  };

  const handleStockSelect = (code: string) => {
    setSelectedStockCode(code);
    setSearchTerm('');
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link href="/dashboard/admin/stock-control/reports">
          <Button variant="outline" size="sm">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
        </Link>
        <div>
          <h1 className="text-3xl font-bold">Gross Profit Report</h1>
          <p className="text-gray-600 mt-1">Profitability analysis by item</p>
        </div>
      </div>

      {/* Filters */}
      <Card className="p-6">
        <div className="flex flex-wrap items-end gap-4">
          <div>
            <label className="text-sm font-medium text-gray-700 mb-1 block">Year</label>
            <Select value={year.toString()} onValueChange={(v) => setYear(parseInt(v))}>
              <SelectTrigger className="w-32">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {years.map(y => (
                  <SelectItem key={y} value={y.toString()}>{y}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="flex-1 min-w-64">
            <label className="text-sm font-medium text-gray-700 mb-1 block">Stock Item (Optional)</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
              <Input
                placeholder="Search for specific item..."
                value={searchTerm}
                onChange={(e) => {
                  setSearchTerm(e.target.value);
                  if (e.target.value) setSelectedStockCode('');
                }}
                className="pl-10"
              />
            </div>
          </div>

          {selectedStockCode && (
            <Button variant="ghost" onClick={() => setSelectedStockCode('')} className="text-red-600">
              Clear Filter
            </Button>
          )}

          <Button onClick={exportToCSV} variant="outline">
            <Download className="w-4 h-4 mr-2" />
            Export CSV
          </Button>
        </div>
      </Card>

      {/* Summary Stats */}
      {totals && (
        <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
          <Card className="p-4">
            <p className="text-xs text-gray-600 uppercase">Total Sales</p>
            <p className="text-xl font-bold">R {totals.totalSales.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</p>
          </Card>
          <Card className="p-4">
            <p className="text-xs text-gray-600 uppercase">Total Cost</p>
            <p className="text-xl font-bold text-red-600">R {totals.totalCost.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</p>
          </Card>
          <Card className="p-4 border-l-4 border-l-green-500">
            <div className="flex items-center gap-2">
              <TrendingUp className="w-5 h-5 text-green-600" />
              <div>
                <p className="text-xs text-gray-600 uppercase">Gross Profit</p>
                <p className="text-xl font-bold text-green-600">R {totals.totalProfit.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</p>
              </div>
            </div>
          </Card>
          <Card className="p-4 border-l-4 border-l-blue-500">
            <div className="flex items-center gap-2">
              <Percent className="w-5 h-5 text-blue-600" />
              <div>
                <p className="text-xs text-gray-600 uppercase">Avg Margin</p>
                <p className="text-xl font-bold text-blue-600">{totals.margin?.toFixed(1)}%</p>
              </div>
            </div>
          </Card>
          <Card className="p-4">
            <p className="text-xs text-gray-600 uppercase">Items Sold</p>
            <p className="text-xl font-bold">{totals.quantitySold.toLocaleString('en-ZA')}</p>
          </Card>
        </div>
      )}

      {/* Monthly Trend */}
      <Card className="p-6">
        <h3 className="text-lg font-semibold mb-4">
          Monthly Trend {selectedStockCode && `— ${selectedStockCode}`}
        </h3>
        {!selectedStockCode ? (
          <p className="text-gray-500 text-center py-8">Click an item below to see its monthly trend</p>
        ) : statsLoading ? (
          <div className="flex items-center justify-center h-32">
            <Loader className="w-6 h-6 animate-spin text-blue-600" />
          </div>
        ) : byMonth.length > 0 ? (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="border-b bg-gray-50">
                  <th className="text-left py-3 px-3 font-medium text-gray-600">Month</th>
                  <th className="text-right py-3 px-3 font-medium text-gray-600">Qty Sold</th>
                  <th className="text-right py-3 px-3 font-medium text-gray-600">Sales</th>
                  <th className="text-right py-3 px-3 font-medium text-gray-600">Cost</th>
                  <th className="text-right py-3 px-3 font-medium text-gray-600">Profit</th>
                  <th className="text-right py-3 px-3 font-medium text-gray-600">Margin</th>
                </tr>
              </thead>
              <tbody>
                {byMonth.map((month: any) => {
                  const margin = month.totalSales > 0 ? (month.totalProfit / month.totalSales) * 100 : 0;
                  const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
                  return (
                    <tr key={month.month} className="border-b hover:bg-gray-50">
                      <td className="py-3 px-3 font-medium">{monthNames[month.month - 1]}</td>
                      <td className="py-3 px-3 text-right">{month.quantitySold.toLocaleString('en-ZA')}</td>
                      <td className="py-3 px-3 text-right">R {month.totalSales.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</td>
                      <td className="py-3 px-3 text-right text-red-600">R {month.totalCost.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</td>
                      <td className="py-3 px-3 text-right font-medium text-green-600">R {month.totalProfit.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</td>
                      <td className="py-3 px-3 text-right">
                        <span className={`px-2 py-1 rounded text-xs font-medium ${
                          margin >= 30 ? 'bg-green-100 text-green-800' :
                          margin >= 20 ? 'bg-amber-100 text-amber-800' :
                          'bg-red-100 text-red-800'
                        }`}>
                          {margin.toFixed(1)}%
                        </span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        ) : (
          <p className="text-gray-500 text-center py-8">No data available for {year}</p>
        )}
      </Card>

      {/* By Item Table */}
      <Card className="p-6">
        <h3 className="text-lg font-semibold mb-4">Profitability by Item</h3>
        
        {statsLoading ? (
          <div className="flex items-center justify-center h-64">
            <Loader className="w-8 h-8 animate-spin text-blue-600" />
          </div>
        ) : paginatedItems.length > 0 ? (
          <>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b bg-gray-50">
                    <th className="text-left py-3 px-3 font-medium text-gray-600">Stock Code</th>
                    <th className="text-left py-3 px-3 font-medium text-gray-600">Description</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Qty Sold</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Sales</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Cost</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Profit</th>
                    <th className="text-right py-3 px-3 font-medium text-gray-600">Margin</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedItems.map((item: any) => (
                    <tr
                      key={item.stock_code}
                      onClick={() => handleStockSelect(item.stock_code)}
                      className={`border-b hover:bg-gray-50 cursor-pointer ${selectedStockCode === item.stock_code ? 'bg-blue-50' : ''}`}
                      title="Click to view this item's monthly trend"
                    >
                      <td className="py-3 px-3 font-mono">{item.stock_code}</td>
                      <td className="py-3 px-3 max-w-xs truncate">{item.description}</td>
                      <td className="py-3 px-3 text-right">{item.quantitySold.toLocaleString('en-ZA')}</td>
                      <td className="py-3 px-3 text-right">R {item.totalSales.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</td>
                      <td className="py-3 px-3 text-right text-red-600">R {item.totalCost.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}</td>
                      <td className="py-3 px-3 text-right font-medium text-green-600">
                        R {item.totalProfit.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}
                      </td>
                      <td className="py-3 px-3 text-right">
                        <span className={`px-2 py-1 rounded text-xs font-medium ${
                          item.margin >= 30 ? 'bg-green-100 text-green-800' :
                          item.margin >= 20 ? 'bg-amber-100 text-amber-800' :
                          'bg-red-100 text-red-800'
                        }`}>
                          {item.margin.toFixed(1)}%
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {filteredItems.length > 25 && (
              <div className="flex items-center justify-between mt-4 pt-4 border-t">
                <p className="text-sm text-gray-600">
                  Showing {((page - 1) * 25) + 1} to {Math.min(page * 25, filteredItems.length)} of {filteredItems.length} items
                </p>
                <Pagination
                  currentPage={page}
                  totalPages={Math.ceil(filteredItems.length / 25)}
                  onPageChange={setPage}
                />
              </div>
            )}
          </>
        ) : (
          <div className="text-center py-12">
            <DollarSign className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <p className="text-gray-600 text-lg">No profit data available for {year}</p>
          </div>
        )}
      </Card>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { stockControlApi } from '@/lib/stockControlApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Loader, ArrowLeft, ArrowDown, ArrowUp } from 'lucide-react';
import Link from 'next/link';
import { Pagination } from '@/components/ui/pagination';

export default function ReceivedReturnedReportPage() {
  const [page, setPage] = useState(1);
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [stockItem, setStockItem] = useState('');

  const { data, isLoading } = useQuery({
    queryKey: ['received-returned-report', dateFrom, dateTo, stockItem, page],
    queryFn: () => stockControlApi.enquiries.receivedReturnedReport({
      date_from: dateFrom || undefined,
      date_to: dateTo || undefined,
      stock_item: stockItem || undefined,
      page,
      page_size: 25,
    }),
    staleTime: 30 * 1000,
  });

  const totalPages = data ? Math.ceil(data.count / 25) : 1;

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Link href="/dashboard/admin/stock-control/reports">
          <Button variant="outline" size="sm">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
        </Link>
        <div>
          <h1 className="text-3xl font-bold">Stock Received / Returned Report</h1>
          <p className="text-gray-600 mt-1">Incoming stock and supplier returns together</p>
        </div>
      </div>

      <Card className="p-6">
        <div className="flex flex-wrap items-end gap-4">
          <div>
            <label className="text-sm font-medium text-gray-700 mb-1 block">Stock Code</label>
            <input
              type="text"
              value={stockItem}
              onChange={(e) => { setStockItem(e.target.value); setPage(1); }}
              placeholder="Filter by stock code..."
              className="px-3 py-2 border rounded-lg"
            />
          </div>
          <div>
            <label className="text-sm font-medium text-gray-700 mb-1 block">From</label>
            <input type="date" value={dateFrom} onChange={(e) => { setDateFrom(e.target.value); setPage(1); }} className="px-3 py-2 border rounded-lg" />
          </div>
          <div>
            <label className="text-sm font-medium text-gray-700 mb-1 block">To</label>
            <input type="date" value={dateTo} onChange={(e) => { setDateTo(e.target.value); setPage(1); }} className="px-3 py-2 border rounded-lg" />
          </div>
        </div>
      </Card>

      <Card className="p-6">
        <h2 className="text-xl font-semibold mb-4">Movements</h2>
        {isLoading ? (
          <div className="flex items-center justify-center h-32">
            <Loader className="w-6 h-6 animate-spin text-blue-600" />
          </div>
        ) : !data?.results || data.results.length === 0 ? (
          <p className="text-gray-500 text-center py-12">No received or returned stock found</p>
        ) : (
          <>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b bg-gray-50">
                    <th className="text-left py-3 px-4 font-medium text-gray-600">Date</th>
                    <th className="text-left py-3 px-4 font-medium text-gray-600">Type</th>
                    <th className="text-left py-3 px-4 font-medium text-gray-600">Stock Code</th>
                    <th className="text-left py-3 px-4 font-medium text-gray-600">Description</th>
                    <th className="text-right py-3 px-4 font-medium text-gray-600">Quantity</th>
                    <th className="text-right py-3 px-4 font-medium text-gray-600">Unit Cost</th>
                    <th className="text-left py-3 px-4 font-medium text-gray-600">Comments</th>
                  </tr>
                </thead>
                <tbody>
                  {data.results.map((tx: any) => {
                    const isReceived = tx.transaction_type === 'INCOMING';
                    return (
                      <tr key={tx.id} className="border-b hover:bg-gray-50">
                        <td className="py-3 px-4">
                          {tx.transaction_date ? new Date(tx.transaction_date).toLocaleDateString('en-ZA') : '-'}
                        </td>
                        <td className="py-3 px-4">
                          <span className={`inline-flex items-center gap-1 px-2 py-1 rounded text-xs font-medium ${
                            isReceived ? 'bg-green-100 text-green-800' : 'bg-amber-100 text-amber-800'
                          }`}>
                            {isReceived ? <ArrowDown className="w-3 h-3" /> : <ArrowUp className="w-3 h-3" />}
                            {isReceived ? 'Received' : 'Returned'}
                          </span>
                        </td>
                        <td className="py-3 px-4 font-mono">{tx.stock_item}</td>
                        <td className="py-3 px-4">{tx.stock_item_detail?.description}</td>
                        <td className={`py-3 px-4 text-right font-medium ${isReceived ? 'text-green-600' : 'text-amber-600'}`}>
                          {isReceived ? '+' : '-'}{Number(isReceived ? tx.quantity_in : tx.quantity_out).toFixed(2)}
                        </td>
                        <td className="py-3 px-4 text-right">R {Number(tx.unit_cost || 0).toFixed(2)}</td>
                        <td className="py-3 px-4 text-gray-600">{tx.comments || '-'}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
            {totalPages > 1 && (
              <div className="mt-4 flex justify-center">
                <Pagination currentPage={page} totalPages={totalPages} onPageChange={setPage} />
              </div>
            )}
          </>
        )}
      </Card>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { stockControlApi } from '@/lib/stockControlApi';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/components/ui/select';
import { 
  Loader, Search, ArrowLeft, Download, AlertTriangle, 
  Package, ArrowRight
} from 'lucide-react';
import Link from 'next/link';
import { Pagination } from '@/components/ui/pagination';

export default function ReorderReportPage() {
  const [page, setPage] = useState(1);
  const [filters, setFilters] = useState({
    search: '',
    level: 'all',
  });

  // Filtered + server-side-paginated list for the table. search/level are
  // now real backend params (StockItemViewSet.low_stock) instead of being
  // fetched in full and refiltered client-side on every keystroke.
  const { data: lowStockItems, isLoading } = useQuery({
    queryKey: ['low-stock-items', filters, page],
    queryFn: () => stockControlApi.stockItems.getLowStock({
      search: filters.search || undefined,
      level: filters.level === 'all' ? undefined : (filters.level as 'critical' | 'low'),
      page,
      page_size: 25,
    }),
    staleTime: 30 * 1000,
  });

  // Unfiltered list for the summary cards, which reflect the whole
  // reorder list regardless of the search/level filters above.
  const { data: allLowStock } = useQuery({
    queryKey: ['low-stock-items-all'],
    queryFn: () => stockControlApi.stockItems.getLowStock({ page_size: 1000 }),
    staleTime: 30 * 1000,
  });

  const handleFilterChange = (key: string, value: string) => {
    setFilters(prev => ({ ...prev, [key]: value }));
    setPage(1);
  };

  const exportToCSV = () => {
    if (!allLowStock?.results) return;

    const headers = ['Stock Code', 'Description', 'QOH', 'Reorder Qty', 'Shortage', 'Cost Price', 'Reorder Value', 'Status'];
    const rows = allLowStock.results.map((item: any) => [
      item.stock_code,
      item.description || '',
      item.quantity_on_hand,
      item.reorder_quantity,
      Math.max(0, item.reorder_quantity - item.quantity_on_hand),
      item.cost_price,
      Math.max(0, item.reorder_quantity - item.quantity_on_hand) * item.cost_price,
      item.quantity_on_hand <= 0 ? 'OUT OF STOCK' : 'LOW STOCK'
    ]);

    const csvContent = [headers, ...rows].map(row => row.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `reorder-report-${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  // Calculate summary stats
  const allItems = allLowStock?.results || [];
  const outOfStock = allItems.filter((item: any) => item.quantity_on_hand <= 0);
  const lowStock = allItems.filter((item: any) => item.quantity_on_hand > 0 && item.quantity_on_hand <= item.reorder_quantity);
  const totalReorderValue = allItems.reduce((sum: number, item: any) => {
    const shortage = Math.max(0, item.reorder_quantity - item.quantity_on_hand);
    return sum + (shortage * (item.cost_price || 0));
  }, 0);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link href="/dashboard/admin/stock-control/reports">
          <Button variant="outline" size="sm">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
        </Link>
        <div>
          <h1 className="text-3xl font-bold">Re-Order Report</h1>
          <p className="text-gray-600 mt-1">Items at or below reorder level</p>
        </div>
      </div>

      {/* Summary Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="p-6 border-l-4 border-l-red-500">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-gray-600 uppercase">Out of Stock</p>
              <p className="text-2xl font-bold text-red-600 mt-1">{outOfStock.length}</p>
            </div>
            <Package className="w-8 h-8 text-red-200" />
          </div>
        </Card>

        <Card className="p-6 border-l-4 border-l-amber-500">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-gray-600 uppercase">Low Stock</p>
              <p className="text-2xl font-bold text-amber-600 mt-1">{lowStock.length}</p>
            </div>
            <AlertTriangle className="w-8 h-8 text-amber-200" />
          </div>
        </Card>

        <Card className="p-6 border-l-4 border-l-blue-500">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-gray-600 uppercase">Total Items</p>
              <p className="text-2xl font-bold text-blue-600 mt-1">{allItems.length}</p>
            </div>
            <Package className="w-8 h-8 text-blue-200" />
          </div>
        </Card>

        <Card className="p-6 border-l-4 border-l-purple-500">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-gray-600 uppercase">Reorder Value</p>
              <p className="text-2xl font-bold text-purple-600 mt-1">
                R {totalReorderValue.toLocaleString('en-ZA', { maximumFractionDigits: 0 })}
              </p>
            </div>
            <Download className="w-8 h-8 text-purple-200" />
          </div>
        </Card>
      </div>

      {/* Filters */}
      <Card className="p-6">
        <div className="flex items-center gap-2 mb-4">
          <Search className="w-5 h-5 text-gray-600" />
          <h2 className="text-lg font-semibold">Filters</h2>
        </div>
        
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
