                  className="w-full px-3 py-2 border rounded-lg"
                  placeholder="e.g., Main Stockfinder Account"
                />
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Base URL *</label>
                <input
                  type="url"
                  value={formData.base_url}
