          <h1 className="text-2xl font-bold text-gray-900">Cash Control</h1>
          <p className="text-sm text-gray-500">Daily till reconciliation for {user?.username || 'the current cashier'}</p>
        </div>
        <div>
          <label className="text-xs text-gray-500 block mb-1">Date</label>
          <Input type="date" value={controlDate} onChange={(e) => setControlDate(e.target.value)} />
        </div>
      </div>

      <div className="p-6 space-y-6">
        {error && (
          <Card className="border-red-200 bg-red-50">
            <CardContent className="pt-6 flex gap-3">
              <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0" />
              <p className="text-red-800">{error}</p>
            </CardContent>
          </Card>
        )}

        {loading ? (
          <p className="text-gray-600">Loading cash control...</p>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <TrendingUp className="w-5 h-5 text-green-600" />
                  Cash Summary
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Cash Sales</span>
                  <span className="font-bold">R{num(summary?.total_sales)}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Receipts on Account</span>
                  <span className="font-bold">R{num(summary?.total_receipts)}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">New Laybyes (Deposits)</span>
                  <span className="font-bold">R{num(summary?.total_new_laybyes)}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Laybye Receipts</span>
                  <span className="font-bold">R{num(summary?.total_laybye_receipts)}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Cash Refunds</span>
                  <span className="font-bold text-red-600">-R{num(summary?.total_refunds)}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Credit Notes</span>
                  <span className="font-bold text-red-600">-R{num(summary?.total_credits)}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Payouts</span>
                  <span className="font-bold text-red-600">-R{num(summary?.total_payouts)}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Cashed Cheques</span>
                  <span className="font-bold text-red-600">-R{num(summary?.total_cashed_cheques)}</span>
                </div>
                <div className="border-t pt-3">
                  <div className="flex justify-between items-center">
                    <span className="font-bold">Expected Cash</span>
                    <span className="text-xl font-bold text-blue-900">R{num(summary?.cash_expected)}</span>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Clock className="w-5 h-5 text-purple-600" />
                  Takings By Tender
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Cash</span>
                  <span className="font-bold">R{num(summary?.cash_takings)}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Cheque</span>
                  <span className="font-bold">R{num(summary?.cheque_takings)}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Speedpoint / Card</span>
                  <span className="font-bold">R{num(summary?.speedpoint_takings)}</span>
                </div>
              </CardContent>
            </Card>

            <Card className="md:col-span-2">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Clock className="w-5 h-5 text-purple-600" />
                  Hourly Analysis
                </CardTitle>
              </CardHeader>
              <CardContent>
                {activeHours.length === 0 ? (
                  <p className="text-center py-4 text-sm text-gray-500">
                    No cash sales recorded for this date
                  </p>
                ) : (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b">
                          <th className="text-left py-2">Hour</th>
                          <th className="text-right py-2">Transactions</th>
                          <th className="text-right py-2">Sales Value</th>
                        </tr>
                      </thead>
                      <tbody>
                        {activeHours.map((h) => (
                          <tr key={h.hour} className="border-b hover:bg-gray-50">
                            <td className="py-2">{String(h.hour).padStart(2, '0')}:00</td>
                            <td className="py-2 text-right">{h.transaction_count}</td>
                            <td className="py-2 text-right font-medium">R{num(h.total_value)}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/useAuth';
import { usePOSAPI } from '@/lib/posApi';
import { getApiErrorMessage } from '@/lib/api';
import Link from 'next/link';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { ArrowLeft, Plus, Trash2, AlertCircle } from 'lucide-react';
import { StockItemPicker } from '@/components/pos';

export default function CreateCashReturnPage() {
  const router = useRouter();
  const { user } = useAuth();
  const posAPI = usePOSAPI(user?.tenant?.slug);

  const [formData, setFormData] = useState({
    return_date: new Date().toISOString().split('T')[0],
    original_sale_number: '',
    customer_name: '',
    line_items: [{ stock_code: '', description: '', qty: 1, price: 0, total: 0 }],
    return_total: 0,
    reason: '',
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleLineItemChange = (index: number, field: string, value: any) => {
    const newItems = [...formData.line_items];
    newItems[index] = { ...newItems[index], [field]: value };
    
    if (field === 'qty' || field === 'price') {
      const qty = field === 'qty' ? value : newItems[index].qty;
      const price = field === 'price' ? value : newItems[index].price;
      newItems[index].total = qty * price;
    }
    
    const newData = { ...formData, line_items: newItems };
    newData.return_total = newData.line_items.reduce((sum, item) => sum + (item.total || 0), 0);
    setFormData(newData);
  };

  const handleLineItemStockSelect = (
    index: number,
    item: { stock_code: string; description: string; selling_price: number }
  ) => {
    const newItems = [...formData.line_items];
    const qty = newItems[index].qty || 1;
    newItems[index] = {
      ...newItems[index],
      stock_code: item.stock_code,
      description: item.description,
      price: item.selling_price,
      total: qty * item.selling_price,
    };
    const return_total = newItems.reduce((sum, i) => sum + (i.total || 0), 0);
    setFormData((prev) => ({ ...prev, line_items: newItems, return_total }));
  };

  const addLineItem = () => {
    setFormData(prev => ({
      ...prev,
      line_items: [
        ...prev.line_items,
        { stock_code: '', description: '', qty: 1, price: 0, total: 0 }
      ]
    }));
  };

  const removeLineItem = (index: number) => {
    const newItems = formData.line_items.filter((_, i) => i !== index);
    const return_total = newItems.reduce((sum, item) => sum + (item.total || 0), 0);
    setFormData(prev => ({
      ...prev,
      line_items: newItems,
      return_total: return_total
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      if (!formData.original_sale_number) {
        setError('Please enter the original sale number');
        return;
      }
      if (!formData.reason) {
        setError('Please enter a reason for the return');
        return;
      }
      if (formData.line_items.length === 0 || formData.line_items.every((i) => !i.stock_code)) {
        setError('Please add at least one line item');
        return;
      }

      const returnNumber = `CR-${Date.now()}`;

      await posAPI.createCashReturn({
        return_number: returnNumber,
        return_date: formData.return_date,
        original_sale_number: formData.original_sale_number,
        customer_name: formData.customer_name,
        reason: formData.reason,
        lines: formData.line_items
          .filter((item) => item.stock_code)
          .map((item, index) => ({
            line_number: index + 1,
            stock_code: item.stock_code,
            description: item.description,
            quantity: item.qty,
            unit_price: item.price,
            tax_code: 1,
          })),
      });

      setSuccess(true);
      setTimeout(() => router.push('/dashboard/pos/cash-return'), 2000);
    } catch (err: unknown) {
      setError(getApiErrorMessage(err, 'Failed to create cash return'));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-6xl mx-auto px-4">
        {/* Header */}
        <div className="flex items-center gap-4 mb-6">
          <Link href="/dashboard/pos/cash-return">
            <Button variant="ghost" size="sm" className="gap-2">
              <ArrowLeft className="w-4 h-4" />
              Back
            </Button>
          </Link>
          <h1 className="text-3xl font-bold text-gray-900">Cash Return - Refund</h1>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Error Alert */}
          {error && (
            <Card className="border-red-200 bg-red-50">
              <CardContent className="pt-6 flex gap-3">
                <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0" />
                <p className="text-red-800">{error}</p>
              </CardContent>
            </Card>
          )}

          {/* Success Alert */}
          {success && (
            <Card className="border-green-200 bg-green-50">
              <CardContent className="pt-6">
                <p className="text-green-800">Cash return created successfully! Redirecting...</p>
              </CardContent>
            </Card>
          )}

          {/* Header Section */}
          <Card>
            <CardHeader>
              <CardTitle>Return Details</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Return Date
                  </label>
                  <Input
                    type="date"
                    name="return_date"
                    value={formData.return_date}
                    onChange={handleInputChange}
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Customer Name
                  </label>
                  <Input
                    type="text"
                    name="customer_name"
                    placeholder="Optional"
                    value={formData.customer_name}
                    onChange={handleInputChange}
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Original Sale Number *
                </label>
                <Input
                  type="text"
                  name="original_sale_number"
                  placeholder="e.g. CS-000123"
                  value={formData.original_sale_number}
                  onChange={handleInputChange}
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Reason *
                </label>
                <textarea
                  name="reason"
                  placeholder="Reason for the return"
                  rows={2}
                  value={formData.reason}
                  onChange={handleInputChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  required
                />
              </div>
            </CardContent>
          </Card>

          <p className="text-sm text-gray-500 -mt-2">
            Cash returns always refund from the till. To credit a debtor account or arrange a
            replacement instead, use a Credit Note.
          </p>

          {/* Items Returned Section */}
          <Card>
            <CardHeader>
              <CardTitle>Items Returned</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b">
                      <th className="text-left py-2">Stock Code</th>
                      <th className="text-left py-2">Description</th>
                      <th className="text-center py-2">Qty</th>
                      <th className="text-right py-2">Price</th>
                      <th className="text-right py-2">Total</th>
                      <th className="text-center py-2"></th>
                    </tr>
                  </thead>
                  <tbody>
                    {formData.line_items.map((item, index) => (
                      <tr key={index} className="border-b hover:bg-gray-50">
                        <td className="py-2 min-w-[180px]">
                          <StockItemPicker
                            onSelect={(stockItem) => handleLineItemStockSelect(index, stockItem)}
                            placeholder={item.stock_code || 'Search stock...'}
                          />
                        </td>
                        <td className="py-2 px-2">
                          <Input
                            type="text"
                            placeholder="Description"
                            value={item.description}
                            onChange={(e) => handleLineItemChange(index, 'description', e.target.value)}
                            className="w-full"
                          />
                        </td>
                        <td className="py-2 px-2 text-center">
                          <Input
                            type="number"
                            min="1"
                            value={item.qty}
                            onChange={(e) => handleLineItemChange(index, 'qty', parseFloat(e.target.value))}
                            className="w-16 text-center"
                          />
                        </td>
                        <td className="py-2 px-2 text-right">
                          <Input
                            type="number"
                            step="0.01"
                            value={item.price}
                            onChange={(e) => handleLineItemChange(index, 'price', parseFloat(e.target.value))}
                            className="w-24 text-right"
                          />
                        </td>
                        <td className="py-2 px-2 text-right font-medium">
                          R{item.total?.toFixed(2) || '0.00'}
                        </td>
                        <td className="py-2 px-2 text-center">
                          <button
                            type="button"
                            onClick={() => removeLineItem(index)}
                            className="text-red-600 hover:text-red-700"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <Button
                type="button"
                onClick={addLineItem}
                variant="outline"
                className="gap-2"
              >
                <Plus className="w-4 h-4" />
                Add Line Item
              </Button>
            </CardContent>
          </Card>

          {/* Refund Summary */}
          <Card>
            <CardContent className="pt-6">
              <div className="bg-red-50 p-4 rounded-lg border border-red-200">
                <p className="text-sm text-gray-600 mb-1">Total Refund Amount</p>
                <p className="text-3xl font-bold text-red-900">R{formData.return_total.toFixed(2)}</p>
              </div>
            </CardContent>
          </Card>

          {/* Action Buttons */}
          <div className="flex justify-between gap-4">
            <Link href="/dashboard/pos/cash-return">
              <Button variant="outline">Cancel</Button>
            </Link>
            <Button type="submit" disabled={loading} className="bg-blue-600 hover:bg-blue-700">
              {loading ? 'Processing...' : 'Process Return'}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useAuth } from '@/lib/useAuth';
import { usePOSAPI } from '@/lib/posApi';
import { useRouter, useParams } from 'next/navigation';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Loader2, ArrowLeft, Printer, FileText } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { DebtorPicker } from '@/components/pos/DebtorPicker';
import type { MaybeAxiosError } from '@/lib/types/errors';

export default function CashSaleDetailPage() {
  const { user, isLoading: authLoading } = useAuth();
  const router = useRouter();
  const params = useParams();
  const posAPI = usePOSAPI(user?.tenant?.slug);

  const [sale, setSale] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Manual §4 "Cash Sale" note: "To convert a Cash Sale into an Account
  // Sale, press [Page Down] at the Tender Routine." Only offered while the
  // sale hasn't been posted/cancelled yet.
  const [convertDialogOpen, setConvertDialogOpen] = useState(false);
  const [selectedDebtor, setSelectedDebtor] = useState<{ account_number: string; name: string } | null>(null);
  const [converting, setConverting] = useState(false);
  const [convertError, setConvertError] = useState<string | null>(null);

  const handleConvert = async () => {
    if (!selectedDebtor) {
      setConvertError('Select a customer to charge this sale to');
      return;
    }
    setConverting(true);
    setConvertError(null);
    try {
      const result: any = await posAPI.convertCashSaleToInvoice(sale.id, selectedDebtor.account_number);
      const invoiceId = result?.invoice?.id;
      if (invoiceId) {
        router.push(`/dashboard/pos/invoices/${invoiceId}`);
      } else {
        setConvertDialogOpen(false);
      }
    } catch (err: unknown) {
      console.error('Error converting cash sale to invoice:', err);
      setConvertError((err as MaybeAxiosError).message || 'Failed to convert to account sale');
    } finally {
      setConverting(false);
    }
  };

  useEffect(() => {
    const fetchSale = async () => {
      if (!params.id || authLoading || !user) return;
      
      try {
        setLoading(true);
        const data = await posAPI.getCashSale(params.id as string);
        setSale(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load cash sale');
      } finally {
        setLoading(false);
      }
    };

    fetchSale();
  }, [params.id, posAPI, authLoading, user]);

  if (authLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
      </div>
    );
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-8">
        <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-red-700">
          {error}
        </div>
        <Button onClick={() => router.back()} className="mt-4">
          Go Back
        </Button>
      </div>
    );
  }

  if (!sale) {
    return (
      <div className="p-8">
        <p>No sale found</p>
        <Button onClick={() => router.push('/dashboard/pos/cash-sales')}>
          Back to List
        </Button>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 p-8">
      <div className="max-w-4xl mx-auto">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-4">
            <Button variant="outline" size="icon" onClick={() => router.back()}>
              <ArrowLeft className="h-4 w-4" />
            </Button>
            <div>
              <h1 className="text-2xl font-bold">Cash Sale</h1>
              <p className="text-gray-600">
                Sale #{sale.sale_number || sale.id}
              </p>
            </div>
          </div>
          <div className="flex gap-2">
            {!sale.is_posted && !sale.is_cancelled && (
              <Button
                variant="outline"
                onClick={() => {
                  setSelectedDebtor(null);
                  setConvertError(null);
                  setConvertDialogOpen(true);
                }}
              >
                <FileText className="h-4 w-4 mr-2" />
                Convert to Account Sale
              </Button>
            )}
            <Button variant="outline">
              <Printer className="h-4 w-4 mr-2" />
              Print
            </Button>
          </div>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>Sale Details</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <p className="text-sm text-gray-600">Date</p>
                <p className="font-medium">{sale.sale_date}</p>
              </div>
              <div>
                <p className="text-sm text-gray-600">Sale Number</p>
                <p className="font-medium">{sale.sale_number}</p>
              </div>
              {sale.customer_name && (
                <div>
                  <p className="text-sm text-gray-600">Customer</p>
                  <p className="font-medium">{sale.customer_name}</p>
                </div>
              )}
              {sale.cashier_name && (
                <div>
                  <p className="text-sm text-gray-600">Cashier</p>
                  <p className="font-medium">{sale.cashier_name}</p>
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {sale.lines && sale.lines.length > 0 && (
          <Card className="mt-6">
            <CardHeader>
              <CardTitle>Line Items</CardTitle>
            </CardHeader>
            <CardContent>
              <table className="w-full">
                <thead>
                  <tr className="border-b">
                    <th className="text-left py-2">Item</th>
                    <th className="text-right py-2">Qty</th>
                    <th className="text-right py-2">Price</th>
                    <th className="text-right py-2">Total</th>
                  </tr>
                </thead>
                <tbody>
                  {sale.lines.map((line: any, index: number) => (
                    <tr key={index} className="border-b">
                      <td className="py-2">
                        <p className="font-medium">{line.description}</p>
                        <p className="text-sm text-gray-500">{line.stock_code}</p>
                      </td>
                      <td className="text-right py-2">{line.quantity}</td>
                      <td className="text-right py-2">R{Number(line.unit_price || 0).toFixed(2)}</td>
                      <td className="text-right py-2">R{Number(line.line_total || 0).toFixed(2)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </CardContent>
          </Card>
        )}

        {sale.tenders && sale.tenders.length > 0 && (
          <Card className="mt-6">
            <CardHeader>
              <CardTitle>Payments</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                {sale.tenders.map((tender: any, index: number) => (
                  <div key={index} className="flex justify-between">
                    <span>{tender.tender_type}</span>
                    <span className="font-medium">R{Number(tender.amount || 0).toFixed(2)}</span>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        <div className="mt-6 flex justify-end">
          <Card className="w-64">
            <CardContent className="pt-6">
              <div className="flex justify-between mb-2">
                <span>Subtotal:</span>
                <span>R{Number(sale.subtotal || 0).toFixed(2)}</span>
              </div>
              <div className="flex justify-between mb-2">
                <span>VAT:</span>
                <span>R{Number(sale.vat_amount || 0).toFixed(2)}</span>
              </div>
              <div className="flex justify-between font-bold text-lg">
                <span>Total:</span>
                <span>R{Number(sale.total_amount || 0).toFixed(2)}</span>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>

      <Dialog open={convertDialogOpen} onOpenChange={setConvertDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Convert to Account Sale</DialogTitle>
            <DialogDescription>
              Select the customer to charge this sale to. A draft invoice will be created and this cash sale will be cancelled.
            </DialogDescription>
          </DialogHeader>
          <div className="py-4">
            <DebtorPicker onSelect={setSelectedDebtor} />
            {selectedDebtor && (
              <p className="text-sm text-gray-600 mt-2">Selected: {selectedDebtor.name}</p>
            )}
            {convertError && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-3 py-2 rounded-lg text-sm mt-3">
                {convertError}
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setConvertDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleConvert} disabled={converting || !selectedDebtor}>
              {converting ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Converting...
                </>
              ) : (
                'Convert'
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useAuth } from '@/lib/useAuth';
import { usePOSAPI, LineItem, TenderData, CashSaleCreateData } from '@/lib/posApi';
import { useRouter } from 'next/navigation';
import { StockItemPicker, GPBadge } from '@/components/pos';
export default function CreateCashSale() {
  const { user } = useAuth();
  const router = useRouter();
  const posAPI = usePOSAPI(user?.tenant?.slug);

  const [formData, setFormData] = useState({
    sale_date: new Date().toISOString().split('T')[0],
    notes: '',
  });

  const [lineItems, setLineItems] = useState<LineItem[]>([
    {
      stock_code: '',  // Use 'stock_code' to match backend
      description: '',
      quantity: 1,
      unit_price: 0,
      discount_percentage: 0,
      tax_code: 1, // STANDARD - 14% VAT
    },
  ]);

  // Track cost prices for GP calculation (not sent to backend)
  const [costPrices, setCostPrices] = useState<{ [key: number]: number }>({});

  const [tenders, setTenders] = useState<TenderData[]>([
    {
      tender_type: 'CASH',
      amount: 0,
    },
  ]);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [totals, setTotals] = useState({
    subtotal: 0,
    tax: 0,
    total: 0,
  });
  const [change, setChange] = useState(0);

  // Calculate totals
  useEffect(() => {
    const newTotals = lineItems.reduce(
      (acc, item) => {
        const lineAmount = item.quantity * item.unit_price;
        const discount = (lineAmount * (item.discount_percentage || 0)) / 100;
        const taxableAmount = lineAmount - discount;
        const taxRate = item.tax_code === 0 ? 0 : item.tax_code === 1 ? 0.14 : 0;
        const tax = taxableAmount * taxRate;

        return {
          subtotal: acc.subtotal + taxableAmount,
          tax: acc.tax + tax,
          total: acc.total + taxableAmount + tax,
        };
      },
      { subtotal: 0, tax: 0, total: 0 }
    );

    setTotals(newTotals);

    // Calculate change
    const tenderTotal = tenders.reduce((sum, t) => sum + (t.amount || 0), 0);
    setChange(tenderTotal - newTotals.total);
  }, [lineItems, tenders]);

  const addLineItem = () => {
    setLineItems([
      ...lineItems,
      {
        stock_code: '',  // Use 'stock_code' to match backend
        description: '',
        quantity: 1,
        unit_price: 0,
        discount_percentage: 0,
        tax_code: 1, // STANDARD - 14% VAT
      },
    ]);
  };

  const removeLineItem = (index: number) => {
    setLineItems(lineItems.filter((_, i) => i !== index));
  };

  const updateLineItem = (index: number, field: string, value: any) => {
    const updated = [...lineItems];
    updated[index] = { ...updated[index], [field]: value };
    setLineItems(updated);
  };

  const addTender = () => {
    setTenders([
      ...tenders,
      {
        tender_type: 'CASH',
        amount: 0,
      },
    ]);
  };

  const removeTender = (index: number) => {
    setTenders(tenders.filter((_, i) => i !== index));
  };

  const updateTender = (index: number, field: string, value: any) => {
    const updated = [...tenders];
    updated[index] = { ...updated[index], [field]: value };
    setTenders(updated);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (lineItems.some((item) => !item.stock_code || !item.quantity || !item.unit_price)) {
      setError('All line items must have item code, quantity, and selling price');
      return;
    }

    if (tenders.some((t) => !t.tender_type || !t.amount)) {
      setError('All tenders must have type and amount');
      return;
    }

    const tenderTotal = tenders.reduce((sum, t) => sum + (t.amount || 0), 0);
    if (tenderTotal < totals.total) {
      setError('Tender amount must be at least equal to the total');
      return;
    }

    try {
      setLoading(true);
      setError(null);

      const saleData: CashSaleCreateData = {
        sale_date: formData.sale_date,
        lines: lineItems,
        tenders: tenders,
        notes: formData.notes,
      };

      console.log('Submitting Cash Sale data:', JSON.stringify(saleData, null, 2));
      
      const result = await posAPI.createCashSale(saleData);
      console.log('Cash Sale created, result:', result);
      
      // Get the sale ID - could be 'id' or 'pk' or the sale_number
      const saleId = result.id || result.pk || result.sale_number;
      console.log('Sale ID:', saleId);
      
      if (saleId) {
        router.push(`/dashboard/pos/cash-sales/${saleId}`);
      } else {
        // Go back to the list if no ID available
        router.push('/dashboard/pos/cash-sales');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create cash sale');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 p-8">
      <div className="max-w-6xl mx-auto">
        <h1 className="text-3xl font-bold text-gray-900 mb-8">Cash Sale</h1>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-8">
          {/* Header Information */}
          <div className="bg-white rounded-lg shadow p-6">
            <h2 className="text-xl font-semibold mb-4">Sale Details</h2>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Sale Date *
              </label>
              <input
                type="date"
                value={formData.sale_date}
                onChange={(e) =>
                  setFormData({ ...formData, sale_date: e.target.value })
                }
                className="w-full md:w-1/3 px-4 py-2 border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500"
                required
              />
            </div>
          </div>

          {/* Line Items */}
          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-semibold">Items</h2>
              <button
                type="button"
                onClick={addLineItem}
                className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm"
              >
                + Add Item
              </button>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-2 py-2 text-left w-48">Item</th>
                    <th className="px-2 py-2 text-left">Description</th>
                    <th className="px-2 py-2 text-right w-20">Qty</th>
                    <th className="px-2 py-2 text-right w-24">Price</th>
                    <th className="px-2 py-2 text-right w-20">Disc %</th>
                    <th className="px-2 py-2 text-left w-24">Tax</th>
                    <th className="px-2 py-2 text-right w-24">Total</th>
                    <th className="px-2 py-2 text-center w-20">GP</th>
                    <th className="px-2 py-2 text-center w-16">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {lineItems.map((item, index) => {
                    const lineAmount = item.quantity * item.unit_price;
                    const discount = (lineAmount * (item.discount_percentage || 0)) / 100;
                    const taxableAmount = lineAmount - discount;
                    const taxRate = item.tax_code === 0 ? 0 : item.tax_code === 1 ? 0.14 : 0;
                    const tax = taxableAmount * taxRate;
                    const lineTotal = taxableAmount + tax;
                    const costPrice = Number(costPrices[index]) || 0;

                    return (
                      <tr key={index} className="hover:bg-gray-50">
                        <td className="px-2 py-2">
                          <StockItemPicker
                            onSelect={(stockItem) => {
                              console.log('CashSale: Received stockItem:', stockItem);
                              console.log('CashSale: Updating line item at index:', index);
                              
                              // Batch all updates into one state change
                              const updatedItems = [...lineItems];
                              updatedItems[index] = {
                                ...updatedItems[index],
                                stock_code: stockItem.stock_code,  // Use 'stock_code' for backend
                                description: stockItem.description,
                                unit_price: stockItem.selling_price,
                                tax_code: stockItem.tax_code === 'ZERO' ? 0 : stockItem.tax_code === 'REDUCED' ? 2 : 1,
                              };
                              setLineItems(updatedItems);
                              
                              // Update cost prices
                              setCostPrices(prev => ({ ...prev, [index]: stockItem.cost_price }));
                              
                              console.log('CashSale: Line items after update:', updatedItems);
                            }}
                            placeholder="Search item..."
                          />
                        </td>
                        <td className="px-2 py-2">
                          <input
                            type="text"
                            value={item.description}
                            onChange={(e) =>
                              updateLineItem(index, 'description', e.target.value)
                            }
                            className="w-full px-2 py-1 border rounded text-sm"
                            placeholder="Description"
                          />
                        </td>
                        <td className="px-2 py-2">
                          <input
                            type="number"
                            value={item.quantity}
                            onChange={(e) =>
                              updateLineItem(index, 'quantity', Number(e.target.value))
                            }
                            className="w-full px-2 py-1 border rounded text-sm text-right"
                            min="0"
                          />
                        </td>
                        <td className="px-2 py-2">
                          <input
                            type="number"
                            value={item.unit_price}
                            onChange={(e) =>
                              updateLineItem(index, 'unit_price', Number(e.target.value))
                            }
                            className="w-full px-2 py-1 border rounded text-sm text-right"
                            min="0"
                            step="0.01"
                          />
                        </td>
                        <td className="px-2 py-2">
                          <input
                            type="number"
                            value={item.discount_percentage || 0}
                            onChange={(e) =>
                              updateLineItem(index, 'discount_percentage', Number(e.target.value))
                            }
                            className="w-full px-2 py-1 border rounded text-sm text-right"
                            min="0"
                            max="100"
                            step="0.01"
                          />
                        </td>
                        <td className="px-2 py-2">
                          <select
                            value={item.tax_code}
                            onChange={(e) =>
                              updateLineItem(index, 'tax_code', Number(e.target.value))
                            }
                            className="w-full px-2 py-1 border rounded text-sm"
                          >
                            <option value={0}>Zero-rated (0%)</option>
                            <option value={1}>Standard (14%)</option>
                          </select>
                        </td>
                        <td className="px-2 py-2 text-right">
                          {lineTotal.toFixed(2)}
                        </td>
                        <td className="px-4 py-2 text-center">
                          {item.quantity > 0 && item.unit_price > 0 ? (
                            <GPBadge 
                              sellingPrice={Number(item.unit_price)} 
                              costPrice={Number(costPrice)} 
                              quantity={Number(item.quantity)} 
                            />
                          ) : (
                            <span className="text-gray-400">-</span>
                          )}
                        </td>
                        <td className="px-2 py-2 text-center">
                          <button
                            type="button"
                            onClick={() => removeLineItem(index)}
                            className="text-red-600 hover:text-red-800 text-sm disabled:opacity-50"
                            disabled={lineItems.length === 1}
                          >
                            ✕
                          </button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            {/* GP Summary */}
            {lineItems.some(item => item.quantity > 0 && item.unit_price > 0) && (
              <div className="mt-4 p-4 bg-green-50 rounded-lg">
                <div className="flex justify-between items-center">
                  <span className="font-medium text-gray-700">Total Gross Profit:</span>
                  <div className="text-right">
                    {(() => {
                      const totalGP = lineItems.reduce((sum, item, idx) => {
                        const cost = Number(costPrices[idx]) || 0;
                        return sum + ((Number(item.unit_price) - cost) * Number(item.quantity));
                      }, 0);
                      const totalSales = lineItems.reduce((sum, item) => sum + (Number(item.unit_price) * Number(item.quantity)), 0);
                      const gpPercent = totalSales > 0 ? (totalGP / totalSales) * 100 : 0;
                      return (
                        <>
                          <span className="text-xl font-bold text-green-700">R{totalGP.toFixed(2)}</span>
                          <span className="text-sm text-green-600 ml-2">({gpPercent.toFixed(1)}%)</span>
                        </>
                      );
                    })()}
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Tenders */}
          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-semibold">Payment Methods</h2>
              <button
                type="button"
                onClick={addTender}
                className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg text-sm"
              >
                + Add Payment
              </button>
            </div>

            <div className="space-y-4">
              {tenders.map((tender, index) => (
                <div key={index} className="flex gap-4 items-end pb-4 border-b">
                  <div className="flex-1">
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Payment Type
                    </label>
                    <select
                      value={tender.tender_type}
                      onChange={(e) =>
                        updateTender(index, 'tender_type', e.target.value)
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                    >
                      <option value="CASH">Cash</option>
                      <option value="CHEQUE">Cheque</option>
                      <option value="CREDIT_CARD">Credit Card</option>
                      <option value="EFT">EFT</option>
                    </select>
                  </div>

                  <div className="flex-1">
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Amount
                    </label>
                    <input
                      type="number"
                      value={tender.amount}
                      onChange={(e) =>
                        updateTender(index, 'amount', Number(e.target.value))
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-right"
                      min="0"
                      step="0.01"
                    />
                  </div>

                  {tender.tender_type === 'CHEQUE' && (
                    <div className="flex-1">
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        Cheque No
                      </label>
                      <input
                        type="text"
                        value={tender.drawer_name || ''}  // Use 'drawer_name' for backend
                        onChange={(e) =>
                          updateTender(index, 'drawer_name', e.target.value)  // Use 'drawer_name'
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                  )}

                  <button
                    type="button"
                    onClick={() => removeTender(index)}
                    className="text-red-600 hover:text-red-800 px-4 py-2"
                  >
                    Delete
                  </button>
                </div>
              ))}
            </div>
          </div>

          {/* Totals and Change */}
          <div className="bg-white rounded-lg shadow p-6 flex justify-end">
            <div className="w-64 space-y-3">
              <div className="flex justify-between pb-2 border-b">
                <span>Subtotal:</span>
                <span>{totals.subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between pb-2 border-b">
                <span>Tax:</span>
                <span>{totals.tax.toFixed(2)}</span>
              </div>
              <div className="flex justify-between font-bold text-lg pb-2 border-b">
                <span>Total:</span>
                <span>{totals.total.toFixed(2)}</span>
              </div>
              <div className="flex justify-between font-semibold text-green-600">
                <span>Change:</span>
                <span>{change >= 0 ? change.toFixed(2) : '(' + Math.abs(change).toFixed(2) + ')'}</span>
              </div>
            </div>
          </div>

          {/* Actions */}
          <div className="flex gap-4">
            <button
              type="submit"
              disabled={loading || change < 0}
              className="bg-green-600 hover:bg-green-700 disabled:bg-gray-400 text-white px-6 py-2 rounded-lg font-medium"
            >
              {loading ? 'Processing...' : 'Complete Sale'}
            </button>
            <button
              type="button"
              onClick={() => router.back()}
              className="bg-gray-300 hover:bg-gray-400 text-gray-800 px-6 py-2 rounded-lg font-medium"
            >
              Cancel
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

