'use client';

import { useState, useEffect } from 'react';
import { useAuth } from '@/lib/useAuth';
import { usePOSAPI } from '@/lib/posApi';
import { useRouter, useParams } from 'next/navigation';
import Link from 'next/link';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ArrowLeft, Printer, Share2, Loader2, Mail, CheckCircle2, Percent, PencilLine } from 'lucide-react';
import { printInvoice, emailInvoice } from '@/lib/printUtils';
import { GrossProfitDisplay, GPBadge } from '@/components/pos/GrossProfitDisplay';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import type { TenderData } from '@/lib/posApi';
import type { MaybeAxiosError } from '@/lib/types/errors';

const TENDER_TYPES: { value: TenderData['tender_type']; label: string }[] = [
  { value: 'CASH', label: 'Cash' },
  { value: 'SPEEDPOINT', label: 'Card / Speedpoint' },
  { value: 'EFT', label: 'EFT' },
  { value: 'CHEQUE', label: 'Cheque' },
  { value: 'VOUCHER', label: 'Voucher' },
];

export default function InvoiceDetail() {
  const { user, isLoading: authLoading } = useAuth();
  const router = useRouter();
  const params = useParams();
  const posAPI = usePOSAPI(user?.tenant?.slug);
  
  const [invoice, setInvoice] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
  const [emailAddress, setEmailAddress] = useState('');
  const [sendingEmail, setSendingEmail] = useState(false);
  const [emailSent, setEmailSent] = useState(false);
  const [paymentDialogOpen, setPaymentDialogOpen] = useState(false);
  const [tenderType, setTenderType] = useState<TenderData['tender_type']>('CASH');
  const [paymentAmount, setPaymentAmount] = useState('');
  const [authorizationCode, setAuthorizationCode] = useState('');
  const [drawerName, setDrawerName] = useState('');
  const [bankName, setBankName] = useState('');
  const [recordingPayment, setRecordingPayment] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  // Manual §1 "Invoice - Subtotal Discount Facility"
  const [discountDialogOpen, setDiscountDialogOpen] = useState(false);
  const [discountPercentage, setDiscountPercentage] = useState('');
  const [applyingDiscount, setApplyingDiscount] = useState(false);
  const [discountError, setDiscountError] = useState<string | null>(null);

  // Manual §1 "Invoice - Set Selling Price Facility"
  const [setPriceDialogOpen, setSetPriceDialogOpen] = useState(false);
  const [targetTotal, setTargetTotal] = useState('');
  const [applyingSetPrice, setApplyingSetPrice] = useState(false);
  const [setPriceError, setSetPriceError] = useState<string | null>(null);

  // Manual §1 "H" header re-display/edit facility
  const [headerDialogOpen, setHeaderDialogOpen] = useState(false);
  const [headerForm, setHeaderForm] = useState({
    invoice_date: '',
    due_date: '',
    delivery_name: '',
    order_number: '',
    customer_reference: '',
  });
  const [savingHeader, setSavingHeader] = useState(false);
  const [headerError, setHeaderError] = useState<string | null>(null);

  const invoiceId = params?.id as string;

  useEffect(() => {
    if (!user || authLoading) return;
    
    loadInvoice();
  }, [user, authLoading, invoiceId]);

  const loadInvoice = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const response = await posAPI.getInvoice(invoiceId);
      setInvoice(response);
    } catch (err: unknown) {
      console.error('Error loading invoice:', err);
      setError((err as MaybeAxiosError).message || 'Failed to load invoice');
    } finally {
      setLoading(false);
    }
  };

  const handleEmailInvoice = async () => {
    if (!emailAddress || !invoice) return;
    
    setSendingEmail(true);
    try {
      const result = await emailInvoice(invoice, emailAddress);
      if (result.success) {
        setEmailSent(true);
        setTimeout(() => {
          setEmailDialogOpen(false);
          setEmailSent(false);
          setEmailAddress('');
        }, 2000);
      } else {
        alert(result.message);
      }
    } catch (err: unknown) {
      console.error('Error sending email:', err);
      alert((err as MaybeAxiosError).message || 'Failed to send email');
    } finally {
      setSendingEmail(false);
    }
  };

  const openPaymentDialog = () => {
    if (!invoice) return;
    const balanceDue = Number(invoice.balance_due ?? invoice.total_amount ?? 0);
    setTenderType('CASH');
    setPaymentAmount(balanceDue.toFixed(2));
    setAuthorizationCode('');
    setDrawerName('');
    setBankName('');
    setPayError(null);
    setPaymentDialogOpen(true);
  };

  const handleRecordPayment = async () => {
    if (!invoice) return;

    const amount = Number(paymentAmount);
    if (!amount || amount <= 0) {
      setPayError('Enter a valid payment amount');
      return;
    }

    setRecordingPayment(true);
    setPayError(null);
    try {
      if (!invoice.is_posted && invoice.status === 'DRAFT') {
        await posAPI.postInvoice(invoiceId);
      }

      const tender: TenderData = { tender_type: tenderType, amount };
      if (tenderType === 'SPEEDPOINT' && authorizationCode) {
        tender.authorization_code = authorizationCode;
      }
      if (tenderType === 'CHEQUE') {
        if (drawerName) tender.drawer_name = drawerName;
        if (bankName) tender.bank_name = bankName;
      }

      await posAPI.tenderInvoice(invoiceId, [tender]);

      setPaymentDialogOpen(false);
      await loadInvoice();
    } catch (err: unknown) {
      console.error('Error recording payment:', err);
      setPayError((err as MaybeAxiosError).message || 'Failed to record payment');
    } finally {
      setRecordingPayment(false);
    }
  };

  const handleApplyDiscount = async () => {
    const percentage = Number(discountPercentage);
    if (Number.isNaN(percentage)) {
      setDiscountError('Enter a valid discount percentage');
      return;
    }
    setApplyingDiscount(true);
    setDiscountError(null);
    try {
      await posAPI.applySubtotalDiscountToInvoice(invoiceId, percentage);
      setDiscountDialogOpen(false);
      setDiscountPercentage('');
      await loadInvoice();
    } catch (err: unknown) {
      console.error('Error applying subtotal discount:', err);
      setDiscountError((err as MaybeAxiosError).message || 'Failed to apply discount');
    } finally {
      setApplyingDiscount(false);
    }
  };

  const handleApplySetPrice = async () => {
    const target = Number(targetTotal);
    if (!target || target <= 0) {
      setSetPriceError('Enter a valid total amount');
      return;
    }
    setApplyingSetPrice(true);
    setSetPriceError(null);
    try {
      await posAPI.applySetPriceOnInvoice(invoiceId, target);
      setSetPriceDialogOpen(false);
      setTargetTotal('');
      await loadInvoice();
    } catch (err: unknown) {
      console.error('Error setting invoice total:', err);
      setSetPriceError((err as MaybeAxiosError).message || 'Failed to set price');
    } finally {
      setApplyingSetPrice(false);
    }
  };

  const openHeaderDialog = () => {
    if (!invoice) return;
    setHeaderForm({
      invoice_date: invoice.invoice_date || '',
      due_date: invoice.due_date || '',
      delivery_name: invoice.delivery_name || '',
      order_number: invoice.order_number || '',
      customer_reference: invoice.customer_reference || '',
    });
    setHeaderError(null);
    setHeaderDialogOpen(true);
  };

  const handleSaveHeader = async () => {
    setSavingHeader(true);
    setHeaderError(null);
    try {
      // posApi's partialUpdateInvoice is typed against InvoiceCreateData,
      // which doesn't include due_date/delivery_name/customer_reference
      // under those exact names — the backend serializer does, so this
      // bypasses the (incomplete) TS shape rather than sending wrong keys.
      await posAPI.partialUpdateInvoice(invoiceId, headerForm as any);
      setHeaderDialogOpen(false);
      await loadInvoice();
    } catch (err: unknown) {
      console.error('Error saving invoice header:', err);
      setHeaderError((err as MaybeAxiosError).message || 'Failed to save header');
    } finally {
      setSavingHeader(false);
    }
  };

  if (authLoading || loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 p-6 flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 p-6">
        <div className="max-w-4xl mx-auto">
          <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg">
            <p>{error}</p>
            <Button 
              variant="link" 
              onClick={() => router.push('/dashboard/pos/invoices')}
              className="text-red-700 p-0 h-auto mt-2"
            >
              Back to Invoices
            </Button>
          </div>
        </div>
      </div>
    );
  }

  if (!invoice) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 p-6">
        <div className="max-w-4xl mx-auto">
          <div className="text-center py-12">
            <p className="text-slate-500">Invoice not found</p>
            <Button 
              variant="link" 
              onClick={() => router.push('/dashboard/pos/invoices')}
              className="mt-2"
            >
              Back to Invoices
            </Button>
          </div>
        </div>
      </div>
    );
  }

  const lineItems = invoice.line_items || [];
  const subtotal = lineItems.reduce((sum: number, item: any) => {
    const itemTotal = (item.quantity || 0) * (item.unit_price || item.selling_price || 0);
    const discount = itemTotal * ((item.discount_percentage || 0) / 100);
    return sum + itemTotal - discount;
  }, 0);
  
  const tax = Number(invoice.tax_amount) || 0;
  const total = Number(invoice.total_amount) || Number(subtotal) + tax;

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 p-6">
      <div className="max-w-4xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Link href="/dashboard/pos/invoices">
              <Button variant="ghost" size="icon">
                <ArrowLeft className="h-5 w-5" />
              </Button>
            </Link>
            <div>
              <h1 className="text-2xl font-bold text-slate-900">
                Invoice {invoice.invoice_number}
              </h1>
              <p className="text-sm text-slate-500 mt-0.5">
                {invoice.status === 'PAID'
                  ? 'Paid'
                  : invoice.status === 'PARTIAL_PAID'
                  ? 'Partially Paid'
                  : invoice.is_cancelled || invoice.status === 'CANCELLED' || invoice.status === 'VOID'
                  ? 'Cancelled'
                  : invoice.is_posted
                  ? 'Posted'
                  : 'Pending'}
              </p>
            </div>
          </div>
          <div className="flex flex-wrap gap-2">
            {invoice.status !== 'PAID' &&
              invoice.status !== 'CANCELLED' &&
              invoice.status !== 'VOID' && (
                <Button variant="default" size="sm" onClick={openPaymentDialog}>
                  <CheckCircle2 className="h-4 w-4 mr-2" />
                  Record Payment
                </Button>
              )}
            {invoice.status === 'DRAFT' && (
              <>
                <Button variant="outline" size="sm" onClick={openHeaderDialog}>
                  <PencilLine className="h-4 w-4 mr-2" />
                  Edit Header
                </Button>
                <Button variant="outline" size="sm" onClick={() => { setDiscountError(null); setDiscountDialogOpen(true); }}>
                  <Percent className="h-4 w-4 mr-2" />
                  Subtotal Discount
                </Button>
                <Button variant="outline" size="sm" onClick={() => { setSetPriceError(null); setTargetTotal(total ? total.toFixed(2) : ''); setSetPriceDialogOpen(true); }}>
                  Set Price
                </Button>
              </>
            )}
            <Button variant="outline" size="sm" onClick={() => printInvoice(invoice)}>
              <Printer className="h-4 w-4 mr-2" />
              Print
            </Button>
            <Button variant="outline" size="sm" onClick={() => setEmailDialogOpen(true)}>
              <Share2 className="h-4 w-4 mr-2" />
              Share
            </Button>
          </div>
        </div>

        {/* Invoice Details */}
        <Card>
          <CardHeader>
            <CardTitle>Invoice Details</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
              <div>
                <p className="text-sm text-slate-500">Invoice Date</p>
                <p className="font-medium">{invoice.invoice_date}</p>
              </div>
              <div>
                <p className="text-sm text-slate-500">Due Date</p>
                <p className="font-medium">{invoice.due_date || 'N/A'}</p>
              </div>
              <div>
                <p className="text-sm text-slate-500">Customer</p>
                <p className="font-medium">{invoice.debtor_name || invoice.debtor?.name || invoice.debtor_account_number || 'Unknown'}</p>
              </div>
              {invoice.customer_reference && (
                <div>
                  <p className="text-sm text-slate-500">Customer Ref</p>
                  <p className="font-medium">{invoice.customer_reference}</p>
                </div>
              )}
              {invoice.order_number && (
                <div>
                  <p className="text-sm text-slate-500">Order Number</p>
                  <p className="font-medium">{invoice.order_number}</p>
                </div>
              )}
              <div>
                <p className="text-sm text-slate-500">Total</p>
                <p className="font-bold text-lg">R{total.toFixed(2)}</p>
              </div>
              {invoice.gross_profit !== undefined && (
                <div>
                  <p className="text-sm text-slate-500">Gross Profit</p>
                  <GrossProfitDisplay
                    sellingPrice={Number(invoice.subtotal) || 0}
                    costPrice={Number(invoice.total_cost) || 0}
                    quantity={1}
                  />
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Line Items */}
        <Card>
          <CardHeader>
            <CardTitle>Line Items</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b">
                    <th className="text-left py-3 px-4 font-medium text-slate-600">Item</th>
                    <th className="text-center py-3 px-4 font-medium text-slate-600">Qty</th>
                    <th className="text-right py-3 px-4 font-medium text-slate-600">Unit Price</th>
                    <th className="text-right py-3 px-4 font-medium text-slate-600">Discount</th>
                    <th className="text-right py-3 px-4 font-medium text-slate-600">Total</th>
                    <th className="text-right py-3 px-4 font-medium text-slate-600">GP</th>
                  </tr>
                </thead>
                <tbody>
                  {lineItems.map((item: any, index: number) => {
                    const itemTotal = (item.quantity || 0) * (item.unit_price || item.selling_price || 0);
                    const discount = itemTotal * ((item.discount_percentage || 0) / 100);
                    const lineTotal = itemTotal - discount;

                    return (
                      <tr key={index} className="border-b">
                        <td className="py-3 px-4">
                          <p className="font-medium">{item.stock_code || item.item_code || 'N/A'}</p>
                          <p className="text-sm text-slate-500">{item.description}</p>
                        </td>
                        <td className="text-center py-3 px-4">{item.quantity}</td>
                        <td className="text-right py-3 px-4">R{(item.unit_price || item.selling_price || 0).toFixed(2)}</td>
                        <td className="text-right py-3 px-4">{item.discount_percentage || 0}%</td>
                        <td className="text-right py-3 px-4 font-medium">R{lineTotal.toFixed(2)}</td>
                        <td className="text-right py-3 px-4">
                          {item.cost_price !== undefined && (
                            <GPBadge
                              sellingPrice={item.unit_price || item.selling_price || 0}
                              costPrice={item.cost_price || 0}
                              quantity={item.quantity || 1}
                            />
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
                <tfoot>
                  <tr>
                    <td colSpan={5} className="text-right py-3 px-4 font-medium">Subtotal</td>
                    <td className="text-right py-3 px-4">R{subtotal.toFixed(2)}</td>
                  </tr>
                  <tr>
                    <td colSpan={5} className="text-right py-3 px-4 font-medium">Tax</td>
                    <td className="text-right py-3 px-4">R{tax.toFixed(2)}</td>
                  </tr>
                  <tr className="border-t-2">
                    <td colSpan={5} className="text-right py-3 px-4 font-bold">Total</td>
                    <td className="text-right py-3 px-4 font-bold text-lg">R{total.toFixed(2)}</td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </CardContent>
        </Card>

        {/* Payment History */}
        {invoice.tenders && invoice.tenders.length > 0 && (
          <Card>
            <CardHeader>
              <CardTitle>Payment History</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b">
                      <th className="text-left py-2 px-4 font-medium text-slate-600">Date</th>
                      <th className="text-left py-2 px-4 font-medium text-slate-600">Method</th>
                      <th className="text-left py-2 px-4 font-medium text-slate-600">Reference</th>
                      <th className="text-right py-2 px-4 font-medium text-slate-600">Amount</th>
                    </tr>
                  </thead>
                  <tbody>
                    {invoice.tenders.map((t: any) => (
                      <tr key={t.id} className="border-b">
                        <td className="py-2 px-4 text-slate-600">
                          {t.created_at ? new Date(t.created_at).toLocaleDateString() : '—'}
                        </td>
                        <td className="py-2 px-4">{t.tender_type_display || t.tender_type}</td>
                        <td className="py-2 px-4 text-slate-500">
                          {t.authorization_code || t.drawer_name || '—'}
                        </td>
                        <td className="text-right py-2 px-4 font-medium">
                          R{Number(t.amount).toFixed(2)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Notes */}
        {invoice.notes && (
          <Card>
            <CardHeader>
              <CardTitle>Notes</CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-sm text-slate-600">{invoice.notes}</p>
            </CardContent>
          </Card>
        )}
      </div>

      {/* Email Dialog */}
      <Dialog open={emailDialogOpen} onOpenChange={setEmailDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Email Invoice</DialogTitle>
            <DialogDescription>
              Enter the email address to send this invoice to.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="email" className="text-right">
                Email
              </Label>
              <Input
                id="email"
                type="email"
                placeholder="customer@example.com"
                value={emailAddress}
                onChange={(e) => setEmailAddress(e.target.value)}
                className="col-span-3"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setEmailDialogOpen(false)}>
              Cancel
            </Button>
            <Button 
              onClick={handleEmailInvoice} 
              disabled={!emailAddress || sendingEmail}
            >
              {sendingEmail ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Sending...
                </>
              ) : emailSent ? (
                <>
                  <Mail className="h-4 w-4 mr-2" />
                  Sent!
                </>
              ) : (
                <>
                  <Mail className="h-4 w-4 mr-2" />
                  Send Email
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Record Payment Dialog */}
      <Dialog open={paymentDialogOpen} onOpenChange={setPaymentDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Record Payment</DialogTitle>
            <DialogDescription>
              Capture how this invoice was paid. This creates a payment record you can review later.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="tender-type" className="text-right">
                Method
              </Label>
              <div className="col-span-3">
                <Select
                  value={tenderType}
                  onValueChange={(v) => setTenderType(v as TenderData['tender_type'])}
                >
                  <SelectTrigger id="tender-type">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {TENDER_TYPES.map((t) => (
                      <SelectItem key={t.value} value={t.value}>
                        {t.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="payment-amount" className="text-right">
                Amount
              </Label>
              <Input
                id="payment-amount"
                type="number"
                step="0.01"
                min="0"
                value={paymentAmount}
                onChange={(e) => setPaymentAmount(e.target.value)}
                className="col-span-3"
              />
            </div>

            {tenderType === 'SPEEDPOINT' && (
              <div className="grid grid-cols-4 items-center gap-4">
                <Label htmlFor="auth-code" className="text-right">
                  Auth Code
                </Label>
                <Input
                  id="auth-code"
                  placeholder="Card authorization code"
                  value={authorizationCode}
                  onChange={(e) => setAuthorizationCode(e.target.value)}
                  className="col-span-3"
                />
              </div>
            )}

            {tenderType === 'CHEQUE' && (
              <>
                <div className="grid grid-cols-4 items-center gap-4">
                  <Label htmlFor="drawer-name" className="text-right">
                    Drawer Name
                  </Label>
                  <Input
                    id="drawer-name"
                    value={drawerName}
                    onChange={(e) => setDrawerName(e.target.value)}
                    className="col-span-3"
                  />
                </div>
                <div className="grid grid-cols-4 items-center gap-4">
                  <Label htmlFor="bank-name" className="text-right">
                    Bank
                  </Label>
                  <Input
                    id="bank-name"
                    value={bankName}
                    onChange={(e) => setBankName(e.target.value)}
                    className="col-span-3"
                  />
                </div>
              </>
            )}

            {payError && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-3 py-2 rounded-lg text-sm">
                {payError}
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setPaymentDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleRecordPayment} disabled={recordingPayment}>
              {recordingPayment ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Recording...
                </>
              ) : (
                <>
                  <CheckCircle2 className="h-4 w-4 mr-2" />
                  Record Payment
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Subtotal Discount Dialog — Manual §1 "Invoice - Subtotal Discount Facility" */}
      <Dialog open={discountDialogOpen} onOpenChange={setDiscountDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Apply Subtotal Discount</DialogTitle>
            <DialogDescription>
              Enter a discount % to apply to every line item. A negative value increases prices instead.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="discount-percentage" className="text-right">
                Discount %
              </Label>
              <Input
                id="discount-percentage"
                type="number"
                step="0.01"
                value={discountPercentage}
                onChange={(e) => setDiscountPercentage(e.target.value)}
                className="col-span-3"
              />
            </div>
            {discountError && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-3 py-2 rounded-lg text-sm">
                {discountError}
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDiscountDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleApplyDiscount} disabled={applyingDiscount}>
              {applyingDiscount ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Applying...
                </>
              ) : (
                'Apply Discount'
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Set Price Dialog — Manual §1 "Invoice - Set Selling Price Facility" */}
      <Dialog open={setPriceDialogOpen} onOpenChange={setSetPriceDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Set Invoice Total</DialogTitle>
            <DialogDescription>
              Enter the revised inclusive total. Every line&apos;s price is scaled proportionally to reach it.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="target-total" className="text-right">
                New Total
              </Label>
              <Input
                id="target-total"
                type="number"
                step="0.01"
                min="0"
                value={targetTotal}
                onChange={(e) => setTargetTotal(e.target.value)}
                className="col-span-3"
              />
            </div>
            {setPriceError && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-3 py-2 rounded-lg text-sm">
                {setPriceError}
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setSetPriceDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleApplySetPrice} disabled={applyingSetPrice}>
              {applyingSetPrice ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Applying...
                </>
              ) : (
                'Set Total'
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Header Edit Dialog — Manual §1 "H" header re-display facility */}
      <Dialog open={headerDialogOpen} onOpenChange={setHeaderDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Invoice Header</DialogTitle>
            <DialogDescription>Review or amend the invoice header details.</DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="header-invoice-date" className="text-right">
                Invoice Date
              </Label>
              <Input
                id="header-invoice-date"
                type="date"
                value={headerForm.invoice_date}
                onChange={(e) => setHeaderForm((f) => ({ ...f, invoice_date: e.target.value }))}
                className="col-span-3"
              />
            </div>
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="header-due-date" className="text-right">
                Due Date
              </Label>
              <Input
                id="header-due-date"
                type="date"
                value={headerForm.due_date}
                onChange={(e) => setHeaderForm((f) => ({ ...f, due_date: e.target.value }))}
                className="col-span-3"
              />
            </div>
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="header-delivery-name" className="text-right">
                Delivery Name
              </Label>
              <Input
                id="header-delivery-name"
                value={headerForm.delivery_name}
                onChange={(e) => setHeaderForm((f) => ({ ...f, delivery_name: e.target.value }))}
                className="col-span-3"
              />
            </div>
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="header-order-number" className="text-right">
                Order Number
              </Label>
              <Input
                id="header-order-number"
                value={headerForm.order_number}
                onChange={(e) => setHeaderForm((f) => ({ ...f, order_number: e.target.value }))}
                className="col-span-3"
              />
            </div>
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="header-customer-ref" className="text-right">
                Customer Ref
              </Label>
              <Input
                id="header-customer-ref"
                value={headerForm.customer_reference}
                onChange={(e) => setHeaderForm((f) => ({ ...f, customer_reference: e.target.value }))}
                className="col-span-3"
              />
            </div>
            {headerError && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-3 py-2 rounded-lg text-sm">
                {headerError}
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setHeaderDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSaveHeader} disabled={savingHeader}>
              {savingHeader ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Saving...
                </>
              ) : (
                'Save'
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useAuth } from '@/lib/useAuth';
import { usePOSAPI, LineItem } from '@/lib/posApi';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { ArrowLeft, Plus, Trash2, Check } from 'lucide-react';
import {
  ErrorAlert,
  SuccessAlert,
  LoadingOverlay,
  AccountInfoCard,
  TotalsSummary,
} from '@/components/pos/form-components';
import { DebtorPicker, StockItemPicker } from '@/components/pos';
import type { MaybeAxiosError } from '@/lib/types/errors';

export default function CreateInvoice() {
  const { user, isLoading: authLoading } = useAuth();
  const router = useRouter();

  // FIX 1: stabilise API instance with useRef pattern (same fix as list page)
  const posAPI = usePOSAPI(user?.tenant?.slug);

  const [step, setStep] = useState<'debtor' | 'header' | 'items' | 'review'>('debtor');

  // Debtor
  const [selectedDebtor, setSelectedDebtor] = useState<any>(null);
  const [debtorError, setDebtorError] = useState<string | null>(null);

  // Header
  const [headerData, setHeaderData] = useState({
    invoice_date: new Date().toISOString().split('T')[0],
    delivery_date: '',
    delivery_details: '',
    reg_make_names: '',
    credit_card: '',
    order_number: '',
    customer_ref: '',
    notes: '',
  });

  // Line items
  const [lineItems, setLineItems] = useState<LineItem[]>([]);
  const [currentItem, setCurrentItem] = useState<Partial<LineItem>>({
    stock_code: '',
    item_code: '',
    description: '',
    quantity: 1,
    unit_price: 0,
    selling_price: 0,
    discount_percentage: 0,
    tax_code: 1,
    cost_price: 0,
  });

  // Form state
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  const handleHeaderChange = (field: string, value: string) => {
    setHeaderData((prev) => ({ ...prev, [field]: value }));
  };

  const handleAddLineItem = () => {
    const code = currentItem.stock_code || currentItem.item_code || '';
    if (!code || !currentItem.description || !currentItem.quantity) {
      setError('Please fill in the stock code, description and quantity');
      return;
    }
    const price = currentItem.unit_price || currentItem.selling_price || 0;
    if (price <= 0) {
      setError('Unit price must be greater than zero');
      return;
    }

    const newItem: LineItem = {
      stock_code: code,
      description: currentItem.description || '',
      quantity: Number(currentItem.quantity) || 0,
      unit_price: Number(price),
      discount_percentage: Number(currentItem.discount_percentage) || 0,
      tax_code: Number(currentItem.tax_code) ?? 1,
      cost_price: Number(currentItem.cost_price) || 0,
    };

    setLineItems((prev) => [...prev, newItem]);
    setCurrentItem({
      stock_code: '',
      item_code: '',
      description: '',
      quantity: 1,
      unit_price: 0,
      selling_price: 0,
      discount_percentage: 0,
      tax_code: 1,
      cost_price: 0,
    });
    setError(null);
  };

  const handleRemoveLineItem = (index: number) => {
    setLineItems((prev) => prev.filter((_, i) => i !== index));
  };

  const calculateTotals = () => {
    let subtotal = 0;
    let totalDiscount = 0;
    let totalTax = 0;

    lineItems.forEach((item) => {
      const itemSubtotal = Number(item.quantity) * Number(item.unit_price || 0);
      const discount = itemSubtotal * (Number(item.discount_percentage || 0) / 100);
      const afterDiscount = itemSubtotal - discount;
      // FIX 2: use 14% VAT to match backend, tax_code 1 = standard
      const taxRate = Number(item.tax_code) === 1 ? 0.14 : 0;
      const tax = afterDiscount * taxRate;
      subtotal += itemSubtotal;
      totalDiscount += discount;
      totalTax += tax;
    });

    return {
      subtotal,
      totalDiscount,
      totalTax,
      total: subtotal - totalDiscount + totalTax,
    };
  };

  const handleSubmitInvoice = async () => {
    if (!selectedDebtor) {
      setError('No debtor selected');
      return;
    }
    if (lineItems.length === 0) {
      setError('Please add at least one line item');
      return;
    }

    // FIX 3: debtor_account_number must be a string of the numeric dno field.
    // DebtorPicker returns the debtor object — use dno (the integer PK the backend expects).
    const accountNumber =
      selectedDebtor.dno != null
        ? String(selectedDebtor.dno)
        : selectedDebtor.account_number != null
        ? String(selectedDebtor.account_number)
        : null;

    if (!accountNumber) {
      setError('Could not determine debtor account number. Please re-select the customer.');
      return;
    }

    try {
      setLoading(true);
      setError(null);

      // Backend requires invoice_number — generate a unique one client-side (max 20 chars)
      const today = headerData.invoice_date.replace(/-/g, ''); // YYYYMMDD
      const rand  = Math.floor(Math.random() * 9999).toString().padStart(4, '0');
      const invoiceNumber = `INV-${today}-${rand}`; // e.g. INV-20250318-0042 (19 chars)

      const invoiceData: any = {
        debtor_account_number: accountNumber,
        invoice_number: invoiceNumber,
        invoice_date: headerData.invoice_date,
        // Backend requires 'lines' (not 'line_items') and each line needs a 'line_number'
        lines: lineItems.map((item, index) => ({
          line_number: index + 1,
          stock_code: item.stock_code || '',
          description: item.description || '',
          quantity: Number(item.quantity),
          unit_price: Number(item.unit_price || 0),
          discount_percentage: Number(item.discount_percentage || 0),
          tax_code: Number(item.tax_code ?? 1),
          cost_price: Number(item.cost_price || 0),
        })),
      };

      // Only include optional header fields that actually have values
      // Auto-set created_by to current logged-in user
      if (user?.username) {
        invoiceData.created_by = user.username;
      }
      if (headerData.delivery_date)    invoiceData.due_date      = headerData.delivery_date;
      if (headerData.order_number)     invoiceData.order_number  = headerData.order_number;
      if (headerData.customer_ref)     invoiceData.customer_reference = headerData.customer_ref;
      if (headerData.delivery_details) invoiceData.delivery_name = headerData.delivery_details;
      if (headerData.notes)            invoiceData.notes         = headerData.notes;

      // ── TEMP DEBUG: log exact payload so we can see what hits the backend ──
      console.log('=== INVOICE PAYLOAD ===');
      console.log(JSON.stringify(invoiceData, null, 2));
      console.log('debtor_account_number type:', typeof invoiceData.debtor_account_number, '| value:', invoiceData.debtor_account_number);
      console.log('lines count:', invoiceData.lines?.length);
      invoiceData.lines?.forEach((l: any, i: number) =>
        console.log(`  line[${i}]:`, JSON.stringify(l))
      );
      console.log('========================');

      const _result = await posAPI.createInvoice(invoiceData);
      setSuccess('Invoice created successfully!');
      setTimeout(() => router.push('/dashboard/pos/invoices'), 2000);
    } catch (err: unknown) {
      console.error('Invoice creation error:', err);
      setError((err as MaybeAxiosError)?.message || 'Failed to create invoice');
    } finally {
      setLoading(false);
    }
  };

  const totals = calculateTotals();

  if (authLoading) return <LoadingOverlay message="Loading..." />;

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 p-6">
      <div className="max-w-6xl mx-auto space-y-6">

        {/* Header */}
        <div className="flex items-center gap-4">
          <Link href="/dashboard/pos/invoices">
            <Button variant="ghost" size="icon" className="hover:bg-slate-200">
              <ArrowLeft className="h-5 w-5" />
            </Button>
          </Link>
          <div>
            <h1 className="text-3xl font-bold text-slate-900">Create Invoice</h1>
            <p className="text-slate-600 mt-1">Invoice Option 1: Processing an Invoice</p>
          </div>
        </div>

        {/* Progress */}
        <div className="flex gap-4">
          {(['debtor', 'header', 'items', 'review'] as const).map((s, i) => (
            <div key={s} className="flex items-center gap-2">
              <div
                className={`flex items-center justify-center w-8 h-8 rounded-full text-sm font-medium ${
                  step === s
                    ? 'bg-blue-600 text-white'
                    : 'bg-slate-200 text-slate-600'
                }`}
              >
                {i + 1}
              </div>
              <span className="text-sm font-medium text-slate-600 capitalize">{s}</span>
              {i < 3 && <div className="w-8 h-0.5 bg-slate-200" />}
            </div>
          ))}
        </div>

        {/* Alerts */}
        {error   && <ErrorAlert   message={error} />}
        {success && <SuccessAlert message={success} />}

        {/* ── Step 1: Debtor ────────────────────────────────────── */}
        {step === 'debtor' && (
          <Card>
            <CardHeader>
              <CardTitle>Step 1: Select Customer</CardTitle>
              <CardDescription>Search and select the customer for this invoice</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <label className="text-sm font-medium">Customer</label>
                <DebtorPicker
                  onSelect={(debtor) => {
                    setSelectedDebtor(debtor);
                    setDebtorError(null);
                  }}
                  label="Customer"
                  placeholder="Search customers..."
                />
              </div>

              {selectedDebtor && (
                <AccountInfoCard
                  accountName={selectedDebtor.name || selectedDebtor.dname || ''}
                  accountNumber={
                    selectedDebtor.dno != null
                      ? String(selectedDebtor.dno)
                      : selectedDebtor.account_number || ''
                  }
                  balance={selectedDebtor.balance}
                  creditLimit={selectedDebtor.credit_limit}
                />
              )}

              {debtorError && <ErrorAlert message={debtorError} />}

              <div className="flex justify-end gap-2 pt-4">
                <Button
                  variant="outline"
                  onClick={() => setSelectedDebtor(null)}
                >
                  Clear
                </Button>
                <Button
                  onClick={() => {
                    if (!selectedDebtor) { setDebtorError('Please select a customer'); return; }
                    setDebtorError(null);
                    setStep('header');
                  }}
                  disabled={!selectedDebtor}
                  className="bg-blue-600"
                >
                  <Check className="h-4 w-4 mr-2" />
                  Confirm &amp; Continue
                </Button>
              </div>
            </CardContent>
          </Card>
        )}

        {/* ── Step 2: Header ────────────────────────────────────── */}
        {step === 'header' && selectedDebtor && (
          <Card>
            <CardHeader>
              <CardTitle>Step 2: Invoice Header Details</CardTitle>
              <CardDescription>
                Customer: {selectedDebtor.name || selectedDebtor.dname}
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-sm font-medium">Invoice Date *</label>
                  <Input
                    type="date"
                    value={headerData.invoice_date}
                    onChange={(e) => handleHeaderChange('invoice_date', e.target.value)}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium">Due Date</label>
                  <Input
                    type="date"
                    value={headerData.delivery_date}
                    onChange={(e) => handleHeaderChange('delivery_date', e.target.value)}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-medium">Delivery Name / Details</label>
                <Input
                  placeholder="e.g., Building A, Floor 3"
                  value={headerData.delivery_details}
                  onChange={(e) => handleHeaderChange('delivery_details', e.target.value)}
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-sm font-medium">Order Number</label>
                  <Input
                    placeholder="e.g., ORD-2025-001"
                    value={headerData.order_number}
                    onChange={(e) => handleHeaderChange('order_number', e.target.value)}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium">Customer Reference</label>
                  <Input
                    placeholder="Customer ref"
                    value={headerData.customer_ref}
                    onChange={(e) => handleHeaderChange('customer_ref', e.target.value)}
                  />
                </div>
              </div>

              <div className="flex justify-between gap-2 pt-4">
                <Button variant="outline" onClick={() => setStep('debtor')}>Back</Button>
                <Button onClick={() => setStep('items')} className="bg-blue-600">
                  <Check className="h-4 w-4 mr-2" />
                  Continue to Items
                </Button>
              </div>
            </CardContent>
          </Card>
        )}

        {/* ── Step 3: Line Items ────────────────────────────────── */}
        {step === 'items' && (
          <div className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Step 3: Add Line Items</CardTitle>
                <CardDescription>Search and add products to the invoice</CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-2">
                  <label className="text-sm font-medium">Select Product</label>
                  <StockItemPicker
                    onSelect={(item) => {
                      setCurrentItem({
                        stock_code: item.stock_code,
                        item_code:  item.stock_code,
                        description: item.description,
                        unit_price:    Number(item.selling_price || 0),
                        selling_price: Number(item.selling_price || 0),
                        cost_price:    Number(item.cost_price || 0),
                        // FIX 5: tax_code from stock item is already an integer; guard against string
                        tax_code: typeof item.tax_code === 'number'
                          ? item.tax_code
                          : item.tax_code_detail?.code === 'STANDARD' ? 1
                          : item.tax_code_detail?.code === 'REDUCED'  ? 2
                          : 0,
                        quantity: 1,
                        discount_percentage: 0,
                      });
                    }}
                    label="Product"
                    placeholder="Search products..."
                  />
                </div>

                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Stock Code</label>
                    <Input
                      value={currentItem.item_code || currentItem.stock_code || ''}
                      onChange={(e) => setCurrentItem({ ...currentItem, stock_code: e.target.value, item_code: e.target.value })}
                      placeholder="Code"
                    />
                  </div>
                  <div className="space-y-2 md:col-span-2">
                    <label className="text-sm font-medium">Description</label>
                    <Input
                      value={currentItem.description || ''}
                      onChange={(e) => setCurrentItem({ ...currentItem, description: e.target.value })}
                      placeholder="Description"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Qty</label>
                    <Input
                      type="number"
                      min="0.01"
                      step="0.01"
                      value={currentItem.quantity || ''}
                      onChange={(e) => setCurrentItem({ ...currentItem, quantity: parseFloat(e.target.value) || 0 })}
                      placeholder="1"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Unit Price (excl. VAT)</label>
                    <Input
                      type="number"
                      min="0"
                      step="0.01"
                      value={currentItem.unit_price || currentItem.selling_price || ''}
                      onChange={(e) => {
                        const v = parseFloat(e.target.value) || 0;
                        setCurrentItem({ ...currentItem, unit_price: v, selling_price: v });
                      }}
                      placeholder="0.00"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Discount %</label>
                    <Input
                      type="number"
                      min="0"
                      max="100"
                      step="0.01"
                      value={currentItem.discount_percentage || ''}
                      onChange={(e) => setCurrentItem({ ...currentItem, discount_percentage: parseFloat(e.target.value) || 0 })}
                      placeholder="0"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Tax Code</label>
                    <select
                      value={Number(currentItem.tax_code) ?? 1}
                      onChange={(e) => setCurrentItem({ ...currentItem, tax_code: parseInt(e.target.value) })}
                      className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    >
                      <option value={0}>Zero (0%)</option>
                      <option value={1}>Standard (14%)</option>
                    </select>
                  </div>
                </div>

                <div className="flex justify-end">
                  <Button onClick={handleAddLineItem} className="gap-2 bg-green-600 hover:bg-green-700">
                    <Plus className="h-4 w-4" />
                    Add Item
                  </Button>
                </div>
              </CardContent>
            </Card>

            {lineItems.length > 0 && (
              <Card>
                <CardHeader>
                  <CardTitle>Invoice Items ({lineItems.length})</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead className="bg-slate-50 border-b-2">
                        <tr>
                          <th className="px-4 py-2 text-left">Code</th>
                          <th className="px-4 py-2 text-left">Description</th>
                          <th className="px-4 py-2 text-center">Qty</th>
                          <th className="px-4 py-2 text-right">Unit Price</th>
                          <th className="px-4 py-2 text-right">Discount</th>
                          <th className="px-4 py-2 text-right">VAT</th>
                          <th className="px-4 py-2 text-right">Total</th>
                          <th className="px-4 py-2 text-center"></th>
                        </tr>
                      </thead>
                      <tbody>
                        {lineItems.map((item, index) => {
                          const base     = Number(item.quantity) * Number(item.unit_price || 0);
                          const disc     = base * (Number(item.discount_percentage || 0) / 100);
                          const net      = base - disc;
                          const vat      = Number(item.tax_code) === 1 ? net * 0.14 : 0;
                          const total    = net + vat;
                          return (
                            <tr key={index} className="border-b hover:bg-slate-50">
                              <td className="px-4 py-2 font-mono text-xs">{item.stock_code}</td>
                              <td className="px-4 py-2">{item.description}</td>
                              <td className="px-4 py-2 text-center">{item.quantity}</td>
                              <td className="px-4 py-2 text-right">R{Number(item.unit_price || 0).toFixed(2)}</td>
                              <td className="px-4 py-2 text-right">{item.discount_percentage || 0}%</td>
                              <td className="px-4 py-2 text-right">R{vat.toFixed(2)}</td>
                              <td className="px-4 py-2 text-right font-semibold">R{total.toFixed(2)}</td>
                              <td className="px-4 py-2 text-center">
                                <button onClick={() => handleRemoveLineItem(index)} className="text-red-500 hover:text-red-700">
                                  <Trash2 className="h-4 w-4" />
                                </button>
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </CardContent>
              </Card>
            )}

            <TotalsSummary
              subtotal={totals.subtotal}
              discount={totals.totalDiscount}
              tax={totals.totalTax}
              total={totals.total}
            />

            <div className="flex justify-between gap-2">
              <Button variant="outline" onClick={() => setStep('header')}>Back</Button>
              <Button
                onClick={() => setStep('review')}
                disabled={lineItems.length === 0}
                className="bg-blue-600"
              >
                <Check className="h-4 w-4 mr-2" />
                Review Invoice
              </Button>
            </div>
          </div>
        )}

        {/* ── Step 4: Review ────────────────────────────────────── */}
        {step === 'review' && (
          <div className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Step 4: Review &amp; Submit</CardTitle>
                <CardDescription>Verify all details before creating the invoice</CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                {/* Customer */}
                <div>
                  <h3 className="font-semibold text-slate-900 mb-3">Customer</h3>
                  <div className="grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <p className="text-slate-500">Account #</p>
                      <p className="font-medium">
                        {selectedDebtor?.dno ?? selectedDebtor?.account_number}
                      </p>
                    </div>
                    <div>
                      <p className="text-slate-500">Name</p>
                      <p className="font-medium">{selectedDebtor?.name || selectedDebtor?.dname}</p>
                    </div>
                  </div>
                </div>

                {/* Invoice details */}
                <div>
                  <h3 className="font-semibold text-slate-900 mb-3">Invoice Details</h3>
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-4 text-sm">
                    <div>
                      <p className="text-slate-500">Invoice Date</p>
                      <p className="font-medium">{headerData.invoice_date}</p>
                    </div>
                    {headerData.delivery_date && (
                      <div>
                        <p className="text-slate-500">Due Date</p>
                        <p className="font-medium">{headerData.delivery_date}</p>
                      </div>
                    )}
                    {headerData.order_number && (
                      <div>
                        <p className="text-slate-500">Order #</p>
                        <p className="font-medium">{headerData.order_number}</p>
                      </div>
                    )}
                    {headerData.customer_ref && (
                      <div>
                        <p className="text-slate-500">Customer Ref</p>
                        <p className="font-medium">{headerData.customer_ref}</p>
                      </div>
                    )}
                  </div>
                </div>

                {/* Items */}
                <div>
                  <h3 className="font-semibold text-slate-900 mb-3">Items ({lineItems.length})</h3>
                  <div className="border rounded-lg overflow-hidden">
                    {lineItems.map((item, index) => {
                      const base  = Number(item.quantity) * Number(item.unit_price || 0);
                      const disc  = base * (Number(item.discount_percentage || 0) / 100);
                      const net   = base - disc;
                      const vat   = Number(item.tax_code) === 1 ? net * 0.14 : 0;
                      const total = net + vat;
                      return (
                        <div key={index} className="p-3 border-b last:border-b-0 bg-slate-50">
                          <div className="flex justify-between items-start">
                            <div>
                              <p className="font-medium text-slate-900 font-mono text-sm">{item.stock_code}</p>
                              <p className="text-sm text-slate-600">{item.description}</p>
                              <p className="text-xs text-slate-500">
                                {item.quantity} × R{Number(item.unit_price || 0).toFixed(2)}
                                {Number(item.discount_percentage) > 0 && ` − ${item.discount_percentage}%`}
                              </p>
                            </div>
                            <p className="font-semibold text-slate-900">R{total.toFixed(2)}</p>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>

                {/* Totals */}
                <div className="bg-blue-50 p-4 rounded-lg grid grid-cols-2 gap-4 text-sm">
                  <div>
                    <p className="text-slate-600">Subtotal</p>
                    <p className="font-semibold">R{totals.subtotal.toFixed(2)}</p>
                  </div>
                  <div>
                    <p className="text-slate-600">Discount</p>
                    <p className="font-semibold">R{totals.totalDiscount.toFixed(2)}</p>
                  </div>
                  <div>
                    <p className="text-slate-600">VAT (14%)</p>
                    <p className="font-semibold">R{totals.totalTax.toFixed(2)}</p>
                  </div>
                  <div>
                    <p className="text-slate-600 font-medium">Total</p>
                    <p className="font-bold text-blue-600 text-lg">R{totals.total.toFixed(2)}</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <div className="flex justify-between gap-2">
              <Button variant="outline" onClick={() => setStep('items')}>
                Back to Items
              </Button>
              <Button
                onClick={handleSubmitInvoice}
                disabled={loading}
                className="gap-2 bg-green-600 hover:bg-green-700"
              >
                {loading ? 'Creating...' : 'Create Invoice'}
              </Button>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

"use client";
import { useState, useEffect, useRef } from "react";
import Link from "next/link";
import { Plus, FileText, Eye, ArrowLeft, Clock, CheckCircle2, AlertCircle } from "lucide-react";
import { useAuth } from "@/lib/useAuth";
import { usePOSAPI } from "@/lib/posApi";
import type { MaybeAxiosError } from '@/lib/types/errors';

interface Invoice {
  id: string;
  invoice_number: string;
  client: string;
  debtor_name: string;
  amount: number;
  due: string;
  status: "Paid" | "Pending" | "Overdue" | "Cancelled";
  invoice_date: string;
  balance_due: number;
}

const fmt = (n: number) =>
  new Intl.NumberFormat("en-ZA", { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);

const STATUS_META: Record<string, { label: string; icon: React.ElementType; cls: string }> = {
  Paid:      { label: "Paid",      icon: CheckCircle2, cls: "status-paid" },
  Pending:   { label: "Pending",   icon: Clock,        cls: "status-pending" },
  Overdue:   { label: "Overdue",   icon: AlertCircle,  cls: "status-overdue" },
  Cancelled: { label: "Cancelled", icon: FileText,      cls: "status-cancelled" },
};

export default function InvoicesPage() {
  const { user, isLoading: authLoading } = useAuth();

  // ── FIX 1: stabilise the API instance so it never re-triggers useEffect ──
  const posAPI = usePOSAPI(user?.tenant?.slug);
  const posAPIRef = useRef(posAPI);

  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [loading, setLoading]   = useState(true);
  const [error, setError]       = useState<string | null>(null);
  const [filter, setFilter]     = useState("All");

  useEffect(() => {
    // Don't run until auth has settled and we have a user
    if (authLoading || !user) return;

    let cancelled = false; // prevent stale setState on unmount

    const fetchInvoices = async () => {
      setLoading(true);
      setError(null);
      try {
        const response = await posAPIRef.current.listInvoices();

        if (cancelled) return;

        // ── FIX 2: handle both paginated {results:[]} and plain array responses ──
        const raw: any[] = Array.isArray(response)
          ? response
          : (response as any).results ?? [];

        setInvoices(
          raw.map((inv: any) => {
            // ── FIX 3: derive status from actual backend fields ──
            let status: Invoice["status"] = "Pending";
            if (inv.is_cancelled || inv.status === "CANCELLED") {
              status = "Cancelled";
            } else if (inv.status === "PAID") {
              status = "Paid";
            } else if (inv.is_overdue || inv.status === "OVERDUE") {
              status = "Overdue";
            }

            return {
              id:             String(inv.invoice_number || inv.id),
              invoice_number: inv.invoice_number ?? String(inv.id),
              // ── FIX 4: debtor_name comes from InvoiceListSerializer as debtor_name ──
              client:         String(inv.debtor_account_number ?? inv.debtor ?? "Unknown"),
              debtor_name:    inv.debtor_name ?? inv.debtor?.dname ?? inv.debtor?.name ?? "",
              amount:         Number(inv.total_amount ?? 0),
              due:            inv.due_date ?? inv.invoice_date ?? "—",
              status,
              invoice_date:   inv.invoice_date ?? "",
              // ── FIX 5: balance_due is a @property on Invoice model ──
              balance_due:    Number(inv.balance_due ?? inv.total_amount ?? 0),
            };
          })
        );
      } catch (err: unknown) {
        if (!cancelled) {
          console.error("Error fetching invoices:", err);
          setError((err as MaybeAxiosError)?.message ?? "Failed to load invoices");
          setInvoices([]);
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    fetchInvoices();

    return () => { cancelled = true; };
  }, [user, authLoading]); // ── FIX 6: posAPI removed from deps — it's stable via ref ──

  const filteredInvoices =
    filter === "All" ? invoices : invoices.filter((inv) => inv.status === filter);

  const totalAmount      = invoices.reduce((s, i) => s + i.amount, 0);
  const totalOutstanding = invoices
    .filter((i) => i.status !== "Paid" && i.status !== "Cancelled")
    .reduce((s, i) => s + i.balance_due, 0);
  const overdueCount = invoices.filter((i) => i.status === "Overdue").length;
  const paidCount    = invoices.filter((i) => i.status === "Paid").length;

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=DM+Mono:wght@400;500&family=DM+Sans:wght@300;400;500&display=swap');

        .inv-root {
          min-height: 100vh;
          background: #0d1117;
          color: #e6edf3;
          font-family: 'DM Sans', sans-serif;
          font-weight: 300;
          padding: 2.5rem 2rem;
        }
        .inv-wrap { max-width: 1100px; margin: 0 auto; }

        .inv-header { display:flex; align-items:flex-start; justify-content:space-between; margin-bottom:2.5rem; gap:1rem; }
        .inv-header-left { display:flex; align-items:center; gap:1.25rem; }
        .back-btn {
          display:flex; align-items:center; justify-content:center;
          width:36px; height:36px; border-radius:8px;
          border:1px solid #30363d; background:transparent; color:#8b949e;
          cursor:pointer; transition:border-color .15s,color .15s; text-decoration:none;
        }
        .back-btn:hover { border-color:#e6edf3; color:#e6edf3; }

        .inv-title { font-family:'DM Serif Display',serif; font-size:2.25rem; font-weight:400; line-height:1; color:#e6edf3; letter-spacing:-0.02em; }
        .inv-subtitle { font-size:.8rem; color:#6e7681; margin-top:.3rem; letter-spacing:.05em; text-transform:uppercase; }

        .new-btn {
          display:flex; align-items:center; gap:.5rem;
          padding:.6rem 1.25rem; background:#e6edf3; color:#0d1117;
          border:none; border-radius:8px; font-family:'DM Sans',sans-serif;
          font-size:.85rem; font-weight:500; cursor:pointer; text-decoration:none;
          white-space:nowrap; transition:background .15s;
        }
        .new-btn:hover { background:#c9d1d9; }

        .stats-strip {
          display:grid; grid-template-columns:repeat(4,1fr);
          gap:1px; background:#21262d; border:1px solid #21262d;
          border-radius:12px; overflow:hidden; margin-bottom:2rem;
        }
        .stat-cell { background:#161b22; padding:1.25rem 1.5rem; display:flex; flex-direction:column; gap:.25rem; }
        .stat-label { font-size:.7rem; color:#6e7681; letter-spacing:.08em; text-transform:uppercase; }
        .stat-value { font-family:'DM Mono',monospace; font-size:1.5rem; font-weight:500; color:#e6edf3; line-height:1; }
        .stat-value.accent { color:#3fb950; }
        .stat-value.warn   { color:#d29922; }
        .stat-value.danger { color:#f85149; }
        .stat-sub { font-size:.75rem; color:#6e7681; margin-top:.1rem; }

        .filter-bar { display:flex; gap:.5rem; margin-bottom:1.5rem; flex-wrap:wrap; }
        .filter-pill {
          padding:.4rem 1rem; border-radius:999px; border:1px solid #30363d;
          background:transparent; color:#8b949e; font-family:'DM Sans',sans-serif;
          font-size:.8rem; cursor:pointer; transition:all .15s;
        }
        .filter-pill:hover  { border-color:#8b949e; color:#e6edf3; }
        .filter-pill.active { border-color:#e6edf3; background:#e6edf3; color:#0d1117; font-weight:500; }

        .table-card { background:#161b22; border:1px solid #21262d; border-radius:12px; overflow:hidden; }
        .table-card-header {
          padding:1.25rem 1.5rem; border-bottom:1px solid #21262d;
          display:flex; align-items:center; justify-content:space-between;
        }
        .table-card-title { font-family:'DM Serif Display',serif; font-size:1.1rem; font-weight:400; color:#e6edf3; }
        .table-count { font-family:'DM Mono',monospace; font-size:.75rem; color:#6e7681; }

        table { width:100%; border-collapse:collapse; }
        thead tr { border-bottom:1px solid #21262d; }
        th { padding:.75rem 1.25rem; font-size:.68rem; font-weight:500; color:#6e7681; letter-spacing:.1em; text-transform:uppercase; text-align:left; }
        th.right { text-align:right; }
        th.center { text-align:center; }

        tbody tr { border-bottom:1px solid #1c2128; transition:background .1s; }
        tbody tr:last-child { border-bottom:none; }
        tbody tr:hover { background:#1c2128; }

        td { padding:.9rem 1.25rem; font-size:.85rem; }
        .td-inv { font-family:'DM Mono',monospace; font-size:.8rem; font-weight:500; color:#58a6ff; }
        .td-client { color:#c9d1d9; }
        .td-client small { display:block; font-size:.72rem; color:#6e7681; margin-top:.1rem; }
        .td-amount { text-align:right; font-family:'DM Mono',monospace; font-size:.85rem; font-weight:500; color:#e6edf3; }
        .td-date { color:#8b949e; font-size:.8rem; }
        .td-actions { text-align:center; }

        .view-btn {
          display:inline-flex; align-items:center; justify-content:center;
          width:30px; height:30px; border-radius:6px; border:1px solid #30363d;
          background:transparent; color:#8b949e; cursor:pointer; text-decoration:none; transition:all .15s;
        }
        .view-btn:hover { border-color:#58a6ff; color:#58a6ff; background:rgba(88,166,255,.08); }

        .status-badge { display:inline-flex; align-items:center; gap:.35rem; padding:.25rem .65rem; border-radius:999px; font-size:.72rem; font-weight:500; letter-spacing:.02em; }
        .status-badge svg { width:11px; height:11px; }
        .status-paid      { background:rgba(63,185,80,.12);  color:#3fb950; border:1px solid rgba(63,185,80,.2); }
        .status-pending   { background:rgba(210,153,34,.12); color:#d29922; border:1px solid rgba(210,153,34,.2); }
        .status-overdue   { background:rgba(248,81,73,.12);  color:#f85149; border:1px solid rgba(248,81,73,.2); }
        .status-cancelled { background:rgba(110,118,129,.12);color:#6e7681; border:1px solid rgba(110,118,129,.2); }

        .empty-state { display:flex; flex-direction:column; align-items:center; justify-content:center; padding:5rem 2rem; gap:1rem; color:#6e7681; text-align:center; }
        .empty-icon { width:48px; height:48px; background:#21262d; border-radius:12px; display:flex; align-items:center; justify-content:center; margin-bottom:.5rem; }
        .empty-title { font-size:1rem; color:#8b949e; font-weight:500; }
        .empty-sub { font-size:.8rem; }

        .error-banner { background:rgba(248,81,73,.1); border:1px solid rgba(248,81,73,.3); border-radius:8px; padding:1rem 1.25rem; color:#f85149; font-size:.85rem; margin-bottom:1.5rem; }

        @keyframes pulse { 0%,100%{opacity:.3} 50%{opacity:.9} }
        .loading-dot { animation:pulse 1.2s ease-in-out infinite; font-size:1.5rem; }
        .loading-dot:nth-child(2) { animation-delay:.2s; }
        .loading-dot:nth-child(3) { animation-delay:.4s; }
        .loading-cell { text-align:center; padding:4rem; color:#6e7681; }

        @media (max-width:700px) {
          .stats-strip { grid-template-columns:repeat(2,1fr); }
          .inv-title { font-size:1.75rem; }
          th.hide-sm, td.hide-sm { display:none; }
        }
      `}</style>

      <div className="inv-root">
        <div className="inv-wrap">

          {/* Header */}
          <header className="inv-header">
            <div className="inv-header-left">
              <Link href="/dashboard/pos" className="back-btn" aria-label="Back">
                <ArrowLeft size={16} />
              </Link>
              <div>
                <h1 className="inv-title">Invoices</h1>
                <p className="inv-subtitle">Accounts Receivable</p>
              </div>
            </div>
            <Link href="/dashboard/pos/invoices/create" className="new-btn">
              <Plus size={15} />
              New Invoice
            </Link>
          </header>

          {/* Error banner */}
          {error && (
            <div className="error-banner">
              ⚠ {error} — check the browser console for details.
            </div>
          )}

          {/* Stats strip */}
          <div className="stats-strip">
            <div className="stat-cell">
              <span className="stat-label">Total Invoiced</span>
              <span className="stat-value">R{fmt(totalAmount)}</span>
              <span className="stat-sub">{invoices.length} invoice{invoices.length !== 1 ? "s" : ""}</span>
            </div>
            <div className="stat-cell">
              <span className="stat-label">Outstanding</span>
              <span className="stat-value warn">R{fmt(totalOutstanding)}</span>
              <span className="stat-sub">balance due</span>
            </div>
            <div className="stat-cell">
              <span className="stat-label">Overdue</span>
              <span className="stat-value danger">{overdueCount}</span>
              <span className="stat-sub">require attention</span>
            </div>
            <div className="stat-cell">
              <span className="stat-label">Paid</span>
              <span className="stat-value accent">{paidCount}</span>
              <span className="stat-sub">this period</span>
            </div>
          </div>

          {/* Filter bar */}
          <div className="filter-bar">
            {["All", "Paid", "Pending", "Overdue", "Cancelled"].map((s) => (
              <button
                key={s}
                onClick={() => setFilter(s)}
                className={`filter-pill${filter === s ? " active" : ""}`}
              >
                {s}
              </button>
            ))}
          </div>

          {/* Table */}
          <div className="table-card">
            <div className="table-card-header">
              <span className="table-card-title">
                {filter === "All" ? "All Invoices" : `${filter} Invoices`}
              </span>
              <span className="table-count">{filteredInvoices.length} records</span>
            </div>

            <div style={{ overflowX: "auto" }}>
              <table>
                <thead>
                  <tr>
                    <th>Invoice #</th>
                    <th>Client</th>
                    <th className="right">Amount</th>
                    <th className="hide-sm">Due Date</th>
                    <th>Status</th>
                    <th className="center">View</th>
                  </tr>
                </thead>
                <tbody>
                  {loading ? (
                    <tr>
                      <td colSpan={6} className="loading-cell">
                        <span className="loading-dot">·</span>
                        <span className="loading-dot">·</span>
                        <span className="loading-dot">·</span>
                      </td>
                    </tr>
                  ) : filteredInvoices.length === 0 ? (
                    <tr>
                      <td colSpan={6}>
                        <div className="empty-state">
                          <div className="empty-icon">
                            <FileText size={22} color="#6e7681" />
                          </div>
                          <p className="empty-title">No invoices found</p>
                          <p className="empty-sub">
                            {filter === "All"
                              ? "Create your first invoice to get started"
                              : `No ${filter.toLowerCase()} invoices match your filter`}
                          </p>
                          {filter === "All" && (
                            <Link href="/dashboard/pos/invoices/create" className="new-btn" style={{ marginTop: ".5rem" }}>
                              <Plus size={14} /> Create Invoice
                            </Link>
                          )}
                        </div>
                      </td>
                    </tr>
                  ) : (
                    filteredInvoices.map((invoice) => {
                      const meta = STATUS_META[invoice.status] ?? STATUS_META.Pending;
                      const StatusIcon = meta.icon;
                      return (
                        <tr key={invoice.id}>
                          <td className="td-inv">{invoice.invoice_number}</td>
                          <td className="td-client">
                            {invoice.debtor_name || invoice.client}
                            {invoice.debtor_name && invoice.client && invoice.debtor_name !== invoice.client && (
                              <small>{invoice.client}</small>
                            )}
                          </td>
                          <td className="td-amount">R{fmt(invoice.amount)}</td>
                          <td className="td-date hide-sm">{invoice.due}</td>
