"use client";
import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useAuth } from "@/lib/useAuth";
import { jobCardsApi } from "@/lib/jobCardsApi";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Edit, Eye } from "lucide-react";

interface Job {
  id: number;
  job_number: string;
  customer_name: string;
  subtotal: number;
  total_amount: number;
  status: string;
  job_date: string;
}

interface Job {
  id: number;
  job_number: string;
  customer_name: string;
  total_amount: number;
  status: string;
  job_date: string;
}

export default function JobCostingPage() {
  const _router = useRouter();
  const { user: _user } = useAuth();
  const [jobs, setJobs] = useState<Job[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    setLoading(true);
    try {
      const response = await jobCardsApi.list({ limit: 100 });
      // Map backend data to frontend interface
      const mappedJobs = response.results.map((job: any) => ({
        id: job.id,
        job_number: job.job_number,
        customer_name: job.customer_name,
        subtotal: parseFloat(job.subtotal) || 0,
        total_amount: parseFloat(job.total_amount) || 0,
        status: job.status,
        job_date: job.job_date
      }));
      setJobs(mappedJobs);
    } catch (error) {
      console.error("Error fetching jobs:", error);
      setJobs([]);
    } finally {
      setLoading(false);
    }
  };

  const handleStatusChange = async (jobId: number, newStatus: string) => {
    try {
      await jobCardsApi.updateStatus(jobId, newStatus);
      // Refresh the list
      fetchJobs();
    } catch (error) {
      console.error("Error updating status:", error);
    }
  };

  const filteredJobs = jobs.filter((job) =>
    job.job_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
