          <div className="space-y-5 py-2">
            {/* Invoice path */}
            <div className="space-y-2 border rounded-lg p-3">
              <p className="text-sm font-medium text-slate-700">Convert to Invoice</p>
              {!hasDebtor && (
                <DebtorPicker
                  onSelect={(debtor) => setSelectedDebtor({ account_number: debtor.account_number, name: debtor.name })}
                  label="Customer"
                />
              )}
              {!hasDebtor && selectedDebtor && (
                <p className="text-sm text-slate-500">
                  Selected: {selectedDebtor.name} (Account #{selectedDebtor.account_number})
                </p>
              )}
              <Button
                className="w-full"
                onClick={handleConvertToInvoice}
                disabled={converting !== null || (!hasDebtor && !selectedDebtor)}
              >
                {converting === 'invoice' ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    Converting...
                  </>
                ) : (
                  <>
                    <FileCheck2 className="h-4 w-4 mr-2" />
                    Convert to Invoice
                  </>
                )}
              </Button>
            </div>

            {/* Cash sale path — only when there's no debtor to charge */}
            {!hasDebtor && (
              <div className="space-y-3 border rounded-lg p-3">
                <p className="text-sm font-medium text-slate-700">Or settle now as a Cash Sale</p>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label htmlFor="cs-tender-type" className="text-xs text-slate-500">Payment Method</Label>
                    <Select value={tenderType} onValueChange={(v) => setTenderType(v as TenderData['tender_type'])}>
                      <SelectTrigger id="cs-tender-type">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {TENDER_TYPES.map((t) => (
                          <SelectItem key={t.value} value={t.value}>
                            {t.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div>
                    <Label htmlFor="cs-amount" className="text-xs text-slate-500">Amount</Label>
                    <Input
                      id="cs-amount"
                      type="number"
                      step="0.01"
                      min="0"
                      value={tenderAmount}
                      onChange={(e) => setTenderAmount(e.target.value)}
                    />
                  </div>
                </div>
                <Button
                  variant="outline"
                  className="w-full"
                  onClick={handleConvertToCashSale}
                  disabled={converting !== null}
                >
                  {converting === 'cash_sale' ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Converting...
                    </>
                  ) : (
                    <>
                      <Receipt className="h-4 w-4 mr-2" />
                      Convert to Cash Sale
                    </>
                  )}
                </Button>
              </div>
            )}

            {convertError && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-3 py-2 rounded-lg text-sm">
                {convertError}
              </div>
            )}
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setConvertDialogOpen(false)}>
              Cancel
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/useAuth';
import { usePOSAPI } from '@/lib/posApi';
import { getApiErrorMessage } from '@/lib/api';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { ArrowLeft, AlertCircle, CheckCircle, Plus, Trash2 } from 'lucide-react';
import { DebtorPicker, StockItemPicker } from '@/components/pos';

export default function CreateQuotationPage() {
  const router = useRouter();
  const { user, isLoading: _authLoading } = useAuth();
  const posAPI = usePOSAPI(user?.tenant?.slug);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    quotation_number: '',
    customer_name: '',
    telephone: '',
    delivery_address: '',
    quote_date: new Date().toISOString().split('T')[0],
    expiry_date: '',
  });

  const [lineItems, setLineItems] = useState<any[]>([]);
  const [newItem, setNewItem] = useState({
    stock_code: '',
    description: '',
    quantity: '',
    unit_rate: '',
    discount_percent: '',
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleAddLineItem = () => {
    if (!newItem.description.trim() || !newItem.quantity || !newItem.unit_rate) {
      setError('Description, quantity, and unit rate are required');
      return;
    }

    const qty = parseFloat(newItem.quantity);
    const rate = parseFloat(newItem.unit_rate);
    const discount = parseFloat(newItem.discount_percent || '0');
    const subtotal = qty * rate;
    const discountAmount = (subtotal * discount) / 100;
    const amount = subtotal - discountAmount;

    const item = {
      id: Date.now(),
      stock_code: newItem.stock_code,
      description: newItem.description,
      quantity: qty,
      unit_rate: rate,
      discount_percent: discount,
      subtotal,
      discount_amount: discountAmount,
      amount,
    };

    setLineItems([...lineItems, item]);
    setNewItem({ stock_code: '', description: '', quantity: '', unit_rate: '', discount_percent: '' });
    setError(null);
  };

  const handleRemoveLineItem = (id: number) => {
    setLineItems(lineItems.filter((item) => item.id !== id));
  };

  const totals = {
    subtotal: lineItems.reduce((sum, item) => sum + item.subtotal, 0),
    discount: lineItems.reduce((sum, item) => sum + item.discount_amount, 0),
    total: lineItems.reduce((sum, item) => sum + item.amount, 0),
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      if (!formData.quotation_number.trim()) {
        throw new Error('Quotation number is required');
      }
      if (!formData.customer_name.trim()) {
        throw new Error('Customer name is required');
      }
      if (lineItems.length === 0) {
        throw new Error('At least one line item is required');
      }

      // Address textarea splits across up to 3x 25-char lines to match the
      // backend's address_line1/2/3 fields.
      const addressLines = formData.delivery_address
        .split('\n')
        .flatMap((line) => line.match(/.{1,25}/g) ?? [])
        .slice(0, 3);

      await posAPI.createQuotation({
        quotation_number: formData.quotation_number,
        quotation_date: formData.quote_date,
        expiry_date: formData.expiry_date,
        customer_name: formData.customer_name,
        telephone: formData.telephone,
        address_line1: addressLines[0] ?? '',
        address_line2: addressLines[1] ?? '',
        address_line3: addressLines[2] ?? '',
        lines: lineItems.map((item, index) => ({
          line_number: index + 1,
          stock_code: item.stock_code,
          description: item.description,
          quantity: item.quantity,
          unit_price: item.unit_rate,
          discount_percentage: item.discount_percent,
          tax_code: 1,
        })),
      });

      setSuccess('Quotation created successfully');
      setTimeout(() => router.push('/dashboard/pos/quotes'), 2000);
    } catch (err: unknown) {
      setError(getApiErrorMessage(err, 'Failed to create quotation'));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white border-b px-6 py-4 flex items-center gap-4">
        <button
          onClick={() => router.back()}
          className="text-blue-600 hover:text-blue-700"
        >
          <ArrowLeft className="w-5 h-5" />
        </button>
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Create Quotation</h1>
          <p className="text-sm text-gray-500">Create new customer quotation</p>
        </div>
      </div>

      <div className="p-6">
        {error && (
          <Card className="border-red-200 bg-red-50 mb-6">
            <CardContent className="pt-6 flex gap-3">
              <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0" />
              <p className="text-red-800">{error}</p>
            </CardContent>
          </Card>
        )}

        {success && (
          <Card className="border-green-200 bg-green-50 mb-6">
            <CardContent className="pt-6 flex gap-3">
              <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0" />
              <p className="text-green-800">{success}</p>
            </CardContent>
          </Card>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Quotation Header */}
          <Card>
            <CardHeader>
              <CardTitle>Quotation Details</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Quotation Number *
                  </label>
                  <Input
                    type="text"
                    name="quotation_number"
                    placeholder="QT-001"
                    value={formData.quotation_number}
                    onChange={handleChange}
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Customer Name *
                  </label>
                  <DebtorPicker
                    onSelect={(debtor) =>
                      setFormData((prev) => ({ ...prev, customer_name: debtor.name }))
                    }
                    placeholder="Search customers or type below..."
                  />
                  <Input
                    type="text"
                    name="customer_name"
                    placeholder="Customer name"
                    value={formData.customer_name}
                    onChange={handleChange}
                    required
                    className="mt-2"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Telephone
                  </label>
                  <Input
                    type="text"
                    name="telephone"
                    placeholder="Optional"
                    value={formData.telephone}
                    onChange={handleChange}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Quote Date *
                  </label>
                  <Input
                    type="date"
                    name="quote_date"
                    value={formData.quote_date}
                    onChange={handleChange}
                    required
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Delivery Address
                </label>
                <textarea
                  name="delivery_address"
                  placeholder="Delivery address"
                  value={formData.delivery_address}
                  onChange={handleChange}
                  rows={2}
                  className="w-full px-3 py-2 border rounded-lg"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Expiry Date *
                </label>
                <Input
                  type="date"
                  name="expiry_date"
                  value={formData.expiry_date}
                  onChange={handleChange}
                  required
                />
              </div>
            </CardContent>
          </Card>

          {/* Line Items */}
          <Card>
            <CardHeader>
              <CardTitle>Items</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-6 gap-3 mb-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Stock Code
                  </label>
                  <StockItemPicker
                    onSelect={(item) =>
                      setNewItem((prev) => ({
                        ...prev,
                        stock_code: item.stock_code,
                        description: item.description,
                        unit_rate: String(item.selling_price),
                      }))
                    }
                    placeholder={newItem.stock_code || 'Search stock (optional)...'}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Description
                  </label>
                  <Input
                    type="text"
                    placeholder="Item"
                    value={newItem.description}
                    onChange={(e) =>
                      setNewItem({ ...newItem, description: e.target.value })
                    }
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Qty
                  </label>
                  <Input
                    type="number"
                    placeholder="0"
                    value={newItem.quantity}
                    onChange={(e) =>
                      setNewItem({ ...newItem, quantity: e.target.value })
                    }
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Unit Rate
                  </label>
                  <Input
                    type="number"
                    placeholder="0.00"
                    step="0.01"
                    value={newItem.unit_rate}
                    onChange={(e) =>
                      setNewItem({ ...newItem, unit_rate: e.target.value })
                    }
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Discount %
                  </label>
                  <Input
                    type="number"
                    placeholder="0"
                    step="0.01"
                    value={newItem.discount_percent || ''}
                    onChange={(e) =>
                      setNewItem({ ...newItem, discount_percent: e.target.value })
                    }
                  />
                </div>
                <div className="flex items-end">
                  <Button
                    type="button"
                    onClick={handleAddLineItem}
                    className="w-full bg-green-600 hover:bg-green-700"
                  >
                    <Plus className="w-4 h-4" />
                  </Button>
                </div>
              </div>

              {lineItems.length > 0 ? (
                <div className="border rounded-lg overflow-hidden">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Stock Code</TableHead>
                        <TableHead>Description</TableHead>
                        <TableHead className="text-right">Qty</TableHead>
                        <TableHead className="text-right">Unit Rate</TableHead>
                        <TableHead className="text-right">Discount</TableHead>
                        <TableHead className="text-right">Amount</TableHead>
                        <TableHead className="w-10"></TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {lineItems.map((item) => (
                        <TableRow key={item.id}>
                          <TableCell>{item.stock_code || '—'}</TableCell>
                          <TableCell>{item.description}</TableCell>
                          <TableCell className="text-right">{item.quantity}</TableCell>
                          <TableCell className="text-right">
                            R{item.unit_rate.toFixed(2)}
                          </TableCell>
                          <TableCell className="text-right">
                            {item.discount_percent}% (R{item.discount_amount.toFixed(2)})
                          </TableCell>
                          <TableCell className="text-right font-medium">
                            R{item.amount.toFixed(2)}
                          </TableCell>
                          <TableCell className="text-center">
                            <button
                              type="button"
                              onClick={() => handleRemoveLineItem(item.id)}
                              className="text-red-600 hover:text-red-700"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </TableCell>
                        </TableRow>
                      ))}
                      <TableRow className="bg-gray-50">
                        <TableCell colSpan={3}></TableCell>
                        <TableCell colSpan={2} className="text-right font-bold">
                          Subtotal:
                        </TableCell>
                        <TableCell className="text-right font-bold">
                          R{totals.subtotal.toFixed(2)}
                        </TableCell>
                        <TableCell></TableCell>
                      </TableRow>
                      <TableRow className="bg-gray-50">
                        <TableCell colSpan={3}></TableCell>
                        <TableCell colSpan={2} className="text-right font-bold">
                          Total Discount:
                        </TableCell>
                        <TableCell className="text-right font-bold text-red-600">
                          -R{totals.discount.toFixed(2)}
                        </TableCell>
                        <TableCell></TableCell>
                      </TableRow>
                      <TableRow className="bg-blue-50">
                        <TableCell colSpan={3}></TableCell>
                        <TableCell colSpan={2} className="text-right font-bold text-blue-900">
                          Total:
                        </TableCell>
                        <TableCell className="text-right font-bold text-lg text-blue-900">
                          R{totals.total.toFixed(2)}
                        </TableCell>
                        <TableCell></TableCell>
                      </TableRow>
                    </TableBody>
                  </Table>
                </div>
              ) : (
                <p className="text-gray-500 text-center py-4">No items added yet</p>
              )}
            </CardContent>
          </Card>

          {/* Actions */}
          <div className="flex gap-4 justify-end">
            <Button
              type="button"
              onClick={() => router.back()}
              variant="outline"
            >
              Cancel
            </Button>
            <Button
              type="submit"
              className="bg-blue-600 hover:bg-blue-700"
              disabled={loading}
            >
              {loading ? 'Saving...' : 'Create Quotation'}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";
import { useState, useEffect, useRef } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Eye } from "lucide-react";
import Link from "next/link";
import { useAuth } from "@/lib/useAuth";
import { usePOSAPI } from "@/lib/posApi";

interface Quote {
  id: number;
  number: string;
  customer: string;
  amount: number;
  expiry: string;
  status: string;
}

export default function QuotesPage() {
  const { user, isLoading: authLoading } = useAuth();
  const posAPI = usePOSAPI(user?.tenant?.slug);
  const posAPIRef = useRef(posAPI);

  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    if (authLoading || !user) return;
    let cancelled = false;

    const fetchQuotes = async () => {
      setLoading(true);
      try {
        const response = await posAPIRef.current.listQuotations();
        if (cancelled) return;

        const raw: any[] = Array.isArray(response) ? response : (response as any).results ?? [];
        setQuotes(
          raw.map((q: any) => ({
            id: q.id,
            number: q.quotation_number ?? String(q.id),
            customer: q.customer_name ?? "Unknown",
            amount: Number(q.total_amount ?? 0),
            expiry: q.expiry_date ?? "",
            status: String(q.status ?? "ACTIVE").toLowerCase(),
          }))
        );
      } catch (error) {
        if (!cancelled) {
          console.error("Error fetching quotes:", error);
          setQuotes([]);
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    fetchQuotes();
    return () => { cancelled = true; };
  }, [user, authLoading]);

  const filteredQuotes = quotes.filter((quote) =>
    quote.number.toLowerCase().includes(searchTerm.toLowerCase()) ||
    quote.customer.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div className="flex justify-center items-center h-screen">Loading...</div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-bold">Quotations</h1>
        <Link href="/dashboard/pos/quotes/create">
          <Button className="bg-blue-600 hover:bg-blue-700">New Quote</Button>
        </Link>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Customer Quotes</CardTitle>
        </CardHeader>
        <CardContent>
          <Input
            type="text"
            placeholder="Search by quote number or customer..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="mb-4"
          />
          {filteredQuotes.length > 0 ? (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b">
                    <th className="text-left py-2">Quote #</th>
                    <th className="text-left py-2">Customer</th>
                    <th className="text-right py-2">Amount</th>
                    <th className="text-left py-2">Expiry Date</th>
                    <th className="text-left py-2">Status</th>
                    <th className="text-center py-2">View</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredQuotes.map((quote) => (
                    <tr key={quote.id} className="border-b hover:bg-gray-50">
                      <td className="py-3 font-medium">{quote.number}</td>
                      <td className="py-3">{quote.customer}</td>
                      <td className="py-3 text-right">R{quote.amount.toFixed(2)}</td>
                      <td className="py-3">{quote.expiry}</td>
                      <td className="py-3">
                        <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                          quote.status === "converted_to_invoice" || quote.status === "invoiced" || quote.status === "job" ? "bg-green-100 text-green-800" :
                          quote.status === "cancelled" || quote.status === "expired" ? "bg-gray-100 text-gray-800" :
                          "bg-blue-100 text-blue-800"
                        }`}>
                          {quote.status.replace(/_/g, " ")}
                        </span>
                      </td>
                      <td className="py-3 text-center">
                        <Link
                          href={`/dashboard/pos/quotes/${quote.id}`}
                          className="inline-flex items-center justify-center w-8 h-8 rounded-md border border-gray-200 text-gray-500 hover:border-blue-400 hover:text-blue-600"
                          aria-label={`View quote ${quote.number}`}
                        >
                          <Eye className="h-4 w-4" />
                        </Link>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="text-center py-8 text-gray-500">No quotes found</div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useAuth } from '@/lib/useAuth';
import { usePOSAPI, TenderData, ReceiptCreateData } from '@/lib/posApi';
import { useRouter } from 'next/navigation';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  AccountInfoCard,
  TenderRow,
  ErrorAlert,
  SuccessAlert,
  LoadingOverlay,
} from '@/components/pos/form-components';
import { DebtorPicker } from '@/components/pos/DebtorPicker';
import {
  AlertCircle,
  Plus,
  ArrowLeft,
  Check,
} from 'lucide-react';

export default function CreateReceipt() {
  const { user } = useAuth();
  const router = useRouter();
  const posAPI = usePOSAPI(user?.tenant?.slug);

  const [formData, setFormData] = useState({
    debtor_account_number: '',
    receipt_type: 'BALANCE_FORWARD' as 'BALANCE_FORWARD' | 'OPEN_ITEM' | 'POST_DATED_CHEQUE',
    receipt_date: new Date().toISOString().split('T')[0],
    amount: 0,
    notes: '',
  });

  const [tenders, setTenders] = useState<TenderData[]>([
    {
      tender_type: 'CASH',
      amount: 0,
    },
  ]);

  const [debtorInfo, setDebtorInfo] = useState<any>(null);
  const [_debtorLoading, _setDebtorLoading] = useState(false);
  const [_debtorError, setDebtorError] = useState<string | null>(null);
  const [_loading, _setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [selectedDebtorName, setSelectedDebtorName] = useState<string>('');

  // Handle debtor selection from picker
  const handleDebtorSelect = (debtor: {
    account_number: string;
    name: string;
    balance: number;
    credit_limit: number;
  }) => {
    setFormData({ ...formData, debtor_account_number: debtor.account_number });
    setDebtorInfo(debtor);
    setSelectedDebtorName(debtor.name);
    setDebtorError(null);
  };

  // Handle manual customer name entry (allow manual entry even without selecting debtor)
  const handleCustomerNameChange = (value: string) => {
    setSelectedDebtorName(value);
    // If the name doesn't match a selected debtor, clear the info
    if (debtorInfo && debtorInfo.name !== value) {
      setDebtorInfo(null);
    }
  };

  // Note: Debtor is now selected via DebtorPicker component above

  const addTender = () => {
    setTenders([
      ...tenders,
      {
        tender_type: 'CASH',
        amount: 0,
      },
    ]);
  };

  const removeTender = (index: number) => {
    if (tenders.length > 1) {
      setTenders(tenders.filter((_, i) => i !== index));
    }
  };

  const updateTender = (index: number, field: string, value: any) => {
    const updated = [...tenders];
    updated[index] = { ...updated[index], [field]: value };
    setTenders(updated);
  };

  const calculateTenderTotal = () => {
    return tenders.reduce((sum, t) => sum + (t.amount || 0), 0);
  };

  const tenderTotal = calculateTenderTotal();
  const amountDue = formData.amount > 0 ? formData.amount : 0;
  const amountPaid = tenderTotal;
  const balance = amountPaid - amountDue;

  const validateForm = () => {
    if (!formData.debtor_account_number) {
      setError('Please select a debtor account');
      return false;
    }
    if (formData.amount <= 0) {
      setError('Receipt amount must be greater than 0');
      return false;
    }
    if (tenders.length === 0 || tenders.some((t) => t.amount <= 0)) {
      setError('All payment methods must have an amount greater than 0');
      return false;
    }
    if (Math.abs(balance) > 0.01) {
      setError(`Amount due (R${amountDue.toFixed(2)}) does not match amount paid (R${amountPaid.toFixed(2)})`);
      return false;
    }
    return true;
  };

  const handleSaveDraft = async () => {
    if (!validateForm()) return;

    try {
      setSubmitting(true);
      setError(null);

      const receiptData: ReceiptCreateData = {
        debtor_account_number: formData.debtor_account_number,
        receipt_type: formData.receipt_type,
        receipt_date: formData.receipt_date,
        tenders: tenders,
        amount: formData.amount,
        notes: formData.notes,
      };

      const result = await posAPI.createReceipt(receiptData);
      setSuccess(`Receipt draft saved successfully! Receipt #${result.receipt_number}`);
      
      setTimeout(() => {
        router.push(`/dashboard/pos/receipts/${result.id}`);
      }, 2000);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save receipt');
    } finally {
      setSubmitting(false);
    }
  };

  const handlePost = async () => {
    if (!validateForm()) return;

    try {
      setSubmitting(true);
      setError(null);

      const receiptData: ReceiptCreateData = {
        debtor_account_number: formData.debtor_account_number,
        receipt_type: formData.receipt_type,
        receipt_date: formData.receipt_date,
        tenders: tenders,
        amount: formData.amount,
        notes: formData.notes,
      };

      const result = await posAPI.createReceipt(receiptData);
      setSuccess(`Receipt posted successfully! Receipt #${result.receipt_number}`);
      
      setTimeout(() => {
        router.push(`/dashboard/pos/receipts`);
      }, 2000);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to post receipt');
    } finally {
      setSubmitting(false);
    }
  };

  if (submitting) {
    return <LoadingOverlay message="Processing receipt..." />;
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-slate-50 to-slate-100 p-6">
      <div className="max-w-5xl mx-auto">
        {/* Header */}
        <div className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-4">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => router.push('/dashboard/pos')}
              className="hover:bg-slate-200"
            >
              <ArrowLeft className="h-5 w-5" />
            </Button>
            <div>
              <h1 className="text-3xl font-bold text-slate-900">Record Payment Receipt</h1>
              <p className="text-slate-600 mt-1">Process debtor account payments</p>
            </div>
          </div>
        </div>

        {/* Success Alert */}
        {success && <SuccessAlert message={success} />}

        {/* Error Alert */}
        {error && <ErrorAlert message={error} />}

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mt-6">
          {/* Main Form - Left Side */}
          <div className="lg:col-span-2 space-y-6">
            {/* Receipt Header Card */}
            <Card>
              <CardHeader>
                <CardTitle>Receipt Information</CardTitle>
                <CardDescription>Basic receipt details</CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                {/* Debtor Selection with Search or Manual Entry */}
                <div className="space-y-2">
                  <label className="text-sm font-medium">
                    Debtor Account <span className="text-red-500">*</span>
                  </label>
                  
                  {/* Option 1: Search existing debtors */}
                  <DebtorPicker
                    onSelect={handleDebtorSelect}
                    label="Select Customer"
                    placeholder="Search for existing debtor..."
                  />
                  
                  {/* Option 2: Manual entry (for non-account customers) */}
                  <div className="mt-2">
                    <Input
                      placeholder="Or manually enter customer name..."
                      value={selectedDebtorName}
                      onChange={(e) => {
                        handleCustomerNameChange(e.target.value);
                        if (e.target.value && !formData.debtor_account_number) {
                          // Allow manual entry without debtor account
                          setFormData({ ...formData, debtor_account_number: e.target.value });
                        }
                      }}
                      className="flex-1"
                    />
                  </div>
                  
                  <p className="text-xs text-slate-500">
                    Search for an existing debtor account OR enter a customer name manually
                  </p>
                </div>

                {/* Debtor Info Card - show selected debtor or manual entry */}
                {(debtorInfo || selectedDebtorName) && (
                  <AccountInfoCard
                    accountName={debtorInfo?.name || selectedDebtorName}
                    accountNumber={debtorInfo?.account_number || formData.debtor_account_number}
                    balance={debtorInfo?.balance || 0}
                    creditLimit={debtorInfo?.credit_limit || 0}
                  />
                )}
              </CardContent>
            </Card>

            {/* Receipt Details Card */}
            <Card>
              <CardHeader>
                <CardTitle>Receipt Details</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-sm font-medium">
                      Receipt Type <span className="text-red-500">*</span>
                    </label>
                    <select
                      value={formData.receipt_type}
                      onChange={(e) =>
                        setFormData({ ...formData, receipt_type: e.target.value as any })
                      }
                      className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    >
                      <option value="BALANCE_FORWARD">Balance Forward</option>
                      <option value="OPEN_ITEM">Open Item</option>
                      <option value="POST_DATED_CHEQUE">Post Dated Cheque</option>
                    </select>
                    <p className="text-xs text-slate-500">
                      BALANCE_FORWARD: Full account payment
                    </p>
                  </div>

                  <div className="space-y-2">
                    <label className="text-sm font-medium">
                      Receipt Date <span className="text-red-500">*</span>
                    </label>
                    <Input
                      type="date"
                      value={formData.receipt_date}
                      onChange={(e) =>
                        setFormData({ ...formData, receipt_date: e.target.value })
                      }
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-medium">
                    Amount Due <span className="text-red-500">*</span>
                  </label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-600">R</span>
                    <Input
                      type="number"
                      min="0"
                      step="0.01"
                      value={formData.amount}
                      onChange={(e) =>
                        setFormData({ ...formData, amount: parseFloat(e.target.value) || 0 })
                      }
                      className="pl-8"
                      placeholder="0.00"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-medium">Notes</label>
                  <textarea
                    value={formData.notes}
                    onChange={(e) =>
                      setFormData({ ...formData, notes: e.target.value })
                    }
                    className="w-full min-h-24 p-3 border border-slate-200 rounded-lg text-sm"
                    placeholder="Optional notes about this receipt..."
                  />
                </div>
              </CardContent>
            </Card>

            {/* Payment Methods Card */}
            <Card>
              <CardHeader className="flex flex-row items-center justify-between">
                <div>
                  <CardTitle>Payment Methods</CardTitle>
                  <CardDescription>How is this payment being received?</CardDescription>
                </div>
                <Button
                  size="sm"
                  onClick={addTender}
                  className="gap-2"
                >
                  <Plus className="h-4 w-4" />
                  Add Payment
                </Button>
              </CardHeader>
              <CardContent className="space-y-4">
                {tenders.map((tender, index) => (
                  <TenderRow
                    key={index}
                    tender={tender}
                    onUpdate={(field, value) =>
                      updateTender(index, field, value)
                    }
                    onRemove={() => removeTender(index)}
                    index={index}
                  />
                ))}
              </CardContent>
            </Card>
          </div>

          {/* Summary - Right Side */}
          <div className="space-y-6">
            {/* Amount Summary */}
            <Card className="sticky top-6">
              <CardHeader>
                <CardTitle className="text-lg">Summary</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-3">
                  <div className="flex justify-between items-center pb-3 border-b">
                    <span className="text-slate-600">Amount Due:</span>
                    <span className="font-semibold">R{amountDue.toFixed(2)}</span>
                  </div>

                  <div className="bg-blue-50 p-3 rounded-lg space-y-2">
                    <p className="text-xs text-slate-600 font-medium">PAYMENT BREAKDOWN</p>
                    {tenders.map((tender, index) => (
                      <div key={index} className="flex justify-between text-sm">
                        <span className="text-slate-600">
                          {tender.tender_type}: {tender.tender_type === 'CHEQUE' && tender.drawer_name && `#${tender.drawer_name}`}
                        </span>
                        <span className="font-medium">R{tender.amount.toFixed(2)}</span>
                      </div>
                    ))}
                  </div>

                  <div className={`flex justify-between items-center p-3 rounded-lg ${balance > 0.01 ? 'bg-green-50' : balance < -0.01 ? 'bg-red-50' : 'bg-green-50'}`}>
                    <span className="font-semibold">Total Paid:</span>
                    <span className={`font-bold text-lg ${Math.abs(balance) > 0.01 ? (balance > 0 ? 'text-green-600' : 'text-red-600') : 'text-green-600'}`}>
                      R{amountPaid.toFixed(2)}
                    </span>
                  </div>

                  {Math.abs(balance) > 0.01 && (
                    <div className={`text-sm p-2 rounded flex items-center gap-2 ${balance > 0 ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                      <AlertCircle className="h-4 w-4" />
                      {balance > 0 ? (
                        <span>Change: R{balance.toFixed(2)}</span>
                      ) : (
                        <span>Shortfall: R{Math.abs(balance).toFixed(2)}</span>
                      )}
                    </div>
                  )}
                </div>

                {Math.abs(balance) < 0.01 && (
                  <div className="flex items-center gap-2 p-3 bg-green-50 border border-green-200 rounded-lg text-green-700">
                    <Check className="h-4 w-4" />
                    <span className="text-sm font-medium">Payment balanced</span>
                  </div>
                )}
              </CardContent>
            </Card>

            {/* Quick Info Card */}
            <Card className="bg-slate-900 text-white border-0">
              <CardContent className="pt-6 space-y-3">
                <div>
                  <p className="text-xs text-slate-400 mb-1">RECEIPT STATUS</p>
                  <p className="text-sm font-medium">Ready to Save</p>
                </div>
                <div>
                  <p className="text-xs text-slate-400 mb-1">TENANT</p>
                  <p className="text-sm font-medium">{user?.tenant?.slug || 'Unknown'}</p>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="mt-8 flex gap-3 justify-end">
          <Button
            variant="outline"
            onClick={() => router.push('/dashboard/pos')}
            disabled={submitting}
          >
            Cancel
          </Button>
          <Button
            variant="outline"
            onClick={handleSaveDraft}
            disabled={submitting || !formData.debtor_account_number}
          >
            Save as Draft
          </Button>
          <Button
            onClick={handlePost}
            disabled={submitting || !formData.debtor_account_number || Math.abs(balance) > 0.01}
            className="gap-2 bg-green-600 hover:bg-green-700"
          >
            <Check className="h-4 w-4" />
            Post Receipt
          </Button>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useAuth } from '@/lib/useAuth';
import { usePOSAPI } from '@/lib/posApi';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Plus,
  ArrowLeft,
  Search,
  Download,
  Eye,
  FileText,
} from 'lucide-react';
import { ErrorAlert, SuccessAlert, LoadingOverlay } from '@/components/pos/form-components';

export default function ReceiptsList() {
  const { user, isLoading: authLoading } = useAuth();
  const router = useRouter();
  const posAPI = usePOSAPI(user?.tenant?.slug);

  const [receipts, setReceipts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<string>('all');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');

  // Fetch receipts from API
  useEffect(() => {
    const fetchReceipts = async () => {
      try {
        setLoading(true);
        setError(null);

        // Call the backend API to fetch receipts
        const response = await posAPI.listReceipts({
          from_date: dateFrom || undefined,
          to_date: dateTo || undefined,
        });

        // Map backend fields to frontend display fields
        const mappedReceipts = response.results.map((receipt: any) => ({
          id: receipt.id,
          receipt_number: receipt.receipt_number,
          debtor_account_number: receipt.debtor_account,
          debtor_name: receipt.debtor_name,
          amount: parseFloat(receipt.amount) || 0,
          total_amount: parseFloat(receipt.total_amount) || 0,
          receipt_type: receipt.tender_type?.toLowerCase(),
          tender_type_display: receipt.tender_type_display,
          receipt_date: receipt.receipt_date,
          is_posted: receipt.is_posted,
          is_cancelled: receipt.is_cancelled,
          status: receipt.is_cancelled ? 'CANCELLED' : receipt.is_posted ? 'POSTED' : 'DRAFT',
          reference: receipt.reference,
          cheque_number: receipt.cheque_number,
          bank_name: receipt.bank_name,
          card_type: receipt.card_type,
          authorization_code: receipt.authorization_code,
          cashier_name: receipt.cashier_name,
          station_number: receipt.station_number,
        }));

        setReceipts(mappedReceipts);
      } catch (err: unknown) {
        console.error('Error fetching receipts:', err);
        setError(err instanceof Error ? err.message : 'Failed to load receipts');
        setReceipts([]);
      } finally {
        setLoading(false);
      }
    };

    fetchReceipts();
  }, [dateFrom, dateTo]);

  // Filter receipts
  const filteredReceipts = receipts.filter((receipt) => {
    const matchesSearch =
      receipt.debtor_account_number?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      receipt.debtor_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      receipt.receipt_number?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      receipt.reference?.toLowerCase().includes(searchTerm.toLowerCase());

    // Filter by status
    const matchesStatus = filterStatus === 'all' || receipt.status === filterStatus;

    return matchesSearch && matchesStatus;
  });

  const handleDelete = async (id: string | number) => {
    if (!confirm('Are you sure you want to delete this receipt?')) {
      return;
    }
    try {
      setLoading(true);
      await posAPI.deleteReceipt(id);
      setSuccess('Receipt deleted successfully');
      // Refresh the list
      setReceipts((prev) => prev.filter((r) => r.id !== id));
      setTimeout(() => setSuccess(null), 3000);
    } catch (err: unknown) {
      console.error('Error deleting receipt:', err);
      setError(err instanceof Error ? err.message : 'Failed to delete receipt');
      setTimeout(() => setError(null), 3000);
    } finally {
      setLoading(false);
    }
  };

  const handleExport = () => {
    // CSV export functionality
    const csv = [
      ['Receipt #', 'Account #', 'Debtor Name', 'Amount', 'Type', 'Date', 'Status'],
      ...filteredReceipts.map((r) => [
        r.receipt_number,
        r.debtor_account_number,
        r.debtor_name,
        r.total_amount || r.amount,
        r.receipt_type,
        new Date(r.receipt_date).toLocaleDateString(),
        r.status,
      ]),
    ]
      .map((row) => row.join(','))
      .join('\n');

    const element = document.createElement('a');
    element.setAttribute('href', `data:text/csv;charset=utf-8,${encodeURIComponent(csv)}`);
    element.setAttribute('download', `receipts-${new Date().toISOString().split('T')[0]}.csv`);
    element.style.display = 'none';
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
  };

  if (authLoading) {
    return <LoadingOverlay message="Loading..." />;
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-slate-50 to-slate-100 p-6 md:p-8">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => router.push('/dashboard/pos')}
              className="hover:bg-slate-200"
            >
              <ArrowLeft className="h-5 w-5" />
            </Button>
            <div>
              <h1 className="text-3xl font-bold text-slate-900">Payment Receipts</h1>
              <p className="text-slate-600 mt-1">Manage customer payment records</p>
            </div>
          </div>
          <Link href="/dashboard/pos/receipts/create">
            <Button className="gap-2 bg-blue-600 hover:bg-blue-700">
              <Plus className="h-4 w-4" />
              New Receipt
            </Button>
          </Link>
        </div>

        {/* Alerts */}
        {error && <ErrorAlert message={error} />}
        {success && <SuccessAlert message={success} />}

        {/* Filters & Search */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Filters</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              {/* Search */}
              <div className="space-y-2">
                <label className="text-sm font-medium">Search</label>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                  <Input
                    placeholder="Receipt # or Account..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="pl-10"
                  />
                </div>
              </div>

              {/* Date From */}
              <div className="space-y-2">
                <label className="text-sm font-medium">From Date</label>
                <Input
                  type="date"
                  value={dateFrom}
                  onChange={(e) => setDateFrom(e.target.value)}
                />
              </div>

              {/* Date To */}
              <div className="space-y-2">
                <label className="text-sm font-medium">To Date</label>
                <Input
                  type="date"
                  value={dateTo}
                  onChange={(e) => setDateTo(e.target.value)}
                />
              </div>

              {/* Status Filter */}
              <div className="space-y-2">
                <label className="text-sm font-medium">Status</label>
                <select
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value)}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  <option value="all">All Status</option>
                  <option value="DRAFT">Draft</option>
                  <option value="POSTED">Posted</option>
                  <option value="CANCELLED">Cancelled</option>
                </select>
              </div>
            </div>

            <div className="flex gap-2">
              <Button
                variant="outline"
                onClick={() => {
                  setSearchTerm('');
                  setFilterStatus('all');
                  setDateFrom('');
                  setDateTo('');
                }}
              >
                Clear Filters
              </Button>
              {filteredReceipts.length > 0 && (
                <Button
                  variant="outline"
                  onClick={handleExport}
                  className="gap-2"
                >
                  <Download className="h-4 w-4" />
                  Export CSV
                </Button>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Results Summary */}
        <div className="text-sm text-slate-600">
          Showing <span className="font-semibold text-slate-900">{filteredReceipts.length}</span> of{' '}
          <span className="font-semibold text-slate-900">{receipts.length}</span> receipts
        </div>

        {/* Receipts Table */}
        {loading ? (
          <LoadingOverlay message="Loading receipts..." />
        ) : filteredReceipts.length === 0 ? (
          <Card>
            <CardContent className="pt-12 pb-12 text-center">
              <FileText className="h-12 w-12 text-slate-300 mx-auto mb-4" />
              <p className="text-slate-600 font-medium mb-2">No receipts found</p>
              <p className="text-slate-500 text-sm mb-4">
                {receipts.length === 0
                  ? 'Create your first receipt to get started'
                  : 'Try adjusting your filters'}
              </p>
              {receipts.length === 0 && (
                <Link href="/dashboard/pos/receipts/create">
                  <Button className="gap-2">
                    <Plus className="h-4 w-4" />
                    Create Receipt
                  </Button>
                </Link>
              )}
            </CardContent>
          </Card>
        ) : (
          <Card>
            <CardContent className="p-0">
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow className="bg-slate-50 hover:bg-slate-50">
                      <TableHead>Receipt #</TableHead>
                      <TableHead>Account #</TableHead>
                      <TableHead>Type</TableHead>
                      <TableHead className="text-right">Amount</TableHead>
                      <TableHead>Date</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {filteredReceipts.map((receipt) => (
                      <TableRow key={receipt.id} className="hover:bg-slate-50">
                        <TableCell className="font-medium text-slate-900">
                          {receipt.receipt_number || 'N/A'}
                        </TableCell>
                        <TableCell>
                          <div className="flex flex-col">
                            <span className="font-medium">{receipt.debtor_account_number}</span>
                            <span className="text-xs text-slate-500">{receipt.debtor_name}</span>
                          </div>
                        </TableCell>
                        <TableCell>
                          <span className="text-sm">
                            {receipt.receipt_type?.replace(/_/g, ' ')}
                          </span>
                        </TableCell>
                        <TableCell className="text-right font-semibold">
                          R{(receipt.total_amount || receipt.amount)?.toFixed(2) || '0.00'}
                        </TableCell>
                        <TableCell>
                          {new Date(receipt.receipt_date).toLocaleDateString()}
                        </TableCell>
                        <TableCell>
                          <span
                            className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${
                              receipt.status === 'POSTED'
                                ? 'bg-green-100 text-green-700'
                                : receipt.status === 'DRAFT'
                                  ? 'bg-yellow-100 text-yellow-700'
                                  : 'bg-slate-100 text-slate-700'
                            }`}
                          >
                            {receipt.status}
                          </span>
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex justify-end gap-2">
                            <Link href={`/dashboard/pos/receipts/${receipt.id}`}>
                              <Button size="sm" variant="ghost">
                                <Eye className="h-4 w-4" />
                              </Button>
                            </Link>
                            <Button
                              size="sm"
                              variant="ghost"
                              onClick={() => handleDelete(receipt.id)}
                              className="text-red-600 hover:text-red-700 hover:bg-red-50"
                            >
                              Delete
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

