'use client';

import React, { useState, useEffect } from 'react';
import {
  PlusCircle,
  FileText,
  Search,
  Download,
  Printer,
  Clock,
  Package,
  Truck,
  BarChart3,
  X,
} from 'lucide-react';

// Import components directly
import { OrderStatusBadge } from '@/components/purchase-orders/common/OrderStatusBadge';
import { OrderSummaryCard } from '@/components/purchase-orders/common/OrderSummaryCard';
import purchaseOrdersApi from '@/lib/purchaseOrdersApi';
import type { PurchaseOrder } from '@/lib/types/purchaseOrders';

export default function PurchaseOrdersPage() {
  const [orders, setOrders] = useState<PurchaseOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalCount, setTotalCount] = useState(0);

  useEffect(() => {
    fetchOrders();
  }, [statusFilter, currentPage]);

  const fetchOrders = async () => {
    setLoading(true);
    try {
      const params: any = { page: currentPage, page_size: 20 };
      if (statusFilter !== 'all') {
        params.status = statusFilter;
      }
      if (searchTerm) {
        params.search = searchTerm;
      }

      const response = await purchaseOrdersApi.orders.list(params);
      setOrders(response.results || response);
      setTotalCount(response.count || 0);
    } catch (error) {
      console.error('Error fetching orders:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    setCurrentPage(1);
    fetchOrders();
  };

  // Calculate summary statistics
  const summaryStats = {
    totalOrders: totalCount,
    pendingOrders: orders.filter((o) => ['O', 'P'].includes(o.status)).length,
    totalValue: orders.reduce((sum, o) => sum + (Number(o.total_value_inclusive) || 0), 0),
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white border-b px-6 py-4">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">Purchase Orders</h1>
            <p className="text-sm text-gray-500">
              Manage orders, receipts, and supplier deliveries
            </p>
          </div>
          <div className="flex gap-3">
            <a
              href="/dashboard/purchase-orders/transactions/new-order"
              className="inline-flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-medium transition-colors"
            >
              <PlusCircle className="w-4 h-4" />
              New Purchase Order
            </a>
          </div>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 p-6">
        <OrderSummaryCard
          title="Total Orders"
          value={summaryStats.totalOrders}
          subtitle="All time"
          icon={<FileText className="w-5 h-5 text-blue-600" />}
          color="info"
        />
        <OrderSummaryCard
          title="Pending Orders"
          value={summaryStats.pendingOrders}
          subtitle="Awaiting processing"
          icon={<Clock className="w-5 h-5 text-yellow-600" />}
          color="warning"
        />
        <OrderSummaryCard
          title="Total Value"
          value={summaryStats.totalValue}
          subtitle="All orders"
          icon={<BarChart3 className="w-5 h-5 text-green-600" />}
          color="success"
        />
        <OrderSummaryCard
          title="Received Today"
          value={0}
          subtitle="Completed receipts"
          icon={<Package className="w-5 h-5 text-purple-600" />}
        />
      </div>

      {/* Filters & Search */}
      <div className="px-6">
        <div className="bg-white rounded-lg border shadow-sm p-4">
          <div className="flex flex-col md:flex-row gap-4 items-start md:items-center justify-between">
            <form onSubmit={handleSearch} className="flex gap-3 w-full md:w-auto">
              <div className="relative flex-1 md:w-80">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input
                  type="text"
                  placeholder="Search orders..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="all">All Status</option>
                <option value="O">Outstanding</option>
                <option value="P">Partially Received</option>
                <option value="F">Fully Received</option>
                <option value="C">Cancelled</option>
              </select>
              <button
                type="submit"
                className="px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg font-medium transition-colors"
              >
                Search
              </button>
            </form>

            <div className="flex gap-2">
              <a
                href="/dashboard/purchase-orders/enquiries/delivery-date"
                className="inline-flex items-center gap-2 px-4 py-2 border border-gray-300 hover:bg-gray-50 text-gray-700 rounded-lg font-medium transition-colors"
              >
                <Search className="w-4 h-4" />
                Enquiries
              </a>
              <a
                href="/dashboard/purchase-orders/reports"
                className="inline-flex items-center gap-2 px-4 py-2 border border-gray-300 hover:bg-gray-50 text-gray-700 rounded-lg font-medium transition-colors"
              >
                <Download className="w-4 h-4" />
                Reports
              </a>
            </div>
          </div>
        </div>
      </div>

      {/* Orders Table */}
      <div className="px-6 pb-6">
        <div className="bg-white rounded-lg border shadow-sm overflow-hidden mt-4">
          {loading ? (
            <div className="p-8 text-center">
              <div className="inline-flex items-center gap-2 text-gray-500">
                <div className="w-5 h-5 border-2 border-gray-300 border-t-blue-600 rounded-full animate-spin" />
                Loading orders...
              </div>
            </div>
          ) : orders.length === 0 ? (
            <div className="p-8 text-center">
              <FileText className="w-12 h-12 text-gray-300 mx-auto mb-4" />
              <p className="text-gray-500">No purchase orders found</p>
              <a
                href="/dashboard/purchase-orders/transactions/new-order"
                className="inline-flex items-center gap-2 mt-4 text-blue-600 hover:text-blue-700 font-medium"
              >
                <PlusCircle className="w-4 h-4" />
                Create your first order
              </a>
            </div>
          ) : (
            <table className="w-full">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Order #
                  </th>
                  <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Date
                  </th>
                  <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Supplier
                  </th>
                  <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Delivery Date
                  </th>
                  <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Amount
                  </th>
                  <th className="text-center px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Status
                  </th>
                  <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {orders.map((order) => (
                  <tr key={order.order_number} className="hover:bg-gray-50">
                    <td className="px-4 py-3 text-sm font-medium text-blue-600">
                      {order.order_number}
                    </td>
                    <td className="px-4 py-3 text-sm text-gray-600">
                      {new Date(order.order_date).toLocaleDateString('en-ZA')}
                    </td>
                    <td className="px-4 py-3 text-sm text-gray-900">
                      {order.supplier_name || order.supplier}
                    </td>
                    <td className="px-4 py-3 text-sm text-gray-600">
                      {new Date(order.delivery_date).toLocaleDateString('en-ZA')}
                    </td>
                    <td className="px-4 py-3 text-sm text-right font-medium">
                      R{' '}
                      {(Number(order.total_value_inclusive) || 0).toLocaleString('en-ZA', {
                        minimumFractionDigits: 2,
                      })}
                    </td>
                    <td className="px-4 py-3 text-center">
                      <OrderStatusBadge status={order.status} size="sm" />
                    </td>
                    <td className="px-4 py-3 text-right">
                      <div className="flex items-center justify-end gap-2">
                        <button
                          className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded"
                          title="View Details"
                        >
                          <FileText className="w-4 h-4" />
                        </button>
                        <button
                          className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded"
                          title="Print"
                        >
                          <Printer className="w-4 h-4" />
                        </button>
                        {['O', 'P'].includes(order.status) && (
                          <a
                            href={`/dashboard/purchase-orders/transactions/stock-received?order=${order.order_number}`}
                            className="p-1.5 text-green-600 hover:text-green-700 hover:bg-green-100 rounded"
                            title="Receive Stock"
                          >
                            <Truck className="w-4 h-4" />
                          </a>
                        )}
                        {['O', 'P'].includes(order.status) && (
                          <a
                            href={`/dashboard/purchase-orders/transactions/cancel-order?order=${order.order_number}`}
                            className="p-1.5 text-red-400 hover:text-red-600 hover:bg-red-100 rounded"
                            title="Cancel Order"
                          >
                            <X className="w-4 h-4" />
                          </a>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}

          {/* Pagination */}
          {totalCount > 20 && (
            <div className="px-4 py-3 border-t bg-gray-50 flex items-center justify-between">
              <p className="text-sm text-gray-500">
                Showing {orders.length} of {totalCount} orders
              </p>
              <div className="flex gap-2">
                <button
                  onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                  disabled={currentPage === 1}
                  className="px-3 py-1 border rounded hover:bg-gray-100 disabled:opacity-50"
                >
                  Previous
                </button>
                <button
                  onClick={() => setCurrentPage((p) => p + 1)}
                  disabled={orders.length < 20}
                  className="px-3 py-1 border rounded hover:bg-gray-100 disabled:opacity-50"
                >
                  Next
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import {
  FileText,
  Download,
  ArrowLeft,
  BarChart3,
  Package,
  TrendingUp,
  Calendar,
  Truck,
} from 'lucide-react';
import Link from 'next/link';
import purchaseOrdersApi from '@/lib/purchaseOrdersApi';
import { getApiErrorMessage } from '@/lib/api';
import { OrderStatusBadge } from '@/components/purchase-orders/common/OrderStatusBadge';

interface ReportTemplate {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
}

const REPORTS: ReportTemplate[] = [
  {
    id: 'outstanding-delivery',
    title: 'Outstanding by Delivery Date',
    description: 'All outstanding orders within the selected date range',
    icon: <Calendar className="w-6 h-6" />,
  },
  {
    id: 'outstanding-stock',
    title: 'Stock on Order',
    description: 'Outstanding inventory organized by stock item',
    icon: <Package className="w-6 h-6" />,
  },
  {
    id: 'pre-orders',
    title: 'Pre-Order Planning',
    description: 'Items below reorder level with suggested order quantities',
    icon: <TrendingUp className="w-6 h-6" />,
  },
  {
    id: 'delivered',
    title: 'Fully Received Orders',
    description: 'All orders that have been fully received',
    icon: <BarChart3 className="w-6 h-6" />,
  },
  {
    id: 'back-orders',
    title: 'Back Orders',
    description: 'Back orders created from short deliveries',
    icon: <Truck className="w-6 h-6" />,
  },
  {
    id: 'delivery-variance',
    title: 'Delivery Variance',
    description: 'Cost and quantity variances found when receiving stock',
    icon: <FileText className="w-6 h-6" />,
  },
];

export default function ReportsPage() {
  const [selectedReport, setSelectedReport] = useState<string | null>(null);
  const [dateFrom, setDateFrom] = useState(
    () => new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
  );
  const [dateTo, setDateTo] = useState(() => new Date().toISOString().split('T')[0]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [rows, setRows] = useState<any[]>([]);
  const [columns, setColumns] = useState<{ key: string; label: string; align?: 'right' }[]>([]);

  const handleGenerateReport = async () => {
    if (!selectedReport) return;
    setLoading(true);
    setError('');
    setRows([]);
    try {
      switch (selectedReport) {
        case 'outstanding-delivery': {
          const data = await purchaseOrdersApi.orders.outstanding({
            delivery_date_from: dateFrom,
            delivery_date_to: dateTo,
          });
          setColumns([
            { key: 'order_number', label: 'Order #' },
            { key: 'supplier_name', label: 'Supplier' },
            { key: 'delivery_date', label: 'Delivery Date' },
            { key: 'status_display', label: 'Status' },
            { key: 'outstanding_value_inclusive', label: 'Outstanding Value', align: 'right' },
          ]);
          setRows(data);
          break;
        }
        case 'outstanding-stock': {
          const data = await purchaseOrdersApi.reports.stockOnOrder();
          setColumns([
            { key: 'stock_code', label: 'Stock Code' },
            { key: 'description', label: 'Description' },
            { key: 'quantity_on_hand', label: 'On Hand', align: 'right' },
            { key: 'quantity_on_order', label: 'On Order', align: 'right' },
            { key: 'reorder_quantity', label: 'Reorder Level', align: 'right' },
          ]);
          setRows(data);
          break;
        }
        case 'pre-orders': {
          const data = await purchaseOrdersApi.reports.preOrderReport();
          setColumns([
            { key: 'stock_code', label: 'Stock Code' },
            { key: 'description', label: 'Description' },
            { key: 'supplier_name', label: 'Supplier' },
            { key: 'suggested_order_qty', label: 'Suggested Qty', align: 'right' },
            { key: 'estimated_value', label: 'Estimated Value', align: 'right' },
          ]);
          setRows(data);
          break;
        }
        case 'delivered': {
          const data = await purchaseOrdersApi.orders.list({ status: 'F', page_size: 100 });
          setColumns([
            { key: 'order_number', label: 'Order #' },
            { key: 'supplier_name', label: 'Supplier' },
            { key: 'order_date', label: 'Order Date' },
            { key: 'total_value_inclusive', label: 'Total Value', align: 'right' },
          ]);
          setRows(data.results || (data as any));
          break;
        }
        case 'back-orders': {
          const data = await purchaseOrdersApi.backOrders.list();
          setColumns([
            { key: 'back_order_number', label: 'Back Order #' },
            { key: 'original_order_number', label: 'Original Order #' },
            { key: 'supplier_name', label: 'Supplier' },
            { key: 'reason', label: 'Reason' },
          ]);
          setRows((data as any).results || data);
          break;
        }
        case 'delivery-variance': {
          const data = await purchaseOrdersApi.orders.deliveryVarianceReport({
            start_date: dateFrom,
            end_date: dateTo,
          });
          setColumns([
            { key: 'order_number', label: 'Order #' },
            { key: 'supplier_name', label: 'Supplier' },
            { key: 'stock_code', label: 'Stock Code' },
            { key: 'quantity_short', label: 'Qty Short', align: 'right' },
            { key: 'value_variance', label: 'Value Variance', align: 'right' },
          ]);
          setRows(data);
          break;
        }
      }
    } catch (err) {
      setError(getApiErrorMessage(err, 'Failed to generate report'));
    } finally {
      setLoading(false);
    }
  };

  const formatCell = (key: string, value: any) => {
    if (value === null || value === undefined) return '';
    if (key === 'status_display' && rows.length) {
      return value;
    }
    if (typeof value === 'number' && key.match(/value|price|cost/i)) {
      return `R ${value.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}`;
    }
    return String(value);
  };

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="bg-white border-b px-6 py-4">
        <Link
          href="/dashboard/purchase-orders"
          className="inline-flex items-center gap-2 text-blue-600 hover:text-blue-700 font-medium mb-4"
        >
          <ArrowLeft className="w-4 h-4" />
          Back to Purchase Orders
        </Link>
        <h1 className="text-2xl font-bold text-gray-900">Purchase Orders Reports</h1>
        <p className="text-sm text-gray-500">
          Generate and view purchase order reports
        </p>
      </div>

      <div className="p-6">
        <div className="max-w-6xl mx-auto">
          {/* Date Range */}
          <div className="bg-white rounded-lg border shadow-sm p-4 mb-6">
            <h3 className="font-semibold text-gray-900 mb-4">Report Period</h3>
            <p className="text-xs text-gray-500 mb-3">Used by Outstanding by Delivery Date and Delivery Variance</p>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">From Date</label>
                <input
                  type="date"
                  value={dateFrom}
                  onChange={(e) => setDateFrom(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">To Date</label>
                <input
                  type="date"
                  value={dateTo}
                  onChange={(e) => setDateTo(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>
          </div>

          {/* Report Templates */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-6">
            {REPORTS.map((report) => (
              <button
                key={report.id}
                onClick={() => setSelectedReport(report.id)}
                className={`p-4 rounded-lg border-2 transition-all text-left ${
                  selectedReport === report.id
                    ? 'border-blue-500 bg-blue-50 shadow-md'
                    : 'border-gray-200 hover:border-gray-300 bg-white'
                }`}
              >
                <div className="flex items-start gap-3">
                  <div
                    className={`p-2 rounded-lg ${
                      selectedReport === report.id
                        ? 'bg-blue-100 text-blue-600'
                        : 'bg-gray-100 text-gray-600'
                    }`}
                  >
                    {report.icon}
                  </div>
                  <div>
                    <h4 className="font-semibold text-gray-900">{report.title}</h4>
                    <p className="text-xs text-gray-500 mt-1">{report.description}</p>
                  </div>
                </div>
              </button>
            ))}
          </div>

          {/* Action */}
          <div className="bg-white rounded-lg border shadow-sm p-4">
            <div className="flex flex-col md:flex-row gap-4 items-end justify-between">
              <div className="text-sm text-gray-600">
                {selectedReport ? (
                  <p>
                    Selected: <strong>{REPORTS.find((r) => r.id === selectedReport)?.title}</strong>
                  </p>
                ) : (
                  <p className="text-gray-400">Select a report to continue</p>
                )}
              </div>
              <button
                onClick={handleGenerateReport}
                disabled={!selectedReport || loading}
                className="flex items-center justify-center gap-2 px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loading ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                    Generating...
                  </>
                ) : (
                  <>
                    <Download className="w-4 h-4" />
                    Generate Report
                  </>
                )}
              </button>
            </div>
          </div>

          {error && (
            <div className="mt-6 p-4 bg-red-50 border border-red-200 rounded text-sm text-red-600">{error}</div>
          )}

          {/* Results */}
          {rows.length > 0 && (
            <div className="mt-6 bg-white rounded-lg border shadow-sm overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead className="bg-gray-50 border-b">
                    <tr>
                      {columns.map((col) => (
                        <th
                          key={col.key}
                          className={`px-4 py-3 text-xs font-medium text-gray-500 uppercase ${
                            col.align === 'right' ? 'text-right' : 'text-left'
                          }`}
                        >
                          {col.label}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="divide-y">
                    {rows.map((row, idx) => (
                      <tr key={idx} className="hover:bg-gray-50">
                        {columns.map((col) => (
                          <td
                            key={col.key}
                            className={`px-4 py-3 text-sm ${col.align === 'right' ? 'text-right font-medium' : ''}`}
                          >
                            {col.key === 'status_display' ? (
                              <OrderStatusBadge status={row.status} size="sm" />
                            ) : (
                              formatCell(col.key, row[col.key])
                            )}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {!loading && selectedReport && rows.length === 0 && (
            <div className="mt-6 bg-white rounded-lg border shadow-sm p-8 text-center text-gray-500">
              Click Generate Report to view results
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { ArrowLeft, AlertTriangle, CheckCircle, Loader } from 'lucide-react';
import Link from 'next/link';
import purchaseOrdersApi from '@/lib/purchaseOrdersApi';
import { getApiErrorMessage } from '@/lib/api';

export default function UtilitiesPage() {
  const [resetting, setResetting] = useState(false);
  const [resetResult, setResetResult] = useState<{ items_updated: number; changes: any[] } | null>(null);
  const [error, setError] = useState('');

  const handleResetQuantities = async () => {
    if (
      !window.confirm(
        "This recomputes every stock item's quantity-on-order from actual outstanding purchase orders. Continue?"
      )
    ) {
      return;
    }

    setResetting(true);
    setError('');
    try {
      const result = await purchaseOrdersApi.utilities.resyncOnOrderQuantities();
      setResetResult(result as any);
    } catch (err) {
      setError(getApiErrorMessage(err, 'Failed to resync on-order quantities'));
    } finally {
      setResetting(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="bg-white border-b px-6 py-4">
        <Link
          href="/dashboard/purchase-orders"
          className="inline-flex items-center gap-2 text-blue-600 hover:text-blue-700 font-medium mb-4"
        >
          <ArrowLeft className="w-4 h-4" />
          Back to Purchase Orders
        </Link>
        <h1 className="text-2xl font-bold text-gray-900">
          Purchase Order Utilities
        </h1>
        <p className="text-sm text-gray-500">
          Maintenance and administrative tools
        </p>
      </div>

      <div className="p-6">
        <div className="max-w-4xl mx-auto space-y-6">
          {error && (
            <div className="p-4 bg-red-50 border border-red-200 rounded flex items-center gap-3">
              <AlertTriangle className="w-5 h-5 text-red-600 flex-shrink-0" />
              <span className="text-red-600">{error}</span>
            </div>
          )}

          {/* Reset Purchase Order Quantities Utility */}
          <div className="bg-white rounded-lg border shadow-sm overflow-hidden">
            <div className="px-6 py-4 border-b bg-gray-50">
              <h2 className="text-lg font-semibold text-gray-900">
                Reset Purchase Order Quantities
              </h2>
              <p className="text-sm text-gray-500 mt-1">
                Resync stock-on-order quantities against actual outstanding purchase orders
              </p>
            </div>

            <div className="px-6 py-6">
              <div className="space-y-4">
                <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                  <h3 className="font-medium text-blue-900 mb-2">
                    What this does:
                  </h3>
                  <ul className="text-sm text-blue-800 space-y-1 list-disc list-inside">
                    <li>Recomputes each stock item&apos;s &quot;quantity on order&quot; from outstanding PO lines</li>
                    <li>Fixes drift caused by bugs, manual edits, or partial failures</li>
                    <li>Safe to run at any time — it only corrects quantity_on_order, nothing else</li>
                    <li>Requires Admin access</li>
                  </ul>
                </div>

                {resetResult ? (
                  <div className="p-4 bg-green-50 border border-green-200 rounded-lg">
                    <div className="flex items-start gap-3">
                      <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0 mt-0.5" />
                      <div className="flex-1">
                        <h4 className="font-medium text-green-900">Resync complete</h4>
                        <p className="text-sm text-green-700 mt-1">
                          {resetResult.items_updated} stock item{resetResult.items_updated === 1 ? '' : 's'} corrected
                        </p>
                        {resetResult.changes?.length > 0 && (
                          <div className="mt-3 max-h-48 overflow-y-auto border border-green-200 rounded bg-white">
                            <table className="w-full text-xs">
                              <thead className="bg-green-100">
                                <tr>
                                  <th className="text-left px-2 py-1">Stock Code</th>
                                  <th className="text-right px-2 py-1">Was</th>
                                  <th className="text-right px-2 py-1">Now</th>
                                </tr>
                              </thead>
                              <tbody>
                                {resetResult.changes.map((c: any, i: number) => (
                                  <tr key={i} className="border-t border-green-100">
                                    <td className="px-2 py-1">{c.stock_code}</td>
                                    <td className="px-2 py-1 text-right">{c.previous_quantity_on_order}</td>
                                    <td className="px-2 py-1 text-right">{c.corrected_quantity_on_order}</td>
                                  </tr>
                                ))}
                              </tbody>
                            </table>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ) : (
                  <p className="text-sm text-gray-600">
                    Click the button below to resync stock-on-order quantities.
                  </p>
                )}
              </div>

              <div className="mt-6 flex justify-end">
                <button
                  onClick={handleResetQuantities}
                  disabled={resetting}
                  className="flex items-center gap-2 px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {resetting ? (
                    <>
                      <Loader className="w-4 h-4 animate-spin" />
                      Resyncing...
                    </>
                  ) : (
                    'Resync Quantities'
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

