      if (!response) {
        throw new Error('Failed to create journal entry');
      }

      setSuccess('Journal entry recorded successfully!');
      setTimeout(() => onComplete(), 2000);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  };

