'use client';

import { useState, useEffect } from 'react';
import { ChevronLeft, Download, Eye } from 'lucide-react';
import creditorsApi from '@/lib/creditorsApi';

interface Transaction {
  id: number;
  supplier: string;
  transaction_type: string;
  transaction_number: string;
  invoice_number: string;
  transaction_date: string;
  amount_inclusive: number;
  vat_amount: number;
  balance_due: number;
  is_allocated: boolean;
}

interface TransactionsListProps {
  onBack: () => void;
}

const transactionTypeLabels: { [key: string]: string } = {
  INVOICE_STOCK: 'Stock Receiving',
  RETURN_STOCK: 'Stock Return',
  INVOICE_EXPENSE: 'Expense Invoice',
  RETURN_EXPENSE: 'Expense Return',
  PAYMENT: 'Payment',
  JOURNAL: 'Journal Entry',
  RFC: 'Return for Credit',
};

export default function TransactionsList({ onBack }: TransactionsListProps) {
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [filteredTransactions, setFilteredTransactions] = useState<Transaction[]>([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    transactionType: '',
    startDate: '',
    endDate: '',
    searchTerm: '',
  });

  useEffect(() => {
    fetchTransactions();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [transactions, filters]);

  const fetchTransactions = async () => {
    try {
      setLoading(true);
      const response = await creditorsApi.transactions.list();
      setTransactions(Array.isArray(response) ? response : []);
    } catch (err) {
      console.error('Error fetching transactions:', err);
      setTransactions([]);
    } finally {
      setLoading(false);
    }
  };

  const applyFilters = () => {
    let filtered = [...transactions];

    if (filters.transactionType) {
      filtered = filtered.filter((t) => t.transaction_type === filters.transactionType);
    }

    if (filters.startDate) {
      filtered = filtered.filter((t) => new Date(t.transaction_date) >= new Date(filters.startDate));
    }

    if (filters.endDate) {
      filtered = filtered.filter((t) => new Date(t.transaction_date) <= new Date(filters.endDate));
    }

    if (filters.searchTerm) {
      const term = filters.searchTerm.toLowerCase();
      filtered = filtered.filter((t) =>
        t.supplier.toLowerCase().includes(term) ||
        t.transaction_number.toLowerCase().includes(term) ||
        t.invoice_number.toLowerCase().includes(term)
      );
    }

    setFilteredTransactions(filtered);
  };

  const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFilters({ ...filters, [name]: value });
  };

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('en-ZA', {
      style: 'currency',
      currency: 'ZAR',
    }).format(value);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-ZA');
  };

  return (
    <div className="bg-white rounded-lg shadow-lg p-6">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-2xl font-bold">Creditors - Transactions List</h2>
          <p className="text-gray-600 mt-1">Total: {filteredTransactions.length} transactions</p>
        </div>
        <button
          onClick={onBack}
          className="flex items-center gap-2 px-4 py-2 text-blue-600 hover:text-blue-800 font-medium"
        >
          <ChevronLeft className="w-5 h-5" />
          Back to Menu
        </button>
      </div>

      {/* Filters */}
      <div className="bg-gray-50 p-4 rounded-lg mb-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Transaction Type
          </label>
          <select
            name="transactionType"
            value={filters.transactionType}
            onChange={handleFilterChange}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">All Types</option>
            {Object.entries(transactionTypeLabels).map(([key, label]) => (
              <option key={key} value={key}>
                {label}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Start Date
          </label>
          <input
            type="date"
            name="startDate"
            value={filters.startDate}
            onChange={handleFilterChange}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            End Date
          </label>
          <input
            type="date"
            name="endDate"
            value={filters.endDate}
            onChange={handleFilterChange}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Search
          </label>
          <input
            type="text"
            name="searchTerm"
            value={filters.searchTerm}
            onChange={handleFilterChange}
            placeholder="Supplier, Ref, Invoice #"
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>
      </div>

      {/* Table */}
      {loading ? (
        <div className="text-center py-8">
          <p className="text-gray-600">Loading transactions...</p>
        </div>
      ) : filteredTransactions.length === 0 ? (
        <div className="text-center py-8">
          <p className="text-gray-600">No transactions found</p>
        </div>
      ) : (
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-gray-50 border-b-2 border-gray-200">
                <th className="px-4 py-3 text-left font-semibold text-gray-900">Date</th>
                <th className="px-4 py-3 text-left font-semibold text-gray-900">Type</th>
                <th className="px-4 py-3 text-left font-semibold text-gray-900">Supplier</th>
                <th className="px-4 py-3 text-left font-semibold text-gray-900">Ref #</th>
                <th className="px-4 py-3 text-left font-semibold text-gray-900">Invoice #</th>
                <th className="px-4 py-3 text-right font-semibold text-gray-900">Amount</th>
                <th className="px-4 py-3 text-right font-semibold text-gray-900">VAT</th>
                <th className="px-4 py-3 text-right font-semibold text-gray-900">Balance Due</th>
                <th className="px-4 py-3 text-center font-semibold text-gray-900">Status</th>
                <th className="px-4 py-3 text-center font-semibold text-gray-900">Action</th>
              </tr>
            </thead>
            <tbody>
              {filteredTransactions.map((txn) => (
                <tr key={txn.id} className="border-b hover:bg-gray-50 transition-colors">
                  <td className="px-4 py-3 text-gray-700">{formatDate(txn.transaction_date)}</td>
                  <td className="px-4 py-3">
                    <span className="px-2 py-1 bg-blue-100 text-blue-800 rounded text-xs font-medium">
                      {transactionTypeLabels[txn.transaction_type] || txn.transaction_type}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-gray-700">{txn.supplier}</td>
                  <td className="px-4 py-3 font-mono text-gray-700">{txn.transaction_number}</td>
                  <td className="px-4 py-3 font-mono text-gray-700">{txn.invoice_number || '-'}</td>
                  <td className="px-4 py-3 text-right text-gray-900 font-semibold">
                    {formatCurrency(txn.amount_inclusive)}
                  </td>
                  <td className="px-4 py-3 text-right text-gray-700">{formatCurrency(txn.vat_amount)}</td>
                  <td className="px-4 py-3 text-right text-gray-700">{formatCurrency(txn.balance_due)}</td>
                  <td className="px-4 py-3 text-center">
                    <span
                      className={`px-2 py-1 rounded text-xs font-medium ${
                        txn.is_allocated
                          ? 'bg-green-100 text-green-800'
                          : 'bg-yellow-100 text-yellow-800'
                      }`}
                    >
                      {txn.is_allocated ? 'Allocated' : 'Pending'}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-center">
                    <button className="text-blue-600 hover:text-blue-800 p-1">
                      <Eye className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Summary */}
      {filteredTransactions.length > 0 && (
        <div className="mt-6 border-t pt-6 grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-blue-50 p-4 rounded-lg border border-blue-200">
            <p className="text-sm text-gray-600 mb-1">Total Transactions</p>
            <p className="text-2xl font-bold text-blue-900">{filteredTransactions.length}</p>
          </div>
          <div className="bg-green-50 p-4 rounded-lg border border-green-200">
            <p className="text-sm text-gray-600 mb-1">Total Amount</p>
            <p className="text-2xl font-bold text-green-900">
              {formatCurrency(
                filteredTransactions.reduce((sum, t) => sum + t.amount_inclusive, 0)
              )}
            </p>
          </div>
          <div className="bg-orange-50 p-4 rounded-lg border border-orange-200">
            <p className="text-sm text-gray-600 mb-1">Total VAT</p>
            <p className="text-2xl font-bold text-orange-900">
              {formatCurrency(filteredTransactions.reduce((sum, t) => sum + t.vat_amount, 0))}
            </p>
          </div>
          <div className="bg-purple-50 p-4 rounded-lg border border-purple-200">
            <p className="text-sm text-gray-600 mb-1">Outstanding Balance</p>
            <p className="text-2xl font-bold text-purple-900">
              {formatCurrency(filteredTransactions.reduce((sum, t) => sum + t.balance_due, 0))}
            </p>
          </div>
        </div>
      )}

      {/* Export Button */}
      <div className="mt-6 flex gap-3">
        <button className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium transition-colors">
          <Download className="w-4 h-4" />
          Export to CSV
        </button>
      </div>
    </div>
  );
}

'use client';

import { Card } from '@/components/ui/card';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import type { DebtorsSummary } from '@/lib/types/debtors';

interface AgeAnalysisChartProps {
  summary: DebtorsSummary;
}

export default function AgeAnalysisChart({ summary }: AgeAnalysisChartProps) {
  const totalReceivable = summary.total_receivable || 0;
  const pct = (amount: number) => (totalReceivable > 0 ? (amount / totalReceivable) * 100 : 0);

  const data = [
    {
      name: 'Current',
      amount: summary.aging_summary?.current || 0,
      percentage: pct(summary.aging_summary?.current || 0),
    },
    {
      name: '0-30 Days',
      amount: summary.aging_summary?.days_30 || 0,
      percentage: pct(summary.aging_summary?.days_30 || 0),
    },
    {
      name: '30-60 Days',
      amount: summary.aging_summary?.days_60 || 0,
      percentage: pct(summary.aging_summary?.days_60 || 0),
    },
    {
      name: '60-90 Days',
      amount: summary.aging_summary?.days_90 || 0,
      percentage: pct(summary.aging_summary?.days_90 || 0),
    },
    {
      name: '120+ Days',
      amount: summary.aging_summary?.days_120_plus || 0,
      percentage: pct(summary.aging_summary?.days_120_plus || 0),
    },
  ];

  const COLORS = ['#22c55e', '#84cc16', '#f59e0b', '#ef4444', '#dc2626'];

  return (
    <Card className="p-6">
      <div className="mb-6">
        <h2 className="text-xl font-bold">Aging Analysis</h2>
        <p className="text-sm text-gray-600 mt-1">Receivables breakdown by age</p>
      </div>

      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={data} margin={{ top: 20, right: 30, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
          <XAxis dataKey="name" />
          <YAxis />
          <Tooltip
            formatter={(value: any) => {
              if (typeof value === 'number') {
                return `$${value.toLocaleString()}`;
              }
              return value;
            }}
          />
          <Bar dataKey="amount" fill="#3b82f6" radius={[8, 8, 0, 0]}>
            {data.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>

      <div className="mt-6 grid grid-cols-5 gap-2 text-xs">
        {data.map((item, idx) => (
          <div key={idx} className="text-center">
            <div className="w-3 h-3 mx-auto mb-1 rounded" style={{ backgroundColor: COLORS[idx] }} />
            <div className="font-semibold">${(item.amount / 1000).toFixed(1)}K</div>
            <div className="text-gray-600">{item.percentage.toFixed(0)}%</div>
          </div>
        ))}
      </div>
    </Card>
  );
}

'use client';

import { useState } from 'react';
import { apiRequest } from '@/lib/api';

interface SalesTransaction {
  id: number;
  date: string;
  description: string;
  quantity: number;
  cost_price: number;
  selling_price: number;
  gross_profit: number;
}

interface AccountData {
  account_number: string;
  account_name: string;
  sales_transactions: SalesTransaction[];
}

export default function AccountSalesHistoryEnquiry() {
  const [startDate, setStartDate] = useState(new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0]);
  const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
  const [accountNumber, setAccountNumber] = useState('');
  const [accountData, setAccountData] = useState<AccountData | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSearch = async () => {
    if (!accountNumber) {
      setError('Please enter an account number');
      return;
    }

    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      params.append('start_date', startDate);
      params.append('end_date', endDate);
      const response = await apiRequest(`/api/v1/debtors/${accountNumber}/sales-history/?${params}`);
      const responseData = (response as any).data || (response as any);
      setAccountData(responseData);
    } catch (err) {
      setError('Account not found or no sales history available');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6 p-6">
      <h2 className="text-2xl font-bold text-gray-900">Account Sales History</h2>

      {/* Date and Account Selection */}
      <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 space-y-4">
        <h3 className="font-semibold text-gray-900">Selection Criteria</h3>
        
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Start Date</label>
            <input
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">End Date</label>
            <input
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Account Number</label>
            <input
              type="text"
              value={accountNumber}
              onChange={(e) => setAccountNumber(e.target.value)}
              placeholder="Enter account #"
              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500"
            />
          </div>
        </div>

        <div className="flex gap-2">
          <button
            onClick={handleSearch}
            disabled={loading}
            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-gray-400 font-medium"
          >
            {loading ? 'Loading...' : 'Generate Report'}
          </button>
        </div>
      </div>

      {/* Error Display */}
      {error && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-red-700 text-sm">
          {error}
        </div>
      )}

      {/* Account Info Summary */}
      <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
        <div className="bg-gradient-to-br from-blue-50 to-blue-100 p-4 rounded-lg border border-blue-200">
          <p className="text-xs text-blue-700 font-medium">Account #</p>
          <p className="text-lg font-bold text-blue-900">{accountData?.account_number || '-'}</p>
        </div>
        <div className="bg-gradient-to-br from-green-50 to-green-100 p-4 rounded-lg border border-green-200">
          <p className="text-xs text-green-700 font-medium">Debtor Name</p>
          <p className="text-lg font-bold text-green-900">{accountData?.account_name || '-'}</p>
        </div>
        <div className="bg-gradient-to-br from-purple-50 to-purple-100 p-4 rounded-lg border border-purple-200">
          <p className="text-xs text-purple-700 font-medium">Period Sales</p>
          <p className="text-lg font-bold text-purple-900">R{accountData ? accountData.sales_transactions.reduce((sum, t) => sum + (t.selling_price * t.quantity), 0).toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '0.00'}</p>
        </div>
        <div className="bg-gradient-to-br from-yellow-50 to-yellow-100 p-4 rounded-lg border border-yellow-200">
          <p className="text-xs text-yellow-700 font-medium">Gross Profit</p>
          <p className="text-lg font-bold text-yellow-900">R{accountData ? accountData.sales_transactions.reduce((sum, t) => sum + t.gross_profit, 0).toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '0.00'}</p>
        </div>
      </div>

      {/* Sales Transactions Table */}
      <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-gray-100 border-b border-gray-200">
                <th className="px-4 py-3 text-left font-semibold text-gray-700">Date</th>
                <th className="px-4 py-3 text-left font-semibold text-gray-700">Description</th>
                <th className="px-4 py-3 text-right font-semibold text-gray-700">Quantity</th>
                <th className="px-4 py-3 text-right font-semibold text-gray-700">Cost Price</th>
                <th className="px-4 py-3 text-right font-semibold text-gray-700">Selling Price</th>
                <th className="px-4 py-3 text-right font-semibold text-gray-700">Gross Profit</th>
              </tr>
            </thead>
            <tbody>
              {accountData && accountData.sales_transactions.length > 0 ? (
                accountData.sales_transactions.map((transaction) => (
                  <tr key={transaction.id} className="border-b border-gray-200 hover:bg-gray-50">
                    <td className="px-4 py-3 text-gray-700">{new Date(transaction.date).toLocaleDateString('en-ZA')}</td>
                    <td className="px-4 py-3 text-gray-700">{transaction.description}</td>
                    <td className="px-4 py-3 text-right">{transaction.quantity}</td>
                    <td className="px-4 py-3 text-right">R{transaction.cost_price.toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
                    <td className="px-4 py-3 text-right">R{transaction.selling_price.toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
                    <td className="px-4 py-3 text-right font-medium">R{transaction.gross_profit.toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
                  </tr>
                ))
              ) : (
                <tr className="border-b border-gray-200 hover:bg-gray-50">
                  <td colSpan={6} className="px-4 py-8 text-center text-gray-500">
                    {accountData ? 'No sales transactions found for this period' : 'Select an account and click "Generate Report" to view sales history'}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Navigation and Print Options */}
      <div className="flex flex-wrap gap-2 justify-between pt-4 border-t border-gray-200">
        <div className="flex gap-2">
          <button className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 text-sm font-medium">
            ← Previous
          </button>
          <button className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 text-sm font-medium">
            Next →
          </button>
        </div>

        <div className="flex gap-2">
          <button className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 text-sm font-medium">
            View Totals
          </button>
          <button className="px-6 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 font-medium">
            Print Listing
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import { Card } from '@/components/ui/card';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import type { DebtorsSummary } from '@/lib/types/debtors';

interface AgingChartProps {
  summary: DebtorsSummary;
}

export default function AgingChart({ summary }: AgingChartProps) {
  const data = [
    { name: 'Current', value: summary.aging_summary?.current || 0 },
    { name: '30 Days', value: summary.aging_summary?.days_30 || 0 },
    { name: '60 Days', value: summary.aging_summary?.days_60 || 0 },
    { name: '90 Days', value: summary.aging_summary?.days_90 || 0 },
    { name: '120+ Days', value: summary.aging_summary?.days_120_plus || 0 },
  ];

  const COLORS = ['#22c55e', '#84cc16', '#f59e0b', '#ef4444', '#991b1b'];

  return (
    <Card className="p-6">
      <h2 className="text-lg font-bold mb-4">Receivables by Age</h2>
      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={data}>
          <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
          <XAxis dataKey="name" />
          <YAxis />
          <Tooltip
            formatter={(value: any) => `$${(value as number).toLocaleString()}`}
            labelFormatter={(label) => `Age: ${label}`}
          />
          <Bar dataKey="value" radius={[8, 8, 0, 0]}>
            {data.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </Card>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { apiRequest } from '@/lib/api';
import SummaryStatistics from './SummaryStatistics';
import AgingChart from './AgingChart';
import AgeAnalysisDisplay from './AgeAnalysisDisplay';
import type { DebtorsSummary, AgeAnalysis } from '@/lib/types/debtors';

export default function DebtorsSummaryEnquiry() {
  const [cutoffDate, setCutoffDate] = useState<string>(
    new Date().toISOString().split('T')[0]
  );
  const [summary, setSummary] = useState<DebtorsSummary | null>(null);
  const [ageAnalysis, setAgeAnalysis] = useState<AgeAnalysis | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string>('');

  const generateReport = async () => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      if (cutoffDate) {
        params.append('cutoff_date', cutoffDate);
      }

      // Fetch summary data
      const summaryResponse = await apiRequest(
        `/api/v1/debtors/summary/?${params}`
      );
      const summaryData = (summaryResponse as any).data || summaryResponse;
      setSummary(summaryData);

      // Fetch age analysis data
      const ageResponse = await apiRequest(
        `/api/v1/debtors/age-analysis/?${params}`
      );
      const ageData = (ageResponse as any).data || ageResponse;
      setAgeAnalysis(ageData);
    } catch (err) {
      setError('Failed to load debtors summary');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  // Load data on component mount
  useEffect(() => {
    generateReport();
  }, []);

  return (
    <div className="space-y-6 p-6">
      <h2 className="text-2xl font-bold text-gray-900">
        Total Debtors Summary - Age Analysis & Control Enquiry
      </h2>

      {/* Filters */}
      <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 space-y-4">
        <h3 className="font-semibold text-gray-900">Report Filters</h3>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Cutoff Date
            </label>
            <input
              type="date"
              value={cutoffDate}
              onChange={(e) => setCutoffDate(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div className="flex items-end">
            <button
              onClick={generateReport}
              disabled={loading}
              className="w-full px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-gray-400 transition-colors font-medium"
            >
              {loading ? 'Loading...' : 'Generate Report'}
            </button>
          </div>
        </div>
      </div>

      {/* Error Message */}
      {error && (
        <div className="bg-red-50 border border-red-200 p-4 rounded-lg">
          <p className="text-red-800 text-sm">{error}</p>
        </div>
      )}

      {/* Summary Statistics */}
      {summary && (
        <div>
          <SummaryStatistics summary={summary} />
        </div>
      )}

      {/* Charts and Analysis */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Aging Chart */}
        {summary && (
          <div>
            <AgingChart summary={summary} />
          </div>
        )}

        {/* Age Analysis Display */}
        {ageAnalysis && (
          <div>
            <AgeAnalysisDisplay ageAnalysis={ageAnalysis} />
          </div>
        )}
      </div>

      {/* Loading State */}
      {loading && (
        <div className="flex justify-center items-center py-12">
          <div className="text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
            <p className="text-gray-600">Loading summary data...</p>
          </div>
        </div>
      )}

      {/* No Data State */}
      {!summary && !loading && (
        <div className="text-center py-12">
          <p className="text-gray-600">Click &quot;Generate Report&quot; to view debtors summary</p>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
