'use client';

import { useState, useEffect } from 'react';
import debtorsApi from '@/lib/debtorsApi';

interface UnmatchedItem {
  id: number;
  debtor_id: number;
  debtor_name: string;
  transaction_type: string;
  transaction_number: string;
  transaction_date: string;
  amount: number;
  balance_due: number;
  days_overdue: number;
}

const TYPE_LABELS: Record<string, string> = {
  IN: 'Invoice',
  CN: 'Credit Note',
  PY: 'Payment',
  RCP: 'Receipt',
  INT: 'Interest Charge',
  JD: 'Journal Debit',
  JC: 'Journal Credit',
  DM: 'Debit Memo',
  CM: 'Credit Memo',
};

const TYPE_COLORS: Record<string, string> = {
  IN: 'bg-red-100 text-red-800',
  CN: 'bg-yellow-100 text-yellow-800',
  PY: 'bg-green-100 text-green-800',
  RCP: 'bg-green-100 text-green-800',
  INT: 'bg-purple-100 text-purple-800',
  JD: 'bg-blue-100 text-blue-800',
  JC: 'bg-blue-100 text-blue-800',
};

export default function UnmatchedItemsEnquiry() {
  const [unmatchedItems, setUnmatchedItems] = useState<UnmatchedItem[]>([]);
  const [viewMode, setViewMode] = useState<'ageing' | 'balance'>('ageing');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedDebtor, setSelectedDebtor] = useState<string>('');

  useEffect(() => {
    loadUnmatchedItems();
  }, []);

  const loadUnmatchedItems = async () => {
    try {
      // DebteopenViewSet.outstanding() lists every Open Item account's
      // unmatched/partially-allocated transactions (balancedue > 0,
      // posted='Y') directly off the Debtopen model — the same open-item
      // ledger receipt allocation posts against — rather than re-deriving
      // "unmatched" from DebtorTransaction client-side. debtor_name comes
      // straight off DebteopenSerializer (item.dno is Debtor's internal pk,
      // not its account number, so it can't be correlated against a
      // separately-loaded debtor list).
      const itemsResponse = await debtorsApi.openItems.outstanding();
      const items = ((itemsResponse as any).results || itemsResponse || []) as any[];
      const today = new Date();

      const allUnmatched: UnmatchedItem[] = items.map((item) => {
        const txDate = new Date(item.date);
        const daysOverdue = Math.max(
          0,
          Math.floor((today.getTime() - txDate.getTime()) / (1000 * 60 * 60 * 24))
        );
        return {
          id: item.id,
          debtor_id: item.debtor_account_number,
          debtor_name: item.debtor_name || `Debtor ${item.debtor_account_number}`,
          transaction_type: item.type,
          transaction_number: item.dtrano,
          transaction_date: item.date,
          amount: parseFloat(item.total),
          balance_due: parseFloat(item.balancedue),
          days_overdue: daysOverdue,
        };
      });

      setUnmatchedItems(allUnmatched);
    } catch (err) {
      setError('Failed to load unmatched items');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const getTransactionTypeDisplay = (type: string) => TYPE_LABELS[type] || type;
  const getTypeColor = (type: string) => TYPE_COLORS[type] || 'bg-gray-100 text-gray-800';

  const getAgeingColor = (days: number) => {
    if (days > 180) return 'text-red-700';
    if (days > 120) return 'text-orange-700';
    if (days > 60) return 'text-yellow-700';
    return 'text-green-700';
  };

  const uniqueDebtors = [...new Set(unmatchedItems.map(item => item.debtor_name))];
  const filteredItems = selectedDebtor
    ? unmatchedItems.filter(item => item.debtor_name === selectedDebtor)
    : unmatchedItems;

  const totalBalance = filteredItems.reduce((sum, item) => sum + item.balance_due, 0);

  if (loading) {
    return <div className="p-6 text-center text-gray-500">Loading unmatched items...</div>;
  }

  return (
    <div className="space-y-6 p-6">
      <h2 className="text-2xl font-bold text-gray-900">Unmatched Open Item Transactions</h2>

      {error && (
        <div className="p-4 bg-red-50 border border-red-200 text-red-700 rounded-lg text-sm">
          {error}
        </div>
      )}

      {/* Summary Cards */}
      <div className="grid grid-cols-3 gap-4">
        <div className="bg-gradient-to-br from-blue-50 to-blue-100 p-4 rounded-lg border border-blue-200">
          <p className="text-xs text-blue-700 font-medium">Total Unmatched</p>
          <p className="text-2xl font-bold text-blue-900">{filteredItems.length}</p>
        </div>

        <div className="bg-gradient-to-br from-red-50 to-red-100 p-4 rounded-lg border border-red-200">
          <p className="text-xs text-red-700 font-medium">Total Balance Due</p>
          <p className="text-2xl font-bold text-red-900">R{totalBalance.toFixed(2)}</p>
        </div>

        <div className="bg-gradient-to-br from-purple-50 to-purple-100 p-4 rounded-lg border border-purple-200">
          <p className="text-xs text-purple-700 font-medium">Debtors with Items</p>
          <p className="text-2xl font-bold text-purple-900">{uniqueDebtors.length}</p>
        </div>
      </div>

      {/* Controls */}
      <div className="flex gap-4 items-center bg-gray-50 p-4 rounded-lg border border-gray-200">
        <div className="flex-1">
          <label className="block text-sm font-medium text-gray-700 mb-2">Filter by Debtor</label>
          <select
            value={selectedDebtor}
            onChange={(e) => setSelectedDebtor(e.target.value)}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            <option value="">All Debtors</option>
            {uniqueDebtors.map(debtor => (
              <option key={debtor} value={debtor}>{debtor}</option>
            ))}
          </select>
        </div>

        <div className="flex gap-2">
          <button
            onClick={() => setViewMode('ageing')}
            className={`px-4 py-2 rounded-lg font-medium transition-colors ${
              viewMode === 'ageing'
                ? 'bg-blue-600 text-white'
                : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
            }`}
          >
            View by Ageing
          </button>
          <button
            onClick={() => setViewMode('balance')}
            className={`px-4 py-2 rounded-lg font-medium transition-colors ${
              viewMode === 'balance'
                ? 'bg-blue-600 text-white'
                : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
            }`}
          >
            View by Balance Due
          </button>
        </div>

        <button
          onClick={() => window.print()}
          className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 font-medium"
        >
          Print
        </button>
      </div>

      {/* Transactions Table */}
      {filteredItems.length > 0 ? (
        <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-gray-100 border-b border-gray-200">
                  <th className="px-4 py-3 text-left font-semibold text-gray-700">Debtor</th>
                  <th className="px-4 py-3 text-left font-semibold text-gray-700">Type</th>
                  <th className="px-4 py-3 text-left font-semibold text-gray-700">Transaction #</th>
                  <th className="px-4 py-3 text-left font-semibold text-gray-700">Date</th>
                  <th className="px-4 py-3 text-right font-semibold text-gray-700">
                    {viewMode === 'balance' ? 'Balance Due' : 'Amount'}
                  </th>
                  <th className="px-4 py-3 text-right font-semibold text-gray-700">Ageing (Days)</th>
                </tr>
              </thead>
              <tbody>
                {filteredItems
                  .sort((a, b) =>
                    viewMode === 'balance'
                      ? b.balance_due - a.balance_due
                      : b.days_overdue - a.days_overdue
                  )
                  .map(item => (
                    <tr key={item.id} className="border-b border-gray-200 hover:bg-gray-50">
                      <td className="px-4 py-3 font-medium text-gray-900">{item.debtor_name}</td>
                      <td className="px-4 py-3">
                        <span className={`px-2 py-1 rounded-full text-xs font-semibold ${getTypeColor(item.transaction_type)}`}>
                          {getTransactionTypeDisplay(item.transaction_type)}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-gray-900">{item.transaction_number}</td>
                      <td className="px-4 py-3 text-gray-600">
                        {new Date(item.transaction_date).toLocaleDateString()}
                      </td>
                      <td className="px-4 py-3 text-right font-semibold text-gray-900">
                        R{item.balance_due.toFixed(2)}
                      </td>
                      <td className={`px-4 py-3 text-right font-semibold ${getAgeingColor(item.days_overdue)}`}>
                        {item.days_overdue} days
                      </td>
                    </tr>
                  ))}
              </tbody>
              <tfoot>
                <tr className="bg-gray-100 border-t-2 border-gray-300">
                  <td colSpan={4} className="px-4 py-3 font-semibold text-gray-900">Total</td>
                  <td className="px-4 py-3 text-right font-bold text-gray-900">
                    R{filteredItems.reduce((sum, item) => sum + item.balance_due, 0).toFixed(2)}
                  </td>
                  <td></td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>
      ) : (
        <div className="p-8 bg-gray-50 border border-gray-200 rounded-lg text-center text-gray-600">
          <p className="text-lg">✓ No unmatched items found</p>
          <p className="text-sm mt-2">All Open Item transactions have been matched.</p>
        </div>
      )}

      {/* Ageing Summary */}
      {viewMode === 'ageing' && filteredItems.length > 0 && (
        <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 space-y-3">
          <h4 className="font-semibold text-gray-900">Ageing Summary</h4>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 text-sm">
            {[
              { label: 'Current (0-30)', min: 0, max: 30 },
              { label: '31-60 Days', min: 31, max: 60 },
              { label: '61-120 Days', min: 61, max: 120 },
              { label: '120+ Days', min: 121, max: Infinity },
            ].map(period => {
              const items = filteredItems.filter(
                item => item.days_overdue >= period.min && item.days_overdue <= period.max
              );
              const total = items.reduce((sum, item) => sum + item.balance_due, 0);
              return (
                <div key={period.label} className="bg-white p-3 rounded border border-gray-200">
                  <p className="text-gray-600 font-medium text-xs">{period.label}</p>
                  <p className="text-lg font-bold text-gray-900">R{total.toFixed(2)}</p>
                  <p className="text-xs text-gray-500">{items.length} items</p>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useMutation } from '@tanstack/react-query';
import debtorsApi from '@/lib/debtorsApi';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card } from '@/components/ui/card';
import { Loader, AlertCircle, CheckCircle } from 'lucide-react';

import type { DebtorAccount, DebtorCreateData, DebtorEditData } from '@/lib/types/debtors';

interface DebtorAccountFormProps {
  initialData?: DebtorAccount;
  isEdit?: boolean;
  onSuccess?: () => void;
}

// Constants
const SUCCESS_REDIRECT_DELAY = 2000;
const MAX_SHORT_NAME_LENGTH = 20;
const MAX_CONTACT_LENGTH = 20;
const MAX_POSTAL_CODE_LENGTH = 4;

const DEFAULT_FORM_DATA: DebtorCreateData = {
  customer_number: 0,
  name: '',
  short_name: '',
  contact_person: '',
  phone: '',
  phone2: '',
  fax: '',
  address_line1: '',
  address_line2: '',
  address_line3: '',
  postal_code: '',
  delivery_address1: '',
  delivery_address2: '',
  delivery_address3: '',
  delivery_address4: '',
  tax_number: '',
  account_type: '',
  price_level: 1,
  payment_terms: 30,
  discount_percentage: 0,
  prompt_payment_discount: 0,
  credit_limit: 0,
  area_code: 0,
  interest_flag: false,
  block_flag: false,
  is_active: true,
  discount_printable: false,
  positive_balance_only: false,
  // Legacy alias fields required by DebtorCreateData type
  dno: 0,
  dname: '',
  d150: 0,
};

type FormData = DebtorCreateData & Partial<Pick<DebtorAccount, 'id' | 'created_at' | 'updated_at'>>;

export default function DebtorAccountForm({
  initialData,
  isEdit = false,
  onSuccess,
}: DebtorAccountFormProps) {
  const [formData, setFormData] = useState<FormData>(DEFAULT_FORM_DATA);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  // Sync formData when initialData changes
  useEffect(() => {
    if (initialData) {
      setFormData({
        ...DEFAULT_FORM_DATA,
        ...initialData,
        // Normalize boolean flags from API ('Y'/'N' or true/false to boolean)
        interest_flag: initialData.interest_flag === 'Y' || initialData.interest_flag === true,
        block_flag: initialData.block_flag === 'Y' || initialData.block_flag === true,
        discount_printable: initialData.discount_printable === 'Y' || initialData.discount_printable === true,
        positive_balance_only: initialData.positive_balance_only === 'Y' || initialData.positive_balance_only === true,
      });
    }
  }, [initialData]);

  const mutation = useMutation({
    mutationFn: async () => {
      const submitData = prepareSubmitData(formData, isEdit);

      if (isEdit && initialData?.id) {
        return debtorsApi.accounts.update(initialData.id, submitData as DebtorEditData);
      } else {
        return debtorsApi.accounts.create(submitData as DebtorCreateData);
      }
    },
    onSuccess: () => {
      setSuccess(true);
      setError(null);
      setTimeout(() => {
        onSuccess?.();
      }, SUCCESS_REDIRECT_DELAY);
    },
    onError: (err: any) => {
      const errorData = err.response?.data;
      // Backend returns { error: { code, message, field_errors } }
      if (errorData?.error) {
        const backendError = errorData.error;
        if (backendError.field_errors) {
          // Format field errors nicely
          const fieldErrors = Object.entries(backendError.field_errors)
            .map(([field, messages]) => `${field}: ${Array.isArray(messages) ? messages.join(', ') : messages}`)
            .join('; ');
          setError(fieldErrors || backendError.message || 'Failed to save account');
        } else {
          setError(backendError.message || 'Failed to save account');
        }
      } else if (typeof errorData === 'object' && errorData !== null) {
        // Fallback for other error formats
        const fieldErrors = Object.entries(errorData)
          .map(([field, message]) => `${field}: ${message}`)
          .join(', ');
        setError(fieldErrors || err.message || 'Failed to save account');
      } else {
        setError(errorData?.detail || err.message || 'Failed to save account');
      }
      setSuccess(false);
    },
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;

    let processedValue: any = value;

    if (type === 'checkbox') {
      processedValue = (e.target as HTMLInputElement).checked;
    } else if (type === 'number') {
      processedValue = value === '' ? 0 : Number(value);
    }

    setFormData((prev) => ({
      ...prev,
      [name]: processedValue,
    }));
    setError(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const validationError = validateForm(formData);
    if (validationError) {
      setError(validationError);
      return;
    }

    mutation.mutate();
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      {/* Error Alert */}
      {error && (
        <div
          className="p-3 bg-red-50 border border-red-200 rounded-lg flex gap-2"
          role="alert"
          aria-live="assertive"
        >
          <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
          <div className="text-sm text-red-800">{error}</div>
        </div>
      )}

      {/* Success Alert */}
      {success && (
        <div
          className="p-3 bg-green-50 border border-green-200 rounded-lg flex gap-2"
          role="alert"
          aria-live="polite"
        >
          <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0 mt-0.5" />
          <div className="text-sm text-green-800">
            {isEdit ? 'Account updated successfully!' : 'Account created successfully!'}
          </div>
        </div>
      )}

      <div className="space-y-8">
        {/* Basic Information Section */}
        <section>
          <h2 className="text-lg font-semibold mb-4">Basic Information</h2>
          <div className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label htmlFor="customer_number" className="block text-sm font-medium mb-1">
                  Account Number
                </label>
                <Input
                  id="customer_number"
                  name="customer_number"
                  value={formData.customer_number || ''}
                  onChange={handleChange}
                  placeholder="Auto-generated"
                  disabled={isEdit}
                  aria-describedby="customer_number-hint"
                />
                <p id="customer_number-hint" className="text-xs text-gray-500 mt-1">
                  {isEdit ? 'Cannot be changed' : 'Will be assigned automatically'}
                </p>
              </div>

              <div>
                <label htmlFor="name" className="block text-sm font-medium mb-1">
                  <span className="text-red-600">* </span>Debtor Name
                </label>
                <Input
                  id="name"
                  name="name"
                  value={formData.name || ''}
                  onChange={handleChange}
                  placeholder="Company name"
                  required
                  aria-required="true"
                  disabled={mutation.isPending}
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label htmlFor="short_name" className="block text-sm font-medium mb-1">
                  <span className="text-red-600">* </span>Short Name
                </label>
                <Input
                  id="short_name"
                  name="short_name"
                  value={formData.short_name || ''}
                  onChange={handleChange}
                  placeholder="Max 20 characters"
                  maxLength={MAX_SHORT_NAME_LENGTH}
                  required
                  aria-required="true"
                  disabled={mutation.isPending}
                />
              </div>

              <div>
                <label htmlFor="account_type" className="block text-sm font-medium mb-1">
                  Account Type
                </label>
                <select
                  id="account_type"
                  name="account_type"
                  value={formData.account_type || ''}
                  onChange={handleChange}
                  className="w-full border rounded-md px-3 py-2 h-10 text-sm"
                  disabled={mutation.isPending}
                >
                  <option value="">Balance Forward</option>
                  <option value="O">Open Item</option>
                  <option value="C">Cash Customer</option>
                </select>
              </div>
            </div>

            <div>
              <label htmlFor="contact_person" className="block text-sm font-medium mb-1">
                Contact Person
              </label>
              <Input
                id="contact_person"
                name="contact_person"
                value={formData.contact_person || ''}
                onChange={handleChange}
                placeholder="e.g., John Smith"
                maxLength={MAX_CONTACT_LENGTH}
                aria-describedby="contact_person-hint"
                disabled={mutation.isPending}
              />
              <p id="contact_person-hint" className="text-xs text-gray-500 mt-1">
                The person to ask for when calling about orders or payments
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label htmlFor="phone" className="block text-sm font-medium mb-1">
                  Telephone
                </label>
                <Input
                  id="phone"
                  name="phone"
                  type="tel"
                  value={formData.phone || ''}
                  onChange={handleChange}
                  placeholder="Primary phone"
                  disabled={mutation.isPending}
                />
              </div>

              <div>
                <label htmlFor="phone2" className="block text-sm font-medium mb-1">
                  Cell Number <span className="text-red-500">*</span>
                </label>
                <Input
                  id="phone2"
                  name="phone2"
                  type="tel"
                  value={formData.phone2 || ''}
                  onChange={handleChange}
                  placeholder="Mobile number (required)"
                  required
                  disabled={mutation.isPending}
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label htmlFor="fax" className="block text-sm font-medium mb-1">
                  Fax
                </label>
                <Input
                  id="fax"
                  name="fax"
                  type="tel"
                  value={formData.fax || ''}
                  onChange={handleChange}
                  placeholder="Fax number"
                  disabled={mutation.isPending}
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label htmlFor="tax_number" className="block text-sm font-medium mb-1">
                  Tax/VAT Number
                </label>
                <Input
                  id="tax_number"
                  name="tax_number"
                  value={formData.tax_number || ''}
                  onChange={handleChange}
                  placeholder="VAT registration"
                  disabled={mutation.isPending}
                />
              </div>

              <div>
                <label htmlFor="postal_code" className="block text-sm font-medium mb-1">
                  Postal Code
                </label>
                <Input
                  id="postal_code"
                  name="postal_code"
                  value={formData.postal_code || ''}
                  onChange={handleChange}
                  placeholder="Postal code"
                  maxLength={MAX_POSTAL_CODE_LENGTH}
                  disabled={mutation.isPending}
                />
              </div>
            </div>
          </div>
        </section>

        {/* Addresses Section */}
        <section>
          <h2 className="text-lg font-semibold mb-4">Addresses</h2>
          <div className="space-y-6">
            <div>
              <h3 className="text-sm font-bold mb-3 text-gray-700">Postal Address</h3>
              <div className="space-y-2">
                <Input
                  id="address_line1"
                  name="address_line1"
                  value={formData.address_line1 || ''}
                  onChange={handleChange}
                  placeholder="Address Line 1"
                  aria-label="Postal address line 1"
                  disabled={mutation.isPending}
                />
                <Input
                  id="address_line2"
                  name="address_line2"
                  value={formData.address_line2 || ''}
                  onChange={handleChange}
                  placeholder="Address Line 2"
                  aria-label="Postal address line 2"
                  disabled={mutation.isPending}
                />
                <Input
                  id="address_line3"
                  name="address_line3"
                  value={formData.address_line3 || ''}
                  onChange={handleChange}
                  placeholder="City"
                  aria-label="Postal address city"
                  disabled={mutation.isPending}
                />
              </div>
            </div>

            <div>
              <h3 className="text-sm font-bold mb-3 text-gray-700">Delivery Address</h3>
              <div className="space-y-2">
                <Input
                  id="delivery_address1"
                  name="delivery_address1"
                  value={formData.delivery_address1 || ''}
                  onChange={handleChange}
                  placeholder="Address Line 1"
                  aria-label="Delivery address line 1"
                  disabled={mutation.isPending}
                />
                <Input
                  id="delivery_address2"
                  name="delivery_address2"
                  value={formData.delivery_address2 || ''}
                  onChange={handleChange}
                  placeholder="Address Line 2"
                  aria-label="Delivery address line 2"
                  disabled={mutation.isPending}
                />
                <Input
                  id="delivery_address3"
                  name="delivery_address3"
                  value={formData.delivery_address3 || ''}
                  onChange={handleChange}
                  placeholder="Address Line 3"
                  aria-label="Delivery address line 3"
                  disabled={mutation.isPending}
                />
                <Input
                  id="delivery_address4"
                  name="delivery_address4"
                  value={formData.delivery_address4 || ''}
                  onChange={handleChange}
                  placeholder="City"
                  aria-label="Delivery address city"
                  disabled={mutation.isPending}
                />
              </div>
            </div>
          </div>
        </section>

        {/* Pricing Section */}
        <section>
          <h2 className="text-lg font-semibold mb-4">Pricing</h2>
          <div className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label htmlFor="price_level" className="block text-sm font-medium mb-1">
                  Price List
                </label>
                <select
                  id="price_level"
                  name="price_level"
                  value={formData.price_level || 1}
                  onChange={handleChange}
                  className="w-full border rounded-md px-3 py-2 h-10 text-sm"
                  disabled={mutation.isPending}
                >
                  <option value={1}>List 1</option>
                  <option value={2}>List 2</option>
                  <option value={3}>List 3</option>
                </select>
              </div>

              <div>
                <label htmlFor="discount_percentage" className="block text-sm font-medium mb-1">
                  Trade Discount (%)
                </label>
                <Input
                  id="discount_percentage"
                  name="discount_percentage"
                  type="number"
                  step="0.01"
                  min="0"
                  max="100"
                  value={formData.discount_percentage || ''}
                  onChange={handleChange}
                  placeholder="0.00"
                  disabled={mutation.isPending}
                />
              </div>

              <div>
                <label htmlFor="prompt_payment_discount" className="block text-sm font-medium mb-1">
                  Prompt Discount (%)
                </label>
                <Input
                  id="prompt_payment_discount"
                  name="prompt_payment_discount"
                  type="number"
                  step="0.01"
                  min="0"
                  max="100"
                  value={formData.prompt_payment_discount || ''}
                  onChange={handleChange}
                  placeholder="0.00"
                  disabled={mutation.isPending}
                />
              </div>
            </div>

            <div>
              <label htmlFor="payment_terms" className="block text-sm font-medium mb-1">
                Payment Terms (days)
              </label>
              <Input
                id="payment_terms"
                name="payment_terms"
