        />
      </div>

      {/* Ageing Period — Open Item debtors only */}
      {isOpenItem && (
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Allocate to Ageing Period <span className="text-red-500">*</span>
          </label>
          <select
            name="age_period"
