export default function Sidebar({ isMobileOpen = false, onMobileClose }: { isMobileOpen?: boolean; onMobileClose?: () => void }) {
  const pathname = usePathname();
  const { hasAddon, stockConsolidationEnabled } = useAuthContext();
  const [openDropdowns, setOpenDropdowns] = useState<{ [key: string]: boolean }>({});
  const [mounted, setMounted] = useState(false);
  const [collapsed, setCollapsed] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const toggleDropdown = (name: string) => {
    if (collapsed) {
      setCollapsed(false);
      setOpenDropdowns((prev) => ({ ...prev, [name]: true }));
      return;
    }
    setOpenDropdowns((prev) => ({ ...prev, [name]: !prev[name] }));
  };

  const hasAccess = (menu: any) => {
    if (menu.addon && !hasAddon(menu.addon)) return false;
    if (menu.feature === "stock_consolidation" && !stockConsolidationEnabled) return false;
    return true;
  };

  // ================== RENDER MENU ==================
  const renderMenu = (menu: any, depth = 0) => {
    if (!hasAccess(menu)) return null;
    const filteredChildren = menu.children?.filter(hasAccess);

    if (menu.type === "link") {
      return (
        <Link
          key={menu.name}
          href={menu.href}
          title={collapsed && depth === 0 ? menu.name : undefined}
          className={`group flex items-center gap-3 rounded-lg transition-all duration-150 relative
            ${collapsed && depth === 0 ? "justify-center px-0 py-3" : "px-3 py-2.5"}
            ${pathname === menu.href
              ? "bg-blue-50 text-blue-700 font-semibold"
              : "text-gray-600 hover:bg-gray-50 hover:text-gray-900"
            }`}
          style={!collapsed ? { paddingLeft: `${depth * 14 + 12}px` } : undefined}
        >
          {menu.icon && (
            <menu.icon
              className={`shrink-0 transition-colors
                ${pathname === menu.href ? "text-blue-600" : "text-gray-400 group-hover:text-gray-600"}
                ${depth === 0 ? "h-5 w-5" : "h-4 w-4"}`}
            />
          )}
          {(!collapsed || depth > 0) && (
            <span className={`truncate leading-tight ${depth === 0 ? "text-sm" : "text-xs"}`}>
              {menu.name}
            </span>
          )}
          {/* Active indicator bar */}
          {pathname === menu.href && (
            <span className="absolute left-0 top-1/2 -translate-y-1/2 w-0.5 h-5 bg-blue-500 rounded-r-full" />
          )}
        </Link>
      );
    }

    if (menu.type === "dropdown" || menu.type === "nested") {
      if (!filteredChildren?.length) return null;
      const isActive = pathname.startsWith(menu.base);
      const isOpen = openDropdowns[menu.name];

      return (
        <div key={menu.name}>
          <button
            onClick={() => toggleDropdown(menu.name)}
            title={collapsed && depth === 0 ? menu.name : undefined}
            className={`group flex items-center w-full rounded-lg transition-all duration-150 relative
              ${collapsed && depth === 0 ? "justify-center px-0 py-3" : "px-3 gap-3"}
              ${menu.type === "dropdown" ? "py-2.5" : "py-2"}
              ${isActive ? "bg-blue-50 text-blue-700 font-semibold" : "text-gray-600 hover:bg-gray-50 hover:text-gray-900"}`}
            style={!collapsed ? { paddingLeft: `${depth * 14 + 12}px` } : undefined}
          >
            {/* Active indicator */}
            {isActive && (
              <span className="absolute left-0 top-1/2 -translate-y-1/2 w-0.5 h-5 bg-blue-500 rounded-r-full" />
            )}
            {menu.icon && (
              <menu.icon
                className={`shrink-0 transition-colors
                  ${isActive ? "text-blue-600" : "text-gray-400 group-hover:text-gray-600"}
                  ${depth === 0 ? "h-5 w-5" : "h-4 w-4"}`}
              />
            )}
            {(!collapsed || depth > 0) && (
              <>
                <span className={`flex-1 text-left truncate leading-tight ${depth === 0 ? "text-sm" : "text-xs"}`}>
                  {menu.name}
                </span>
                <ChevronDown
                  className={`h-3.5 w-3.5 shrink-0 text-gray-400 transition-transform duration-200 ${isOpen ? "rotate-180" : ""}`}
                />
              </>
            )}
          </button>

          {(!collapsed || depth > 0) && (
            <div
              className={`flex flex-col gap-0.5 overflow-hidden transition-all duration-200 ease-in-out ${
                isOpen ? "max-h-[1000px] opacity-100 mt-0.5" : "max-h-0 opacity-0"
              }`}
            >
              {/* Subtle left border for nested groups */}
              <div className="ml-5 pl-3 border-l border-gray-100 flex flex-col gap-0.5">
                {filteredChildren.map((child: any) => renderMenu(child, depth + 1))}
              </div>
            </div>
          )}
        </div>
      );
    }
  };

  return (
    <>
      {/* Mobile overlay backdrop */}
      {isMobileOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-30 md:hidden"
          onClick={onMobileClose}
        />
      )}
      {/* Sidebar */}
      <aside
        className={`relative flex flex-col h-screen bg-white border-r border-gray-100 shadow-sm transition-all duration-300 ease-in-out shrink-0
          ${collapsed ? "w-16" : "w-64"}
          ${isMobileOpen 
            ? "fixed inset-y-0 left-0 z-40 transform-none" 
            : "hidden md:flex md:translate-x-0 -translate-x-full"}`}
      >
        {/* Toggle button — sits on the right edge */}
        <button
          onClick={() => setCollapsed((v) => !v)}
          aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          className="absolute -right-3 top-6 z-20 flex items-center justify-center w-6 h-6 rounded-full bg-white border border-gray-200 shadow-sm text-gray-500 hover:text-blue-600 hover:border-blue-300 hover:shadow-md transition-all duration-150 hidden md:flex"
        >
          {collapsed
            ? <PanelLeftOpen className="h-3 w-3" />
            : <PanelLeftClose className="h-3 w-3" />
          }
        </button>

        {/* Mobile close button */}
        {isMobileOpen && (
          <button
            onClick={onMobileClose}
            aria-label="Close sidebar"
            className="absolute top-4 right-4 z-50 p-1 rounded-md bg-gray-100 text-gray-600 hover:bg-gray-200 md:hidden"
          >
            <X className="h-5 w-5" />
          </button>
        )}

        {/* Logo */}
        <div className={`flex items-center h-16 border-b border-gray-100 shrink-0 transition-all duration-300 ${collapsed ? "justify-center px-0" : "px-5 gap-3"}`}>
          <Link href="/" className="flex items-center gap-2.5 min-w-0">
            <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-blue-700 rounded-lg flex items-center justify-center text-white font-bold text-sm shrink-0 shadow-sm">
              BO
            </div>
            {!collapsed && (
              <span className="text-base font-bold text-gray-900 tracking-tight truncate">BlueOlive</span>
            )}
          </Link>
        </div>

        {/* Scrollable nav */}
        {mounted && (
          <nav className="flex-1 overflow-y-auto overflow-x-hidden py-3 px-2 flex flex-col gap-0.5 scrollbar-thin scrollbar-thumb-gray-200 scrollbar-track-transparent">
            {menuConfig.map((menu) => renderMenu(menu))}
          </nav>
        )}

        {/* Bottom user hint when collapsed */}
        {collapsed && (
          <div className="shrink-0 h-12 border-t border-gray-100 flex items-center justify-center">
            <div className="w-7 h-7 rounded-full bg-gray-100 flex items-center justify-center text-gray-400">
              <UserCog className="h-4 w-4" />
            </div>
          </div>
        )}
      </aside>
    </>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { 
  ArrowLeft, 
  ArrowRight, 
  Check, 
  Loader2, 
  AlertCircle, 
  Building2,
  User,
  Mail,
  Lock,
  Globe,
  Sparkles
} from 'lucide-react';
import { signup, login, checkTenantSetupStatus, validateSubdomain, getActiveSubscriptionPlans } from '@/lib/api';
import { useAuthContext } from '@/lib/AuthContext';
import { setTenant } from '@/lib/shopContext';
import type { MaybeAxiosError } from '@/lib/types/errors';

// Signup provisions the tenant's database + admin user in the background
// (can take a while under load), so we poll rather than assume it's done
// when signup() returns. These bound how long we wait before giving up.
const SETUP_POLL_INTERVAL_MS = 2500;
const SETUP_POLL_TIMEOUT_MS = 3 * 60 * 1000;

function sleep(ms: number) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// Types
interface SignupFormData {
  email: string;
  username: string;
  password: string;
  confirmPassword: string;
  firstName: string;
  lastName: string;
  companyName: string;
  subdomain: string;
  subscriptionPlanId: string;
}

interface FormErrors {
  [key: string]: string;
}

interface SubdomainStatus {
  validated: boolean;
  checking: boolean;
  available: boolean | null;
  error: string;
  suggestions: string[];
}

// Steps configuration
const STEPS = [
  { id: 1, title: 'Account', description: 'Create your account' },
  { id: 2, title: 'Organization', description: 'Set up your company' },
  { id: 3, title: 'Plan', description: 'Choose your plan' },
];

// Maps the backend's snake_case field names (returned in signup error
// responses as `field` or `missing_fields`) to this form's field names and
// the step each one lives on, so a field-specific server error can both
// highlight the right input and jump the user to the right step.
const BACKEND_FIELD_TO_FORM_FIELD: Record<string, keyof SignupFormData> = {
  email: 'email',
  username: 'username',
  password: 'password',
  confirm_password: 'confirmPassword',
  first_name: 'firstName',
  last_name: 'lastName',
  company_name: 'companyName',
  subdomain: 'subdomain',
  subscription_plan_id: 'subscriptionPlanId',
};

const FORM_FIELD_TO_STEP: Record<keyof SignupFormData, number> = {
  email: 1,
  username: 1,
  password: 1,
  confirmPassword: 1,
  firstName: 1,
  lastName: 1,
  companyName: 2,
  subdomain: 2,
  subscriptionPlanId: 3,
};

export default function MultiStepSignupForm() {
  const router = useRouter();
  const { refetch } = useAuthContext();
  
  // Form state
  const [formData, setFormData] = useState<SignupFormData>({
    email: '',
    username: '',
    password: '',
    confirmPassword: '',
    firstName: '',
    lastName: '',
    companyName: '',
    subdomain: '',
    subscriptionPlanId: '',
  });

  const [currentStep, setCurrentStep] = useState(1);
  const [errors, setErrors] = useState<FormErrors>({});
  const [subdomainStatus, setSubdomainStatus] = useState<SubdomainStatus>({
    validated: false,
    checking: false,
    available: null,
    error: '',
    suggestions: [],
  });
  const [plans, setPlans] = useState<Record<string, unknown>[]>([]);
  const [plansLoading, setPlansLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState('');
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [setupMessage, setSetupMessage] = useState('Creating your account...');
  const [readyToLogin, setReadyToLogin] = useState(false);
  const [tenantSlug, setTenantSlugValue] = useState<string | null>(null);
  const [loggingIn, setLoggingIn] = useState(false);

  // Fetch subscription plans on mount
  useEffect(() => {
    async function fetchPlans() {
      try {
        const data = await getActiveSubscriptionPlans();
        setPlans(data);
        // Set default to first non-trial plan if available
        const nonTrialPlan = data.find((p) => !p.is_trial);
        if (nonTrialPlan) {
          setFormData(prev => ({ ...prev, subscriptionPlanId: String(nonTrialPlan.id) }));
        }
      } catch (error) {
        console.error('Failed to fetch plans:', error);
      } finally {
        setPlansLoading(false);
      }
    }
    fetchPlans();
  }, []);

  // Debounced subdomain validation
  const validateSubdomainDebounced = useCallback(
    async (subdomain: string) => {
      if (subdomain.length < 3) {
        setSubdomainStatus({
          validated: false,
          checking: false,
          available: null,
          error: 'Subdomain must be at least 3 characters',
          suggestions: [],
        });
        return;
      }

      if (!/^[a-z0-9][a-z0-9-]*[a-z0-9]$/.test(subdomain)) {
        setSubdomainStatus({
          validated: false,
          checking: false,
          available: null,
          error: 'Subdomain can only contain letters, numbers, and hyphens',
          suggestions: [],
        });
        return;
      }

      setSubdomainStatus(prev => ({ ...prev, checking: true, error: '' }));

      try {
        const result = await validateSubdomain(subdomain);
        setSubdomainStatus({
          validated: true,
          checking: false,
          available: result.available,
          error: '',
          suggestions: result.suggestions || [],
        });
      } catch (error: unknown) {
        setSubdomainStatus({
          validated: false,
          checking: false,
          available: null,
          error: (error as MaybeAxiosError)?.response?.data?.detail || 'Unable to validate subdomain',
          suggestions: [],
        });
      }
    },
    []
  );

  // Trigger subdomain validation when it changes
  useEffect(() => {
    const timer = setTimeout(() => {
      if (formData.subdomain) {
        validateSubdomainDebounced(formData.subdomain);
      }
    }, 500); // Debounce for 500ms

    return () => clearTimeout(timer);
  }, [formData.subdomain, validateSubdomainDebounced]);

  // Handle input changes
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    
    // Clear error when user starts typing
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
    
    // Clear subdomain status when user modifies it
    if (name === 'subdomain') {
      setSubdomainStatus(prev => ({ ...prev, validated: false }));
    }
  };

  // Apply a signup/login error response from the backend: highlights the
  // specific field it named (data.field, or every field in
  // data.missing_fields), jumps to whichever step that field lives on so
  // it's actually visible, and shows the human-readable detail message as
  // a banner too. Falls back to just the banner if the backend didn't name
  // a field (e.g. an unexpected 500).
  const applyServerError = (data: any, fallbackMsg: string) => {
    const detail = data?.detail || fallbackMsg;

    if (Array.isArray(data?.missing_fields) && data.missing_fields.length > 0) {
      const newFieldErrors: FormErrors = {};
      let earliestStep = STEPS.length;

      for (const backendField of data.missing_fields as string[]) {
        const formField = BACKEND_FIELD_TO_FORM_FIELD[backendField];
        if (formField) {
          newFieldErrors[formField] = 'This field is required';
          earliestStep = Math.min(earliestStep, FORM_FIELD_TO_STEP[formField]);
        }
      }

      setErrors(prev => ({ ...prev, ...newFieldErrors }));
      if (earliestStep < STEPS.length + 1) setCurrentStep(earliestStep);
      setSubmitError(detail);
      return;
    }

    if (data?.field) {
      const formField = BACKEND_FIELD_TO_FORM_FIELD[data.field];
      if (formField) {
        setErrors(prev => ({ ...prev, [formField]: detail }));
        setCurrentStep(FORM_FIELD_TO_STEP[formField]);
      }
      setSubmitError(detail);
      return;
    }

    setSubmitError(detail);
  };

  // Validate current step
  const validateStep = (step: number): boolean => {
    const newErrors: FormErrors = {};

    if (step === 1) {
      if (!formData.email) {
        newErrors.email = 'Email is required';
      } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
        newErrors.email = 'Please enter a valid email address';
      }
      
      if (!formData.username) {
        newErrors.username = 'Username is required';
      } else if (formData.username.length < 3) {
        newErrors.username = 'Username must be at least 3 characters';
      } else if (!/^[a-zA-Z0-9_]+$/.test(formData.username)) {
        newErrors.username = 'Username can only contain letters, numbers, and underscores';
      }
      
      if (!formData.password) {
        newErrors.password = 'Password is required';
      } else if (formData.password.length < 8) {
        newErrors.password = 'Password must be at least 8 characters';
      }
      
      if (!formData.confirmPassword) {
        newErrors.confirmPassword = 'Please confirm your password';
      } else if (formData.password !== formData.confirmPassword) {
        newErrors.confirmPassword = 'Passwords do not match';
      }
      
      if (!formData.firstName) {
        newErrors.firstName = 'First name is required';
      }
      
      if (!formData.lastName) {
        newErrors.lastName = 'Last name is required';
      }
    }

    if (step === 2) {
      if (!formData.companyName) {
        newErrors.companyName = 'Company name is required';
      } else if (formData.companyName.length < 2) {
        newErrors.companyName = 'Company name must be at least 2 characters';
      }
      
      if (!formData.subdomain) {
        newErrors.subdomain = 'Subdomain is required';
      } else if (!subdomainStatus.validated || !subdomainStatus.available) {
        newErrors.subdomain = subdomainStatus.error || 'Please enter a valid subdomain';
      }
    }

    if (step === 3) {
      if (!formData.subscriptionPlanId) {
        newErrors.subscriptionPlanId = 'Please select a subscription plan';
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // Handle step navigation
  const handleNext = () => {
    if (validateStep(currentStep)) {
      setCurrentStep(prev => Math.min(prev + 1, STEPS.length));
    }
  };

  const handleBack = () => {
    setCurrentStep(prev => Math.max(prev - 1, 1));
  };

  // Handle final submission
  const handleSubmit = async () => {
    if (!validateStep(3)) return;

    setSubmitting(true);
    setSubmitError('');

    try {
      const response = await signup({
        email: formData.email,
        username: formData.username,
        password: formData.password,
        confirm_password: formData.confirmPassword,
        first_name: formData.firstName,
        last_name: formData.lastName,
        company_name: formData.companyName,
        subdomain: formData.subdomain,
        subscription_plan_id: parseInt(formData.subscriptionPlanId),
      });

      // Signup only creates the tenant row - provisioning the database and
      // admin user happens in the background and can take a while, so we
      // show the waiting screen and poll rather than assuming it's done.
      const tenantId = response.data?.tenant_id;
      const tenantSlugFromResponse = response.data?.tenant_slug;
      if (!tenantId || !tenantSlugFromResponse) {
        throw new Error('Signup succeeded but no tenant id/slug was returned');
      }
      setTenantSlugValue(tenantSlugFromResponse);

      setSubmitSuccess(true);
      setSetupMessage('Setting up your workspace...');

      const deadline = Date.now() + SETUP_POLL_TIMEOUT_MS;
      let ready = false;
      let failed = false;

      while (Date.now() < deadline) {
        const status = await checkTenantSetupStatus(tenantId);
        setSetupMessage(status.message);

        if (status.is_ready) {
          ready = true;
          break;
        }
        if (status.setup_status === 'failed') {
          failed = true;
          break;
        }
        await sleep(SETUP_POLL_INTERVAL_MS);
      }

      if (failed) {
        setSubmitSuccess(false);
        setSubmitError(
          'We could not finish setting up your account. Please contact support with the email address you signed up with, or try again with a different company name.'
        );
        return;
      }

      if (!ready) {
        setSubmitSuccess(false);
        setSubmitError(
          'Setup is taking longer than expected. Your account may still finish in the background - try logging in from the login page in a few minutes, or contact support if it still does not work.'
        );
        return;
      }

      // Provisioning finished - stop here and let the user explicitly click
      // "Log In" (see handleLoginNow) rather than silently logging them in
      // and redirecting, so it's unmistakable that their account is ready.
      setReadyToLogin(true);
    } catch (error: unknown) {
      setSubmitSuccess(false);
      applyServerError(
        (error as MaybeAxiosError)?.response?.data,
        (error as MaybeAxiosError)?.response?.data?.message || (error as MaybeAxiosError)?.message || 'Signup failed. Please check your details and try again.'
      );
    } finally {
      setSubmitting(false);
    }
  };

  // Called when the user clicks "Log In" on the "your account is ready"
  // screen. Uses tenant_slug captured from the signup response, not
  // formData.subdomain - login resolves the tenant by slug (derived from
  // company name), which can differ from the subdomain the user picked.
  const handleLoginNow = async () => {
    if (!tenantSlug) return;

    setLoggingIn(true);
    setSubmitError('');

    try {
      await login(tenantSlug, formData.username, formData.password);

      // Store tenant in localStorage
      setTenant(formData.subdomain);

      // Refetch user profile
      try {
        await refetch();
      } catch {
        console.warn('Refetch failed, proceeding with redirect anyway');
      }

      router.push('/dashboard');
    } catch (error: unknown) {
      // Stay on the "ready" screen and let them retry the button - the
      // account is already provisioned, this was just a login-call hiccup
      // (network blip, etc.), not a reason to send them back to the form.
      const errorMsg =
        (error as MaybeAxiosError)?.response?.data?.detail ||
        (error as MaybeAxiosError)?.response?.data?.message ||
        (error as MaybeAxiosError)?.message ||
        'Login failed. Please try again.';
      setSubmitError(errorMsg);
    } finally {
      setLoggingIn(false);
    }
  };

  // Get step completion status
  const isStepCompleted = (step: number): boolean => {
    if (step < currentStep) return true;
    if (step === currentStep) return false;
    return false;
  };

  // Render form field with validation
  const renderField = (
    name: keyof SignupFormData,
    label: string,
    type: string = 'text',
    required: boolean = false,
    helperText?: string,
    icon?: React.ReactNode
  ) => (
    <div className="space-y-1">
      <label 
        htmlFor={name} 
        className="block text-sm font-medium text-gray-300"
      >
        {label}
        {required && <span className="text-red-400 ml-1">*</span>}
      </label>
      <div className="relative">
        {icon && (
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <span className="text-gray-400 h-5 w-5">{icon}</span>
          </div>
        )}
        <input
          type={type}
          name={name}
          id={name}
          value={formData[name]}
          onChange={handleChange}
          disabled={submitting}
          className={`
            block w-full rounded-lg bg-gray-800 border text-white placeholder-gray-400
            focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-900
            ${errors[name] 
              ? 'border-red-500 focus:ring-red-500' 
              : 'border-gray-600 focus:ring-indigo-500'
            }
            ${icon ? 'pl-10' : 'pl-4'} pr-4 py-3
            transition-colors duration-200
          `}
          aria-invalid={errors[name] ? 'true' : 'false'}
          aria-describedby={errors[name] ? `${name}-error` : undefined}
        />
      </div>
      {helperText && !errors[name] && (
        <p className="text-xs text-gray-500 mt-1">{helperText}</p>
      )}
      {errors[name] && (
        <p id={`${name}-error`} className="text-sm text-red-400 mt-1 flex items-center gap-1" role="alert">
          <AlertCircle className="h-4 w-4" />
          {errors[name]}
        </p>
      )}
    </div>
  );

  // Render step 1: Account details
  const renderStep1 = () => (
    <div className="space-y-5">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
        {renderField('firstName', 'First Name', 'text', true, undefined, <User className="h-5 w-5" />)}
        {renderField('lastName', 'Last Name', 'text', true, undefined, <User className="h-5 w-5" />)}
      </div>
      <>
        {renderField('email', 'Email Address', 'email', true, 'We will send a verification link to this email', <Mail className="h-5 w-5" />)}
        {renderField('username', 'Username', 'text', true, 'This will be used for login', <User className="h-5 w-5" />)}
      </>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
        {renderField('password', 'Password', 'password', true, 'At least 8 characters', <Lock className="h-5 w-5" />)}
        {renderField('confirmPassword', 'Confirm Password', 'password', true, undefined, <Lock className="h-5 w-5" />)}
      </div>
    </div>
  );

  // Render step 2: Organization details
  const renderStep2 = () => (
    <div className="space-y-5">
      <>
        {renderField('companyName', 'Company Name', 'text', true, 'Your organization legal name', <Building2 className="h-5 w-5" />)}
      </>
      
      <div className="space-y-1">
        <label 
          htmlFor="subdomain" 
          className="block text-sm font-medium text-gray-300"
        >
          Subdomain <span className="text-red-400 ml-1">*</span>
        </label>
        <div className="relative">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Globe className="h-5 w-5 text-gray-400" />
          </div>
          <input
            type="text"
            name="subdomain"
            id="subdomain"
            value={formData.subdomain}
            onChange={handleChange}
            disabled={submitting}
            placeholder="your-company"
            className={`
              block w-full rounded-lg bg-gray-800 border text-white placeholder-gray-400
              focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-900
              ${errors.subdomain 
                ? 'border-red-500 focus:ring-red-500' 
                : subdomainStatus.available === true
                  ? 'border-green-500 focus:ring-green-500'
                  : 'border-gray-600 focus:ring-indigo-500'
              }
              pl-10 pr-20 py-3
              transition-colors duration-200
            `}
          />
          <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
            {subdomainStatus.checking ? (
              <Loader2 className="h-5 w-5 text-gray-400 animate-spin" />
            ) : subdomainStatus.available === true ? (
              <Check className="h-5 w-5 text-green-500" />
            ) : null}
          </div>
        </div>
        
        {/* Domain preview */}
        <div className="mt-2 text-sm text-gray-500">
          Your URL will be: <span className="text-indigo-400 font-mono">{formData.subdomain || 'your-company'}.blueolive.co.za</span>
        </div>
        
        {/* Validation feedback */}
        {errors.subdomain && (
          <p className="text-sm text-red-400 mt-1 flex items-center gap-1" role="alert">
            <AlertCircle className="h-4 w-4" />
            {errors.subdomain}
          </p>
        )}
        {subdomainStatus.error && !errors.subdomain && (
          <p className="text-sm text-red-400 mt-1 flex items-center gap-1" role="alert">
            <AlertCircle className="h-4 w-4" />
            {subdomainStatus.error}
          </p>
        )}
        {subdomainStatus.suggestions.length > 0 && (
          <div className="mt-2">
            <p className="text-sm text-gray-400">Available alternatives:</p>
            <div className="flex flex-wrap gap-2 mt-1">
              {subdomainStatus.suggestions.map((suggestion, idx) => (
                <button
                  key={idx}
                  type="button"
                  onClick={() => setFormData(prev => ({ ...prev, subdomain: suggestion }))}
                  className="text-sm px-3 py-1 bg-gray-700 hover:bg-gray-600 text-indigo-300 rounded-full transition-colors"
                >
                  {suggestion}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );

  // Render step 3: Plan selection
  const renderStep3 = () => (
    <div className="space-y-5">
      <div>
        <label className="block text-sm font-medium text-gray-300 mb-3">
          Select a Plan <span className="text-red-400 ml-1">*</span>
        </label>
        {plansLoading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-8 w-8 text-indigo-500 animate-spin" />
            <span className="ml-2 text-gray-400">Loading plans...</span>
          </div>
        ) : plans.length === 0 ? (
          <div className="text-center py-8 text-gray-400">
            No subscription plans available. Please contact support.
          </div>
        ) : (
          <div className="grid gap-4">
            {plans.map((plan: any) => (
              <label
                key={plan.id}
                className={`
                  relative block cursor-pointer rounded-xl border-2 p-4 transition-all duration-200
                  ${formData.subscriptionPlanId === plan.id.toString()
                    ? 'border-indigo-500 bg-indigo-500/10'
                    : 'border-gray-700 bg-gray-800 hover:border-gray-600'
                  }
                `}
              >
                <input
                  type="radio"
                  name="subscriptionPlanId"
                  value={plan.id}
                  checked={formData.subscriptionPlanId === plan.id.toString()}
                  onChange={handleChange}
                  className="sr-only"
                />
                <div className="flex items-start justify-between">
                  <div>
                    <span className="block text-lg font-semibold text-white">
                      {plan.name}
                    </span>
                    <span className="block text-sm text-gray-400 mt-1">
                      {plan.description || 'No description available'}
                    </span>
                  </div>
                  <div className="text-right">
                    <span className="block text-xl font-bold text-indigo-400">
                      {plan.is_trial ? 'Free Trial' : `R${plan.price}/mo`}
                    </span>
                  </div>
                </div>
                {formData.subscriptionPlanId === plan.id.toString() && (
                  <div className="absolute top-4 right-4">
                    <Check className="h-5 w-5 text-indigo-500" />
                  </div>
                )}
              </label>
            ))}
          </div>
        )}
        {errors.subscriptionPlanId && (
          <p className="text-sm text-red-400 mt-2 flex items-center gap-1" role="alert">
            <AlertCircle className="h-4 w-4" />
            {errors.subscriptionPlanId}
          </p>
        )}
      </div>
    </div>
  );

  // Render "account ready, please log in" state
  if (submitSuccess && readyToLogin) {
    return (
      <div className="text-center py-12">
        <div className="mx-auto w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center mb-4">
          <Check className="h-8 w-8 text-green-500" />
        </div>
        <h3 className="text-2xl font-bold text-white mb-2">Your account is ready!</h3>
        <p className="text-gray-400 mb-6">Your workspace has been set up. Log in to get started.</p>
        {submitError && (
          <div className="max-w-sm mx-auto mb-6 p-4 bg-red-500/10 border border-red-500/20 rounded-lg flex items-start gap-3 text-left" role="alert">
            <AlertCircle className="h-5 w-5 text-red-400 flex-shrink-0 mt-0.5" />
            <p className="text-sm text-red-400">{submitError}</p>
          </div>
        )}
        <button
          type="button"
          onClick={handleLoginNow}
          disabled={loggingIn}
          className="inline-flex items-center gap-2 px-6 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {loggingIn ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              Logging in...
            </>
          ) : (
            <>
              Log In
              <ArrowRight className="h-4 w-4" />
            </>
          )}
        </button>
      </div>
    );
  }

  // Render "still setting up" state
  if (submitSuccess) {
    return (
      <div className="text-center py-12">
        <div className="mx-auto w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center mb-4">
          <Check className="h-8 w-8 text-green-500" />
        </div>
        <h3 className="text-2xl font-bold text-white mb-2">Account Created!</h3>
        <p className="text-gray-400 mb-6">This can take a few moments, please don&apos;t close this page.</p>
        <div className="flex items-center justify-center gap-2">
          <Loader2 className="h-5 w-5 text-indigo-500 animate-spin" />
          <span className="text-gray-400">{setupMessage}</span>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto">
      {/* Step indicator */}
      <nav aria-label="Progress" className="mb-8">
        <ol role="list" className="flex items-center justify-between">
          {STEPS.map((step, stepIdx) => (
            <li key={step.title} className={`relative ${stepIdx !== STEPS.length - 1 ? 'pr-8 sm:pr-20 flex-1' : ''}`}>
              {stepIdx !== STEPS.length - 1 && (
                <div 
                  className={`
                    absolute top-4 right-0 h-0.5 w-full transition-colors duration-300
                    ${currentStep > step.id ? 'bg-indigo-500' : 'bg-gray-700'}
                  `}
                  aria-hidden="true"
                />
              )}
              <button
                onClick={() => {
                  if (currentStep > step.id) {
                    setCurrentStep(step.id);
                  }
                }}
                disabled={step.id > currentStep}
                className={`
                  relative flex flex-col items-start group focus:outline-none
                  ${step.id > currentStep ? 'cursor-not-allowed opacity-50' : 'cursor-pointer'}
                `}
              >
                <span className="flex items-center">
                  <span 
                    className={`
                      relative z-10 flex h-8 w-8 items-center justify-center rounded-full transition-colors duration-300
                      ${isStepCompleted(step.id) 
                        ? 'bg-indigo-500' 
                        : currentStep === step.id
                          ? 'border-2 border-indigo-500 bg-gray-800'
                          : 'border-2 border-gray-700 bg-gray-800'
                      }
                    `}
                  >
                    {isStepCompleted(step.id) ? (
                      <Check className="h-5 w-5 text-white" aria-hidden="true" />
                    ) : (
                      <span className={`text-sm ${currentStep === step.id ? 'text-indigo-500' : 'text-gray-400'}`}>
                        {step.id}
                      </span>
                    )}
                  </span>
                </span>
                <span className="mt-2 text-sm font-medium">
                  <span className={currentStep === step.id ? 'text-white' : 'text-gray-400'}>
                    {step.title}
                  </span>
                </span>
                <span className="text-xs text-gray-500 mt-0.5">
                  {step.description}
                </span>
              </button>
            </li>
          ))}
        </ol>
      </nav>

      {/* Form content */}
      <div className="bg-gray-900 rounded-2xl border border-gray-800 p-6 sm:p-8">
        {/* Step title */}
        <div className="mb-6">
          <h2 className="text-xl font-semibold text-white flex items-center gap-2">
            {currentStep === 1 && <User className="h-5 w-5 text-indigo-500" />}
            {currentStep === 2 && <Building2 className="h-5 w-5 text-indigo-500" />}
            {currentStep === 3 && <Sparkles className="h-5 w-5 text-indigo-500" />}
            {STEPS[currentStep - 1].title}
          </h2>
          <p className="text-gray-400 text-sm mt-1">
            {STEPS[currentStep - 1].description}
          </p>
        </div>

        {/* Error message */}
        {submitError && (
          <div className="mb-6 p-4 bg-red-500/10 border border-red-500/20 rounded-lg flex items-start gap-3" role="alert">
            <AlertCircle className="h-5 w-5 text-red-400 flex-shrink-0 mt-0.5" />
            <div>
              <p className="text-sm text-red-400">{submitError}</p>
            </div>
          </div>
        )}

        {/* Step content */}
        <form onSubmit={(e) => e.preventDefault()}>
          {currentStep === 1 && renderStep1()}
          {currentStep === 2 && renderStep2()}
          {currentStep === 3 && renderStep3()}
        </form>

        {/* Navigation buttons */}
        <div className="mt-8 flex items-center justify-between">
          <button
            type="button"
            onClick={handleBack}
            disabled={currentStep === 1 || submitting}
            className={`
              flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-colors
              ${currentStep === 1 
                ? 'text-gray-600 cursor-not-allowed' 
                : 'text-gray-300 hover:text-white hover:bg-gray-800'
              }
            `}
          >
            <ArrowLeft className="h-4 w-4" />
            Back
          </button>

          {currentStep < STEPS.length ? (
            <button
              type="button"
              onClick={handleNext}
              disabled={submitting}
              className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Continue
              <ArrowRight className="h-4 w-4" />
            </button>
          ) : (
            <button
              type="button"
              onClick={handleSubmit}
              disabled={submitting}
              className="flex items-center gap-2 px-6 py-2.5 bg-green-600 hover:bg-green-700 text-white rounded-lg font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {submitting ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" />
                  Creating Account...
                </>
              ) : (
                <>
                  <Sparkles className="h-4 w-4" />
                  Create Account
                </>
              )}
            </button>
          )}
        </div>
      </div>

      {/* Footer link */}
      <p className="mt-6 text-center text-sm text-gray-400">
        Already have an account?{' '}
        <Link href="/auth?tab=login" className="text-indigo-400 hover:text-indigo-300 font-medium">
          Sign in
        </Link>
      </p>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { ArrowLeft, Plus, Search, Edit2, Trash2 } from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { stockControlApi } from '@/lib/stockControlApi';
import type { ContractPricing } from '@/lib/types/stockControl';

interface ContractPricingMaintenanceProps {
  onBack: () => void;
}

type FormState = {
  id?: number;
  debtor: string;
  scope: 'stock_item' | 'department' | 'supplier';
  stock_item: string;
  department: string;
  supplier: string;
  pricing_method: 'ACTUAL' | 'COST_MARKUP';
  contract_price: string;
  markup_percent: string;
  discount_percent: string;
  valid_from: string;
  valid_until: string;
  is_fixed_pricing: boolean;
};

const emptyForm: FormState = {
  debtor: '',
  scope: 'stock_item',
  stock_item: '',
  department: '',
  supplier: '',
  pricing_method: 'ACTUAL',
  contract_price: '',
  markup_percent: '',
  discount_percent: '0',
  valid_from: '',
  valid_until: '',
  is_fixed_pricing: false,
};

export default function ContractPricingMaintenance({ onBack }: ContractPricingMaintenanceProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [formData, setFormData] = useState<FormState>(emptyForm);
  const queryClient = useQueryClient();

  const { data: contracts = [], isLoading, error } = useQuery({
    queryKey: ['contract-pricing'],
    queryFn: async () => {
      const result = await stockControlApi.contractPricing.list();
      return result.results ?? (result as unknown as ContractPricing[]);
    },
  });

  const mutation = useMutation({
    mutationFn: async (payload: Partial<ContractPricing>) => {
      if (editingId) {
        return stockControlApi.contractPricing.update(editingId, payload);
      }
      return stockControlApi.contractPricing.create(payload as Partial<ContractPricing>);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['contract-pricing'] });
      setShowForm(false);
      setEditingId(null);
      setFormData(emptyForm);
    },
    onError: (err: any) => {
      const data = err?.response?.data;
      const msg = data && typeof data === 'object'
        ? Object.entries(data).map(([k, v]: any) => `${k}: ${Array.isArray(v) ? v.join(', ') : v}`).join(' | ')
        : err?.message ?? 'Unknown error';
      alert(`Save failed: ${msg}`);
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id: number) => stockControlApi.contractPricing.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['contract-pricing'] });
    },
  });

  const handleEdit = (contract: ContractPricing) => {
    setEditingId(contract.id);
    setFormData({
      id: contract.id,
      debtor: String(contract.debtor ?? ''),
      scope: contract.stock_item ? 'stock_item' : contract.department ? 'department' : 'supplier',
      stock_item: contract.stock_item ?? '',
      department: contract.department != null ? String(contract.department) : '',
      supplier: contract.supplier != null ? String(contract.supplier) : '',
      pricing_method: contract.pricing_method,
      contract_price: contract.contract_price != null ? String(contract.contract_price) : '',
      markup_percent: contract.markup_percent != null ? String(contract.markup_percent) : '',
      discount_percent: contract.discount_percent != null ? String(contract.discount_percent) : '0',
      valid_from: contract.valid_from ?? '',
      valid_until: contract.valid_until ?? '',
      is_fixed_pricing: !!contract.is_fixed_pricing,
    });
    setShowForm(true);
  };

  const handleNew = () => {
    setEditingId(null);
    setFormData(emptyForm);
    setShowForm(!showForm);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.debtor.trim()) {
      alert('Debtor account number is required.');
      return;
    }
    if (formData.scope === 'stock_item' && !formData.stock_item.trim()) {
      alert('Stock code is required for item-specific pricing.');
      return;
    }
    if (formData.scope === 'department' && !formData.department.trim()) {
      alert('Department is required for department-based pricing.');
      return;
    }
    if (formData.scope === 'supplier' && !formData.supplier.trim()) {
      alert('Supplier is required for supplier-based pricing.');
      return;
    }
    if (formData.pricing_method === 'ACTUAL' && !formData.contract_price) {
      alert('Contract price is required for the Actual Price method.');
      return;
    }
    if (formData.pricing_method === 'COST_MARKUP' && !formData.markup_percent) {
      alert('Markup % is required for the Cost + Markup method.');
      return;
    }

    const payload: Partial<ContractPricing> = {
      debtor: formData.debtor.trim() as unknown as number,
      pricing_method: formData.pricing_method,
      discount_percent: formData.discount_percent ? Number(formData.discount_percent) : 0,
      is_fixed_pricing: formData.is_fixed_pricing,
      valid_from: formData.valid_from || null,
      valid_until: formData.valid_until || null,
      stock_item: formData.scope === 'stock_item' ? formData.stock_item.trim() : null,
      department: formData.scope === 'department' ? (Number(formData.department) as any) : null,
      supplier: formData.scope === 'supplier' ? (Number(formData.supplier) as any) : null,
    };
    if (formData.pricing_method === 'ACTUAL') {
      payload.contract_price = Number(formData.contract_price);
    } else {
      payload.markup_percent = Number(formData.markup_percent);
    }

    mutation.mutate(payload);
  };

  const filteredContracts = contracts.filter((c: ContractPricing) => {
    const value = `${c.debtor} ${c.stock_item ?? ''}`.toLowerCase();
    return value.includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <button onClick={onBack} className="flex items-center gap-2 text-blue-600 hover:text-blue-800">
          <ArrowLeft className="w-4 h-4" />
          Back to Menu
        </button>
        <h2 className="text-2xl font-bold text-gray-900">Contract Pricing</h2>
        <button
          onClick={handleNew}
          className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700"
        >
          <Plus className="w-4 h-4" />
          New Contract Price
        </button>
      </div>

      {showForm && (
        <div className="bg-white border border-gray-200 rounded-lg p-6">
          <h3 className="text-lg font-semibold mb-4">
            {editingId ? 'Edit Contract Price' : 'Create Contract Price'}
          </h3>

          <div className="mb-4 flex gap-4">
            <label className="flex items-center gap-2">
              <input
                type="radio"
                checked={formData.scope === 'stock_item'}
                onChange={() => setFormData({ ...formData, scope: 'stock_item' })}
              />
              Item-specific
            </label>
            <label className="flex items-center gap-2">
              <input
                type="radio"
                checked={formData.scope === 'department'}
                onChange={() => setFormData({ ...formData, scope: 'department' })}
              />
              Department-based
            </label>
            <label className="flex items-center gap-2">
              <input
                type="radio"
                checked={formData.scope === 'supplier'}
                onChange={() => setFormData({ ...formData, scope: 'supplier' })}
              />
              Supplier-based
            </label>
          </div>

          <form onSubmit={handleSubmit} className="grid md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Debtor Account Number *</label>
              <input
                type="text"
                value={formData.debtor}
                onChange={(e) => setFormData({ ...formData, debtor: e.target.value })}
                placeholder="Debtor account number"
                className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                required
              />
            </div>

            {formData.scope === 'stock_item' && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Stock Code *</label>
                <input
                  type="text"
                  value={formData.stock_item}
                  onChange={(e) => setFormData({ ...formData, stock_item: e.target.value })}
                  placeholder="Stock code"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                  required
                />
              </div>
            )}
            {formData.scope === 'department' && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Department Number *</label>
                <input
                  type="number"
                  value={formData.department}
                  onChange={(e) => setFormData({ ...formData, department: e.target.value })}
                  placeholder="Department number"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                  required
                />
              </div>
            )}
            {formData.scope === 'supplier' && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Supplier Number *</label>
                <input
                  type="number"
                  value={formData.supplier}
                  onChange={(e) => setFormData({ ...formData, supplier: e.target.value })}
                  placeholder="Supplier account number"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                  required
                />
              </div>
            )}

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Pricing Method *</label>
              <select
                value={formData.pricing_method}
                onChange={(e) => setFormData({ ...formData, pricing_method: e.target.value as 'ACTUAL' | 'COST_MARKUP' })}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg"
              >
                <option value="ACTUAL">Actual Price</option>
                <option value="COST_MARKUP">Cost + Markup %</option>
              </select>
            </div>

            {formData.pricing_method === 'ACTUAL' ? (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Contract Price *</label>
                <input
                  type="number"
                  step="0.01"
                  value={formData.contract_price}
                  onChange={(e) => setFormData({ ...formData, contract_price: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                  required
                />
              </div>
            ) : (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Markup % *</label>
                <input
                  type="number"
                  step="0.01"
                  value={formData.markup_percent}
                  onChange={(e) => setFormData({ ...formData, markup_percent: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                  required
                />
              </div>
            )}

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Discount %</label>
              <input
                type="number"
                step="0.01"
                value={formData.discount_percent}
                onChange={(e) => setFormData({ ...formData, discount_percent: e.target.value })}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg"
              />
            </div>

            <div className="flex items-end">
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={formData.is_fixed_pricing}
                  onChange={(e) => setFormData({ ...formData, is_fixed_pricing: e.target.checked })}
                  className="w-4 h-4"
                />
                <span className="text-sm font-medium">Fixed Pricing (POS cannot discount further)</span>
              </label>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Valid From</label>
              <input
                type="date"
                value={formData.valid_from}
                onChange={(e) => setFormData({ ...formData, valid_from: e.target.value })}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Valid Until</label>
              <input
                type="date"
                value={formData.valid_until}
                onChange={(e) => setFormData({ ...formData, valid_until: e.target.value })}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg"
              />
            </div>

            <div className="md:col-span-2 flex gap-3">
              <button
                type="submit"
                disabled={mutation.isPending}
                className="flex-1 bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50"
              >
                {mutation.isPending ? 'Saving...' : editingId ? 'Update Contract Price' : 'Create Contract Price'}
              </button>
              <button
                type="button"
                onClick={() => setShowForm(false)}
                className="flex-1 bg-gray-300 text-gray-700 py-2 rounded-lg hover:bg-gray-400"
              >
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}

      <div className="relative">
        <Search className="absolute left-3 top-3 w-4 h-4 text-gray-400" />
        <input
          type="text"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          placeholder="Search by debtor or stock code..."
          className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg"
        />
      </div>

      <div className="overflow-x-auto bg-white rounded-lg border border-gray-200">
        <table className="w-full">
          <thead className="border-b border-gray-200 bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">Debtor</th>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">Scope</th>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">Method</th>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">Price / Markup</th>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">Valid</th>
              <th className="px-6 py-3 text-right text-sm font-semibold text-gray-900">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {isLoading ? (
              <tr><td colSpan={6} className="px-6 py-4 text-center text-gray-500">Loading...</td></tr>
            ) : error ? (
              <tr><td colSpan={6} className="px-6 py-4 text-center text-red-500">Error loading contract prices</td></tr>
            ) : filteredContracts.length === 0 ? (
              <tr><td colSpan={6} className="px-6 py-4 text-center text-gray-500">No contract prices found</td></tr>
            ) : (
              filteredContracts.map((c: ContractPricing) => (
                <tr key={c.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 text-sm font-medium text-gray-900">{c.debtor}</td>
                  <td className="px-6 py-4 text-sm text-gray-600">
                    {c.stock_item ?? (c.department ? `Dept ${c.department}` : c.supplier ? `Supplier ${c.supplier}` : '-')}
                  </td>
                  <td className="px-6 py-4 text-sm text-gray-600">{c.pricing_method === 'ACTUAL' ? 'Actual' : 'Cost + Markup'}</td>
                  <td className="px-6 py-4 text-sm text-gray-600">
                    {c.pricing_method === 'ACTUAL' ? `R ${Number(c.contract_price ?? 0).toFixed(2)}` : `${c.markup_percent}%`}
                  </td>
                  <td className="px-6 py-4 text-sm text-gray-600">
                    {c.valid_from || '-'} to {c.valid_until || 'open'}
                  </td>
                  <td className="px-6 py-4 text-right space-x-2">
                    <button onClick={() => handleEdit(c)} className="text-blue-600 hover:text-blue-800">
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button onClick={() => deleteMutation.mutate(c.id)} className="text-red-600 hover:text-red-800">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { ArrowLeft, Plus, Edit2, Trash2 } from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { stockControlApi } from '@/lib/stockControlApi';
import type { OneTouchLookupKey } from '@/lib/types/stockControl';

interface OneTouchLookupKeyMaintenanceProps {
  onBack: () => void;
}

export default function OneTouchLookupKeyMaintenance({ onBack }: OneTouchLookupKeyMaintenanceProps) {
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [keyCharacter, setKeyCharacter] = useState('');
  const [stockCode, setStockCode] = useState('');
  const queryClient = useQueryClient();

  const { data: keys = [], isLoading, error } = useQuery({
    queryKey: ['lookup-keys'],
    queryFn: async () => {
      const result = await stockControlApi.lookupKeys.list();
      return result.results ?? (result as unknown as OneTouchLookupKey[]);
    },
  });

  const mutation = useMutation({
    mutationFn: async () => {
      const payload = { key_character: keyCharacter.toUpperCase(), stock_item: stockCode.trim() };
      if (editingId) {
        return stockControlApi.lookupKeys.update(editingId, payload);
      }
      return stockControlApi.lookupKeys.create(payload);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['lookup-keys'] });
      resetForm();
    },
    onError: (err: any) => {
      const data = err?.response?.data;
      const msg = data && typeof data === 'object'
        ? Object.entries(data).map(([k, v]: any) => `${k}: ${Array.isArray(v) ? v.join(', ') : v}`).join(' | ')
        : err?.message ?? 'Unknown error';
      alert(`Save failed: ${msg}`);
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id: number) => stockControlApi.lookupKeys.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['lookup-keys'] });
    },
  });

  const resetForm = () => {
    setShowForm(false);
    setEditingId(null);
    setKeyCharacter('');
    setStockCode('');
  };

  const handleEdit = (key: OneTouchLookupKey) => {
    setEditingId(key.id);
    setKeyCharacter(key.key_character);
    setStockCode(key.stock_item);
    setShowForm(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!/^[A-Z]$/.test(keyCharacter.toUpperCase())) {
      alert('Key must be a single letter A-Z.');
      return;
    }
    if (!stockCode.trim()) {
      alert('Stock code is required.');
      return;
    }
    mutation.mutate();
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <button onClick={onBack} className="flex items-center gap-2 text-blue-600 hover:text-blue-800">
          <ArrowLeft className="w-4 h-4" />
          Back
        </button>
        <h2 className="text-2xl font-bold text-gray-900">One-Touch Look-Up Keys</h2>
        <button
          onClick={() => {
            resetForm();
            setShowForm(true);
          }}
          className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700"
        >
          <Plus className="w-4 h-4" />
          New Key
        </button>
      </div>

      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 text-sm text-blue-800">
        Link a single letter (A-Z) to a stock code for fast POS access — press Shift + the letter
        instead of searching, and the linked item&apos;s details are pulled in automatically.
      </div>

      {showForm && (
        <div className="bg-white border border-gray-200 rounded-lg p-6">
          <h3 className="text-lg font-semibold mb-4">
            {editingId ? 'Edit Look-Up Key' : 'New Look-Up Key'}
          </h3>
          <form onSubmit={handleSubmit} className="grid md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Key (A-Z) *</label>
              <input
                type="text"
                maxLength={1}
                value={keyCharacter}
                onChange={(e) => setKeyCharacter(e.target.value.toUpperCase())}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg uppercase"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Stock Code *</label>
              <input
                type="text"
                value={stockCode}
                onChange={(e) => setStockCode(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                required
              />
            </div>
            <div className="md:col-span-2 flex gap-3">
              <button
                type="submit"
                disabled={mutation.isPending}
                className="flex-1 bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50"
              >
                {mutation.isPending ? 'Saving...' : editingId ? 'Update Key' : 'Create Key'}
              </button>
              <button
                type="button"
                onClick={resetForm}
                className="flex-1 bg-gray-300 text-gray-700 py-2 rounded-lg hover:bg-gray-400"
              >
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}

      <div className="overflow-x-auto bg-white rounded-lg border border-gray-200">
        <table className="w-full">
          <thead className="border-b border-gray-200 bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">Key</th>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">Stock Code</th>
              <th className="px-6 py-3 text-right text-sm font-semibold text-gray-900">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {isLoading ? (
              <tr><td colSpan={3} className="px-6 py-4 text-center text-gray-500">Loading...</td></tr>
            ) : error ? (
              <tr><td colSpan={3} className="px-6 py-4 text-center text-red-500">Error loading keys</td></tr>
            ) : keys.length === 0 ? (
              <tr><td colSpan={3} className="px-6 py-4 text-center text-gray-500">No look-up keys set up yet</td></tr>
            ) : (
              [...keys].sort((a, b) => a.key_character.localeCompare(b.key_character)).map((key) => (
                <tr key={key.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 text-lg font-mono font-bold text-gray-900">{key.key_character}</td>
                  <td className="px-6 py-4 text-sm text-gray-600">{key.stock_item}</td>
                  <td className="px-6 py-4 text-right space-x-2">
                    <button onClick={() => handleEdit(key)} className="text-blue-600 hover:text-blue-800">
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button onClick={() => deleteMutation.mutate(key.id)} className="text-red-600 hover:text-red-800">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { ArrowLeft, Plus, Search, Edit2, Trash2 } from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '@/lib/api';
import { stockControlApi } from '@/lib/stockControlApi';

interface SpecialDeal {
  id?: string;
  stock_code: string;
  stock_description?: string;
  cost_price: number;
  special_cost_price: number;
  special_selling_price_1?: number;
  special_selling_price_2?: number;
  special_selling_price_3?: number;
  special_markup_1?: number;
  special_markup_2?: number;
  special_markup_3?: number;
  start_date: string;
  end_date: string;
  markup_percentage: number;
  type: 'individual' | 'department';
  department?: string;
  increase_decrease?: '+' | '-';
  percentage_rand?: 'P' | 'R';
  amount?: number;
  sales_price_levels?: string;
}

interface SpecialDealMaintenanceProps {
  onBack: () => void;
}

export default function SpecialDealMaintenance({ onBack }: SpecialDealMaintenanceProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [dealType, setDealType] = useState<'individual' | 'department'>('individual');
  const [editingId, setEditingId] = useState<string | null>(null);
  const queryClient = useQueryClient();

  const [formData, setFormData] = useState<SpecialDeal>({
    stock_code: '',
    cost_price: 0,
    special_cost_price: 0,
    start_date: '',
    end_date: '',
    markup_percentage: 0,
    type: 'individual',
    department: '',
    increase_decrease: '+',
    percentage_rand: 'P',
    amount: 0,
    sales_price_levels: ''
  });

  // Helper function to calculate selling prices from markup percentage
  const calculateSellingPrices = (costPrice: number, markupPercent: number) => {
    if (!costPrice || !markupPercent) return { price1: 0, price2: 0, price3: 0 };
    const markup = markupPercent / 100;
    const sellingPrice = costPrice * (1 + markup);
    return {
      price1: Math.round(sellingPrice * 100) / 100,
      price2: Math.round(sellingPrice * 100) / 100,
      price3: Math.round(sellingPrice * 100) / 100
    };
  };

  // Helper function to calculate markup from selling price
  const calculateMarkup = (costPrice: number, sellingPrice: number) => {
    if (!costPrice || !sellingPrice) return 0;
    const markup = ((sellingPrice - costPrice) / costPrice) * 100;
    return Math.round(markup * 100) / 100;
  };

  // Handle markup percentage change
  const handleMarkupChange = (value: number) => {
    setFormData({ ...formData, markup_percentage: value });
    const prices = calculateSellingPrices(formData.special_cost_price, value);
    setFormData(prev => ({
      ...prev,
      markup_percentage: value,
      special_selling_price_1: prices.price1,
      special_selling_price_2: prices.price2,
      special_selling_price_3: prices.price3
    }));
  };

  // Handle selling price change
  const handleSellingPriceChange = (priceLevel: 1 | 2 | 3, value: number) => {
    const priceKey = `special_selling_price_${priceLevel}` as keyof SpecialDeal;
    setFormData(prev => ({
      ...prev,
      [priceKey]: value
    }));
    
    // Recalculate markup based on first price level
    if (priceLevel === 1) {
      const newMarkup = calculateMarkup(formData.special_cost_price, value);
      setFormData(prev => ({
        ...prev,
        markup_percentage: newMarkup
      }));
    }
  };

  // Fetch special deals
  const { data: deals = [], isLoading, error } = useQuery({
    queryKey: ['special-deals'],
    queryFn: async () => {
      const response = await api.get('/api/stock-control/special-deals/');
      return response.data.results || response.data;
    }
  });

  // Create/Update mutation
  const mutation = useMutation({
    mutationFn: async (data: SpecialDeal) => {
      if (editingId) {
        return api.put(`/api/stock-control/special-deals/${editingId}/`, data);
      } else {
        return api.post('/api/stock-control/special-deals/', data);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['special-deals'] });
      setShowForm(false);
      setEditingId(null);
      setFormData({
        stock_code: '',
        cost_price: 0,
        special_cost_price: 0,
        start_date: '',
        end_date: '',
        markup_percentage: 0,
        type: 'individual',
        department: '',
        increase_decrease: '+',
        percentage_rand: 'P',
        amount: 0,
        sales_price_levels: ''
      });
    }
  });

  // Delete mutation
  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return api.delete(`/api/stock-control/special-deals/${id}/`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['special-deals'] });
    }
  });

  // Bulk-by-department mutation — one SpecialDeal per active item in the
  // department, each priced from its own current selling price.
  const bulkDepartmentMutation = useMutation({
    mutationFn: (data: {
      department: number;
      start_date: string;
      end_date: string;
      increase_decrease: '+' | '-';
      percentage_rand: 'P' | 'R';
      amount: number;
    }) => stockControlApi.specialDeals.bulkCreateForDepartment(data),
    onSuccess: (result) => {
      queryClient.invalidateQueries({ queryKey: ['special-deals'] });
      setShowForm(false);
      setEditingId(null);
      setFormData({
        stock_code: '',
        cost_price: 0,
        special_cost_price: 0,
        start_date: '',
        end_date: '',
        markup_percentage: 0,
        type: 'individual',
        department: '',
        increase_decrease: '+',
        percentage_rand: 'P',
        amount: 0,
        sales_price_levels: ''
      });
      alert(result.message);
    },
    onError: (err: any) => {
      const data = err?.response?.data;
      const msg = data && typeof data === 'object'
        ? Object.entries(data).map(([k, v]: any) => `${k}: ${Array.isArray(v) ? v.join(', ') : v}`).join(' | ')
        : err?.message ?? 'Unknown error';
      alert(`Bulk deal creation failed: ${msg}`);
    },
  });

  const handleEdit = (deal: SpecialDeal) => {
    setFormData(deal);
    setEditingId(deal.id || '');
    setShowForm(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (dealType === 'department') {
      if (!formData.department || !formData.amount || !formData.start_date || !formData.end_date) {
        alert('Department, amount, start date and end date are required.');
        return;
      }
      bulkDepartmentMutation.mutate({
        department: Number(formData.department),
        start_date: formData.start_date,
        end_date: formData.end_date,
        increase_decrease: formData.increase_decrease || '+',
        percentage_rand: formData.percentage_rand || 'P',
        amount: formData.amount,
      });
      return;
    }

    // Individual item pricing — transform form data to backend format
    const submitData: any = {
      stock_item: formData.stock_code, // Backend expects stock_item with stock code
      special_cost_price: formData.special_cost_price,
      start_date: formData.start_date,
      end_date: formData.end_date,
      is_active: true,
    };

    // Calculate selling prices based on markup_percentage
    if (formData.markup_percentage) {
      const markup = formData.markup_percentage / 100;
      const basePrice = formData.special_cost_price * (1 + markup);
      submitData.special_selling_price_1 = basePrice;
      submitData.special_selling_price_2 = basePrice;
      submitData.special_selling_price_3 = basePrice;
      submitData.special_markup_1 = formData.markup_percentage;
      submitData.special_markup_2 = formData.markup_percentage;
      submitData.special_markup_3 = formData.markup_percentage;
    }

    mutation.mutate(submitData);
  };

  const filteredDeals = deals.filter((deal: SpecialDeal) => {
    const searchValue = (deal.stock_code || deal.department || '').toLowerCase();
    return searchValue.includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <button
          onClick={onBack}
          className="flex items-center gap-2 text-blue-600 hover:text-blue-800"
        >
          <ArrowLeft className="w-4 h-4" />
          Back to Menu
        </button>
        <h2 className="text-2xl font-bold text-gray-900">Special Deal Maintenance</h2>
        <button
          onClick={() => {
            setShowForm(!showForm);
            setEditingId(null);
            setFormData({
              stock_code: '',
              cost_price: 0,
              special_cost_price: 0,
              start_date: '',
              end_date: '',
              markup_percentage: 0,
              type: 'individual',
              department: '',
              increase_decrease: '+',
              percentage_rand: 'P',
              amount: 0,
              sales_price_levels: ''
            });
          }}
          className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700"
        >
          <Plus className="w-4 h-4" />
          New Deal
        </button>
      </div>

      {/* Form */}
      {showForm && (
        <div className="bg-white border border-gray-200 rounded-lg p-6">
          <h3 className="text-lg font-semibold mb-4">
            {editingId ? 'Edit Special Deal' : 'Create New Special Deal'}
          </h3>
          
          <div className="mb-4 flex gap-4">
            <label className="flex items-center gap-2">
              <input
                type="radio"
                value="individual"
                checked={dealType === 'individual'}
                onChange={(e) => {
                  setDealType(e.target.value as 'individual' | 'department');
                  setFormData({ ...formData, type: 'individual' });
                }}
              />
              Individual Stock Items
            </label>
            <label className="flex items-center gap-2">
              <input
                type="radio"
                value="department"
                checked={dealType === 'department'}
                onChange={(e) => {
                  setDealType(e.target.value as 'individual' | 'department');
                  setFormData({ ...formData, type: 'department' });
                }}
              />
              Entire Departments
            </label>
          </div>

          <form onSubmit={handleSubmit} className="grid md:grid-cols-2 gap-4">
            {dealType === 'individual' ? (
              <>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Stock Code *
                  </label>
                  <input
                    type="text"
                    value={formData.stock_code}
                    onChange={(e) => setFormData({ ...formData, stock_code: e.target.value })}
                    placeholder="Stock code"
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                    required
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Special Cost Price *
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    value={formData.special_cost_price || ''}
                    onChange={(e) => setFormData({ ...formData, special_cost_price: e.target.value ? parseFloat(e.target.value) : 0 })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                    required
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Mark-up % *
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    value={formData.markup_percentage || ''}
                    onChange={(e) => handleMarkupChange(e.target.value ? parseFloat(e.target.value) : 0)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                    required
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Selling Price Level 1 (Recommended)
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    value={formData.special_selling_price_1 || ''}
                    onChange={(e) => handleSellingPriceChange(1, e.target.value ? parseFloat(e.target.value) : 0)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-gray-50"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Selling Price Level 2
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    value={formData.special_selling_price_2 || ''}
                    onChange={(e) => handleSellingPriceChange(2, e.target.value ? parseFloat(e.target.value) : 0)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-gray-50"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Selling Price Level 3
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    value={formData.special_selling_price_3 || ''}
                    onChange={(e) => handleSellingPriceChange(3, e.target.value ? parseFloat(e.target.value) : 0)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-gray-50"
                  />
                </div>
              </>
            ) : (
              <>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Department Number *
                  </label>
                  <input
                    type="number"
                    value={formData.department}
                    onChange={(e) => setFormData({ ...formData, department: e.target.value })}
                    placeholder="Department number"
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                    required
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Increase/Decrease *
                  </label>
                  <select
                    value={formData.increase_decrease || '+'}
                    onChange={(e) => setFormData({ ...formData, increase_decrease: e.target.value as '+' | '-' })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                  >
                    <option value="+">Increase (+)</option>
                    <option value="-">Decrease (-)</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Percentage/Rand *
                  </label>
                  <select
                    value={formData.percentage_rand || 'P'}
                    onChange={(e) => setFormData({ ...formData, percentage_rand: e.target.value as 'P' | 'R' })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                  >
                    <option value="P">Percentage (%)</option>
                    <option value="R">Rand Value (R)</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Amount *
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    value={formData.amount || ''}
                    onChange={(e) => setFormData({ ...formData, amount: e.target.value ? parseFloat(e.target.value) : 0 })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                    required
                  />
                </div>

                <p className="text-xs text-gray-500 md:col-span-2">
                  Applies to all active items in the department, adjusting each item&apos;s own
                  Selling Price 1/2/3 by this amount.
                </p>
              </>
            )}

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Start Date *
              </label>
              <input
                type="date"
                value={formData.start_date}
                onChange={(e) => setFormData({ ...formData, start_date: e.target.value })}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                End Date *
              </label>
              <input
                type="date"
                value={formData.end_date}
                onChange={(e) => setFormData({ ...formData, end_date: e.target.value })}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                required
              />
            </div>

            <div className="md:col-span-2 flex gap-3">
              <button
                type="submit"
                disabled={mutation.isPending || bulkDepartmentMutation.isPending}
                className="flex-1 bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50"
              >
                {mutation.isPending || bulkDepartmentMutation.isPending
                  ? 'Saving...'
                  : dealType === 'department'
                  ? 'Create Deals for Department'
                  : editingId
                  ? 'Update Deal'
                  : 'Create Deal'}
              </button>
              <button
                type="button"
                onClick={() => setShowForm(false)}
                className="flex-1 bg-gray-300 text-gray-700 py-2 rounded-lg hover:bg-gray-400"
              >
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Search */}
      <div className="relative">
        <Search className="absolute left-3 top-3 w-4 h-4 text-gray-400" />
        <input
          type="text"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          placeholder="Search by stock code..."
          className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg"
        />
      </div>

      {/* Table */}
      <div className="overflow-x-auto bg-white rounded-lg border border-gray-200">
        <table className="w-full">
          <thead className="border-b border-gray-200 bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">Code/Dept</th>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">Type</th>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">Start Date</th>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">End Date</th>
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-900">Markup %</th>
              <th className="px-6 py-3 text-right text-sm font-semibold text-gray-900">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {isLoading ? (
              <tr>
                <td colSpan={6} className="px-6 py-4 text-center text-gray-500">Loading...</td>
              </tr>
            ) : error ? (
              <tr>
                <td colSpan={6} className="px-6 py-4 text-center text-red-500">Error loading deals: {(error as any).message}</td>
              </tr>
            ) : filteredDeals.length === 0 ? (
              <tr>
                <td colSpan={6} className="px-6 py-4 text-center text-gray-500">No special deals found</td>
              </tr>
            ) : (
              filteredDeals.map((deal: SpecialDeal) => (
                <tr key={deal.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 text-sm font-medium text-gray-900">{deal.stock_code || deal.department}</td>
                  <td className="px-6 py-4 text-sm text-gray-600 capitalize">{deal.type}</td>
                  <td className="px-6 py-4 text-sm text-gray-600">{deal.start_date}</td>
                  <td className="px-6 py-4 text-sm text-gray-600">{deal.end_date}</td>
                  <td className="px-6 py-4 text-sm text-gray-600">{deal.markup_percentage ? `${deal.markup_percentage}%` : (deal.special_markup_1 ? `${deal.special_markup_1}%` : '-')}</td>
                  <td className="px-6 py-4 text-right space-x-2">
                    <button
                      onClick={() => handleEdit(deal)}
                      className="text-blue-600 hover:text-blue-800"
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => deal.id && deleteMutation.mutate(deal.id)}
                      className="text-red-600 hover:text-red-800"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

