'use client';

import { useState, useEffect } from 'react';
import { ArrowLeft, Plus, Trash2, Save, X } from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '@/lib/api';
import { stockControlApi } from '@/lib/stockControlApi';

interface StockAdjustmentsProps {
  onBack: () => void;
}

export default function StockAdjustments({ onBack }: StockAdjustmentsProps) {
  const [selectedStockCode, setSelectedStockCode] = useState('');
  const [newQuantity, setNewQuantity] = useState(0);
  const [adjustmentReason, setAdjustmentReason] = useState('MANUAL_ADJUSTMENT');
  const [adjustments, setAdjustments] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [stockItems, setStockItems] = useState<any[]>([]);
  const [filteredItems, setFilteredItems] = useState<any[]>([]);
  const [showItemsList, setShowItemsList] = useState(false);
  const queryClient = useQueryClient();

  // Fetch stock items
  const { data: stockData } = useQuery({
    queryKey: ['stock-items'],
    queryFn: async () => {
      const response = await api.get('/api/stock-control/stock-items/');
      return response.data.results || response.data;
    },
  });

  // Apply the adjustment via StockItemViewSet.adjust_stock, the endpoint
  // that actually creates the ADJUSTMENT transaction and moves QOH in one
  // step — this used to post a raw StockTransaction to a URL that doesn't
  // exist, and even fixed to the right URL, type: 'ADJUSTMENT' isn't one
  // of the types the backend moves stock for automatically.
  const createAdjustment = useMutation({
    mutationFn: async (data: { stockCode: string; quantity: number; comments: string }) =>
      stockControlApi.stockItems.adjustStock(data.stockCode, {
        quantity: data.quantity,
        comments: data.comments,
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['stock-items'] });
      alert('Stock adjustment completed successfully!');
      setAdjustments([]);
      onBack();
    },
    onError: (error: any) => {
      alert(`Error: ${error.response?.data?.detail || error.message}`);
    },
  });

  useEffect(() => {
    if (stockData) {
      setStockItems(stockData);
    }
  }, [stockData]);

  useEffect(() => {
    if (searchTerm) {
      const filtered = stockItems.filter(
        (item) =>
          item.stock_code.toLowerCase().includes(searchTerm.toLowerCase()) ||
          item.description.toLowerCase().includes(searchTerm.toLowerCase())
      );
      setFilteredItems(filtered);
      setShowItemsList(true);
    } else {
      setFilteredItems([]);
      setShowItemsList(false);
    }
  }, [searchTerm, stockItems]);

  const handleSelectItem = (item: any) => {
    setSelectedStockCode(item.stock_code);
    setNewQuantity(item.quantity_on_hand);
    setSearchTerm(item.stock_code);
    setShowItemsList(false);
  };

  const handleAddAdjustment = () => {
    if (!selectedStockCode || newQuantity < 0) {
      alert('Please select an item and enter a valid quantity');
      return;
    }

    const item = stockItems.find((s) => s.stock_code === selectedStockCode);
    const currentQty = parseFloat(item?.quantity_on_hand) || 0;
    const difference = newQuantity - currentQty;

    const adjustment = {
      stock_code: selectedStockCode,
      description: item?.description || '',
      current_qty: currentQty,
      new_qty: newQuantity,
      difference,
      reason: adjustmentReason,
    };

    setAdjustments([...adjustments, adjustment]);
    setSelectedStockCode('');
    setNewQuantity(0);
    setSearchTerm('');
    setAdjustmentReason('MANUAL_ADJUSTMENT');
  };

  const handleRemoveAdjustment = (index: number) => {
    setAdjustments(adjustments.filter((_, i) => i !== index));
  };

  const handleSubmit = async () => {
    if (adjustments.length === 0) {
      alert('Please add at least one adjustment');
      return;
    }

    try {
      for (const adj of adjustments) {
        await createAdjustment.mutateAsync({
          stockCode: adj.stock_code,
          quantity: adj.difference,
          comments: adj.reason,
        });
      }
    } catch (error) {
      console.error('Error creating adjustment:', error);
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-lg p-6">
      <div className="flex items-center gap-4 mb-6">
        <button
          onClick={onBack}
          className="flex items-center gap-2 px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg"
        >
          <ArrowLeft size={20} />
          Back
        </button>
        <h3 className="text-2xl font-bold">Stock Item Adjustments</h3>
      </div>

      {/* Add Adjustment Section */}
      <div className="bg-gray-50 rounded-lg p-6 mb-6">
        <h4 className="text-lg font-semibold mb-4">Add Stock Adjustment</h4>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-4">
          <div>
            <label className="block text-sm font-medium mb-2">Stock Code / Description</label>
            <div className="relative">
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Search stock..."
                className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
              {showItemsList && (
                <div className="absolute top-full left-0 right-0 bg-white border border-t-0 rounded-b-lg shadow-lg max-h-40 overflow-y-auto z-10">
                  {filteredItems.map((item) => (
                    <div
                      key={item.stock_code}
                      onClick={() => handleSelectItem(item)}
                      className="px-4 py-2 hover:bg-gray-100 cursor-pointer"
                    >
                      <p className="font-medium">{item.stock_code}</p>
                      <p className="text-sm text-gray-600">{item.description}</p>
                      <p className="text-xs text-gray-500">Current: {item.quantity_on_hand.toFixed(2)}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium mb-2">New Quantity</label>
            <input
              type="number"
              value={newQuantity}
              onChange={(e) => setNewQuantity(parseFloat(e.target.value) || 0)}
              step="0.01"
              min="0"
              className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium mb-2">Reason</label>
            <select
              value={adjustmentReason}
              onChange={(e) => setAdjustmentReason(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="MANUAL_ADJUSTMENT">Manual Adjustment</option>
              <option value="STOCK_DISCREPANCY">Stock Discrepancy</option>
              <option value="SHRINKAGE">Shrinkage</option>
              <option value="DAMAGE">Damaged Goods</option>
              <option value="LOST">Lost Stock</option>
              <option value="CORRECTION">Correction</option>
            </select>
          </div>
          <div className="flex items-end">
            <button
              onClick={handleAddAdjustment}
              disabled={!selectedStockCode}
              className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition"
            >
              <Plus size={20} />
              Add
            </button>
          </div>
        </div>
      </div>

      {/* Adjustments List */}
      <div className="mb-6">
        <h4 className="text-lg font-semibold mb-4">Pending Adjustments</h4>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-gray-100 border-b">
              <tr>
                <th className="text-left px-4 py-2">Stock Code</th>
                <th className="text-left px-4 py-2">Description</th>
                <th className="text-right px-4 py-2">Current Qty</th>
                <th className="text-right px-4 py-2">New Qty</th>
                <th className="text-right px-4 py-2">Difference</th>
                <th className="text-left px-4 py-2">Reason</th>
                <th className="text-center px-4 py-2">Action</th>
              </tr>
            </thead>
            <tbody>
              {adjustments.map((adj, index) => (
                <tr key={index} className={`border-b ${adj.difference > 0 ? 'bg-green-50' : 'bg-red-50'}`}>
                  <td className="px-4 py-2 font-medium">{adj.stock_code}</td>
                  <td className="px-4 py-2">{adj.description}</td>
                  <td className="text-right px-4 py-2">{adj.current_qty.toFixed(2)}</td>
                  <td className="text-right px-4 py-2">{adj.new_qty.toFixed(2)}</td>
                  <td className={`text-right px-4 py-2 font-semibold ${adj.difference > 0 ? 'text-green-600' : 'text-red-600'}`}>
                    {adj.difference > 0 ? '+' : ''}{adj.difference.toFixed(2)}
                  </td>
                  <td className="px-4 py-2 text-xs text-gray-600">{adj.reason}</td>
                  <td className="text-center px-4 py-2">
                    <button
                      onClick={() => handleRemoveAdjustment(index)}
                      className="text-red-600 hover:text-red-800"
                    >
                      <Trash2 size={18} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {adjustments.length === 0 && (
          <div className="p-4 text-center text-gray-500 bg-gray-50 rounded-lg">
            No adjustments added yet.
          </div>
        )}
      </div>

      {/* Action Buttons */}
      <div className="flex gap-4 justify-end">
        <button
          onClick={onBack}
          className="flex items-center gap-2 px-6 py-2 bg-gray-300 text-gray-800 rounded-lg hover:bg-gray-400 transition"
        >
          <X size={20} />
          Cancel
        </button>
        <button
          onClick={handleSubmit}
          disabled={adjustments.length === 0 || createAdjustment.isPending}
          className="flex items-center gap-2 px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:opacity-50 transition"
        >
          <Save size={20} />
          {createAdjustment.isPending ? 'Processing...' : 'Apply Adjustments'}
        </button>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Save, X, ChevronUp, ChevronDown } from 'lucide-react';
import { useMutation } from '@tanstack/react-query';
import { api } from '@/lib/api';
import { stockControlApi } from '@/lib/stockControlApi';

interface StockCountProps {
  onBack: () => void;
}

export default function StockCount({ onBack }: StockCountProps) {
  const [stockTakeId, setStockTakeId] = useState<number | null>(null);
  const [currentItemIndex, setCurrentItemIndex] = useState(0);
  const [countedQuantities, setCountedQuantities] = useState<{ [key: string]: number }>({});
  const [stockItems, setStockItems] = useState<any[]>([]);
  // stock_code -> StockTakeItem id, so re-saving (e.g. after Previous) updates
  // the existing row instead of hitting the (stock_take, stock_item) unique
  // constraint on a second create.
  const savedItemIds = useRef<{ [stockCode: string]: number }>({});

  // Create new stock take session
  const createStockTake = useMutation({
    mutationFn: async () => {
      return stockControlApi.stockTakes.create({
        stock_take_date: new Date().toISOString().split('T')[0],
        status: 'IN_PROGRESS',
        description: 'Physical stock count session',
      });
    },
    onSuccess: (data) => {
      setStockTakeId(data.id);
      loadStockItems();
    },
  });

  // Load stock items for counting
  const loadStockItems = async () => {
    try {
      const response = await api.get('/api/stock-control/stock-items/');
      const items = response.data.results || response.data;
      setStockItems(items.filter((item: any) => item.is_active));
    } catch (error) {
      console.error('Error loading stock items:', error);
    }
  };

  // Save quantity for current item
  const saveQuantity = useMutation({
    mutationFn: async (quantity: number) => {
      if (!stockTakeId || !stockItems[currentItemIndex]) {
        throw new Error('Invalid stock take or item');
      }

      const item = stockItems[currentItemIndex];
      const existingId = savedItemIds.current[item.stock_code];
      if (existingId) {
        return stockControlApi.stockTakeItems.recordCount(existingId, quantity);
      }

      const created = await stockControlApi.stockTakeItems.create({
        stock_take: stockTakeId,
        stock_item: item.stock_code,
        quantity_on_hand: item.quantity_on_hand,
      });
      savedItemIds.current[item.stock_code] = created.id;
      return stockControlApi.stockTakeItems.recordCount(created.id, quantity);
    },
    onSuccess: () => {
      // Move to next item
      if (currentItemIndex < stockItems.length - 1) {
        setCurrentItemIndex(currentItemIndex + 1);
      }
    },
  });

  useEffect(() => {
    if (!stockTakeId) {
      createStockTake.mutate();
    }
  }, []);

  if (!stockItems.length) {
    return (
      <div className="bg-white rounded-lg shadow-lg p-6 text-center">
        <p className="text-gray-600">Loading stock items...</p>
      </div>
    );
  }

  const currentItem = stockItems[currentItemIndex];
  const currentQuantity = countedQuantities[currentItem?.stock_code] || 0;

  const handleSave = () => {
    setCountedQuantities({
      ...countedQuantities,
      [currentItem.stock_code]: currentQuantity,
    });
    saveQuantity.mutate(currentQuantity);
  };

  return (
    <div className="bg-white rounded-lg shadow-lg p-6">
      <div className="flex items-center gap-4 mb-6">
        <button
          onClick={onBack}
          className="flex items-center gap-2 px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg"
        >
          <ArrowLeft size={20} />
          Back
        </button>
        <h3 className="text-2xl font-bold">Stock Count</h3>
      </div>

      <div className="mb-6 p-4 bg-gray-100 rounded-lg">
        <p className="text-sm text-gray-600">
          Item <strong>{currentItemIndex + 1}</strong> of <strong>{stockItems.length}</strong>
        </p>
        <div className="w-full bg-gray-300 rounded-full h-2 mt-2">
          <div
            className="bg-blue-600 h-2 rounded-full transition-all duration-300"
            style={{
              width: `${((currentItemIndex + 1) / stockItems.length) * 100}%`,
            }}
          ></div>
        </div>
      </div>

      {currentItem && (
        <div className="bg-gray-50 rounded-lg p-8 mb-6">
          <h4 className="text-lg font-semibold mb-4 text-gray-700">Item Information</h4>
          <div className="grid grid-cols-2 gap-4 mb-6">
            <div>
              <p className="text-sm text-gray-600">Stock Code</p>
              <p className="text-2xl font-bold">{currentItem.stock_code}</p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Description</p>
              <p className="text-lg">{currentItem.description}</p>
            </div>
            <div>
              <p className="text-sm text-gray-600">System Quantity on Hand</p>
              <p className="text-2xl font-bold text-green-600">{currentItem.quantity_on_hand.toFixed(2)}</p>
            </div>
            <div>
              <p className="text-sm text-gray-600">Monthly Sales to Date</p>
              <p className="text-lg">{currentItem.sales_mtd_quantity?.toFixed(2) || '0.00'}</p>
            </div>
          </div>

          <div className="bg-white rounded-lg p-6 border-2 border-blue-500">
            <label className="block text-sm font-medium mb-4">Quantity Counted</label>
            <input
              type="number"
              value={currentQuantity}
              onChange={(e) =>
                setCountedQuantities({
                  ...countedQuantities,
                  [currentItem.stock_code]: parseFloat(e.target.value) || 0,
                })
              }
              step="0.01"
              min="0"
              autoFocus
              className="w-full px-6 py-4 text-3xl font-bold border-2 border-blue-500 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-700"
              onKeyPress={(e) => {
                if (e.key === 'Enter') {
                  handleSave();
                }
              }}
            />
            <p className="text-xs text-gray-500 mt-2">Press [Enter] to save and move to next item, or click Save</p>
          </div>

          {currentQuantity !== currentItem.quantity_on_hand && (
            <div className="mt-4 p-4 bg-yellow-50 border-l-4 border-yellow-600 rounded">
              <p className="text-sm text-yellow-800">
                <strong>Variance:</strong> Counted {currentQuantity.toFixed(2)} vs System {currentItem.quantity_on_hand.toFixed(2)} 
                ({(currentQuantity - currentItem.quantity_on_hand).toFixed(2)})
              </p>
            </div>
          )}
        </div>
      )}

      <div className="flex gap-4 justify-center">
        <button
          onClick={onBack}
          className="flex items-center gap-2 px-6 py-2 bg-gray-300 text-gray-800 rounded-lg hover:bg-gray-400 transition"
        >
          <X size={20} />
          End Count
        </button>

        <button
          onClick={() => setCurrentItemIndex(Math.max(0, currentItemIndex - 1))}
          disabled={currentItemIndex === 0}
          className="flex items-center gap-2 px-6 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 disabled:opacity-50 transition"
        >
          <ChevronUp size={20} />
          Previous
        </button>

        <button
          onClick={handleSave}
          disabled={saveQuantity.isPending}
          className="flex items-center gap-2 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 transition"
        >
          <Save size={20} />
          {saveQuantity.isPending ? 'Saving...' : 'Save & Next'}
        </button>

        <button
          onClick={() =>
            setCurrentItemIndex(Math.min(stockItems.length - 1, currentItemIndex + 1))
          }
          disabled={currentItemIndex === stockItems.length - 1}
          className="flex items-center gap-2 px-6 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 disabled:opacity-50 transition"
        >
          <ChevronDown size={20} />
          Skip
        </button>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { ArrowLeft, RefreshCw } from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { stockControlApi } from '@/lib/stockControlApi';
import type { StockTake } from '@/lib/types/stockControl';

interface StockTakeUpdateProps {
  onBack: () => void;
}

/**
 * "F. Stock Take Update" — apply a stock take's counted quantities to
 * live QOH. Was previously routed to the same component as "G. Stock Item
 * Adjustment" in StockTakeMenu.tsx, so this screen (and update_stock's
 * mode/After-Trading options) had no UI at all.
 */
export default function StockTakeUpdate({ onBack }: StockTakeUpdateProps) {
  const [selectedId, setSelectedId] = useState<number | ''>('');
  const [mode, setMode] = useState<'overwrite' | 'additive'>('overwrite');
  const [resetNegatives, setResetNegatives] = useState(false);
  const [setUncounted, setSetUncounted] = useState(false);
  const [isAfterTrading, setIsAfterTrading] = useState(false);
  const [tradingStartDate, setTradingStartDate] = useState('');
  const queryClient = useQueryClient();

  const { data: stockTakes, isLoading } = useQuery({
    queryKey: ['stock-takes', 'updatable'],
    queryFn: async () => {
      const result = await stockControlApi.stockTakes.list();
      const takes = result.results ?? (result as unknown as StockTake[]);
      return takes.filter((t) => t.status === 'IN_PROGRESS' || t.status === 'COMPLETED');
    },
  });

  const selectedTake = stockTakes?.find((t) => t.id === selectedId);

  const applyFlagsMutation = useMutation({
    mutationFn: async (id: number) =>
      stockControlApi.stockTakes.update(id, {
        reset_negatives_to_zero: resetNegatives,
        set_uncounted_to_zero: setUncounted,
        is_after_trading: isAfterTrading,
        trading_start_date: isAfterTrading && tradingStartDate ? tradingStartDate : undefined,
      }),
  });

  const updateStockMutation = useMutation({
    mutationFn: async (id: number) => stockControlApi.stockTakes.updateStock(id, mode),
    onSuccess: (data: any) => {
      queryClient.invalidateQueries({ queryKey: ['stock-takes'] });
      queryClient.invalidateQueries({ queryKey: ['stock-items'] });
      alert(data?.message ?? 'Stock take applied.');
      onBack();
    },
    onError: (error: any) => {
      const msg = error?.response?.data?.error ?? error?.message ?? 'Unknown error';
      alert(`Update failed: ${msg}`);
    },
  });

  const handleApply = async () => {
    if (!selectedId) {
      alert('Select a stock take first.');
      return;
    }
    if (isAfterTrading && !tradingStartDate) {
      alert('Trading start date is required for an After-Trading update.');
      return;
    }
    if (isAfterTrading && mode === 'additive') {
      alert('Additive mode cannot be combined with an After-Trading update.');
      return;
    }
    await applyFlagsMutation.mutateAsync(selectedId);
    await updateStockMutation.mutateAsync(selectedId);
  };

  const busy = applyFlagsMutation.isPending || updateStockMutation.isPending;

  return (
    <div className="bg-white rounded-lg shadow-lg p-6">
      <div className="flex items-center gap-4 mb-6">
        <button onClick={onBack} className="flex items-center gap-2 px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg">
          <ArrowLeft size={20} />
          Back
        </button>
        <h3 className="text-2xl font-bold">Stock Take Update</h3>
      </div>

      <div className="mb-6">
        <label className="block text-sm font-medium mb-2">Select Stock Take</label>
        <select
          value={selectedId}
          onChange={(e) => setSelectedId(e.target.value ? parseInt(e.target.value) : '')}
          disabled={isLoading}
          className="w-full md:w-96 px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
        >
          <option value="">{isLoading ? 'Loading...' : '-- Select Stock Take --'}</option>
          {stockTakes?.map((st) => (
            <option key={st.id} value={st.id}>
              {st.stock_take_date} ({st.status}) — {st.item_count ?? 0} items
            </option>
          ))}
        </select>
        {stockTakes && stockTakes.length === 0 && !isLoading && (
          <p className="text-sm text-gray-500 mt-2">No in-progress or completed stock takes to update.</p>
        )}
      </div>

      {selectedTake && (
        <div className="bg-gray-50 rounded-lg p-6 mb-6 space-y-4">
          <div>
            <label className="block text-sm font-medium mb-2">Update Mode</label>
            <div className="flex gap-6">
              <label className="flex items-center gap-2">
                <input
                  type="radio"
                  checked={mode === 'overwrite'}
                  onChange={() => setMode('overwrite')}
                />
                Overwrite (counted quantity is the new QOH)
              </label>
              <label className="flex items-center gap-2">
                <input
                  type="radio"
                  checked={mode === 'additive'}
                  disabled={isAfterTrading}
                  onChange={() => setMode('additive')}
                />
                Additive (counted quantity is added to current QOH)
              </label>
            </div>
          </div>

          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={isAfterTrading}
              onChange={(e) => {
                setIsAfterTrading(e.target.checked);
                if (e.target.checked) setMode('overwrite');
              }}
              className="w-4 h-4"
            />
            <span className="text-sm font-medium">
              After-Trading update (sales/receipts happened since the physical count — preserve those movements instead of overwriting them)
            </span>
          </label>

          {isAfterTrading && (
            <div>
              <label className="block text-sm font-medium mb-2">Trading Start Date *</label>
              <input
                type="datetime-local"
                value={tradingStartDate}
                onChange={(e) => setTradingStartDate(e.target.value)}
                className="w-full md:w-72 px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
          )}

          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={resetNegatives}
              onChange={(e) => setResetNegatives(e.target.checked)}
              className="w-4 h-4"
            />
            <span className="text-sm">Reset negative counts to zero</span>
          </label>

          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={setUncounted}
              onChange={(e) => setSetUncounted(e.target.checked)}
              className="w-4 h-4"
            />
            <span className="text-sm">Set uncounted items to zero</span>
          </label>
        </div>
      )}

      <div className="flex gap-4 justify-end">
        <button onClick={onBack} className="px-6 py-2 bg-gray-300 text-gray-800 rounded-lg hover:bg-gray-400 transition">
          Cancel
        </button>
        <button
          onClick={handleApply}
          disabled={!selectedId || busy}
          className="flex items-center gap-2 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 transition"
        >
          <RefreshCw size={20} />
          {busy ? 'Applying...' : 'Apply to Stock'}
        </button>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { ArrowLeft, Download } from 'lucide-react';
import { useQuery } from '@tanstack/react-query';
import { api } from '@/lib/api';

interface StockValuationProps {
  onBack: () => void;
}

export default function StockValuation({ onBack }: StockValuationProps) {
  const [selectedStockTake, setSelectedStockTake] = useState<number | ''>('');
  const [valuationType, setValuationType] = useState('actual');

  // Fetch stock takes
  const { data: stockTakes } = useQuery({
    queryKey: ['stock-takes'],
    queryFn: async () => {
      const response = await api.get('/api/stock-control/stock-takes/');
      return response.data.results || response.data;
    },
  });

  // Fetch valuation items
  const { data: valuationItems } = useQuery({
    queryKey: ['valuation-items', selectedStockTake, valuationType],
    queryFn: async () => {
      if (!selectedStockTake) return [];
      const response = await api.get(`/api/stock-control/stock-takes/${selectedStockTake}/items/`);
      return response.data.results || response.data;
    },
    enabled: !!selectedStockTake,
  });

  const calculateValuation = () => {
    if (!valuationItems) return 0;
    return valuationItems.reduce((total: number, item: any) => {
      const qty = valuationType === 'actual' ? item.quantity_on_hand : item.quantity_counted;
      return total + qty * item.cost_price_at_count;
    }, 0);
  };

  const totalValuation = calculateValuation();

  return (
    <div className="bg-white rounded-lg shadow-lg p-6">
      <div className="flex items-center gap-4 mb-6">
        <button
          onClick={onBack}
          className="flex items-center gap-2 px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg"
        >
          <ArrowLeft size={20} />
          Back
        </button>
        <h3 className="text-2xl font-bold">Stock Valuation Report</h3>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
        <div>
          <label className="block text-sm font-medium mb-2">Select Stock Take</label>
          <select
            value={selectedStockTake}
            onChange={(e) => setSelectedStockTake(e.target.value ? parseInt(e.target.value) : '')}
            className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">-- Select Stock Take --</option>
            {stockTakes?.map((st: any) => (
              <option key={st.id} value={st.id}>
                {st.stock_take_date} ({st.status})
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium mb-2">Valuation Type</label>
          <select
            value={valuationType}
            onChange={(e) => setValuationType(e.target.value)}
            className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="actual">Actual Qty on Hand</option>
            <option value="counted">Quantity Counted</option>
          </select>
        </div>
      </div>

      {selectedStockTake && (
        <>
          <div className="overflow-x-auto mb-6">
            <table className="w-full text-sm">
              <thead className="bg-gray-100 border-b">
                <tr>
                  <th className="text-left px-4 py-2">Stock Code</th>
                  <th className="text-left px-4 py-2">Description</th>
                  <th className="text-right px-4 py-2">Quantity</th>
                  <th className="text-right px-4 py-2">Cost Price</th>
                  <th className="text-right px-4 py-2">Valuation</th>
                </tr>
              </thead>
              <tbody>
                {valuationItems?.map((item: any, index: number) => {
                  const qty = valuationType === 'actual' ? item.quantity_on_hand : item.quantity_counted;
                  const value = qty * item.cost_price_at_count;
                  return (
                    <tr key={index} className="border-b hover:bg-gray-50">
                      <td className="px-4 py-2 font-medium">{item.stock_item?.stock_code}</td>
                      <td className="px-4 py-2">{item.stock_item?.description}</td>
                      <td className="text-right px-4 py-2">{qty.toFixed(2)}</td>
                      <td className="text-right px-4 py-2">R {item.cost_price_at_count.toFixed(2)}</td>
                      <td className="text-right px-4 py-2 font-semibold">R {value.toFixed(2)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          <div className="mb-6 space-y-2 text-right max-w-md ml-auto">
            <div className="flex justify-between text-lg border-t pt-4">
              <span>Total Stock Valuation:</span>
              <span className="font-bold text-2xl text-blue-600">
                R {totalValuation.toFixed(2)}
              </span>
            </div>
            <p className="text-xs text-gray-500">
              {valuationType === 'actual' 
                ? 'Based on Actual Quantity on Hand' 
                : 'Based on Quantity Counted'}
            </p>
          </div>
        </>
      )}

      <div className="flex gap-4 justify-center">
        <button
          onClick={onBack}
          className="px-6 py-2 bg-gray-300 text-gray-800 rounded-lg hover:bg-gray-400 transition"
        >
          Back
        </button>
        <button
          disabled={!selectedStockTake}
          className="flex items-center gap-2 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 transition"
        >
          <Download size={20} />
          Export Valuation
        </button>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { ArrowLeft, Download } from 'lucide-react';
import { useQuery } from '@tanstack/react-query';
import { stockControlApi } from '@/lib/stockControlApi';

interface VarianceReportProps {
  onBack: () => void;
}

export default function VarianceReport({ onBack }: VarianceReportProps) {
  const [selectedStockTake, setSelectedStockTake] = useState<number | ''>('');

  // Fetch stock takes
  const { data: stockTakes } = useQuery({
    queryKey: ['stock-takes'],
    queryFn: async () => {
      const result = await stockControlApi.stockTakes.list();
      return result.results ?? result;
    },
  });

  // Fetch variance items — the dedicated variance-report action already
  // filters to non-zero variance server-side.
  const { data: varianceItems, isLoading: _isLoading } = useQuery({
    queryKey: ['variance-items', selectedStockTake],
    queryFn: async () => {
      if (!selectedStockTake) return [];
      return stockControlApi.stockTakes.getVarianceReport(selectedStockTake);
    },
    enabled: !!selectedStockTake,
  });

  const calculateTotals = () => {
    if (!varianceItems) return { quantity: 0, value: 0 };
    return {
      quantity: varianceItems.reduce((sum: number, item: any) => sum + (item.variance_quantity || 0), 0),
      value: varianceItems.reduce((sum: number, item: any) => sum + (item.variance_value || 0), 0),
    };
  };

  const totals = calculateTotals();

  return (
    <div className="bg-white rounded-lg shadow-lg p-6">
      <div className="flex items-center gap-4 mb-6">
        <button
          onClick={onBack}
          className="flex items-center gap-2 px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg"
        >
          <ArrowLeft size={20} />
          Back
        </button>
        <h3 className="text-2xl font-bold">Stock Variance Report</h3>
      </div>

      <div className="mb-6">
        <label className="block text-sm font-medium mb-2">Select Stock Take</label>
        <select
          value={selectedStockTake}
          onChange={(e) => setSelectedStockTake(e.target.value ? parseInt(e.target.value) : '')}
          className="w-full md:w-80 px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
        >
          <option value="">-- Select Stock Take --</option>
          {stockTakes?.map((st: any) => (
            <option key={st.id} value={st.id}>
              {st.stock_take_date} ({st.status})
            </option>
          ))}
        </select>
      </div>

      {selectedStockTake && (
        <>
          <div className="overflow-x-auto mb-6">
            <table className="w-full text-sm">
              <thead className="bg-gray-100 border-b">
                <tr>
                  <th className="text-left px-4 py-2">Stock Code</th>
                  <th className="text-left px-4 py-2">Description</th>
                  <th className="text-right px-4 py-2">System Qty</th>
                  <th className="text-right px-4 py-2">Counted Qty</th>
                  <th className="text-right px-4 py-2">Variance Qty</th>
                  <th className="text-right px-4 py-2">Cost Price</th>
                  <th className="text-right px-4 py-2">Variance Value</th>
                </tr>
              </thead>
              <tbody>
                {varianceItems?.map((item: any, index: number) => (
                  <tr key={index} className={`border-b ${item.variance_quantity < 0 ? 'bg-red-50' : 'bg-green-50'}`}>
                    <td className="px-4 py-2 font-medium">{item.stock_item_detail?.stock_code ?? item.stock_item}</td>
                    <td className="px-4 py-2">{item.stock_item_detail?.description ?? ''}</td>
                    <td className="text-right px-4 py-2">{item.quantity_on_hand.toFixed(2)}</td>
                    <td className="text-right px-4 py-2">{item.quantity_counted.toFixed(2)}</td>
                    <td className={`text-right px-4 py-2 font-semibold ${item.variance_quantity < 0 ? 'text-red-600' : 'text-green-600'}`}>
                      {item.variance_quantity.toFixed(2)}
                    </td>
                    <td className="text-right px-4 py-2">R {item.cost_price_at_count.toFixed(2)}</td>
                    <td className={`text-right px-4 py-2 font-semibold ${item.variance_value < 0 ? 'text-red-600' : 'text-green-600'}`}>
                      R {item.variance_value.toFixed(2)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {varianceItems && varianceItems.length > 0 && (
            <div className="mb-6 space-y-2 text-right max-w-md ml-auto">
              <div className="flex justify-between text-sm border-t pt-2">
                <span>Total Variance Qty:</span>
                <span className={`font-bold ${totals.quantity < 0 ? 'text-red-600' : 'text-green-600'}`}>
                  {totals.quantity.toFixed(2)}
                </span>
              </div>
              <div className="flex justify-between text-lg border-t pt-2">
                <span>Total Variance Value:</span>
                <span className={`font-bold ${totals.value < 0 ? 'text-red-600' : 'text-green-600'}`}>
                  R {totals.value.toFixed(2)}
                </span>
              </div>
            </div>
          )}

          {varianceItems && varianceItems.length === 0 && (
            <div className="p-4 bg-green-50 border-l-4 border-green-600 rounded">
              <p className="text-sm text-green-800">
                <strong>No Variances Found:</strong> All counted quantities match system quantities.
              </p>
            </div>
          )}
        </>
      )}

      <div className="flex gap-4 justify-center">
        <button
          onClick={onBack}
          className="px-6 py-2 bg-gray-300 text-gray-800 rounded-lg hover:bg-gray-400 transition"
        >
          Back
        </button>
        <button
          disabled={!selectedStockTake}
          className="flex items-center gap-2 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 transition"
        >
          <Download size={20} />
          Export Report
        </button>
      </div>
    </div>
  );
}

