'use client';
import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';
import { apiRequest } from './api';
import { setTenant, setShops, getTenant } from './shopContext';
import type { MaybeAxiosError } from '@/lib/types/errors';

export interface Shop {
  id: number;
  name: string;
  schema_name: string;
  is_head_office: boolean;
  is_current: boolean;
  enabled_addons: string[];
  enable_stock_consolidation: boolean;
}

export interface User {
  id: number;
  username: string;
  email: string;
  role: string;
  is_superuser: boolean;
  is_admin: boolean;
  tenant_id: number | null;
}

interface AuthContextType {
  user: User | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  isAdmin: boolean;
  isAccountant: boolean;
  setUser: (user: User | null) => void;
  refetch: () => Promise<void>;
  // Shop-related properties
  currentShop: Shop | null;
  accessibleShops: Shop[];
  switchShop: (shopId: number) => Promise<void>;
  refetchShops: () => Promise<void>;
  // Subscribe to shop changes - useful for auto-refreshing data
  onShopChange: (callback: (shop: Shop) => void) => () => void;
  // Tenant-level optional addons (cash_book/general_ledger/gas/stockfinder) -
  // same list on every shop (Tenant.enabled_addons is tenant-wide, not per-shop)
  hasAddon: (addon: string) => boolean;
  // Tenant-wide toggle for Stock Consolidation (inter-branch transfers) -
  // same value on every shop (Tenant.enable_stock_consolidation)
  stockConsolidationEnabled: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [hasAttemptedInitialFetch, setHasAttemptedInitialFetch] = useState(false);
  const [currentShop, setCurrentShop] = useState<Shop | null>(null);
  const [accessibleShops, setAccessibleShops] = useState<Shop[]>([]);
  
  // Shop change callbacks for auto-refresh
  const [shopChangeCallbacks, setShopChangeCallbacks] = useState<Set<(shop: Shop) => void>>(new Set());
  
  // Register callback for shop changes
  const onShopChange = useCallback((callback: (shop: Shop) => void) => {
    setShopChangeCallbacks(prev => {
      const newSet = new Set(prev);
      newSet.add(callback);
      return newSet;
    });
    // Return unsubscribe function
    return () => {
      setShopChangeCallbacks(prev => {
        const newSet = new Set(prev);
        newSet.delete(callback);
        return newSet;
      });
    };
  }, []);
  
  // Notify all subscribers when shop changes
  const notifyShopChange = useCallback((shop: Shop) => {
    shopChangeCallbacks.forEach(callback => {
      try {
        callback(shop);
      } catch (e) {
        console.error('Error in shop change callback:', e);
      }
    });
  }, [shopChangeCallbacks]);

  const refetchShops = useCallback(async () => {
    try {
      const response = await apiRequest('/api/v1/tenants/my-shops/');
      const shops = response.data as Shop[];
      setAccessibleShops(shops || []);
      
      // Store shops in localStorage for API calls
      if (shops && shops.length > 0) {
        // Convert AuthContext Shop to shopContext Shop format
        const shopsForStorage = shops.map(shop => ({
          id: shop.id,
          name: shop.name,
          slug: shop.schema_name,
          tenant_id: 0, // Will be set from tenant
          is_active: true,
        }));
        setShops(shopsForStorage);
        
        // Also store tenant from first shop's schema_name if not already set
        const existingTenant = getTenant();
        if (!existingTenant && shops[0].schema_name) {
          setTenant(shops[0].schema_name);
        }
      }
      
        // Find current shop - also save to localStorage for X-Shop-ID header
        const current = shops?.find((s: Shop) => s.is_current);
        if (current) {
          setCurrentShop(current);
          if (typeof window !== 'undefined') {
            localStorage.setItem('currentShopId', String(current.id));
          }
        } else if (shops && shops.length > 0) {
          setCurrentShop(shops[0]);
          if (typeof window !== 'undefined') {
            localStorage.setItem('currentShopId', String(shops[0].id));
          }
        } else {
          setCurrentShop(null);
        }
    } catch (error: unknown) {
      // Don't crash if shops endpoint fails - user might not have shop access yet
      console.error('Could not fetch accessible shops:', (error as MaybeAxiosError)?.response?.data || error);
      setAccessibleShops([]);
      setCurrentShop(null);
    }
  }, []);

  const hasAddon = useCallback((addon: string) => {
    return (currentShop?.enabled_addons ?? accessibleShops[0]?.enabled_addons ?? []).includes(addon);
  }, [currentShop, accessibleShops]);

  const stockConsolidationEnabled =
    currentShop?.enable_stock_consolidation ?? accessibleShops[0]?.enable_stock_consolidation ?? true;

  const switchShop = useCallback(async (shopId: number) => {
    try {
      const response = await apiRequest('/api/v1/tenants/switch-shop/', {
        method: 'POST',
        data: { shop_id: shopId },
      });
      
      // Refresh shops after switching
      await refetchShops();
      
      return response.data;
    } catch (error) {
      console.error('Failed to switch shop:', error);
      throw error;
    }
  }, [refetchShops]);

  // Effect to notify subscribers when currentShop changes (e.g., after shop switch)
  useEffect(() => {
    if (currentShop && hasAttemptedInitialFetch) {
      notifyShopChange(currentShop);
    }
  }, [currentShop, hasAttemptedInitialFetch, notifyShopChange]);

  const refetch = useCallback(async (isInitialLoad: boolean = false) => {
    try {
      setIsLoading(true);
      // Cookies are sent automatically with withCredentials: true
      // No need to check localStorage
      const response = await apiRequest('/api/v1/users/auth/profile/', {
        skipRateLimitRetry: isInitialLoad, // Don't retry on initial load, just accept the failure
      });
      setUser(response.data);
      
      // Also fetch shops on profile fetch
      await refetchShops();
    } catch (error: unknown) {
      // 401 is expected when user hasn't logged in - don't log as error
      if ((error as MaybeAxiosError)?.response?.status === 401) {
        setUser(null);
        setCurrentShop(null);
        setAccessibleShops([]);
      } else if ((error as MaybeAxiosError)?.response?.status === 429) {
        // Rate limited
        if (isInitialLoad) {
          // On initial load, just accept it as "not logged in" to avoid blocking login
          console.debug('Profile endpoint rate limited on initial load - skipping retry');
        } else {
          // On explicit refetch (e.g., after login), log the issue
          console.warn('Rate limited on auth profile fetch - likely due to stale tokens');
        }
        setUser(null);
      } else if ((error as MaybeAxiosError)?.message === 'Network Error' || !(error as MaybeAxiosError)?.response) {
        // Network error - backend might not be running
        console.warn('Network error connecting to API. Backend may not be running at:', process.env.NEXT_PUBLIC_API_BASE || 'http://localhost:8000');
        setUser(null);
      } else {
        console.error('Failed to fetch user profile:', error);
        setUser(null);
      }
    } finally {
      setIsLoading(false);
    }
  }, [refetchShops]);

  useEffect(() => {
    // Only fetch user once on initial mount
    if (!hasAttemptedInitialFetch) {
      setHasAttemptedInitialFetch(true);
      // Mark as initial load so we don't retry on 429
      refetch(true);
    }
  }, [hasAttemptedInitialFetch, refetch]);

  const value: AuthContextType = {
    user,
    isLoading,
    isAuthenticated: user !== null,
    isAdmin: user?.is_admin || false,
    isAccountant: user?.role === 'ACCOUNTANT',
    setUser,
    refetch,
    currentShop,
    accessibleShops,
    switchShop,
    refetchShops,
    onShopChange,
    hasAddon,
    stockConsolidationEnabled,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

/**
 * Hook to use authentication context
 * Must be used within AuthProvider
 */
export function useAuthContext() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuthContext must be used within AuthProvider');
  }
  return context;
}

/**
 * Authentication API Client
 * 
 * Handles all authentication endpoints:
 * - CSRF token management
 * - User registration and login
 * - Token refresh
 * - Logout
 * - Profile management
 * 
 * Base URL: /api/v1/users/auth/
 */

import { api } from './api';
import { ENDPOINTS } from './api-config';

export interface LoginCredentials {
  email: string;
  password: string;
}

export interface SignupData {
  email: string;
  password: string;
  password_confirm: string;
  first_name?: string;
  last_name?: string;
}

export interface UserProfile {
  id: number;
  email: string;
  first_name: string;
  last_name: string;
  is_active: boolean;
  created_at: string;
}

export interface AuthResponse {
  access_token?: string;
  refresh_token?: string;
  user?: UserProfile;
}

export interface TokenRefreshResponse {
  access_token: string;
}

export const authApi = {
  /**
   * Get CSRF token for form submissions
   */
  getCSRFToken: async (): Promise<{ csrfToken: string }> => {
    const response = await api.get(ENDPOINTS.AUTH.CSRF);
    return response.data;
  },

  /**
   * Register new user
   */
  signup: async (data: SignupData): Promise<AuthResponse> => {
    const response = await api.post<AuthResponse>(ENDPOINTS.AUTH.SIGNUP, data);
    return response.data;
  },

  /**
   * Login with email and password
   */
  login: async (credentials: LoginCredentials): Promise<AuthResponse> => {
    const response = await api.post<AuthResponse>(ENDPOINTS.AUTH.LOGIN, credentials);
    return response.data;
  },

  /**
   * Unified login endpoint (supports multiple auth methods)
   */
  unifiedLogin: async (data: any): Promise<AuthResponse> => {
    const response = await api.post<AuthResponse>(ENDPOINTS.AUTH.UNIFIED_LOGIN, data);
    return response.data;
  },

  /**
   * Logout user
   */
  logout: async (): Promise<void> => {
    await api.post(ENDPOINTS.AUTH.LOGOUT);
  },

  /**
   * Refresh access token using refresh token
   */
  refreshToken: async (): Promise<TokenRefreshResponse> => {
    const response = await api.post<TokenRefreshResponse>(ENDPOINTS.AUTH.TOKEN_REFRESH);
    return response.data;
  },

  /**
   * Get current user profile
   */
  getProfile: async (): Promise<UserProfile> => {
    const response = await api.get<UserProfile>(ENDPOINTS.AUTH.PROFILE);
    return response.data;
  },

  /**
   * Update current user profile
   */
  updateProfile: async (data: Partial<UserProfile>): Promise<UserProfile> => {
    const response = await api.patch<UserProfile>(ENDPOINTS.AUTH.PROFILE, data);
    return response.data;
  },

  /**
   * Check if user is authenticated
   */
  isAuthenticated: async (): Promise<boolean> => {
    try {
      await authApi.getProfile();
      return true;
    } catch {
      return false;
    }
  },
};

export default authApi;

/**
 * Cash Control API Client
 * 
 * Handles all communication with Django backend for:
 * - Cash register opening and closing
 * - Cash floats and balancing
 * - Cash reconciliation
 * - Daily till management
 * 
 * Base URL: /api/v1/pos/cash-control/
 */

import { api } from './api';
import { ENDPOINTS } from './api-config';

export interface CashControlOpenData {
  opening_date: string; // YYYY-MM-DD
  opening_time?: string; // HH:MM:SS
  opening_float: number;
  operator_id?: string;
  till_number?: string;
  notes?: string;
}

export interface CashControlCloseData {
  closing_date: string; // YYYY-MM-DD
  closing_time?: string; // HH:MM:SS
  closing_float: number;
  cash_in_till: number;
  over_short?: number;
  notes?: string;
}

export interface CashControl {
  id: string | number;
  opening_date: string;
  closing_date?: string;
  opening_float: number;
  closing_float?: number;
  cash_in_till?: number;
  over_short?: number;
  status: 'OPEN' | 'CLOSED';
  created_at?: string;
  updated_at?: string;
}

export interface CashControlFilters {
  status?: string;
  opening_date_from?: string;
  opening_date_to?: string;
  page?: number;
  limit?: number;
}

export interface PaginatedResponse<T> {
  count: number;
  next?: string;
  previous?: string;
  results: T[];
}

export const cashControlApi = {
  /**
   * Get all cash controls with optional filtering
   */
  list: async (filters?: CashControlFilters) => {
    const response = await api.get<PaginatedResponse<CashControl>>(
      ENDPOINTS.POS.CASH_CONTROL,
      { params: filters }
    );
    return response.data;
  },

  /**
   * Get current open cash control
   */
  getCurrent: async () => {
    const response = await api.get<CashControl>(
      `${ENDPOINTS.POS.CASH_CONTROL}current/`
    );
    return response.data;
  },

  /**
   * Get a single cash control by ID
   */
  get: async (id: string | number) => {
    const response = await api.get<CashControl>(`${ENDPOINTS.POS.CASH_CONTROL}${id}/`);
    return response.data;
  },

  /**
   * Open a new cash control
   */
  open: async (data: CashControlOpenData) => {
    const response = await api.post<CashControl>(ENDPOINTS.POS.CASH_CONTROL, data);
    return response.data;
  },

  /**
   * Close an open cash control
   */
  close: async (id: string | number, data: CashControlCloseData) => {
    const response = await api.post(
      `${ENDPOINTS.POS.CASH_CONTROL}${id}/close/`,
      data
    );
    return response.data;
  },

  /**
   * Get cash control summary
   */
  getSummary: async () => {
    const response = await api.get<any>(
      `${ENDPOINTS.POS.CASH_CONTROL}summary/`
    );
    return response.data;
  },

  /**
   * Get today's cash control
   */
  getToday: async () => {
    const response = await api.get<CashControl>(
      `${ENDPOINTS.POS.CASH_CONTROL}today/`
    );
    return response.data;
  },
};

export default cashControlApi;

/**
 * Cash Returns API Client
 * 
 * Handles all communication with Django backend for:
 * - Cash return transactions (goods returned for cash refund)
 * - Return tracking and authorization
 * - Return status management
 * 
 * Base URL: /api/v1/pos/cash-returns/
 */

import { api } from './api';
import { ENDPOINTS } from './api-config';

export interface CashReturnLineItem {
  item_code: string;
  description: string;
  quantity: number;
  unit_price: number;
  discount_percentage?: number;
  reason: string; // e.g., "DAMAGED", "WRONG_ITEM", "CUSTOMER_RETURN", "OVERSTOCKED"
}

export interface CashReturnCreateData {
  return_date: string; // YYYY-MM-DD
  original_transaction_number?: string;
  line_items: CashReturnLineItem[];
  refund_amount: number;
  refund_method: 'CASH' | 'CHEQUE' | 'CREDIT_CARD' | 'EFT';
  notes?: string;
  authorization_code?: string;
}

export interface CashReturnUpdateData {
  status?: 'DRAFT' | 'APPROVED' | 'COMPLETED' | 'REJECTED';
  authorization_code?: string;
  notes?: string;
  line_items?: CashReturnLineItem[];
}

export interface CashReturn {
  id: string | number;
  return_number?: string;
  return_date: string;
  original_transaction_number?: string;
  refund_amount: number;
  refund_method: string;
  status?: 'DRAFT' | 'APPROVED' | 'COMPLETED' | 'REJECTED';
  authorization_code?: string;
  notes?: string;
  created_at?: string;
  updated_at?: string;
  created_by?: string;
}

export interface CashReturnFilters {
  status?: string;
  refund_method?: string;
  return_date_from?: string;
  return_date_to?: string;
  search?: string;
  page?: number;
  limit?: number;
}

export interface PaginatedResponse<T> {
  count: number;
  next?: string;
  previous?: string;
  results: T[];
}

export const cashReturnsApi = {
  /**
   * Get all cash returns with optional filtering
   */
  list: async (filters?: CashReturnFilters) => {
    const response = await api.get<PaginatedResponse<CashReturn>>(
      ENDPOINTS.POS.CASH_RETURNS,
      { params: filters }
    );
    return response.data;
  },

  /**
   * Get a single cash return by ID
   */
  get: async (id: string | number) => {
    const response = await api.get<CashReturn>(`${ENDPOINTS.POS.CASH_RETURNS}${id}/`);
    return response.data;
  },

  /**
   * Create a new cash return
