}

// ============================================================================
// SUPPLIER LEDGER (read-only)
// ============================================================================

export function useSupplierLedger(
  params: { creditor?: number; transaction_type?: string; search?: string; page?: number } = {},
  enabled = true
): UseApiResponse<PaginatedResponse<SupplierLedgerEntry>> {
  return useApiFetch(
