  const updateInvoice = (id: string | number, data: Partial<CreditorInvoiceCreateData>) =>
    run(() => api.patch<CreditorInvoice>(`${ENDPOINTS.CREDITORS.INVOICES}${id}/`, data).then((r) => r.data));

