// lib/useSettings.ts
"use client";

import { useState, useEffect, useCallback } from 'react';
import { api } from './api';

export interface SettingsData {
  departments: Record<string, unknown>[];
  salesAreas: Record<string, unknown>[];
  incomeCategories: Record<string, unknown>[];
  expenseCategories: Record<string, unknown>[];
  taxCodes: Record<string, unknown>[];
  paymentMethods: Record<string, unknown>[];
  creditTerms: Record<string, unknown>[];
  systemConfig: Record<string, unknown> | null;
}

const initialState: SettingsData = {
  departments: [],
  salesAreas: [],
  incomeCategories: [],
  expenseCategories: [],
  taxCodes: [],
  paymentMethods: [],
  creditTerms: [],
  systemConfig: null,
};

let cachedSettings: SettingsData | null = null;

/**
 * Custom hook to fetch and cache all settings/reference data
 * Use this hook in any component that needs access to settings
 */
export function useSettings() {
  const [settings, setSettings] = useState<SettingsData>(initialState);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchSettings = useCallback(async (forceRefresh = false) => {
    // Return cached data if available and not forcing refresh
    if (cachedSettings && !forceRefresh) {
      setSettings(cachedSettings);
      return cachedSettings;
    }

    setLoading(true);
    setError(null);

    try {
      const [
        deptRes,
        areasRes,
        incomeRes,
        expenseRes,
        taxRes,
        paymentRes,
        creditRes,
        systemRes,
      ] = await Promise.all([
        api.get('/api/settings/departments/'),
        api.get('/api/settings/sales-areas/'),
        api.get('/api/settings/income-categories/'),
        api.get('/api/settings/expense-categories/'),
        api.get('/api/settings/tax-codes/'),
        api.get('/api/settings/payment-methods/'),
        api.get('/api/settings/credit-terms/'),
        api.get('/api/settings/system-config/'),
      ]);

      const data: SettingsData = {
        departments: deptRes.data.results || deptRes.data,
        salesAreas: areasRes.data.results || areasRes.data,
        incomeCategories: incomeRes.data.results || incomeRes.data,
        expenseCategories: expenseRes.data.results || expenseRes.data,
        taxCodes: taxRes.data.results || taxRes.data,
        paymentMethods: paymentRes.data.results || paymentRes.data,
        creditTerms: creditRes.data.results || creditRes.data,
        systemConfig: systemRes.data.results?.[0] || systemRes.data,
      };

      cachedSettings = data;
      setSettings(data);
      return data;
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : 'Failed to fetch settings';
      setError(errorMsg);
      console.error('Failed to fetch settings:', err);
      return null;
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchSettings();
  }, [fetchSettings]);

  return {
    ...settings,
    loading,
    error,
    refreshSettings: (force?: boolean) => fetchSettings(force),
  };
}

/**
 * Helper function to get a specific setting type without the hook
 * Useful for one-off requests
 */
export async function getSettingType(type: keyof SettingsData) {
  try {
    const endpoints: Record<keyof SettingsData, string> = {
      departments: '/api/settings/departments/',
      salesAreas: '/api/settings/sales-areas/',
      incomeCategories: '/api/settings/income-categories/',
      expenseCategories: '/api/settings/expense-categories/',
      taxCodes: '/api/settings/tax-codes/',
      paymentMethods: '/api/settings/payment-methods/',
      creditTerms: '/api/settings/credit-terms/',
      systemConfig: '/api/settings/system-config/',
    };

    const response = await api.get(endpoints[type]);
    return response.data.results || response.data;
  } catch (error) {
    console.error(`Failed to fetch ${type}:`, error);
    return null;
  }
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/**
 * Extract user-friendly error message from API response
 * Handles various error formats: field validation, detail messages, HTML errors, and raw errors
 */
export function extractErrorMessage(error: any): string {
  // Handle network errors
  if (!error.response) {
    if (error.code === 'ERR_NETWORK') {
      return 'Network error: Cannot reach the server. Please check your connection or try again later.';
    }
    if (error.message?.includes('ERR_CONNECTION')) {
      return 'Connection lost: The server is not responding. Please check if the server is running.';
    }
    return error.message || 'A network error occurred. Please try again.';
  }

  // Handle HTML error responses (backend returning error pages)
  if (typeof error.response.data === 'string' && error.response.data.includes('<!doctype html>')) {
    if (error.response.status >= 500) {
      return 'Server error (500): The server encountered an internal error. Please check the server logs or contact support.';
    }
    return `Server error (${error.response.status}): The request could not be processed.`;
  }

  // Handle JSON error responses
  if (error.response?.data && typeof error.response.data === 'object') {
    const data = error.response.data;
    
    // For server errors (5xx), provide helpful message
    if (error.response.status >= 500) {
      // Check for detail message first
      if (data.detail) {
        return `Server error: ${data.detail}`;
      }
      // Generic 500 error message
      return 'Server error. Please try again later or contact support if the problem persists.';
    }
    
    // Extract first field error (for validation errors)
    for (const [field, messages] of Object.entries(data)) {
      if (Array.isArray(messages) && messages.length > 0) {
        return `${field}: ${messages[0]}`;
      }
      if (typeof messages === 'string') {
        return `${field}: ${messages}`;
      }
    }
    
    // Fall back to detail field if present
    if (data.detail) {
      return data.detail;
    }
  }
  
  // Handle axios error message (e.g., "Request failed with status code 500")
  if (error.message) {
    return error.message;
  }
  
  // Generic fallback
  return 'An unexpected error occurred. Please try again.';
}
/**
 * Format ISO timestamp to readable time string
 * Examples: "2:30 PM", "Yesterday 3:45 PM", "Feb 10, 2:30 PM"
 */
export function formatTime(isoString: string): string {
  const date = new Date(isoString);
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const messageDate = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  
  const diffTime = today.getTime() - messageDate.getTime();
  const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

  const timeStr = date.toLocaleTimeString('en-US', { 
    hour: 'numeric', 
    minute: '2-digit',
    hour12: true 
  });

  if (diffDays === 0) {
    return timeStr; // Same day: "2:30 PM"
  } else if (diffDays === 1) {
    return `Yesterday ${timeStr}`; // Yesterday: "Yesterday 2:30 PM"
  } else if (diffDays < 7) {
    const dayName = date.toLocaleDateString('en-US', { weekday: 'short' });
    return `${dayName} ${timeStr}`; // Within a week: "Mon 2:30 PM"
  } else {
    const dateStr = date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    return `${dateStr} ${timeStr}`; // Older: "Feb 10, 2:30 PM"
  }
}

/**
 * API Error Handler Utility
 * Centralized error handling for API responses
 */

import { AxiosError } from 'axios';

export interface ApiError {
  statusCode: number;
  message: string;
  details?: Record<string, any>;
  isNetworkError: boolean;
  isValidationError: boolean;
  isAuthError: boolean;
  isNotFoundError: boolean;
  isServerError: boolean;
}

/**
 * Parse and standardize API errors
 */
export function parseApiError(error: unknown): ApiError {
  const defaultError: ApiError = {
    statusCode: 500,
    message: 'An unexpected error occurred',
    isNetworkError: false,
    isValidationError: false,
    isAuthError: false,
    isNotFoundError: false,
    isServerError: true,
  };

  if (!error) return defaultError;

  // Handle Axios errors
  if ((error as any).isAxiosError) {
    const axiosError = error as AxiosError;
    const status = axiosError.response?.status || 500;
    const data = axiosError.response?.data as any;

    return {
      statusCode: status,
      message: data?.detail || data?.message || axiosError.message || 'Unknown error',
      details: data?.errors || data,
      isNetworkError: !axiosError.response,
      isValidationError: status === 400 || status === 422,
      isAuthError: status === 401 || status === 403,
      isNotFoundError: status === 404,
      isServerError: status >= 500,
    };
  }

  // Handle Error objects
  if (error instanceof Error) {
    return {
      ...defaultError,
      message: error.message,
      isNetworkError: error.message.includes('Network'),
    };
  }

  // Handle string errors
  if (typeof error === 'string') {
    return {
      ...defaultError,
      message: error,
    };
  }

  return defaultError;
}

/**
 * Get user-friendly error message
 */
export function getErrorMessage(error: unknown): string {
  const apiError = parseApiError(error);

  if (apiError.isNetworkError) {
    return 'Network error. Please check your connection and try again.';
  }

  if (apiError.isAuthError) {
    return 'You do not have permission to perform this action. Please log in again.';
  }

  if (apiError.isNotFoundError) {
    return 'The requested resource was not found.';
  }

  if (apiError.isValidationError) {
    return apiError.message || 'Please check your input and try again.';
  }

  if (apiError.isServerError) {
    return 'Server error. Please try again later.';
  }

  return apiError.message || 'An unexpected error occurred';
}

/**
 * Get validation errors from API response
 */
export function getValidationErrors(error: unknown): Record<string, string> {
  const apiError = parseApiError(error);
  
  if (!apiError.isValidationError || !apiError.details) {
    return {};
  }

  const details = apiError.details;
  const errors: Record<string, string> = {};

  // Handle different error response formats
  if (typeof details === 'object') {
    Object.entries(details).forEach(([key, value]) => {
      if (Array.isArray(value)) {
        errors[key] = value[0]?.message || value[0] || 'Invalid value';
      } else if (typeof value === 'object' && value !== null) {
        errors[key] = (value as any).message || JSON.stringify(value);
      } else {
        errors[key] = String(value);
      }
    });
  }

  return errors;
}

/**
 * Map API errors to form field errors
 */
export function mapApiErrorsToFormFields(
  error: unknown
): Record<string, string> {
  const validationErrors = getValidationErrors(error);
  const fieldErrorMap: Record<string, string> = {};

  // Map common API field names to form field names
  const fieldMapping: Record<string, string> = {
    debtor_account_number: 'debtorAccountNumber',
    account_number: 'accountNumber',
    cheque_number: 'chequeNumber',
    invoice_number: 'invoiceNumber',
    reference_number: 'referenceNumber',
    credit_note_date: 'creditNoteDate',
    job_date: 'jobDate',
    repair_date: 'repairDate',
    return_date: 'returnDate',
    cheque_date: 'chequeDate',
    opening_date: 'openingDate',
    closing_date: 'closingDate',
    line_items: 'lineItems',
  };

  Object.entries(validationErrors).forEach(([apiField, message]) => {
    const formField = fieldMapping[apiField] || apiField;
    fieldErrorMap[formField] = message;
  });

  return fieldErrorMap;
}

/**
 * Retry API request with exponential backoff
 */
export async function retryRequest<T>(
  requestFn: () => Promise<T>,
  maxRetries = 3,
  baseDelayMs = 1000
): Promise<T> {
  let lastError: Error | null = null;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await requestFn();
    } catch (error) {
      lastError = error as Error;
      const apiError = parseApiError(error);

      // Don't retry on validation or auth errors
      if (
        apiError.isValidationError ||
        apiError.isAuthError ||
        apiError.isNotFoundError
      ) {
        throw error;
      }

      // Only retry on network errors or 5xx server errors
      if (apiError.isNetworkError || apiError.isServerError) {
        if (attempt < maxRetries - 1) {
          const delayMs = baseDelayMs * Math.pow(2, attempt);
          await new Promise((resolve) => setTimeout(resolve, delayMs));
          continue;
        }
      }

      throw error;
    }
  }

  throw lastError || new Error('Request failed after maximum retries');
}

/**
 * Common API error handler wrapper
 */
export function createApiErrorHandler(onError?: (error: ApiError) => void) {
  return (error: unknown) => {
    const apiError = parseApiError(error);
    onError?.(apiError);
    return apiError;
  };
}

/**
 * Toast Notification Utility
 * Simple toast notification system for user feedback
 */

import React, { useEffect, useState } from 'react';

export type ToastType = 'success' | 'error' | 'warning' | 'info';

export interface Toast {
  id: string;
  message: string;
  type: ToastType;
  duration?: number;
}

export interface ToastContextType {
  toasts: Toast[];
  addToast: (message: string, type: ToastType, duration?: number) => void;
  removeToast: (id: string) => void;
  clearAll: () => void;
}

// Singleton instance for toast management
let toastInstance: ToastContextType | null = null;

/**
 * Simple toast notification system
 */
export function createToastManager(): ToastContextType {
  const toasts: Toast[] = [];
  const listeners: Set<(toasts: Toast[]) => void> = new Set();

  const notify = (toasts: Toast[]) => {
    listeners.forEach((listener) => listener(toasts));
  };

  return {
    toasts,
    addToast: (message: string, type: ToastType, duration = 3000) => {
      const id = Date.now().toString();
      const toast: Toast = { id, message, type, duration };
      
      toasts.push(toast);
      notify([...toasts]);

      if (duration > 0) {
        setTimeout(() => {
          const index = toasts.findIndex((t) => t.id === id);
          if (index !== -1) {
            toasts.splice(index, 1);
            notify([...toasts]);
          }
        }, duration);
      }

      return id;
    },
    removeToast: (id: string) => {
      const index = toasts.findIndex((t) => t.id === id);
      if (index !== -1) {
        toasts.splice(index, 1);
        notify([...toasts]);
      }
    },
    clearAll: () => {
      toasts.length = 0;
      notify([]);
    },
  };
}

/**
 * Hook to use toast notifications
 */
export function useToast() {
  if (!toastInstance) {
    toastInstance = createToastManager();
  }

  return {
    success: (message: string, duration?: number) =>
      toastInstance!.addToast(message, 'success', duration),
    error: (message: string, duration?: number) =>
      toastInstance!.addToast(message, 'error', duration),
    warning: (message: string, duration?: number) =>
      toastInstance!.addToast(message, 'warning', duration),
    info: (message: string, duration?: number) =>
      toastInstance!.addToast(message, 'info', duration),
    remove: (id: string) => toastInstance!.removeToast(id),
    clearAll: () => toastInstance!.clearAll(),
  };
}

/**
 * Toast Container Component
 */
export function ToastContainer() {
  const [toasts, setToasts] = useState<Toast[]>([]);

  useEffect(() => {
    if (!toastInstance) {
      toastInstance = createToastManager();
    }

    const _listener = (updatedToasts: Toast[]) => {
      setToasts([...updatedToasts]);
    };

    // Set initial toasts
    setToasts([...toastInstance.toasts]);
  }, []);

  const getToastStyles = (type: ToastType) => {
    const baseClass = 'px-4 py-3 rounded-lg font-medium text-white flex items-center gap-2';
    
    switch (type) {
      case 'success':
        return `${baseClass} bg-green-600`;
      case 'error':
        return `${baseClass} bg-red-600`;
      case 'warning':
        return `${baseClass} bg-yellow-600`;
      case 'info':
        return `${baseClass} bg-blue-600`;
      default:
        return baseClass;
    }
  };

  const getIcon = (type: ToastType) => {
    switch (type) {
      case 'success':
        return '✓';
      case 'error':
        return '✕';
      case 'warning':
        return '⚠';
      case 'info':
        return 'ℹ';
      default:
        return '';
    }
  };

  return (
    <div className="fixed bottom-4 right-4 z-50 space-y-2 pointer-events-none">
      {toasts.map((toast) => (
        <div
          key={toast.id}
          className={`${getToastStyles(toast.type)} shadow-lg animate-in fade-in slide-in-from-bottom-4 duration-300 pointer-events-auto`}
        >
          <span className="text-lg">{getIcon(toast.type)}</span>
          <span>{toast.message}</span>
          <button
            onClick={() => toastInstance?.removeToast(toast.id)}
            className="ml-auto font-bold hover:opacity-80 transition-opacity"
          >
            ×
          </button>
        </div>
      ))}
    </div>
  );
}

/**
 * Form Validation Utilities
 * Standard validation rules and error handling for forms across the application
 */

export interface ValidationResult {
  isValid: boolean;
  errors: Record<string, string>;
}

export interface ValidationRule {
  required?: boolean | string;
  minLength?: { value: number; message: string };
  maxLength?: { value: number; message: string };
  pattern?: { value: RegExp; message: string };
  custom?: (value: any) => string | null;
}

export interface FormValidationRules {
  [fieldName: string]: ValidationRule;
}

/**
 * Standard validation patterns
 */
export const ValidationPatterns = {
  EMAIL: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
  PHONE: /^(\+27|0)[0-9]{9,}$/,
  ACCOUNT_NUMBER: /^[A-Za-z0-9\-]+$/,
  NUMERIC: /^[0-9]+$/,
  DECIMAL: /^[0-9]+(\.[0-9]{1,2})?$/,
  DATE: /^\d{4}-\d{2}-\d{2}$/,
  CHEQUE_NUMBER: /^[0-9]{6,10}$/,
  VAT_NUMBER: /^[0-9]{10}$/,
};

/**
 * Standard validation messages
 */
export const ValidationMessages = {
  REQUIRED: 'This field is required',
  INVALID_EMAIL: 'Please enter a valid email address',
  INVALID_PHONE: 'Please enter a valid phone number',
  INVALID_ACCOUNT: 'Please enter a valid account number',
  INVALID_NUMERIC: 'Please enter a valid number',
  INVALID_DECIMAL: 'Please enter a valid decimal number',
  INVALID_DATE: 'Please enter a valid date (YYYY-MM-DD)',
  INVALID_CHEQUE: 'Please enter a valid cheque number',
  INVALID_VAT: 'Please enter a valid VAT number',
  MIN_LENGTH: (min: number) => `Minimum ${min} characters required`,
  MAX_LENGTH: (max: number) => `Maximum ${max} characters allowed`,
};

/**
 * Validate a single field value against a rule
 */
export function validateField(
  value: any,
  rule: ValidationRule,
  _fieldName: string
): string | null {
  // Check required
  if (rule.required) {
    if (value === undefined || value === null || value === '') {
      return typeof rule.required === 'string'
        ? rule.required
        : ValidationMessages.REQUIRED;
    }
  }

  // Skip further validation if value is empty and not required
  if (!rule.required && (value === undefined || value === null || value === '')) {
    return null;
  }

  // Check min length
  if (rule.minLength && value.length < rule.minLength.value) {
    return rule.minLength.message;
  }

  // Check max length
  if (rule.maxLength && value.length > rule.maxLength.value) {
    return rule.maxLength.message;
  }

  // Check pattern
  if (rule.pattern && !rule.pattern.value.test(value)) {
    return rule.pattern.message;
  }

  // Check custom validation
  if (rule.custom) {
    const error = rule.custom(value);
    if (error) return error;
  }

  return null;
}

/**
 * Validate entire form object against rules
 */
export function validateForm(
  data: Record<string, any>,
  rules: FormValidationRules
): ValidationResult {
  const errors: Record<string, string> = {};

  Object.entries(rules).forEach(([fieldName, rule]) => {
    const error = validateField(data[fieldName], rule, fieldName);
    if (error) {
      errors[fieldName] = error;
    }
  });

  return {
    isValid: Object.keys(errors).length === 0,
    errors,
  };
}

/**
 * Predefined validation rules for common fields
 */
export const CommonValidationRules = {
  accountNumber: (required = true): ValidationRule => ({
    required: required ? ValidationMessages.REQUIRED : false,
    pattern: {
      value: ValidationPatterns.ACCOUNT_NUMBER,
      message: ValidationMessages.INVALID_ACCOUNT,
    },
  }),

  email: (required = true): ValidationRule => ({
    required: required ? ValidationMessages.REQUIRED : false,
    pattern: {
      value: ValidationPatterns.EMAIL,
      message: ValidationMessages.INVALID_EMAIL,
    },
  }),

  phone: (required = true): ValidationRule => ({
    required: required ? ValidationMessages.REQUIRED : false,
    pattern: {
      value: ValidationPatterns.PHONE,
      message: ValidationMessages.INVALID_PHONE,
    },
  }),

  amount: (required = true): ValidationRule => ({
    required: required ? ValidationMessages.REQUIRED : false,
    pattern: {
      value: ValidationPatterns.DECIMAL,
      message: ValidationMessages.INVALID_DECIMAL,
    },
    custom: (value) => {
      if (typeof value === 'string') {
        const num = parseFloat(value);
        if (isNaN(num)) return ValidationMessages.INVALID_DECIMAL;
        if (num < 0) return 'Amount cannot be negative';
      }
      return null;
    },
  }),

  date: (required = true): ValidationRule => ({
    required: required ? ValidationMessages.REQUIRED : false,
    pattern: {
      value: ValidationPatterns.DATE,
      message: ValidationMessages.INVALID_DATE,
    },
  }),

  chequeNumber: (required = true): ValidationRule => ({
    required: required ? ValidationMessages.REQUIRED : false,
    pattern: {
      value: ValidationPatterns.CHEQUE_NUMBER,
      message: ValidationMessages.INVALID_CHEQUE,
    },
  }),

  text: (required = true, minLength = 0, maxLength = 255): ValidationRule => ({
    required: required ? ValidationMessages.REQUIRED : false,
    minLength:
      minLength > 0
        ? {
            value: minLength,
            message: ValidationMessages.MIN_LENGTH(minLength),
          }
        : undefined,
    maxLength: {
      value: maxLength,
      message: ValidationMessages.MAX_LENGTH(maxLength),
    },
  }),
};

/**
 * Format validation errors for display
 */
export function formatValidationErrors(
  errors: Record<string, string>
): string {
  const errorList = Object.entries(errors)
    .map(([field, message]) => `${field}: ${message}`)
    .join('\n');
  return errorList;
}
